-- Phase 1: Supabase Auth owns credentials; these tables contain application data only.
-- Run the entire file in Supabase SQL Editor. It never deletes local or existing app data.
begin;
create table public.mentor_profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  nickname text not null default 'Học viên' check (char_length(nickname) between 1 and 80),
  bio text not null default '' check (char_length(bio) <= 500),
  avatar_path text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create table public.mentor_preferences (
  user_id uuid primary key references auth.users(id) on delete cascade,
  grade smallint check (grade in (10,11,12)),
  subjects text[] not null default '{}',
  language text not null default 'vi' check (language in ('vi','en')),
  theme text not null default 'system' check (theme in ('system','light','dark')),
  updated_at timestamptz not null default now(),
  check (subjects <@ array['math','literature','english','history','geography','chemistry','physics','biology','economics_law']::text[])
);
create table public.mentor_timetable (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  day smallint not null check (day between 1 and 7),
  period smallint not null check (period between 1 and 10),
  subject text not null check (char_length(subject) between 1 and 120),
  teacher text check (char_length(teacher) <= 120),
  notes text check (char_length(notes) <= 2000),
  updated_at timestamptz not null default now(),
  unique (user_id,day,period)
);

create function public.mentor_stamp_updated_at() returns trigger language plpgsql set search_path = '' as $$
begin new.updated_at = now(); return new; end;
$$;
create trigger mentor_profiles_updated before update on public.mentor_profiles for each row execute function public.mentor_stamp_updated_at();
create trigger mentor_preferences_updated before update on public.mentor_preferences for each row execute function public.mentor_stamp_updated_at();
create trigger mentor_timetable_updated before update on public.mentor_timetable for each row execute function public.mentor_stamp_updated_at();

-- No role, EXP or reward fields come from user metadata.
create function public.mentor_create_user() returns trigger language plpgsql security definer set search_path = '' as $$
begin
  insert into public.mentor_profiles(id,nickname)
    values(new.id,coalesce(nullif(left(trim(new.raw_user_meta_data->>'nickname'),80),''),'Học viên'));
  insert into public.mentor_preferences(user_id) values(new.id);
  return new;
end;
$$;
revoke all on function public.mentor_create_user() from public,anon,authenticated;
create trigger mentor_auth_user_created after insert on auth.users for each row execute function public.mentor_create_user();
-- Backfill accounts created before installing this migration.
insert into public.mentor_profiles(id) select id from auth.users on conflict do nothing;
insert into public.mentor_preferences(user_id) select id from auth.users on conflict do nothing;

alter table public.mentor_profiles enable row level security;
alter table public.mentor_preferences enable row level security;
alter table public.mentor_timetable enable row level security;
revoke all on public.mentor_profiles,public.mentor_preferences,public.mentor_timetable from anon,authenticated;
grant select on public.mentor_profiles to authenticated;
grant update(nickname,bio,avatar_path) on public.mentor_profiles to authenticated;
grant select on public.mentor_preferences to authenticated;
grant update(grade,subjects,language,theme) on public.mentor_preferences to authenticated;
grant select,insert,update,delete on public.mentor_timetable to authenticated;
create policy mentor_profile_read on public.mentor_profiles for select to authenticated using (true);
create policy mentor_profile_edit on public.mentor_profiles for update to authenticated using ((select auth.uid())=id) with check ((select auth.uid())=id);
create policy mentor_preferences_owner on public.mentor_preferences for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy mentor_timetable_owner on public.mentor_timetable for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);

-- Explicit publication only for tables needed by the first sync phase.
do $$ declare t text; begin
  foreach t in array array['mentor_profiles','mentor_preferences','mentor_timetable'] loop
    if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename=t) then
      execute format('alter publication supabase_realtime add table public.%I',t);
    end if;
  end loop;
end $$;
commit;



begin;
alter table public.mentor_timetable add column if not exists client_id bigint generated always as identity unique;
create table if not exists public.mentor_todos(
 id bigint generated always as identity primary key,
 user_id uuid not null references auth.users(id) on delete cascade,
 title text not null check(char_length(title) between 1 and 500),
 day smallint not null check(day between 1 and 7), priority smallint not null default 1 check(priority between 0 and 2),
 linked_subject text, completed boolean not null default false, created_at timestamptz not null default now(), completed_at timestamptz,
 updated_at timestamptz not null default now()
);
create table if not exists public.mentor_schedule_logs(
 id bigint generated always as identity primary key,
 user_id uuid not null references auth.users(id) on delete cascade,
 action text not null check(char_length(action)<=40), entity text not null check(char_length(entity)<=40),
 description text not null check(char_length(description)<=2000), created_at timestamptz not null default now()
);
alter table public.mentor_todos enable row level security;
alter table public.mentor_schedule_logs enable row level security;
revoke all on public.mentor_todos,public.mentor_schedule_logs from anon,authenticated;
grant select,insert,update,delete on public.mentor_todos,public.mentor_schedule_logs to authenticated;
grant usage,select on sequence public.mentor_todos_id_seq,public.mentor_schedule_logs_id_seq,public.mentor_timetable_client_id_seq to authenticated;
create policy mentor_todos_owner on public.mentor_todos to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy mentor_schedule_logs_owner on public.mentor_schedule_logs to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create function public.mentor_schedule_action(op text,data jsonb default '{}'::jsonb)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare uid uuid:=auth.uid(); item bigint; count_added int:=0; rowdata jsonb; result jsonb;
begin
 if uid is null then raise exception 'AUTHENTICATION_REQUIRED' using errcode='28000'; end if;
 if op='entries' then
  select coalesce(jsonb_agg(to_jsonb(t) order by period),'[]') into result from public.mentor_timetable t where user_id=uid and day=(data->>'day')::int;
  return jsonb_build_object('items',result);
 elsif op='insert_entry' then
  insert into public.mentor_timetable(user_id,day,period,subject,teacher,notes) values(uid,(data->>'day')::int,(data->>'period')::int,data->>'title',data->>'teacher',data->>'notes') returning client_id into item;
 elsif op='update_entry' then
  update public.mentor_timetable set day=(data->>'day')::int,period=(data->>'period')::int,subject=data->>'title',teacher=data->>'teacher',notes=data->>'notes' where user_id=uid and client_id=(data->>'id')::bigint returning client_id into item;
  if item is null then raise exception 'NOT_FOUND'; end if;
 elsif op='delete_entry' then delete from public.mentor_timetable where user_id=uid and client_id=(data->>'id')::bigint;
 elsif op='import' then
  if jsonb_typeof(data->'entries')<>'array' or jsonb_array_length(data->'entries') not between 1 and 70 then raise exception 'INVALID_IMPORT'; end if;
  for rowdata in select value from jsonb_array_elements(data->'entries') loop
   insert into public.mentor_timetable(user_id,day,period,subject) values(uid,(rowdata->>'day')::int,(rowdata->>'period')::int,rowdata->>'title') on conflict(user_id,day,period) do nothing;
   if found then count_added:=count_added+1; end if;
  end loop;
  return jsonb_build_object('inserted',count_added);
 elsif op='todos' then
  select coalesce(jsonb_agg(to_jsonb(t) order by completed,priority desc,id),'[]') into result from public.mentor_todos t where user_id=uid and day=(data->>'day')::int;
  return jsonb_build_object('items',result);
 elsif op='insert_todo' then
  insert into public.mentor_todos(user_id,title,day,priority,linked_subject,completed) values(uid,data->>'title',(data->>'day')::int,(data->>'priority')::int,data->>'linked_subject',coalesce((data->>'completed')::boolean,false)) returning id into item;
 elsif op='update_todo' then
  update public.mentor_todos set title=data->>'title',day=(data->>'day')::int,priority=(data->>'priority')::int,linked_subject=data->>'linked_subject',updated_at=now() where user_id=uid and id=(data->>'id')::bigint returning id into item;
  if item is null then raise exception 'NOT_FOUND'; end if;
 elsif op='todo_status' then
  update public.mentor_todos set completed=(data->>'completed')::boolean,completed_at=case when (data->>'completed')::boolean then now() else null end,updated_at=now() where user_id=uid and id=(data->>'id')::bigint returning id into item;
  if item is null then raise exception 'NOT_FOUND'; end if;
 elsif op='delete_todo' then delete from public.mentor_todos where user_id=uid and id=(data->>'id')::bigint;
 elsif op='logs' then
  select coalesce(jsonb_agg(to_jsonb(t) order by id desc),'[]') into result from (select * from public.mentor_schedule_logs where user_id=uid order by id desc limit least(greatest(coalesce((data->>'limit')::int,50),1),100)) t;
  return jsonb_build_object('items',result);
 elsif op='insert_log' then
  insert into public.mentor_schedule_logs(user_id,action,entity,description) values(uid,data->>'action',data->>'entity',data->>'description') returning id into item;
 elsif op='clear_logs' then delete from public.mentor_schedule_logs where user_id=uid;
 else raise exception 'UNKNOWN_OPERATION'; end if;
 return jsonb_build_object('id',item);
end; $$;
revoke all on function public.mentor_schedule_action(text,jsonb) from public,anon;
grant execute on function public.mentor_schedule_action(text,jsonb) to authenticated;
commit;


begin;
create table public.mentor_course_units(
 subject_id text not null,grade int not null check(grade between 10 and 12),course_version text not null,
 unit_id text not null,position int not null,kind text not null,title text not null,course_title text not null,source_note text not null,
 guidance jsonb not null default '[]',examples jsonb not null default '[]',questions jsonb not null,sources jsonb not null default '[]',
 primary key(subject_id,grade,unit_id)
);
create table public.mentor_enrollments(
 id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade,
 subject_id text not null,grade int not null check(grade between 10 and 12),placement jsonb,revision int not null default 1,updated_at timestamptz not null default now(),unique(user_id,subject_id,grade)
);
create table public.mentor_attempts(
 id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade,
 enrollment_id uuid not null references public.mentor_enrollments(id) on delete cascade,unit_id text not null,course_version text not null,
 kind text not null,state text not null default 'IN_PROGRESS',step int not null default 0,answers jsonb not null default '{}',
 revision int not null default 1,updated_at timestamptz not null default now()
);
create unique index mentor_one_pending_unit on public.mentor_attempts(user_id,enrollment_id,unit_id,course_version) where state='IN_PROGRESS';
create table public.mentor_awards(
 user_id uuid not null references auth.users(id) on delete cascade,subject_id text not null,grade int not null,unit_id text not null,
 xp int not null check(xp in (200,400)),learning_day date not null default (now() at time zone 'Asia/Ho_Chi_Minh')::date,created_at timestamptz not null default now(),primary key(user_id,subject_id,grade,unit_id)
);
create table public.mentor_learning_days(user_id uuid not null references auth.users(id) on delete cascade,day date not null,primary key(user_id,day));
create table public.mentor_completions(attempt_id uuid primary key references public.mentor_attempts(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,result jsonb not null);
create table public.mentor_requests(user_id uuid not null references auth.users(id) on delete cascade,key text not null,fingerprint text not null,result jsonb not null,primary key(user_id,key));
alter table public.mentor_course_units enable row level security;
alter table public.mentor_enrollments enable row level security;
alter table public.mentor_attempts enable row level security;
alter table public.mentor_awards enable row level security;
alter table public.mentor_learning_days enable row level security;
alter table public.mentor_completions enable row level security;
alter table public.mentor_requests enable row level security;
revoke all on public.mentor_course_units,public.mentor_enrollments,public.mentor_attempts,public.mentor_awards,public.mentor_learning_days,public.mentor_completions,public.mentor_requests from anon,authenticated;
-- No client can write points, mark answers correct or read private answer keys directly.
create function public.mentor_streak(uid uuid) returns int language sql stable set search_path='' as $$
 with d as(select day,row_number() over(order by day desc) n,max(day) over() last from public.mentor_learning_days where user_id=uid and day<=(now() at time zone 'Asia/Ho_Chi_Minh')::date)
 select case when max(last)>=(now() at time zone 'Asia/Ho_Chi_Minh')::date-1 then count(*) filter(where day=last-(n::int-1))::int else 0 end from d;
$$;
revoke all on function public.mentor_streak(uuid) from public,anon,authenticated;
create function public.mentor_attempt_view(aid uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare a public.mentor_attempts; e public.mentor_enrollments; u public.mentor_course_units; q jsonb; ans jsonb; visible jsonb:='[]'; options jsonb;
begin
 select * into a from public.mentor_attempts where id=aid and user_id=auth.uid();
 if a.id is null then raise sqlstate 'PT404' using message='ATTEMPT_NOT_FOUND'; end if;
 select * into e from public.mentor_enrollments where id=a.enrollment_id;
 select * into u from public.mentor_course_units where subject_id=e.subject_id and grade=e.grade and unit_id=a.unit_id;
 if u.course_version<>a.course_version then raise sqlstate 'PT409' using message='CURRICULUM_VERSION_CONFLICT'; end if;
 for q in select value from jsonb_array_elements(u.questions) loop
  ans:=a.answers->(q->>'id');
  if not(a.state='COMPLETED' or (a.kind<>'PLACEMENT' and coalesce((ans->>'wrongCount')::int,0)>=2)) then q:=q-'correctOptionId'-'explanation'; end if;
  select jsonb_agg(value order by md5(aid::text||':'||(q->>'id')||':'||(value->>'id'))) into options from jsonb_array_elements(q->'options');
  visible:=visible||jsonb_build_array(jsonb_set(q,'{options}',options));
 end loop;
 return jsonb_build_object('id',a.id,'enrollmentId',e.id,'lessonId',a.unit_id,'subjectId',e.subject_id,'grade',e.grade,'rewardUnitId',a.unit_id,'curriculumVersion',a.course_version,'kind',a.kind,'step',a.step,'answers',coalesce((select jsonb_agg(value) from jsonb_each(a.answers)),'[]'),'questions',visible,'sourceLessonIds',u.sources,'guidance',u.guidance,'examples',u.examples,'state',a.state,'revision',a.revision,'updatedAt',a.updated_at);
end; $$;
revoke all on function public.mentor_attempt_view(uuid) from public,anon,authenticated;

create function public.mentor_learning_api(method text,path text,body jsonb default '{}',request_key text default null,expected_revision int default null,query jsonb default '{}') returns jsonb
language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); e public.mentor_enrollments; a public.mentor_attempts; u public.mentor_course_units; units jsonb:='[]'; x record; unit_state text; done bool; ready bool; result jsonb; q jsonb; ans jsonb; old jsonb; prev jsonb; sid text; chosen text; correct bool; wrong int; submissions jsonb; score int; xp int:=0; first_reward bool:=false; lit bool:=false; day date:=(now() at time zone 'Asia/Ho_Chi_Minh')::date; daily bigint; item uuid; fingerprint text:=md5(method||path||body::text); cached public.mentor_requests;
begin
 if uid is null then raise sqlstate 'PT401' using message='AUTHENTICATION_REQUIRED'; end if;
 perform pg_advisory_xact_lock(hashtextextended(uid::text,0));
 if method<>'GET' and request_key is not null then
  select * into cached from public.mentor_requests where user_id=uid and key=request_key;
  if cached.key is not null then
   if cached.fingerprint<>fingerprint then raise sqlstate 'PT409' using message='IDEMPOTENCY_CONFLICT'; end if;
   return cached.result;
  end if;
 end if;
 if path='/subjects' then
  select jsonb_build_object('items',jsonb_agg(jsonb_build_object('id',s,'implementation',case when s in ('physics','chemistry','biology') then 'ACTIVE' else 'FRAMEWORK' end,'availableGrades',coalesce((select jsonb_agg(distinct grade) from public.mentor_course_units where subject_id=s),'[]')))) into result from unnest(array['math','literature','english','history','geography','physics','chemistry','biology','economics_law']) s;
 elsif path='/enrollments' and method='POST' then
  if not exists(select 1 from public.mentor_course_units where subject_id=body->>'subjectId' and grade=(body->>'grade')::int) then raise sqlstate 'PT409' using message='CURRICULUM_NOT_PUBLISHED'; end if;
  insert into public.mentor_enrollments(user_id,subject_id,grade) values(uid,body->>'subjectId',(body->>'grade')::int) on conflict(user_id,subject_id,grade) do update set updated_at=public.mentor_enrollments.updated_at returning * into e;
  result:=jsonb_build_object('id',e.id,'subjectId',e.subject_id,'grade',e.grade,'placement',e.placement,'revision',e.revision,'updatedAt',e.updated_at);
 elsif path='/enrollments' and method='GET' then
  select jsonb_build_object('items',coalesce(jsonb_agg(jsonb_build_object('id',id,'subjectId',subject_id,'grade',grade,'placement',placement,'revision',revision,'updatedAt',updated_at)),'[]')) into result from public.mentor_enrollments where user_id=uid;
 elsif path ~ '^/enrollments/[^/]+/path$' then
  select * into e from public.mentor_enrollments where id=split_part(path,'/',3)::uuid and user_id=uid;
  if e.id is null then raise sqlstate 'PT404' using message='ENROLLMENT_NOT_FOUND'; end if;
  ready:=e.placement is not null;
  for u in select * from public.mentor_course_units where subject_id=e.subject_id and grade=e.grade and kind<>'PLACEMENT' order by position loop
   done:=exists(select 1 from public.mentor_attempts where user_id=uid and enrollment_id=e.id and unit_id=u.unit_id and state='COMPLETED');
   unit_state:=case when done then 'COMPLETED' when ready then 'AVAILABLE' else 'LOCKED' end;
   units:=units||jsonb_build_array(jsonb_build_object('id',u.unit_id,'title',u.title,'kind',u.kind,'xp',case when u.kind='LESSON' then 200 else 400 end,'state',unit_state,'questionCount',jsonb_array_length(u.questions),'sourceLessonIds',u.sources));
   ready:=ready and done;
  end loop;
  result:=jsonb_build_object('enrollment',jsonb_build_object('id',e.id,'subjectId',e.subject_id,'grade',e.grade,'placement',e.placement,'revision',e.revision),'title',u.course_title,'curriculumVersion',u.course_version,'sourceNote',u.source_note,'units',units,'pendingAttempts',coalesce((select jsonb_agg(jsonb_build_object('id',id,'unit_id',unit_id)) from public.mentor_attempts where user_id=uid and enrollment_id=e.id and state='IN_PROGRESS'),'[]'));
 elsif path in ('/placements','/attempts') and method='POST' then
  select * into e from public.mentor_enrollments where id=(body->>'enrollmentId')::uuid and user_id=uid;
  if e.id is null then raise sqlstate 'PT404' using message='ENROLLMENT_NOT_FOUND'; end if;
  select * into u from public.mentor_course_units where subject_id=e.subject_id and grade=e.grade and unit_id=case when path='/placements' then 'placement' else body->>'lessonId' end;
  if u.unit_id is null then raise sqlstate 'PT404' using message='LESSON_NOT_FOUND'; end if;
  if path='/placements' then
   if e.placement is not null then raise sqlstate 'PT409' using message='PLACEMENT_ALREADY_COMPLETED'; end if;
  else
   if u.kind='PLACEMENT' then raise sqlstate 'PT409' using message='INVALID_LESSON'; end if;
   if e.placement is null then raise sqlstate 'PT409' using message='PLACEMENT_REQUIRED'; end if;
   if u.course_version<>body->>'curriculumVersion' then raise sqlstate 'PT409' using message='CURRICULUM_VERSION_CONFLICT'; end if;
   if exists(select 1 from public.mentor_course_units prior where prior.subject_id=e.subject_id and prior.grade=e.grade and prior.kind<>'PLACEMENT' and prior.position<u.position and not exists(select 1 from public.mentor_attempts t where t.user_id=uid and t.enrollment_id=e.id and t.unit_id=prior.unit_id and t.state='COMPLETED')) then raise sqlstate 'PT409' using message='PREVIOUS_LESSON_REQUIRED'; end if;
  end if;
  select * into a from public.mentor_attempts where user_id=uid and enrollment_id=e.id and unit_id=u.unit_id and course_version=u.course_version and state='IN_PROGRESS';
  if a.id is null then insert into public.mentor_attempts(user_id,enrollment_id,unit_id,course_version,kind) values(uid,e.id,u.unit_id,u.course_version,u.kind) returning * into a; end if;
  result:=public.mentor_attempt_view(a.id);
 elsif path ~ '^/attempts/[^/]+$' and method='GET' then result:=public.mentor_attempt_view(split_part(path,'/',3)::uuid);
 elsif path ~ '^/attempts/[^/]+$' and method='PATCH' then
  select * into a from public.mentor_attempts where id=split_part(path,'/',3)::uuid and user_id=uid for update;
  if a.id is null then raise sqlstate 'PT404' using message='ATTEMPT_NOT_FOUND'; end if;
  if expected_revision is null or expected_revision<>a.revision then raise sqlstate 'PT409' using message='REVISION_CONFLICT'; end if;
  if a.state<>'IN_PROGRESS' then raise sqlstate 'PT409' using message='ATTEMPT_ALREADY_COMPLETED'; end if;
  select * into e from public.mentor_enrollments where id=a.enrollment_id;
  select * into u from public.mentor_course_units where subject_id=e.subject_id and grade=e.grade and unit_id=a.unit_id;
  if u.course_version<>a.course_version then raise sqlstate 'PT409' using message='CURRICULUM_VERSION_CONFLICT'; end if;
  if (body->>'step')::int not between 0 and jsonb_array_length(u.questions)+2 or jsonb_typeof(body->'answers')<>'array' then raise sqlstate 'PT400' using message='INVALID_STEP'; end if;
  prev:=a.answers;
  for ans in select value from jsonb_array_elements(body->'answers') loop
   select value into q from jsonb_array_elements(u.questions) where value->>'id'=ans->>'questionId';
   if q is null then raise sqlstate 'PT400' using message='INVALID_QUESTION'; end if;
   chosen:=ans->>'selectedOptionId'; sid:=ans->>'submissionId';
   if sid is null or char_length(sid) not between 1 and 100 or not exists(select 1 from jsonb_array_elements(q->'options') where value->>'id'=chosen) then raise sqlstate 'PT400' using message='INVALID_ANSWER'; end if;
   old:=coalesce(prev->(q->>'id'),'{}'); submissions:=coalesce(old->'submissions','{}');
   if submissions ? sid then
    if submissions->>sid<>chosen then raise sqlstate 'PT409' using message='SUBMISSION_CONFLICT'; end if;
    continue;
   end if;
   if a.kind='PLACEMENT' and old<>'{}' then raise sqlstate 'PT409' using message='PLACEMENT_ANSWER_FINAL'; end if;
   if (select count(*) from jsonb_object_keys(submissions))>=100 then raise sqlstate 'PT409' using message='TOO_MANY_ANSWER_ATTEMPTS'; end if;
   correct:=chosen=q->>'correctOptionId'; wrong:=coalesce((old->>'wrongCount')::int,0)+case when correct then 0 else 1 end;
   ans:=jsonb_build_object('questionId',q->>'id','selectedOptionId',chosen,'correct',correct,'wrongCount',wrong,'assisted',coalesce((old->>'assisted')::boolean,false) or wrong>=2,'firstTryCorrect',coalesce((old->>'firstTryCorrect')::boolean,correct),'submissions',submissions||jsonb_build_object(sid,chosen));
   prev:=jsonb_set(prev,array[q->>'id'],ans,true);
  end loop;
  update public.mentor_attempts set step=(body->>'step')::int,answers=prev,revision=revision+1,updated_at=now() where id=a.id;
  result:=public.mentor_attempt_view(a.id);
 elsif path='/completions' and method='POST' then
  select * into a from public.mentor_attempts where id=(body->>'attemptId')::uuid and user_id=uid for update;
  if a.id is null then raise sqlstate 'PT404' using message='ATTEMPT_NOT_FOUND'; end if;
  select c.result||jsonb_build_object('replayed',true) into result from public.mentor_completions c where c.attempt_id=a.id;
  if result is not null then return result; end if;
  select * into e from public.mentor_enrollments where id=a.enrollment_id;
  select * into u from public.mentor_course_units where subject_id=e.subject_id and grade=e.grade and unit_id=a.unit_id;
  if u.course_version<>a.course_version then raise sqlstate 'PT409' using message='CURRICULUM_VERSION_CONFLICT'; end if;
  if exists(select 1 from jsonb_array_elements(u.questions) question_row where not(a.answers ? (question_row->>'id')) or (a.kind<>'PLACEMENT' and not coalesce((a.answers->(question_row->>'id')->>'correct')::boolean,false))) then raise sqlstate 'PT409' using message='PRACTICE_NOT_FINISHED'; end if;
  if a.kind='PLACEMENT' then
   select count(*) filter(where (value->>'correct')::boolean) into score from jsonb_each(a.answers);
   ans:=jsonb_build_object('correct',score,'total',jsonb_array_length(u.questions),'recommendation',case when score<jsonb_array_length(u.questions)*.6 then 'GUIDED' else 'STANDARD' end,'scope','INTRODUCTORY_BLOCK','completedAt',now());
   update public.mentor_enrollments set placement=ans,revision=revision+1,updated_at=now() where id=e.id;
  else
   xp:=case when a.kind='LESSON' then 200 else 400 end;
   insert into public.mentor_awards(user_id,subject_id,grade,unit_id,xp,learning_day) values(uid,e.subject_id,e.grade,a.unit_id,xp,day) on conflict do nothing;
   first_reward:=found; if not first_reward then xp:=0; end if;
   insert into public.mentor_learning_days values(uid,day) on conflict do nothing; lit:=found;
  end if;
  select coalesce(sum(w.xp),0) into daily from public.mentor_awards w where user_id=uid and learning_day=day;
  result:=jsonb_build_object('id',gen_random_uuid(),'attemptId',a.id,'rewardUnitId',a.unit_id,'kind',a.kind,'xpAwarded',xp,'firstRewardForUnit',first_reward,'streakLit',lit,'streakDays',public.mentor_streak(uid),'dailyXp',daily,'learningDay',day,'timezone','Asia/Ho_Chi_Minh','completedAt',now(),'replayed',false,'revision',1);
  if a.kind='PLACEMENT' then result:=result||jsonb_build_object('assessment',ans); end if;
  insert into public.mentor_completions values(a.id,uid,result);
  update public.mentor_attempts set state='COMPLETED',revision=revision+1,updated_at=now() where id=a.id;
 else raise sqlstate 'PT404' using message='API_NOT_IMPLEMENTED'; end if;
 if method<>'GET' and request_key is not null then insert into public.mentor_requests values(uid,request_key,fingerprint,result); end if;
 return result;
end; $$;
revoke all on function public.mentor_learning_api(text,text,jsonb,text,int,jsonb) from public,anon;
grant execute on function public.mentor_learning_api(text,text,jsonb,text,int,jsonb) to authenticated;
commit;


begin;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('biology',10,'intro-2026.1','biology-10-cell-basics',1,'LESSON','Tế bào — đơn vị của sự sống','Tế bào, chuyển hóa và sinh sản','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Tế bào là đơn vị cấu trúc và chức năng cơ bản của cơ thể sống. Một sinh vật có thể gồm một hoặc nhiều tế bào."]'::jsonb,'["Vi khuẩn là sinh vật đơn bào. Cơ thể người gồm nhiều loại tế bào đảm nhiệm các chức năng khác nhau."]'::jsonb,'[{"id": "biology-10-cell-basics-q1", "prompt": "Đơn vị cấu trúc và chức năng cơ bản của cơ thể sống là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tế bào"}, {"id": "b", "text": "Nguyên tử riêng lẻ"}, {"id": "c", "text": "Cơ quan"}], "correctOptionId": "a", "explanation": "Các hoạt động sống cơ bản diễn ra ở cấp tế bào; cơ quan được cấu tạo từ nhiều tế bào."}, {"id": "biology-10-cell-basics-q2", "prompt": "Sinh vật đơn bào có cơ thể gồm?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đúng hai tế bào"}, {"id": "b", "text": "Không có tế bào"}, {"id": "c", "text": "Một tế bào"}], "correctOptionId": "c", "explanation": "Đơn bào nghĩa là cơ thể gồm một tế bào thực hiện các hoạt động sống."}, {"id": "biology-10-cell-basics-q3", "prompt": "Tế bào cơ và tế bào thần kinh có hình dạng khác nhau chủ yếu vì?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Một loại không phải tế bào"}, {"id": "b", "text": "Chuyên hóa cho chức năng khác nhau"}, {"id": "c", "text": "Không có điểm chung nào"}], "correctOptionId": "b", "explanation": "Sự chuyên hóa về cấu trúc giúp tế bào đảm nhiệm chức năng như co cơ hoặc truyền tín hiệu."}]'::jsonb,'["biology-10-cell-basics"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('biology',10,'intro-2026.1','biology-10-membrane',2,'LESSON','Màng sinh chất','Tế bào, chuyển hóa và sinh sản','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Màng sinh chất bao quanh tế bào, gồm lớp kép phospholipid và protein. Màng có tính thấm chọn lọc, điều hòa trao đổi chất với môi trường."]'::jsonb,'["Một số phân tử nhỏ không phân cực có thể đi qua lớp lipid; nhiều chất khác cần protein vận chuyển."]'::jsonb,'[{"id": "biology-10-membrane-q1", "prompt": "Thành phần nền tảng của màng sinh chất là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Một lớp cellulose duy nhất"}, {"id": "b", "text": "Chỉ DNA"}, {"id": "c", "text": "Lớp kép phospholipid và protein"}], "correctOptionId": "c", "explanation": "Lớp kép phospholipid tạo nền màng, protein tham gia vận chuyển và nhiều chức năng khác."}, {"id": "biology-10-membrane-q2", "prompt": "Tính thấm chọn lọc nghĩa là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Không chất nào đi qua"}, {"id": "b", "text": "Các chất đi qua màng với khả năng khác nhau"}, {"id": "c", "text": "Mọi chất đi qua như nhau"}], "correctOptionId": "b", "explanation": "Màng không phải hàng rào kín tuyệt đối; cấu trúc màng và protein quyết định khả năng đi qua của từng chất."}, {"id": "biology-10-membrane-q3", "prompt": "Nếu màng mất khả năng điều hòa trao đổi chất, nguy cơ trực tiếp là?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Mất ổn định môi trường bên trong tế bào"}, {"id": "b", "text": "Tự tăng gấp đôi DNA ngay"}, {"id": "c", "text": "Tạo thêm thành cellulose ngay"}], "correctOptionId": "a", "explanation": "Trao đổi không được kiểm soát làm xáo trộn thành phần bên trong, ảnh hưởng hoạt động sống của tế bào."}]'::jsonb,'["biology-10-membrane"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('biology',10,'intro-2026.1','biology-10-prokaryote',3,'LESSON','Tế bào nhân sơ','Tế bào, chuyển hóa và sinh sản','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Tế bào nhân sơ không có nhân được bao bởi màng nhân. Vật chất di truyền nằm ở vùng nhân; tế bào vẫn có màng sinh chất và ribosome."]'::jsonb,'["Vi khuẩn có DNA ở vùng nhân và ribosome để tổng hợp protein; không có ti thể có màng bao như tế bào nhân thực."]'::jsonb,'[{"id": "biology-10-prokaryote-q1", "prompt": "Đặc điểm nổi bật của tế bào nhân sơ là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Không có màng sinh chất"}, {"id": "b", "text": "Không có nhân được màng nhân bao bọc"}, {"id": "c", "text": "Không có DNA"}], "correctOptionId": "b", "explanation": "Nhân sơ có DNA nhưng DNA không nằm trong nhân có màng bao."}, {"id": "biology-10-prokaryote-q2", "prompt": "Cấu trúc nào có ở tế bào vi khuẩn điển hình?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Ribosome"}, {"id": "b", "text": "Lục lạp có màng kép"}, {"id": "c", "text": "Nhân có màng bao"}], "correctOptionId": "a", "explanation": "Ribosome tham gia tổng hợp protein và có ở cả tế bào nhân sơ lẫn nhân thực."}, {"id": "biology-10-prokaryote-q3", "prompt": "Quan sát thấy tế bào không có màng nhân. Có thể kết luận tế bào không có vật chất di truyền không?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Có; DNA chỉ tồn tại trong màng nhân"}, {"id": "b", "text": "Có; mọi tế bào đều có nhân thực"}, {"id": "c", "text": "Không; cần phân biệt DNA với màng nhân"}], "correctOptionId": "c", "explanation": "Tế bào nhân sơ chứa DNA ở vùng nhân. Thiếu màng nhân không đồng nghĩa thiếu DNA."}]'::jsonb,'["biology-10-prokaryote"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('biology',10,'intro-2026.1','biology-10-eukaryote',4,'LESSON','Tế bào nhân thực','Tế bào, chuyển hóa và sinh sản','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Tế bào nhân thực có nhân được màng bao bọc và các bào quan chuyên hóa. Nhân chứa phần lớn DNA của tế bào; ribosome tổng hợp protein."]'::jsonb,'["Tế bào động vật điển hình có nhân, ti thể và ribosome. Tế bào thực vật quang hợp còn có lục lạp."]'::jsonb,'[{"id": "biology-10-eukaryote-q1", "prompt": "Tế bào nhân thực điển hình có đặc điểm nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Có nhân được màng bao bọc"}, {"id": "b", "text": "Luôn không có DNA"}, {"id": "c", "text": "Không có ribosome"}], "correctOptionId": "a", "explanation": "Nhân có màng bao là đặc điểm phân biệt cơ bản của tế bào nhân thực."}, {"id": "biology-10-eukaryote-q2", "prompt": "Cấu trúc trực tiếp tổng hợp protein là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Màng nhân"}, {"id": "b", "text": "Không bào"}, {"id": "c", "text": "Ribosome"}], "correctOptionId": "c", "explanation": "Ribosome liên kết các amino acid theo thông tin được truyền từ gene."}, {"id": "biology-10-eukaryote-q3", "prompt": "Một tế bào lá đang quang hợp cần bào quan nào trực tiếp thu nhận năng lượng ánh sáng?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Nhân"}, {"id": "b", "text": "Lục lạp"}, {"id": "c", "text": "Ribosome"}], "correctOptionId": "b", "explanation": "Lục lạp chứa sắc tố quang hợp và bộ máy chuyển hóa năng lượng ánh sáng."}]'::jsonb,'["biology-10-eukaryote"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('biology',10,'intro-2026.1','biology-10-transport',5,'LESSON','Vận chuyển qua màng','Tế bào, chuyển hóa và sinh sản','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Khuếch tán thụ động không cần tế bào cung cấp năng lượng trực tiếp và đi theo gradient nồng độ của chất. Thẩm thấu là sự di chuyển của nước qua màng thấm chọn lọc."]'::jsonb,'["Với màng chỉ cho nước qua, nước có xu hướng đi từ phía có nồng độ chất tan thấp sang phía có nồng độ chất tan cao hơn."]'::jsonb,'[{"id": "biology-10-transport-q1", "prompt": "Vận chuyển thụ động thường có đặc điểm nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Luôn tiêu thụ ATP trực tiếp"}, {"id": "b", "text": "Luôn ngược gradient nồng độ"}, {"id": "c", "text": "Không cần cung cấp năng lượng trực tiếp"}], "correctOptionId": "c", "explanation": "Khuếch tán sử dụng chênh lệch nồng độ, không cần tế bào cung cấp năng lượng trực tiếp."}, {"id": "biology-10-transport-q2", "prompt": "Thẩm thấu là sự di chuyển của chất nào qua màng thấm chọn lọc?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chỉ DNA"}, {"id": "b", "text": "Nước"}, {"id": "c", "text": "Chỉ protein"}], "correctOptionId": "b", "explanation": "Thuật ngữ thẩm thấu mô tả chuyển động của nước qua màng thấm chọn lọc."}, {"id": "biology-10-transport-q3", "prompt": "Màng chỉ cho nước qua, một phía nhiều chất tan hơn. Nước có xu hướng đi về đâu?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Phía có nồng độ chất tan cao hơn"}, {"id": "b", "text": "Phía có nồng độ chất tan thấp hơn"}, {"id": "c", "text": "Không di chuyển dù có chênh lệch"}], "correctOptionId": "a", "explanation": "Trong điều kiện đã nêu, chênh lệch thế nước làm nước đi về phía có nhiều chất tan hơn. Cần xét cả áp suất nếu điều kiện thay đổi."}]'::jsonb,'["biology-10-transport"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('biology',10,'intro-2026.1','biology-10-review-1',6,'FIVE_LESSON_REVIEW','Ôn tập 1','Tế bào, chuyển hóa và sinh sản','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "biology-10-cell-basics-q1", "prompt": "Đơn vị cấu trúc và chức năng cơ bản của cơ thể sống là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tế bào"}, {"id": "b", "text": "Nguyên tử riêng lẻ"}, {"id": "c", "text": "Cơ quan"}], "correctOptionId": "a", "explanation": "Các hoạt động sống cơ bản diễn ra ở cấp tế bào; cơ quan được cấu tạo từ nhiều tế bào."}, {"id": "biology-10-cell-basics-q2", "prompt": "Sinh vật đơn bào có cơ thể gồm?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đúng hai tế bào"}, {"id": "b", "text": "Không có tế bào"}, {"id": "c", "text": "Một tế bào"}], "correctOptionId": "c", "explanation": "Đơn bào nghĩa là cơ thể gồm một tế bào thực hiện các hoạt động sống."}, {"id": "biology-10-membrane-q1", "prompt": "Thành phần nền tảng của màng sinh chất là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Một lớp cellulose duy nhất"}, {"id": "b", "text": "Chỉ DNA"}, {"id": "c", "text": "Lớp kép phospholipid và protein"}], "correctOptionId": "c", "explanation": "Lớp kép phospholipid tạo nền màng, protein tham gia vận chuyển và nhiều chức năng khác."}, {"id": "biology-10-membrane-q2", "prompt": "Tính thấm chọn lọc nghĩa là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Không chất nào đi qua"}, {"id": "b", "text": "Các chất đi qua màng với khả năng khác nhau"}, {"id": "c", "text": "Mọi chất đi qua như nhau"}], "correctOptionId": "b", "explanation": "Màng không phải hàng rào kín tuyệt đối; cấu trúc màng và protein quyết định khả năng đi qua của từng chất."}, {"id": "biology-10-prokaryote-q1", "prompt": "Đặc điểm nổi bật của tế bào nhân sơ là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Không có màng sinh chất"}, {"id": "b", "text": "Không có nhân được màng nhân bao bọc"}, {"id": "c", "text": "Không có DNA"}], "correctOptionId": "b", "explanation": "Nhân sơ có DNA nhưng DNA không nằm trong nhân có màng bao."}, {"id": "biology-10-prokaryote-q2", "prompt": "Cấu trúc nào có ở tế bào vi khuẩn điển hình?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Ribosome"}, {"id": "b", "text": "Lục lạp có màng kép"}, {"id": "c", "text": "Nhân có màng bao"}], "correctOptionId": "a", "explanation": "Ribosome tham gia tổng hợp protein và có ở cả tế bào nhân sơ lẫn nhân thực."}, {"id": "biology-10-eukaryote-q1", "prompt": "Tế bào nhân thực điển hình có đặc điểm nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Có nhân được màng bao bọc"}, {"id": "b", "text": "Luôn không có DNA"}, {"id": "c", "text": "Không có ribosome"}], "correctOptionId": "a", "explanation": "Nhân có màng bao là đặc điểm phân biệt cơ bản của tế bào nhân thực."}, {"id": "biology-10-eukaryote-q2", "prompt": "Cấu trúc trực tiếp tổng hợp protein là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Màng nhân"}, {"id": "b", "text": "Không bào"}, {"id": "c", "text": "Ribosome"}], "correctOptionId": "c", "explanation": "Ribosome liên kết các amino acid theo thông tin được truyền từ gene."}, {"id": "biology-10-transport-q1", "prompt": "Vận chuyển thụ động thường có đặc điểm nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Luôn tiêu thụ ATP trực tiếp"}, {"id": "b", "text": "Luôn ngược gradient nồng độ"}, {"id": "c", "text": "Không cần cung cấp năng lượng trực tiếp"}], "correctOptionId": "c", "explanation": "Khuếch tán sử dụng chênh lệch nồng độ, không cần tế bào cung cấp năng lượng trực tiếp."}, {"id": "biology-10-transport-q2", "prompt": "Thẩm thấu là sự di chuyển của chất nào qua màng thấm chọn lọc?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chỉ DNA"}, {"id": "b", "text": "Nước"}, {"id": "c", "text": "Chỉ protein"}], "correctOptionId": "b", "explanation": "Thuật ngữ thẩm thấu mô tả chuyển động của nước qua màng thấm chọn lọc."}]'::jsonb,'["biology-10-cell-basics", "biology-10-membrane", "biology-10-prokaryote", "biology-10-eukaryote", "biology-10-transport"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('biology',10,'intro-2026.1','biology-10-water',7,'LESSON','Nước trong tế bào','Tế bào, chuyển hóa và sinh sản','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Nước có tính phân cực, tạo liên kết hydrogen và hòa tan nhiều chất ion hoặc phân cực. Nước là môi trường của nhiều phản ứng sinh hóa; không phải dung môi hòa tan được mọi chất."]'::jsonb,'["Muối ăn hòa tan trong nước nhưng dầu không hòa tan tốt. Hai hiện tượng liên quan tính chất phân tử và tương tác với nước, không chỉ do chất ở thể rắn hay lỏng."]'::jsonb,'[{"id": "biology-10-water-q1", "prompt": "Nước hòa tan tốt nhiều chất nhờ đặc tính nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Không tương tác với ion"}, {"id": "b", "text": "Tính phân cực"}, {"id": "c", "text": "Hoàn toàn không phân cực"}], "correctOptionId": "b", "explanation": "Phân tử nước có các phần điện tích khác nhau, tương tác được với ion và nhiều phân tử phân cực."}, {"id": "biology-10-water-q2", "prompt": "Chất nào không hòa tan tốt trong nước ở điều kiện thường?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Dầu ăn"}, {"id": "b", "text": "Muối ăn với lượng vừa phải"}, {"id": "c", "text": "Đường với lượng vừa phải"}], "correctOptionId": "a", "explanation": "Dầu chủ yếu gồm các phân tử kị nước, khó hòa tan trong nước phân cực."}, {"id": "biology-10-water-q3", "prompt": "Nhận định nào phù hợp về nước trong tế bào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Chỉ làm tăng khối lượng, không có vai trò khác"}, {"id": "b", "text": "Hòa tan hoàn toàn mọi loại lipid"}, {"id": "c", "text": "Là môi trường phản ứng nhưng không hòa tan mọi chất"}], "correctOptionId": "c", "explanation": "Nước tham gia cấu trúc và phản ứng, nhưng các chất kị nước vẫn cần cách tổ chức hoặc vận chuyển riêng."}]'::jsonb,'["biology-10-water"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('biology',10,'intro-2026.1','biology-10-carbohydrates',8,'LESSON','Carbohydrate: đường và chất dự trữ','Tế bào, chuyển hóa và sinh sản','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Carbohydrate gồm đường đơn, đường đôi và đường đa. Glucose là nguồn nguyên liệu năng lượng quan trọng; tinh bột ở thực vật và glycogen ở động vật giúp dự trữ, còn cellulose tham gia thành tế bào thực vật."]'::jsonb,'["Hạt gạo dự trữ tinh bột. Trong cơ thể người, glycogen tập trung chủ yếu ở gan và cơ; cellulose không được enzyme tiêu hóa của người phân giải như tinh bột."]'::jsonb,'[{"id": "biology-10-carbohydrates-q1", "prompt": "Glucose thuộc nhóm nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Đường đơn"}, {"id": "b", "text": "Protein"}, {"id": "c", "text": "Nucleic acid"}], "correctOptionId": "a", "explanation": "Glucose là monosaccharide, một đơn vị đường đơn phổ biến."}, {"id": "biology-10-carbohydrates-q2", "prompt": "Chất dự trữ carbohydrate điển hình ở động vật là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cellulose"}, {"id": "b", "text": "DNA"}, {"id": "c", "text": "Glycogen"}], "correctOptionId": "c", "explanation": "Glycogen dự trữ glucose, đặc biệt ở gan và cơ."}, {"id": "biology-10-carbohydrates-q3", "prompt": "Tinh bột và cellulose đều tạo từ glucose nhưng có vai trò khác nhau vì?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Tinh bột là protein"}, {"id": "b", "text": "Cách liên kết và cấu trúc khác nhau"}, {"id": "c", "text": "Cellulose không chứa nguyên tử carbon"}], "correctOptionId": "b", "explanation": "Kiểu liên kết và cách sắp xếp các đơn vị làm thay đổi hình dạng, tính chất và khả năng enzyme phân giải."}]'::jsonb,'["biology-10-carbohydrates"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('biology',10,'intro-2026.1','biology-10-lipids',9,'LESSON','Lipid: dự trữ và tạo màng','Tế bào, chuyển hóa và sinh sản','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Lipid là nhóm chất đa dạng, phần lớn ít tan trong nước. Mỡ dự trữ năng lượng; phospholipid có đầu ưa nước và đuôi kị nước, thuận lợi hình thành lớp kép của màng."]'::jsonb,'["Trong lớp kép phospholipid, các đầu ưa nước hướng về môi trường nước hai phía, các đuôi kị nước hướng vào nhau bên trong."]'::jsonb,'[{"id": "biology-10-lipids-q1", "prompt": "Đặc điểm chung của nhiều lipid là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Đều là chuỗi amino acid"}, {"id": "b", "text": "Đều chứa thông tin di truyền"}, {"id": "c", "text": "Ít tan trong nước"}], "correctOptionId": "c", "explanation": "Lipid có nhiều vùng không phân cực, nên thường khó hòa tan trong nước."}, {"id": "biology-10-lipids-q2", "prompt": "Trong lớp kép màng, đuôi phospholipid thường hướng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chỉ vào nhân tế bào"}, {"id": "b", "text": "Vào nhau, tránh môi trường nước"}, {"id": "c", "text": "Ra nước ở cả hai phía"}], "correctOptionId": "b", "explanation": "Đuôi kị nước được che bên trong, còn đầu ưa nước hướng ra các môi trường nước."}, {"id": "biology-10-lipids-q3", "prompt": "Chức năng nào phù hợp với mỡ dự trữ?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Dự trữ năng lượng dài hạn"}, {"id": "b", "text": "Làm khuôn trực tiếp sao chép DNA"}, {"id": "c", "text": "Luôn xúc tác mọi phản ứng"}], "correctOptionId": "a", "explanation": "Mỡ là nguồn dự trữ giàu năng lượng; không đảm nhiệm chức năng lưu trữ trình tự di truyền của DNA."}]'::jsonb,'["biology-10-lipids"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('biology',10,'intro-2026.1','biology-10-proteins',10,'LESSON','Protein và hình dạng chức năng','Tế bào, chuyển hóa và sinh sản','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Protein được cấu tạo từ amino acid nối bằng liên kết peptide. Trình tự và sự gấp cuộn quyết định cấu trúc không gian và chức năng; nhiệt độ hoặc pH không phù hợp có thể gây biến tính."]'::jsonb,'["Lòng trắng trứng đông lại khi đun do protein thay đổi cấu trúc. Biến tính không nhất thiết đồng nghĩa mọi liên kết peptide đều bị cắt."]'::jsonb,'[{"id": "biology-10-proteins-q1", "prompt": "Đơn phân cấu tạo protein là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Nucleotide"}, {"id": "b", "text": "Amino acid"}, {"id": "c", "text": "Glucose"}], "correctOptionId": "b", "explanation": "Các amino acid nối thành chuỗi polypeptide qua liên kết peptide."}, {"id": "biology-10-proteins-q2", "prompt": "Protein có thể mất chức năng khi bị biến tính chủ yếu do?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Thay đổi cấu trúc không gian phù hợp"}, {"id": "b", "text": "Luôn chuyển thành DNA"}, {"id": "c", "text": "Tự mất mọi nguyên tử carbon"}], "correctOptionId": "a", "explanation": "Nhiều chức năng phụ thuộc hình dạng; thay đổi gấp cuộn có thể làm mất vị trí gắn hay hoạt tính."}, {"id": "biology-10-proteins-q3", "prompt": "Đun nóng một enzyme làm mất hoạt tính. Kết luận hợp lý nhất?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Mọi amino acid chắc chắn đã biến thành glucose"}, {"id": "b", "text": "Enzyme chưa từng là protein"}, {"id": "c", "text": "Cấu trúc enzyme có thể đã biến đổi"}], "correctOptionId": "c", "explanation": "Nhiệt cao có thể làm biến tính enzyme protein; chỉ từ mất hoạt tính chưa kết luận mọi liên kết peptide bị phá."}]'::jsonb,'["biology-10-proteins"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('biology',10,'intro-2026.1','biology-10-nucleic-acids',11,'LESSON','DNA và RNA','Tế bào, chuyển hóa và sinh sản','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["DNA và RNA là nucleic acid, cấu tạo từ nucleotide. DNA lưu trữ thông tin di truyền; nhiều loại RNA tham gia biểu hiện thông tin. DNA thường có A, T, G, C; RNA thường có A, U, G, C."]'::jsonb,'["Trong DNA mạch kép, A bắt cặp với T, G với C. Đoạn một mạch A–G–T có mạch bổ sung tương ứng T–C–A, nếu chỉ xét thứ tự bắt cặp."]'::jsonb,'[{"id": "biology-10-nucleic-acids-q1", "prompt": "Đơn phân của nucleic acid là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Nucleotide"}, {"id": "b", "text": "Amino acid"}, {"id": "c", "text": "Acid béo"}], "correctOptionId": "a", "explanation": "Nucleotide gồm đường, phosphate và base nitrogen."}, {"id": "biology-10-nucleic-acids-q2", "prompt": "Base thường có ở RNA thay cho T của DNA là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "G"}, {"id": "b", "text": "C"}, {"id": "c", "text": "U"}], "correctOptionId": "c", "explanation": "RNA dùng uracil (U), còn DNA thường dùng thymine (T)."}, {"id": "biology-10-nucleic-acids-q3", "prompt": "Trong DNA mạch kép, mạch A–G–T có các base bổ sung lần lượt?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "A–G–T"}, {"id": "b", "text": "T–C–A"}, {"id": "c", "text": "U–C–A"}], "correctOptionId": "b", "explanation": "A ghép T, G ghép C, T ghép A. U thuộc RNA, không dùng cho câu hỏi DNA này."}]'::jsonb,'["biology-10-nucleic-acids"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('biology',10,'intro-2026.1','biology-10-review-2',12,'FIVE_LESSON_REVIEW','Ôn tập 2','Tế bào, chuyển hóa và sinh sản','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "biology-10-water-q1", "prompt": "Nước hòa tan tốt nhiều chất nhờ đặc tính nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Không tương tác với ion"}, {"id": "b", "text": "Tính phân cực"}, {"id": "c", "text": "Hoàn toàn không phân cực"}], "correctOptionId": "b", "explanation": "Phân tử nước có các phần điện tích khác nhau, tương tác được với ion và nhiều phân tử phân cực."}, {"id": "biology-10-water-q2", "prompt": "Chất nào không hòa tan tốt trong nước ở điều kiện thường?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Dầu ăn"}, {"id": "b", "text": "Muối ăn với lượng vừa phải"}, {"id": "c", "text": "Đường với lượng vừa phải"}], "correctOptionId": "a", "explanation": "Dầu chủ yếu gồm các phân tử kị nước, khó hòa tan trong nước phân cực."}, {"id": "biology-10-carbohydrates-q1", "prompt": "Glucose thuộc nhóm nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Đường đơn"}, {"id": "b", "text": "Protein"}, {"id": "c", "text": "Nucleic acid"}], "correctOptionId": "a", "explanation": "Glucose là monosaccharide, một đơn vị đường đơn phổ biến."}, {"id": "biology-10-carbohydrates-q2", "prompt": "Chất dự trữ carbohydrate điển hình ở động vật là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cellulose"}, {"id": "b", "text": "DNA"}, {"id": "c", "text": "Glycogen"}], "correctOptionId": "c", "explanation": "Glycogen dự trữ glucose, đặc biệt ở gan và cơ."}, {"id": "biology-10-lipids-q1", "prompt": "Đặc điểm chung của nhiều lipid là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Đều là chuỗi amino acid"}, {"id": "b", "text": "Đều chứa thông tin di truyền"}, {"id": "c", "text": "Ít tan trong nước"}], "correctOptionId": "c", "explanation": "Lipid có nhiều vùng không phân cực, nên thường khó hòa tan trong nước."}, {"id": "biology-10-lipids-q2", "prompt": "Trong lớp kép màng, đuôi phospholipid thường hướng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chỉ vào nhân tế bào"}, {"id": "b", "text": "Vào nhau, tránh môi trường nước"}, {"id": "c", "text": "Ra nước ở cả hai phía"}], "correctOptionId": "b", "explanation": "Đuôi kị nước được che bên trong, còn đầu ưa nước hướng ra các môi trường nước."}, {"id": "biology-10-proteins-q1", "prompt": "Đơn phân cấu tạo protein là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Nucleotide"}, {"id": "b", "text": "Amino acid"}, {"id": "c", "text": "Glucose"}], "correctOptionId": "b", "explanation": "Các amino acid nối thành chuỗi polypeptide qua liên kết peptide."}, {"id": "biology-10-proteins-q2", "prompt": "Protein có thể mất chức năng khi bị biến tính chủ yếu do?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Thay đổi cấu trúc không gian phù hợp"}, {"id": "b", "text": "Luôn chuyển thành DNA"}, {"id": "c", "text": "Tự mất mọi nguyên tử carbon"}], "correctOptionId": "a", "explanation": "Nhiều chức năng phụ thuộc hình dạng; thay đổi gấp cuộn có thể làm mất vị trí gắn hay hoạt tính."}, {"id": "biology-10-nucleic-acids-q1", "prompt": "Đơn phân của nucleic acid là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Nucleotide"}, {"id": "b", "text": "Amino acid"}, {"id": "c", "text": "Acid béo"}], "correctOptionId": "a", "explanation": "Nucleotide gồm đường, phosphate và base nitrogen."}, {"id": "biology-10-nucleic-acids-q2", "prompt": "Base thường có ở RNA thay cho T của DNA là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "G"}, {"id": "b", "text": "C"}, {"id": "c", "text": "U"}], "correctOptionId": "c", "explanation": "RNA dùng uracil (U), còn DNA thường dùng thymine (T)."}]'::jsonb,'["biology-10-water", "biology-10-carbohydrates", "biology-10-lipids", "biology-10-proteins", "biology-10-nucleic-acids"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('biology',10,'intro-2026.1','biology-10-organelles',13,'LESSON','Sự phối hợp của các bào quan','Tế bào, chuyển hóa và sinh sản','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Ribosome tổng hợp protein; lưới nội chất và bộ máy Golgi tham gia xử lí, vận chuyển nhiều sản phẩm tế bào. Ti thể tham gia hô hấp tế bào; lục lạp quang hợp ở tế bào thực vật có khả năng quang hợp."]'::jsonb,'["Một protein tiết ra ngoài thường được tổng hợp trên ribosome gắn lưới nội chất hạt, đi qua hệ thống màng và Golgi rồi được đưa ra ngoài qua túi vận chuyển."]'::jsonb,'[{"id": "biology-10-organelles-q1", "prompt": "Cấu trúc trực tiếp tổng hợp chuỗi polypeptide là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Bộ máy Golgi"}, {"id": "b", "text": "Thành cellulose"}, {"id": "c", "text": "Ribosome"}], "correctOptionId": "c", "explanation": "Ribosome thực hiện dịch mã để tạo chuỗi polypeptide."}, {"id": "biology-10-organelles-q2", "prompt": "Bào quan nổi bật trong biến đổi, phân loại và đóng gói nhiều sản phẩm là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Thành tế bào"}, {"id": "b", "text": "Bộ máy Golgi"}, {"id": "c", "text": "Nucleoid của vi khuẩn"}], "correctOptionId": "b", "explanation": "Golgi nhận và xử lí nhiều sản phẩm từ lưới nội chất trước khi phân phối."}, {"id": "biology-10-organelles-q3", "prompt": "Protein tiết bị kẹt do hệ Golgi hoạt động kém. Khâu dễ bị ảnh hưởng là?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Xử lí và phân phối protein"}, {"id": "b", "text": "Nhân đôi mọi neutron"}, {"id": "c", "text": "Tạo ánh sáng cho quang hợp"}], "correctOptionId": "a", "explanation": "Golgi hỗ trợ hoàn thiện, phân loại, đóng gói; rối loạn làm giảm vận chuyển protein đến nơi cần."}]'::jsonb,'["biology-10-organelles"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('biology',10,'intro-2026.1','biology-10-enzymes',14,'LESSON','Enzyme và trung tâm hoạt động','Tế bào, chuyển hóa và sinh sản','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Enzyme là chất xúc tác sinh học, phần lớn có bản chất protein. Enzyme giảm năng lượng hoạt hóa, có tính đặc hiệu và không bị tiêu hao tổng thể sau phản ứng. Hoạt tính phụ thuộc điều kiện như nhiệt độ, pH."]'::jsonb,'["Amylase hỗ trợ phân giải tinh bột nhưng không thay thế mọi enzyme khác. Tăng nhiệt độ quá cao có thể làm enzyme biến tính thay vì luôn làm phản ứng nhanh hơn."]'::jsonb,'[{"id": "biology-10-enzymes-q1", "prompt": "Enzyme làm phản ứng thuận lợi hơn chủ yếu bằng cách?", "difficulty": "EASY", "options": [{"id": "a", "text": "Luôn tăng nhiệt độ đến sôi"}, {"id": "b", "text": "Giảm năng lượng hoạt hóa"}, {"id": "c", "text": "Tự tạo thêm nguyên tử"}], "correctOptionId": "b", "explanation": "Enzyme tạo con đường phản ứng có rào năng lượng thấp hơn, không thay đổi quy luật bảo toàn vật chất."}, {"id": "biology-10-enzymes-q2", "prompt": "Một enzyme thường chỉ phù hợp với một số cơ chất vì?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đặc điểm trung tâm hoạt động phù hợp"}, {"id": "b", "text": "Nó không tương tác với phân tử nào"}, {"id": "c", "text": "Mọi cơ chất đều có hình dạng giống nhau"}], "correctOptionId": "a", "explanation": "Sự phù hợp cấu trúc và tính chất hóa học giúp enzyme nhận diện cơ chất."}, {"id": "biology-10-enzymes-q3", "prompt": "Đun rất nóng làm tốc độ phản ứng do enzyme giảm. Giải thích phù hợp?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Enzyme chắc chắn hoạt động mạnh hơn vô hạn"}, {"id": "b", "text": "Năng lượng hoạt hóa tự bằng 0 mãi mãi"}, {"id": "c", "text": "Enzyme có thể bị biến tính"}], "correctOptionId": "c", "explanation": "Nhiệt quá mức làm thay đổi cấu trúc, trung tâm hoạt động có thể không còn phù hợp cơ chất."}]'::jsonb,'["biology-10-enzymes"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('biology',10,'intro-2026.1','biology-10-atp',15,'LESSON','ATP và sự ghép cặp năng lượng','Tế bào, chuyển hóa và sinh sản','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["ATP là chất trung gian truyền năng lượng phổ biến trong tế bào, gồm adenine, ribose và ba nhóm phosphate. Thủy phân ATP thành ADP và phosphate có thể ghép với quá trình cần năng lượng; ATP được tái tạo liên tục."]'::jsonb,'["Bơm ion chủ động có thể ghép với thủy phân ATP để đưa ion ngược gradient. ATP không thay thế mỡ hay glycogen như kho dự trữ năng lượng dài hạn chính."]'::jsonb,'[{"id": "biology-10-atp-q1", "prompt": "ATP có bao nhiêu nhóm phosphate?", "difficulty": "EASY", "options": [{"id": "a", "text": "3"}, {"id": "b", "text": "1"}, {"id": "c", "text": "2"}], "correctOptionId": "a", "explanation": "Tên adenosine triphosphate thể hiện ba nhóm phosphate."}, {"id": "biology-10-atp-q2", "prompt": "Sản phẩm thường xét khi thủy phân ATP là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "DNA và glucose"}, {"id": "b", "text": "Protein và cellulose"}, {"id": "c", "text": "ADP và phosphate vô cơ"}], "correctOptionId": "c", "explanation": "Phản ứng ATP + nước → ADP + Pi có thể cung cấp năng lượng tự do cho quá trình ghép cặp."}, {"id": "biology-10-atp-q3", "prompt": "Bơm ion vận chuyển ngược gradient cần ATP. ATP chủ yếu đóng vai trò?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Tạo thêm ion từ hư không"}, {"id": "b", "text": "Trung gian ghép năng lượng cho vận chuyển"}, {"id": "c", "text": "Mang nguyên vẹn ion qua màng như túi"}], "correctOptionId": "b", "explanation": "Bơm dùng năng lượng của phản ứng ghép cặp để đổi cấu hình và vận chuyển ion; ATP không tự là chiếc túi chở ion."}]'::jsonb,'["biology-10-atp"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('biology',10,'intro-2026.1','biology-10-cellular-respiration',16,'LESSON','Hô hấp tế bào','Tế bào, chuyển hóa và sinh sản','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Hô hấp tế bào phân giải chất hữu cơ và chuyển một phần năng lượng thành ATP. Trong hô hấp hiếu khí, oxygen là chất nhận electron cuối; đường phân ở tế bào chất, các giai đoạn tiếp theo chủ yếu ở ti thể của tế bào nhân thực."]'::jsonb,'["Tế bào người có thể oxi hóa glucose, tạo CO₂, nước và ATP. Không đồng nhất hô hấp tế bào với động tác hít thở của cả cơ thể."]'::jsonb,'[{"id": "biology-10-cellular-respiration-q1", "prompt": "Vai trò quan trọng của hô hấp tế bào là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Chỉ đưa không khí vào phổi"}, {"id": "b", "text": "Luôn tạo glucose từ CO₂"}, {"id": "c", "text": "Chuyển năng lượng chất hữu cơ thành dạng tế bào sử dụng"}], "correctOptionId": "c", "explanation": "Hô hấp tế bào là chuỗi phản ứng chuyển hóa; hít thở hỗ trợ trao đổi khí ở cấp cơ thể."}, {"id": "biology-10-cellular-respiration-q2", "prompt": "Ở tế bào nhân thực, đường phân diễn ra tại?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Ngoài thành tế bào"}, {"id": "b", "text": "Tế bào chất"}, {"id": "c", "text": "Chỉ trong nhân"}], "correctOptionId": "b", "explanation": "Đường phân diễn ra ở bào tương, không bắt buộc phải có ti thể."}, {"id": "biology-10-cellular-respiration-q3", "prompt": "Thiếu oxygen kéo dài, chuỗi truyền electron hiếu khí bị ảnh hưởng vì?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Thiếu chất nhận electron cuối cùng"}, {"id": "b", "text": "Oxygen là enzyme duy nhất của đường phân"}, {"id": "c", "text": "Mọi tế bào lập tức không còn DNA"}], "correctOptionId": "a", "explanation": "Trong hô hấp hiếu khí, O₂ nhận electron cuối. Thiếu nó làm hạn chế chuỗi truyền electron và tổng hợp ATP theo cơ chế này."}]'::jsonb,'["biology-10-cellular-respiration"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('biology',10,'intro-2026.1','biology-10-photosynthesis',17,'LESSON','Quang hợp ở thực vật','Tế bào, chuyển hóa và sinh sản','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Quang hợp chuyển năng lượng ánh sáng thành năng lượng hóa học, sử dụng CO₂ để tạo chất hữu cơ. Ở thực vật, pha sáng diễn ra ở màng thylakoid; chu trình Calvin diễn ra ở chất nền lục lạp và sử dụng sản phẩm pha sáng."]'::jsonb,'["Oxygen giải phóng trong quang hợp có nguồn từ nước. Cây vẫn hô hấp tế bào cả khi có ánh sáng; quang hợp không thay thế hô hấp."]'::jsonb,'[{"id": "biology-10-photosynthesis-q1", "prompt": "Bào quan quang hợp ở thực vật là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Bộ máy Golgi"}, {"id": "b", "text": "Lục lạp"}, {"id": "c", "text": "Ti thể"}], "correctOptionId": "b", "explanation": "Lục lạp chứa hệ sắc tố và bộ máy quang hợp."}, {"id": "biology-10-photosynthesis-q2", "prompt": "Nguồn carbon để tổng hợp chất hữu cơ trong quang hợp là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "CO₂"}, {"id": "b", "text": "O₂"}, {"id": "c", "text": "N₂ khí quyển trực tiếp ở mọi cây"}], "correctOptionId": "a", "explanation": "CO₂ được cố định vào hợp chất hữu cơ; O₂ không phải nguồn carbon."}, {"id": "biology-10-photosynthesis-q3", "prompt": "Ban ngày, tế bào lá có lục lạp thường thực hiện?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Chỉ quang hợp, hô hấp dừng hoàn toàn"}, {"id": "b", "text": "Chỉ hô hấp, không thể quang hợp"}, {"id": "c", "text": "Cả quang hợp và hô hấp tế bào"}], "correctOptionId": "c", "explanation": "Khi điều kiện phù hợp, quang hợp diễn ra song song với hô hấp tế bào, dù trao đổi khí ròng có thể nghiêng về quang hợp."}]'::jsonb,'["biology-10-photosynthesis"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('biology',10,'intro-2026.1','biology-10-review-3',18,'FIVE_LESSON_REVIEW','Ôn tập 3','Tế bào, chuyển hóa và sinh sản','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "biology-10-organelles-q1", "prompt": "Cấu trúc trực tiếp tổng hợp chuỗi polypeptide là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Bộ máy Golgi"}, {"id": "b", "text": "Thành cellulose"}, {"id": "c", "text": "Ribosome"}], "correctOptionId": "c", "explanation": "Ribosome thực hiện dịch mã để tạo chuỗi polypeptide."}, {"id": "biology-10-organelles-q2", "prompt": "Bào quan nổi bật trong biến đổi, phân loại và đóng gói nhiều sản phẩm là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Thành tế bào"}, {"id": "b", "text": "Bộ máy Golgi"}, {"id": "c", "text": "Nucleoid của vi khuẩn"}], "correctOptionId": "b", "explanation": "Golgi nhận và xử lí nhiều sản phẩm từ lưới nội chất trước khi phân phối."}, {"id": "biology-10-enzymes-q1", "prompt": "Enzyme làm phản ứng thuận lợi hơn chủ yếu bằng cách?", "difficulty": "EASY", "options": [{"id": "a", "text": "Luôn tăng nhiệt độ đến sôi"}, {"id": "b", "text": "Giảm năng lượng hoạt hóa"}, {"id": "c", "text": "Tự tạo thêm nguyên tử"}], "correctOptionId": "b", "explanation": "Enzyme tạo con đường phản ứng có rào năng lượng thấp hơn, không thay đổi quy luật bảo toàn vật chất."}, {"id": "biology-10-enzymes-q2", "prompt": "Một enzyme thường chỉ phù hợp với một số cơ chất vì?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đặc điểm trung tâm hoạt động phù hợp"}, {"id": "b", "text": "Nó không tương tác với phân tử nào"}, {"id": "c", "text": "Mọi cơ chất đều có hình dạng giống nhau"}], "correctOptionId": "a", "explanation": "Sự phù hợp cấu trúc và tính chất hóa học giúp enzyme nhận diện cơ chất."}, {"id": "biology-10-atp-q1", "prompt": "ATP có bao nhiêu nhóm phosphate?", "difficulty": "EASY", "options": [{"id": "a", "text": "3"}, {"id": "b", "text": "1"}, {"id": "c", "text": "2"}], "correctOptionId": "a", "explanation": "Tên adenosine triphosphate thể hiện ba nhóm phosphate."}, {"id": "biology-10-atp-q2", "prompt": "Sản phẩm thường xét khi thủy phân ATP là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "DNA và glucose"}, {"id": "b", "text": "Protein và cellulose"}, {"id": "c", "text": "ADP và phosphate vô cơ"}], "correctOptionId": "c", "explanation": "Phản ứng ATP + nước → ADP + Pi có thể cung cấp năng lượng tự do cho quá trình ghép cặp."}, {"id": "biology-10-cellular-respiration-q1", "prompt": "Vai trò quan trọng của hô hấp tế bào là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Chỉ đưa không khí vào phổi"}, {"id": "b", "text": "Luôn tạo glucose từ CO₂"}, {"id": "c", "text": "Chuyển năng lượng chất hữu cơ thành dạng tế bào sử dụng"}], "correctOptionId": "c", "explanation": "Hô hấp tế bào là chuỗi phản ứng chuyển hóa; hít thở hỗ trợ trao đổi khí ở cấp cơ thể."}, {"id": "biology-10-cellular-respiration-q2", "prompt": "Ở tế bào nhân thực, đường phân diễn ra tại?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Ngoài thành tế bào"}, {"id": "b", "text": "Tế bào chất"}, {"id": "c", "text": "Chỉ trong nhân"}], "correctOptionId": "b", "explanation": "Đường phân diễn ra ở bào tương, không bắt buộc phải có ti thể."}, {"id": "biology-10-photosynthesis-q1", "prompt": "Bào quan quang hợp ở thực vật là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Bộ máy Golgi"}, {"id": "b", "text": "Lục lạp"}, {"id": "c", "text": "Ti thể"}], "correctOptionId": "b", "explanation": "Lục lạp chứa hệ sắc tố và bộ máy quang hợp."}, {"id": "biology-10-photosynthesis-q2", "prompt": "Nguồn carbon để tổng hợp chất hữu cơ trong quang hợp là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "CO₂"}, {"id": "b", "text": "O₂"}, {"id": "c", "text": "N₂ khí quyển trực tiếp ở mọi cây"}], "correctOptionId": "a", "explanation": "CO₂ được cố định vào hợp chất hữu cơ; O₂ không phải nguồn carbon."}]'::jsonb,'["biology-10-organelles", "biology-10-enzymes", "biology-10-atp", "biology-10-cellular-respiration", "biology-10-photosynthesis"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('biology',10,'intro-2026.1','biology-10-cell-cycle',19,'LESSON','Chu kì tế bào','Tế bào, chuyển hóa và sinh sản','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Chu kì tế bào gồm kì trung gian và giai đoạn phân bào. Trong kì trung gian, pha S nhân đôi DNA; tế bào còn tăng trưởng và chuẩn bị. Các điểm kiểm soát giúp hạn chế truyền sai hỏng sang tế bào con."]'::jsonb,'["Trước nguyên phân, một nhiễm sắc thể được nhân đôi thành hai chromatid chị em gắn nhau. Lượng DNA tăng nhưng số nhiễm sắc thể tính theo tâm động chưa tăng ngay ở pha S."]'::jsonb,'[{"id": "biology-10-cell-cycle-q1", "prompt": "DNA được nhân đôi chủ yếu ở pha nào của kì trung gian?", "difficulty": "EASY", "options": [{"id": "a", "text": "Pha S"}, {"id": "b", "text": "Pha G₁"}, {"id": "c", "text": "Pha G₂"}], "correctOptionId": "a", "explanation": "Pha S là giai đoạn tổng hợp, nhân đôi DNA trước phân bào."}, {"id": "biology-10-cell-cycle-q2", "prompt": "Hai chromatid chị em hình thành sau quá trình?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tế bào mất toàn bộ DNA"}, {"id": "b", "text": "Hô hấp tế bào trực tiếp"}, {"id": "c", "text": "Nhân đôi DNA"}], "correctOptionId": "c", "explanation": "Nhân đôi tạo hai bản sao DNA gắn với nhau trong nhiễm sắc thể kép."}, {"id": "biology-10-cell-cycle-q3", "prompt": "Điểm kiểm soát phát hiện DNA hỏng trước phân chia giúp?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Thay mọi gene bằng protein"}, {"id": "b", "text": "Hạn chế truyền sai hỏng cho tế bào con"}, {"id": "c", "text": "Đảm bảo mọi tế bào phân chia nhanh vô hạn"}], "correctOptionId": "b", "explanation": "Dừng chu kì có thể tạo thời gian sửa chữa hoặc ngăn tế bào sai hỏng tiếp tục phân chia."}]'::jsonb,'["biology-10-cell-cycle"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('biology',10,'intro-2026.1','biology-10-mitosis',20,'LESSON','Nguyên phân và sự phân li','Tế bào, chuyển hóa và sinh sản','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Nguyên phân phân li các chromatid chị em về hai cực sau khi DNA đã nhân đôi. Nếu diễn ra bình thường và chia tế bào chất hoàn tất, một tế bào tạo hai tế bào con có bộ nhiễm sắc thể như tế bào mẹ ban đầu."]'::jsonb,'["Tế bào cơ thể có 2n = 4 trải qua một lần nguyên phân bình thường tạo hai tế bào con, mỗi tế bào 2n = 4."]'::jsonb,'[{"id": "biology-10-mitosis-q1", "prompt": "Sau một lần nguyên phân và chia tế bào chất bình thường, số tế bào con là?", "difficulty": "EASY", "options": [{"id": "a", "text": "4"}, {"id": "b", "text": "8"}, {"id": "c", "text": "2"}], "correctOptionId": "c", "explanation": "Một tế bào phân chia thành hai tế bào con."}, {"id": "biology-10-mitosis-q2", "prompt": "Tế bào mẹ 2n = 8 nguyên phân bình thường. Mỗi tế bào con có?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "16 nhiễm sắc thể ổn định"}, {"id": "b", "text": "8 nhiễm sắc thể"}, {"id": "c", "text": "4 nhiễm sắc thể"}], "correctOptionId": "b", "explanation": "Nguyên phân bảo toàn số nhiễm sắc thể của tế bào mẹ ở mỗi tế bào con."}, {"id": "biology-10-mitosis-q3", "prompt": "Một tế bào nguyên phân liên tiếp hai lần, mọi tế bào con đều tiếp tục chia bình thường. Có bao nhiêu tế bào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "4"}, {"id": "b", "text": "2"}, {"id": "c", "text": "8"}], "correctOptionId": "a", "explanation": "Mỗi lần số tế bào gấp đôi: 1 → 2 → 4. Không nhầm số lần phân chia với số tế bào."}]'::jsonb,'["biology-10-mitosis"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('biology',10,'intro-2026.1','biology-10-meiosis',21,'LESSON','Giảm phân và bộ nhiễm sắc thể','Tế bào, chuyển hóa và sinh sản','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Giảm phân gồm một lần nhân đôi DNA và hai lần phân bào, tạo tế bào có số nhiễm sắc thể giảm một nửa. Cặp nhiễm sắc thể tương đồng phân li ở giảm phân I; chromatid chị em thường phân li ở giảm phân II."]'::jsonb,'["Một tế bào mẹ 2n = 6 giảm phân bình thường tạo các sản phẩm mang n = 3. Tổ hợp và trao đổi chéo góp phần tạo biến dị di truyền."]'::jsonb,'[{"id": "biology-10-meiosis-q1", "prompt": "Trước hai lần phân bào giảm phân, DNA nhân đôi mấy lần?", "difficulty": "EASY", "options": [{"id": "a", "text": "Không nhân đôi"}, {"id": "b", "text": "1"}, {"id": "c", "text": "2"}], "correctOptionId": "b", "explanation": "DNA nhân đôi trước giảm phân I; không có lần nhân đôi DNA xen giữa giảm phân I và II."}, {"id": "biology-10-meiosis-q2", "prompt": "Tế bào mẹ 2n = 10 giảm phân bình thường. Sản phẩm đơn bội có?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "5 nhiễm sắc thể"}, {"id": "b", "text": "10 nhiễm sắc thể"}, {"id": "c", "text": "20 nhiễm sắc thể"}], "correctOptionId": "a", "explanation": "Bộ đơn bội n bằng một nửa 2n, nên n = 5."}, {"id": "biology-10-meiosis-q3", "prompt": "Điểm phân biệt quan trọng ở giảm phân I là?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "DNA nhân đôi thêm ngay khi hai cực tách"}, {"id": "b", "text": "Mọi tế bào con giữ nguyên bộ lưỡng bội"}, {"id": "c", "text": "Các nhiễm sắc thể tương đồng phân li"}], "correctOptionId": "c", "explanation": "Sự phân li của cặp tương đồng làm giảm số bộ nhiễm sắc thể; chromatid chị em chủ yếu tách ở lần II."}]'::jsonb,'["biology-10-meiosis"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('biology',10,'intro-2026.1','biology-10-microbial-growth',22,'LESSON','Sinh trưởng của quần thể vi khuẩn','Tế bào, chuyển hóa và sinh sản','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Nhiều vi khuẩn sinh sản bằng phân đôi. Trong pha lũy thừa với điều kiện phù hợp và thời gian thế hệ g không đổi, N = N₀ × 2ᵏ, k = t/g. Công thức không áp dụng vô hạn khi dinh dưỡng cạn hoặc chất thải tích tụ."]'::jsonb,'["Ban đầu 100 tế bào, sau ba thế hệ phân đôi lý tưởng: N = 100 × 2³ = 800 tế bào."]'::jsonb,'[{"id": "biology-10-microbial-growth-q1", "prompt": "Sau một lần phân đôi bình thường, một vi khuẩn tạo?", "difficulty": "EASY", "options": [{"id": "a", "text": "2 tế bào"}, {"id": "b", "text": "4 tế bào ngay lập tức"}, {"id": "c", "text": "1 virus"}], "correctOptionId": "a", "explanation": "Một tế bào mẹ phân chia thành hai tế bào con."}, {"id": "biology-10-microbial-growth-q2", "prompt": "Ban đầu 20 tế bào, sau hai thế hệ phân đôi lý tưởng có?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "40"}, {"id": "b", "text": "60"}, {"id": "c", "text": "80"}], "correctOptionId": "c", "explanation": "N = 20 × 2² = 80 tế bào."}, {"id": "biology-10-microbial-growth-q3", "prompt": "Vì sao không dùng N = N₀ × 2ᵏ mãi trong bình nuôi kín?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Số tế bào luôn tự giữ ở 2"}, {"id": "b", "text": "Dinh dưỡng và môi trường trở nên hạn chế"}, {"id": "c", "text": "Vi khuẩn không bao giờ cần nguyên liệu"}], "correctOptionId": "b", "explanation": "Mô hình tăng lũy thừa cần điều kiện phù hợp; cạn dinh dưỡng và tích tụ chất thải làm thay đổi tốc độ sinh trưởng."}]'::jsonb,'["biology-10-microbial-growth"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('biology',10,'intro-2026.1','biology-10-viruses',23,'LESSON','Virus và tế bào chủ','Tế bào, chuyển hóa và sinh sản','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Virus có vật chất di truyền DNA hoặc RNA và vỏ protein; một số có vỏ ngoài. Virus không có hệ tế bào và chuyển hóa độc lập, phải dựa vào tế bào chủ để nhân lên. Kháng sinh kháng khuẩn không trực tiếp trị virus."]'::jsonb,'["Virus cúm nhân lên trong tế bào chủ. Dùng kháng sinh cho nhiễm virus đơn thuần không loại được virus; việc điều trị cần hướng dẫn chuyên môn, không tự dùng thuốc."]'::jsonb,'[{"id": "biology-10-viruses-q1", "prompt": "Virus cần yếu tố nào để nhân lên?", "difficulty": "EASY", "options": [{"id": "a", "text": "Chỉ nước tinh khiết"}, {"id": "b", "text": "Chỉ đường trong bình vô trùng"}, {"id": "c", "text": "Tế bào chủ phù hợp"}], "correctOptionId": "c", "explanation": "Virus cần bộ máy và nguyên liệu của tế bào chủ vì không có chuyển hóa độc lập đầy đủ."}, {"id": "biology-10-viruses-q2", "prompt": "Thành phần có ở virus điển hình là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Ribosome tự hoạt động độc lập"}, {"id": "b", "text": "Vật chất di truyền và vỏ protein"}, {"id": "c", "text": "Nhân có màng và ti thể"}], "correctOptionId": "b", "explanation": "Virus không có cấu trúc tế bào; hệ gene và capsid là hai thành phần cơ bản."}, {"id": "biology-10-viruses-q3", "prompt": "Vì sao kháng sinh kháng khuẩn không trực tiếp diệt virus?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Virus không có nhiều đích tác động đặc trưng của vi khuẩn"}, {"id": "b", "text": "Virus là một vi khuẩn lớn hơn"}, {"id": "c", "text": "Kháng sinh luôn làm virus biến thành tế bào người"}], "correctOptionId": "a", "explanation": "Nhiều kháng sinh nhắm thành tế bào hoặc ribosome vi khuẩn; virus không có các cấu trúc đó. Không suy ra cách điều trị cá nhân từ bài học này."}]'::jsonb,'["biology-10-viruses"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('biology',10,'intro-2026.1','biology-10-review-4',24,'FIVE_LESSON_REVIEW','Ôn tập 4','Tế bào, chuyển hóa và sinh sản','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "biology-10-cell-cycle-q1", "prompt": "DNA được nhân đôi chủ yếu ở pha nào của kì trung gian?", "difficulty": "EASY", "options": [{"id": "a", "text": "Pha S"}, {"id": "b", "text": "Pha G₁"}, {"id": "c", "text": "Pha G₂"}], "correctOptionId": "a", "explanation": "Pha S là giai đoạn tổng hợp, nhân đôi DNA trước phân bào."}, {"id": "biology-10-cell-cycle-q2", "prompt": "Hai chromatid chị em hình thành sau quá trình?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tế bào mất toàn bộ DNA"}, {"id": "b", "text": "Hô hấp tế bào trực tiếp"}, {"id": "c", "text": "Nhân đôi DNA"}], "correctOptionId": "c", "explanation": "Nhân đôi tạo hai bản sao DNA gắn với nhau trong nhiễm sắc thể kép."}, {"id": "biology-10-mitosis-q1", "prompt": "Sau một lần nguyên phân và chia tế bào chất bình thường, số tế bào con là?", "difficulty": "EASY", "options": [{"id": "a", "text": "4"}, {"id": "b", "text": "8"}, {"id": "c", "text": "2"}], "correctOptionId": "c", "explanation": "Một tế bào phân chia thành hai tế bào con."}, {"id": "biology-10-mitosis-q2", "prompt": "Tế bào mẹ 2n = 8 nguyên phân bình thường. Mỗi tế bào con có?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "16 nhiễm sắc thể ổn định"}, {"id": "b", "text": "8 nhiễm sắc thể"}, {"id": "c", "text": "4 nhiễm sắc thể"}], "correctOptionId": "b", "explanation": "Nguyên phân bảo toàn số nhiễm sắc thể của tế bào mẹ ở mỗi tế bào con."}, {"id": "biology-10-meiosis-q1", "prompt": "Trước hai lần phân bào giảm phân, DNA nhân đôi mấy lần?", "difficulty": "EASY", "options": [{"id": "a", "text": "Không nhân đôi"}, {"id": "b", "text": "1"}, {"id": "c", "text": "2"}], "correctOptionId": "b", "explanation": "DNA nhân đôi trước giảm phân I; không có lần nhân đôi DNA xen giữa giảm phân I và II."}, {"id": "biology-10-meiosis-q2", "prompt": "Tế bào mẹ 2n = 10 giảm phân bình thường. Sản phẩm đơn bội có?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "5 nhiễm sắc thể"}, {"id": "b", "text": "10 nhiễm sắc thể"}, {"id": "c", "text": "20 nhiễm sắc thể"}], "correctOptionId": "a", "explanation": "Bộ đơn bội n bằng một nửa 2n, nên n = 5."}, {"id": "biology-10-microbial-growth-q1", "prompt": "Sau một lần phân đôi bình thường, một vi khuẩn tạo?", "difficulty": "EASY", "options": [{"id": "a", "text": "2 tế bào"}, {"id": "b", "text": "4 tế bào ngay lập tức"}, {"id": "c", "text": "1 virus"}], "correctOptionId": "a", "explanation": "Một tế bào mẹ phân chia thành hai tế bào con."}, {"id": "biology-10-microbial-growth-q2", "prompt": "Ban đầu 20 tế bào, sau hai thế hệ phân đôi lý tưởng có?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "40"}, {"id": "b", "text": "60"}, {"id": "c", "text": "80"}], "correctOptionId": "c", "explanation": "N = 20 × 2² = 80 tế bào."}, {"id": "biology-10-viruses-q1", "prompt": "Virus cần yếu tố nào để nhân lên?", "difficulty": "EASY", "options": [{"id": "a", "text": "Chỉ nước tinh khiết"}, {"id": "b", "text": "Chỉ đường trong bình vô trùng"}, {"id": "c", "text": "Tế bào chủ phù hợp"}], "correctOptionId": "c", "explanation": "Virus cần bộ máy và nguyên liệu của tế bào chủ vì không có chuyển hóa độc lập đầy đủ."}, {"id": "biology-10-viruses-q2", "prompt": "Thành phần có ở virus điển hình là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Ribosome tự hoạt động độc lập"}, {"id": "b", "text": "Vật chất di truyền và vỏ protein"}, {"id": "c", "text": "Nhân có màng và ti thể"}], "correctOptionId": "b", "explanation": "Virus không có cấu trúc tế bào; hệ gene và capsid là hai thành phần cơ bản."}]'::jsonb,'["biology-10-cell-cycle", "biology-10-mitosis", "biology-10-meiosis", "biology-10-microbial-growth", "biology-10-viruses"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('biology',10,'intro-2026.1','placement',0,'PLACEMENT','Khảo sát đầu vào','Tế bào, chuyển hóa và sinh sản','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "biology-10-cell-basics-q1", "prompt": "Đơn vị cấu trúc và chức năng cơ bản của cơ thể sống là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tế bào"}, {"id": "b", "text": "Nguyên tử riêng lẻ"}, {"id": "c", "text": "Cơ quan"}], "correctOptionId": "a", "explanation": "Các hoạt động sống cơ bản diễn ra ở cấp tế bào; cơ quan được cấu tạo từ nhiều tế bào."}, {"id": "biology-10-cell-basics-q2", "prompt": "Sinh vật đơn bào có cơ thể gồm?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đúng hai tế bào"}, {"id": "b", "text": "Không có tế bào"}, {"id": "c", "text": "Một tế bào"}], "correctOptionId": "c", "explanation": "Đơn bào nghĩa là cơ thể gồm một tế bào thực hiện các hoạt động sống."}, {"id": "biology-10-membrane-q1", "prompt": "Thành phần nền tảng của màng sinh chất là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Một lớp cellulose duy nhất"}, {"id": "b", "text": "Chỉ DNA"}, {"id": "c", "text": "Lớp kép phospholipid và protein"}], "correctOptionId": "c", "explanation": "Lớp kép phospholipid tạo nền màng, protein tham gia vận chuyển và nhiều chức năng khác."}, {"id": "biology-10-membrane-q2", "prompt": "Tính thấm chọn lọc nghĩa là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Không chất nào đi qua"}, {"id": "b", "text": "Các chất đi qua màng với khả năng khác nhau"}, {"id": "c", "text": "Mọi chất đi qua như nhau"}], "correctOptionId": "b", "explanation": "Màng không phải hàng rào kín tuyệt đối; cấu trúc màng và protein quyết định khả năng đi qua của từng chất."}, {"id": "biology-10-prokaryote-q1", "prompt": "Đặc điểm nổi bật của tế bào nhân sơ là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Không có màng sinh chất"}, {"id": "b", "text": "Không có nhân được màng nhân bao bọc"}, {"id": "c", "text": "Không có DNA"}], "correctOptionId": "b", "explanation": "Nhân sơ có DNA nhưng DNA không nằm trong nhân có màng bao."}, {"id": "biology-10-prokaryote-q2", "prompt": "Cấu trúc nào có ở tế bào vi khuẩn điển hình?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Ribosome"}, {"id": "b", "text": "Lục lạp có màng kép"}, {"id": "c", "text": "Nhân có màng bao"}], "correctOptionId": "a", "explanation": "Ribosome tham gia tổng hợp protein và có ở cả tế bào nhân sơ lẫn nhân thực."}, {"id": "biology-10-eukaryote-q1", "prompt": "Tế bào nhân thực điển hình có đặc điểm nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Có nhân được màng bao bọc"}, {"id": "b", "text": "Luôn không có DNA"}, {"id": "c", "text": "Không có ribosome"}], "correctOptionId": "a", "explanation": "Nhân có màng bao là đặc điểm phân biệt cơ bản của tế bào nhân thực."}, {"id": "biology-10-eukaryote-q2", "prompt": "Cấu trúc trực tiếp tổng hợp protein là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Màng nhân"}, {"id": "b", "text": "Không bào"}, {"id": "c", "text": "Ribosome"}], "correctOptionId": "c", "explanation": "Ribosome liên kết các amino acid theo thông tin được truyền từ gene."}, {"id": "biology-10-transport-q1", "prompt": "Vận chuyển thụ động thường có đặc điểm nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Luôn tiêu thụ ATP trực tiếp"}, {"id": "b", "text": "Luôn ngược gradient nồng độ"}, {"id": "c", "text": "Không cần cung cấp năng lượng trực tiếp"}], "correctOptionId": "c", "explanation": "Khuếch tán sử dụng chênh lệch nồng độ, không cần tế bào cung cấp năng lượng trực tiếp."}, {"id": "biology-10-transport-q2", "prompt": "Thẩm thấu là sự di chuyển của chất nào qua màng thấm chọn lọc?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chỉ DNA"}, {"id": "b", "text": "Nước"}, {"id": "c", "text": "Chỉ protein"}], "correctOptionId": "b", "explanation": "Thuật ngữ thẩm thấu mô tả chuyển động của nước qua màng thấm chọn lọc."}]'::jsonb,'[]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('chemistry',10,'intro-2026.1','chemistry-10-particles',1,'LESSON','Các hạt trong nguyên tử','Từ nguyên tử đến phản ứng hóa học','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Nguyên tử gồm hạt nhân và các electron. Proton mang điện dương, electron mang điện âm; neutron không mang điện."]'::jsonb,'["Nguyên tử carbon-12 có 6 proton, 6 neutron và 6 electron khi trung hòa."]'::jsonb,'[{"id": "chemistry-10-particles-q1", "prompt": "Hạt nào mang điện tích âm?", "difficulty": "EASY", "options": [{"id": "a", "text": "Electron"}, {"id": "b", "text": "Proton"}, {"id": "c", "text": "Neutron"}], "correctOptionId": "a", "explanation": "Electron mang điện tích −1 theo đơn vị điện tích nguyên tố."}, {"id": "chemistry-10-particles-q2", "prompt": "Hai loại hạt chủ yếu tạo nên hạt nhân nguyên tử là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Electron và proton"}, {"id": "b", "text": "Electron và neutron"}, {"id": "c", "text": "Proton và neutron"}], "correctOptionId": "c", "explanation": "Hạt nhân gồm proton và neutron; electron phân bố ngoài hạt nhân."}, {"id": "chemistry-10-particles-q3", "prompt": "Một nguyên tử trung hòa có 8 proton. Nó có bao nhiêu electron?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "0"}, {"id": "b", "text": "8"}, {"id": "c", "text": "16"}], "correctOptionId": "b", "explanation": "Trung hòa điện nghĩa tổng điện tích dương và âm cân bằng. Vì vậy số electron bằng số proton, bằng 8."}]'::jsonb,'["chemistry-10-particles"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('chemistry',10,'intro-2026.1','chemistry-10-atomic-number',2,'LESSON','Số hiệu nguyên tử','Từ nguyên tử đến phản ứng hóa học','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Số hiệu nguyên tử Z bằng số proton. Các nguyên tử thuộc cùng một nguyên tố có cùng Z."]'::jsonb,'["Mọi nguyên tử oxygen có Z = 8, tức đều có 8 proton, dù số neutron có thể khác nhau."]'::jsonb,'[{"id": "chemistry-10-atomic-number-q1", "prompt": "Số hiệu nguyên tử Z bằng số hạt nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Neutron"}, {"id": "b", "text": "Proton cộng neutron"}, {"id": "c", "text": "Proton"}], "correctOptionId": "c", "explanation": "Z được định nghĩa là số proton trong hạt nhân."}, {"id": "chemistry-10-atomic-number-q2", "prompt": "Nguyên tử có 11 proton thuộc nguyên tố có Z bằng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Không xác định"}, {"id": "b", "text": "11"}, {"id": "c", "text": "22"}], "correctOptionId": "b", "explanation": "Z bằng số proton nên Z = 11."}, {"id": "chemistry-10-atomic-number-q3", "prompt": "Hai nguyên tử có cùng số proton nhưng khác số neutron có cùng nguyên tố không?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Có"}, {"id": "b", "text": "Không"}, {"id": "c", "text": "Chỉ khi cùng số khối"}], "correctOptionId": "a", "explanation": "Số proton quyết định nguyên tố. Khác số neutron không làm đổi nguyên tố."}]'::jsonb,'["chemistry-10-atomic-number"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('chemistry',10,'intro-2026.1','chemistry-10-mass-number',3,'LESSON','Số khối','Từ nguyên tử đến phản ứng hóa học','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Số khối A = Z + N, trong đó N là số neutron. A là số đếm nucleon, không phải khối lượng nguyên tử đo bằng gam."]'::jsonb,'["Natri-23 có Z = 11 nên N = 23 − 11 = 12 neutron."]'::jsonb,'[{"id": "chemistry-10-mass-number-q1", "prompt": "Công thức liên hệ số khối A, proton Z và neutron N là?", "difficulty": "EASY", "options": [{"id": "a", "text": "A = số electron"}, {"id": "b", "text": "A = Z + N"}, {"id": "c", "text": "A = Z − N"}], "correctOptionId": "b", "explanation": "Số khối là tổng số proton và neutron trong hạt nhân."}, {"id": "chemistry-10-mass-number-q2", "prompt": "Nguyên tử có 6 proton và 7 neutron có số khối là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "13"}, {"id": "b", "text": "1"}, {"id": "c", "text": "6"}], "correctOptionId": "a", "explanation": "A = 6 + 7 = 13."}, {"id": "chemistry-10-mass-number-q3", "prompt": "Hạt nhân có A = 35 và Z = 17. Số neutron là?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "52"}, {"id": "b", "text": "17"}, {"id": "c", "text": "18"}], "correctOptionId": "c", "explanation": "N = A − Z = 35 − 17 = 18."}]'::jsonb,'["chemistry-10-mass-number"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('chemistry',10,'intro-2026.1','chemistry-10-isotopes',4,'LESSON','Đồng vị','Từ nguyên tử đến phản ứng hóa học','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Đồng vị của cùng nguyên tố có cùng số proton nhưng khác số neutron, nên thường khác số khối."]'::jsonb,'["Carbon-12 và carbon-14 đều có 6 proton; chúng lần lượt có 6 và 8 neutron."]'::jsonb,'[{"id": "chemistry-10-isotopes-q1", "prompt": "Các đồng vị của cùng nguyên tố luôn giống nhau về?", "difficulty": "EASY", "options": [{"id": "a", "text": "Số proton"}, {"id": "b", "text": "Số neutron"}, {"id": "c", "text": "Số khối"}], "correctOptionId": "a", "explanation": "Cùng nguyên tố nghĩa cùng Z, do đó cùng số proton."}, {"id": "chemistry-10-isotopes-q2", "prompt": "Carbon-14 có 6 proton. Số neutron là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "6"}, {"id": "b", "text": "14"}, {"id": "c", "text": "8"}], "correctOptionId": "c", "explanation": "N = 14 − 6 = 8."}, {"id": "chemistry-10-isotopes-q3", "prompt": "Hai nguyên tử có (Z, A) là (8, 16) và (8, 18). Chúng là?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Cùng số neutron"}, {"id": "b", "text": "Hai đồng vị của oxygen"}, {"id": "c", "text": "Hai nguyên tố khác nhau"}], "correctOptionId": "b", "explanation": "Cả hai có Z = 8 nhưng A khác nhau, nên là đồng vị; số neutron lần lượt là 8 và 10."}]'::jsonb,'["chemistry-10-isotopes"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('chemistry',10,'intro-2026.1','chemistry-10-ions',5,'LESSON','Nguyên tử và ion','Từ nguyên tử đến phản ứng hóa học','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Khi nhường hoặc nhận electron, nguyên tử trở thành ion. Nhường electron tạo ion dương; nhận electron tạo ion âm. Hạt nhân không đổi trong quá trình này."]'::jsonb,'["Na có 11 proton. Khi nhường 1 electron, Na⁺ còn 10 electron và vẫn có 11 proton."]'::jsonb,'[{"id": "chemistry-10-ions-q1", "prompt": "Nguyên tử nhường một electron thường tạo thành?", "difficulty": "EASY", "options": [{"id": "a", "text": "Ion âm"}, {"id": "b", "text": "Nguyên tố mới"}, {"id": "c", "text": "Ion dương"}], "correctOptionId": "c", "explanation": "Mất electron âm khiến tổng điện tích trở nên dương; số proton không đổi."}, {"id": "chemistry-10-ions-q2", "prompt": "Nguyên tử có 17 proton nhận thêm 1 electron từ trạng thái trung hòa. Ion có bao nhiêu electron?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "17"}, {"id": "b", "text": "18"}, {"id": "c", "text": "16"}], "correctOptionId": "b", "explanation": "Ban đầu có 17 electron; nhận thêm 1 thành 18 electron."}, {"id": "chemistry-10-ions-q3", "prompt": "Ion Mg²⁺ có Z = 12. Số proton và electron lần lượt là?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "12 và 10"}, {"id": "b", "text": "10 và 12"}, {"id": "c", "text": "12 và 14"}], "correctOptionId": "a", "explanation": "Z = 12 nên có 12 proton. Điện tích 2+ do mất 2 electron, còn 10 electron."}]'::jsonb,'["chemistry-10-ions"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('chemistry',10,'intro-2026.1','chemistry-10-review-1',6,'FIVE_LESSON_REVIEW','Ôn tập 1','Từ nguyên tử đến phản ứng hóa học','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "chemistry-10-particles-q1", "prompt": "Hạt nào mang điện tích âm?", "difficulty": "EASY", "options": [{"id": "a", "text": "Electron"}, {"id": "b", "text": "Proton"}, {"id": "c", "text": "Neutron"}], "correctOptionId": "a", "explanation": "Electron mang điện tích −1 theo đơn vị điện tích nguyên tố."}, {"id": "chemistry-10-particles-q2", "prompt": "Hai loại hạt chủ yếu tạo nên hạt nhân nguyên tử là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Electron và proton"}, {"id": "b", "text": "Electron và neutron"}, {"id": "c", "text": "Proton và neutron"}], "correctOptionId": "c", "explanation": "Hạt nhân gồm proton và neutron; electron phân bố ngoài hạt nhân."}, {"id": "chemistry-10-atomic-number-q1", "prompt": "Số hiệu nguyên tử Z bằng số hạt nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Neutron"}, {"id": "b", "text": "Proton cộng neutron"}, {"id": "c", "text": "Proton"}], "correctOptionId": "c", "explanation": "Z được định nghĩa là số proton trong hạt nhân."}, {"id": "chemistry-10-atomic-number-q2", "prompt": "Nguyên tử có 11 proton thuộc nguyên tố có Z bằng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Không xác định"}, {"id": "b", "text": "11"}, {"id": "c", "text": "22"}], "correctOptionId": "b", "explanation": "Z bằng số proton nên Z = 11."}, {"id": "chemistry-10-mass-number-q1", "prompt": "Công thức liên hệ số khối A, proton Z và neutron N là?", "difficulty": "EASY", "options": [{"id": "a", "text": "A = số electron"}, {"id": "b", "text": "A = Z + N"}, {"id": "c", "text": "A = Z − N"}], "correctOptionId": "b", "explanation": "Số khối là tổng số proton và neutron trong hạt nhân."}, {"id": "chemistry-10-mass-number-q2", "prompt": "Nguyên tử có 6 proton và 7 neutron có số khối là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "13"}, {"id": "b", "text": "1"}, {"id": "c", "text": "6"}], "correctOptionId": "a", "explanation": "A = 6 + 7 = 13."}, {"id": "chemistry-10-isotopes-q1", "prompt": "Các đồng vị của cùng nguyên tố luôn giống nhau về?", "difficulty": "EASY", "options": [{"id": "a", "text": "Số proton"}, {"id": "b", "text": "Số neutron"}, {"id": "c", "text": "Số khối"}], "correctOptionId": "a", "explanation": "Cùng nguyên tố nghĩa cùng Z, do đó cùng số proton."}, {"id": "chemistry-10-isotopes-q2", "prompt": "Carbon-14 có 6 proton. Số neutron là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "6"}, {"id": "b", "text": "14"}, {"id": "c", "text": "8"}], "correctOptionId": "c", "explanation": "N = 14 − 6 = 8."}, {"id": "chemistry-10-ions-q1", "prompt": "Nguyên tử nhường một electron thường tạo thành?", "difficulty": "EASY", "options": [{"id": "a", "text": "Ion âm"}, {"id": "b", "text": "Nguyên tố mới"}, {"id": "c", "text": "Ion dương"}], "correctOptionId": "c", "explanation": "Mất electron âm khiến tổng điện tích trở nên dương; số proton không đổi."}, {"id": "chemistry-10-ions-q2", "prompt": "Nguyên tử có 17 proton nhận thêm 1 electron từ trạng thái trung hòa. Ion có bao nhiêu electron?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "17"}, {"id": "b", "text": "18"}, {"id": "c", "text": "16"}], "correctOptionId": "b", "explanation": "Ban đầu có 17 electron; nhận thêm 1 thành 18 electron."}]'::jsonb,'["chemistry-10-particles", "chemistry-10-atomic-number", "chemistry-10-mass-number", "chemistry-10-isotopes", "chemistry-10-ions"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('chemistry',10,'intro-2026.1','chemistry-10-electron-shells',7,'LESSON','Lớp và phân lớp electron','Từ nguyên tử đến phản ứng hóa học','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Electron trong nguyên tử được mô tả theo lớp và phân lớp năng lượng. Lớp n có tối đa 2n² electron; các phân lớp s, p, d, f chứa tối đa 2, 6, 10, 14 electron. Sức chứa tối đa không đồng nghĩa lớp đã được điền đầy."]'::jsonb,'["Lớp n = 2 có phân lớp 2s và 2p, tổng sức chứa tối đa 2 + 6 = 8 electron."]'::jsonb,'[{"id": "chemistry-10-electron-shells-q1", "prompt": "Phân lớp s chứa tối đa bao nhiêu electron?", "difficulty": "EASY", "options": [{"id": "a", "text": "8"}, {"id": "b", "text": "2"}, {"id": "c", "text": "6"}], "correctOptionId": "b", "explanation": "Phân lớp s có một orbital; mỗi orbital chứa tối đa hai electron."}, {"id": "chemistry-10-electron-shells-q2", "prompt": "Lớp n = 2 chứa tối đa bao nhiêu electron?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "8"}, {"id": "b", "text": "4"}, {"id": "c", "text": "18"}], "correctOptionId": "a", "explanation": "2n² = 2 × 2² = 8 electron."}, {"id": "chemistry-10-electron-shells-q3", "prompt": "Phân lớp 2p đang có 4 electron. Nó nhận thêm tối đa bao nhiêu để đầy?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "4"}, {"id": "b", "text": "6"}, {"id": "c", "text": "2"}], "correctOptionId": "c", "explanation": "Phân lớp p chứa tối đa 6; còn 6 − 4 = 2 chỗ electron."}]'::jsonb,'["chemistry-10-electron-shells"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('chemistry',10,'intro-2026.1','chemistry-10-electron-configuration',8,'LESSON','Viết cấu hình electron đơn giản','Từ nguyên tử đến phản ứng hóa học','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Ở trạng thái cơ bản, electron điền vào các mức năng lượng thấp trước. Với 18 nguyên tố đầu có thứ tự 1s, 2s, 2p, 3s, 3p. Tổng các số mũ bằng số electron của nguyên tử hoặc ion đang xét."]'::jsonb,'["Na trung hòa có Z = 11: 1s² 2s² 2p⁶ 3s¹. Tổng electron là 2 + 2 + 6 + 1 = 11."]'::jsonb,'[{"id": "chemistry-10-electron-configuration-q1", "prompt": "Tổng số mũ trong cấu hình electron cho biết?", "difficulty": "EASY", "options": [{"id": "a", "text": "Số electron"}, {"id": "b", "text": "Luôn là số neutron"}, {"id": "c", "text": "Luôn là số khối"}], "correctOptionId": "a", "explanation": "Mỗi số mũ đếm electron ở phân lớp tương ứng."}, {"id": "chemistry-10-electron-configuration-q2", "prompt": "Cấu hình 1s² 2s² 2p⁶ có tổng bao nhiêu electron?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "8"}, {"id": "b", "text": "6"}, {"id": "c", "text": "10"}], "correctOptionId": "c", "explanation": "Cộng 2 + 2 + 6 = 10 electron."}, {"id": "chemistry-10-electron-configuration-q3", "prompt": "Nguyên tử Mg có Z = 12. Cấu hình trạng thái cơ bản nào đúng?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "1s² 2s² 2p⁶ 3s¹"}, {"id": "b", "text": "1s² 2s² 2p⁶ 3s²"}, {"id": "c", "text": "1s² 2s² 2p⁸"}], "correctOptionId": "b", "explanation": "Mg trung hòa có 12 electron; 2p tối đa 6 và hai electron còn lại vào 3s."}]'::jsonb,'["chemistry-10-electron-configuration"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('chemistry',10,'intro-2026.1','chemistry-10-valence-electrons',9,'LESSON','Electron lớp ngoài cùng','Từ nguyên tử đến phản ứng hóa học','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Electron lớp ngoài cùng thuộc lớp có n lớn nhất đang có electron. Với nguyên tố nhóm A, chúng giúp dự đoán nhiều tính chất hóa học; không được suy rộng mọi quy tắc nhóm A cho kim loại chuyển tiếp."]'::jsonb,'["Al: 1s² 2s² 2p⁶ 3s² 3p¹. Lớp ngoài cùng n = 3 có 2 + 1 = 3 electron."]'::jsonb,'[{"id": "chemistry-10-valence-electrons-q1", "prompt": "Lớp ngoài cùng là lớp đang có electron với n?", "difficulty": "EASY", "options": [{"id": "a", "text": "Nhỏ nhất"}, {"id": "b", "text": "Luôn bằng 1"}, {"id": "c", "text": "Lớn nhất"}], "correctOptionId": "c", "explanation": "Xét lớp có electron và số lượng tử chính n lớn nhất."}, {"id": "chemistry-10-valence-electrons-q2", "prompt": "Na có cấu hình kết thúc 3s¹, không có electron lớp cao hơn. Số electron ngoài cùng là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "11"}, {"id": "b", "text": "1"}, {"id": "c", "text": "3"}], "correctOptionId": "b", "explanation": "Lớp ngoài cùng n = 3 chỉ chứa một electron ở 3s."}, {"id": "chemistry-10-valence-electrons-q3", "prompt": "Cấu hình kết thúc 3s² 3p⁵, không có lớp cao hơn. Electron ngoài cùng là?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "7"}, {"id": "b", "text": "5"}, {"id": "c", "text": "17"}], "correctOptionId": "a", "explanation": "Cộng electron cùng lớp n = 3: 2 + 5 = 7; không chỉ đếm phân lớp cuối."}]'::jsonb,'["chemistry-10-valence-electrons"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('chemistry',10,'intro-2026.1','chemistry-10-periodic-table',10,'LESSON','Chu kì trong bảng tuần hoàn','Từ nguyên tử đến phản ứng hóa học','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Bảng tuần hoàn hiện đại xếp nguyên tố theo chiều tăng số hiệu nguyên tử Z. Với nguyên tử trạng thái cơ bản, số lớp có electron bằng số thứ tự chu kì."]'::jsonb,'["Na có ba lớp electron và Z = 11 nên thuộc chu kì 3; vị trí không được xác định bằng số neutron."]'::jsonb,'[{"id": "chemistry-10-periodic-table-q1", "prompt": "Bảng tuần hoàn xếp theo chiều tăng của?", "difficulty": "EASY", "options": [{"id": "a", "text": "Số khối của mọi đồng vị"}, {"id": "b", "text": "Số hiệu nguyên tử"}, {"id": "c", "text": "Số neutron"}], "correctOptionId": "b", "explanation": "Z là số proton và xác định nguyên tố; các đồng vị vẫn chung một ô."}, {"id": "chemistry-10-periodic-table-q2", "prompt": "Nguyên tử trạng thái cơ bản có hai lớp electron thuộc chu kì?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "2"}, {"id": "b", "text": "1"}, {"id": "c", "text": "4"}], "correctOptionId": "a", "explanation": "Số lớp đang có electron bằng số chu kì."}, {"id": "chemistry-10-periodic-table-q3", "prompt": "Mg có cấu hình 1s² 2s² 2p⁶ 3s². Thuộc chu kì nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "2"}, {"id": "b", "text": "12"}, {"id": "c", "text": "3"}], "correctOptionId": "c", "explanation": "Có các lớp n = 1, 2, 3; lớp lớn nhất n = 3 nên ở chu kì 3."}]'::jsonb,'["chemistry-10-periodic-table"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('chemistry',10,'intro-2026.1','chemistry-10-periodic-trends',11,'LESSON','Xu hướng tính chất trong một chu kì','Từ nguyên tử đến phản ứng hóa học','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Trong một chu kì của các nguyên tố nhóm A, từ trái sang phải bán kính nguyên tử nhìn chung giảm; độ âm điện nhìn chung tăng nếu không xét khí hiếm. Đây là xu hướng, không thay thế dữ liệu khi cần so sánh chính xác."]'::jsonb,'["Trong chu kì 3, Na có bán kính nguyên tử lớn hơn Cl; Cl hút electron liên kết mạnh hơn Na."]'::jsonb,'[{"id": "chemistry-10-periodic-trends-q1", "prompt": "Từ trái sang phải trong một chu kì nhóm A, bán kính nhìn chung?", "difficulty": "EASY", "options": [{"id": "a", "text": "Giảm"}, {"id": "b", "text": "Tăng mãi"}, {"id": "c", "text": "Luôn bằng nhau"}], "correctOptionId": "a", "explanation": "Điện tích hạt nhân tăng trong khi electron được thêm cùng lớp chính, làm lực hút hiệu dụng nhìn chung tăng."}, {"id": "chemistry-10-periodic-trends-q2", "prompt": "Trong chu kì 3, Na và Cl: nguyên tử nào thường có bán kính lớn hơn?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cl"}, {"id": "b", "text": "Luôn bằng nhau"}, {"id": "c", "text": "Na"}], "correctOptionId": "c", "explanation": "Na ở phía trái chu kì, phù hợp xu hướng bán kính giảm sang phải."}, {"id": "chemistry-10-periodic-trends-q3", "prompt": "So Na và Cl, nguyên tố nào hút cặp electron liên kết mạnh hơn?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Không thể so bằng độ âm điện"}, {"id": "b", "text": "Cl"}, {"id": "c", "text": "Na"}], "correctOptionId": "b", "explanation": "Cl có độ âm điện cao hơn; độ âm điện mô tả khả năng hút electron trong liên kết."}]'::jsonb,'["chemistry-10-periodic-trends"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('chemistry',10,'intro-2026.1','chemistry-10-review-2',12,'FIVE_LESSON_REVIEW','Ôn tập 2','Từ nguyên tử đến phản ứng hóa học','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "chemistry-10-electron-shells-q1", "prompt": "Phân lớp s chứa tối đa bao nhiêu electron?", "difficulty": "EASY", "options": [{"id": "a", "text": "8"}, {"id": "b", "text": "2"}, {"id": "c", "text": "6"}], "correctOptionId": "b", "explanation": "Phân lớp s có một orbital; mỗi orbital chứa tối đa hai electron."}, {"id": "chemistry-10-electron-shells-q2", "prompt": "Lớp n = 2 chứa tối đa bao nhiêu electron?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "8"}, {"id": "b", "text": "4"}, {"id": "c", "text": "18"}], "correctOptionId": "a", "explanation": "2n² = 2 × 2² = 8 electron."}, {"id": "chemistry-10-electron-configuration-q1", "prompt": "Tổng số mũ trong cấu hình electron cho biết?", "difficulty": "EASY", "options": [{"id": "a", "text": "Số electron"}, {"id": "b", "text": "Luôn là số neutron"}, {"id": "c", "text": "Luôn là số khối"}], "correctOptionId": "a", "explanation": "Mỗi số mũ đếm electron ở phân lớp tương ứng."}, {"id": "chemistry-10-electron-configuration-q2", "prompt": "Cấu hình 1s² 2s² 2p⁶ có tổng bao nhiêu electron?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "8"}, {"id": "b", "text": "6"}, {"id": "c", "text": "10"}], "correctOptionId": "c", "explanation": "Cộng 2 + 2 + 6 = 10 electron."}, {"id": "chemistry-10-valence-electrons-q1", "prompt": "Lớp ngoài cùng là lớp đang có electron với n?", "difficulty": "EASY", "options": [{"id": "a", "text": "Nhỏ nhất"}, {"id": "b", "text": "Luôn bằng 1"}, {"id": "c", "text": "Lớn nhất"}], "correctOptionId": "c", "explanation": "Xét lớp có electron và số lượng tử chính n lớn nhất."}, {"id": "chemistry-10-valence-electrons-q2", "prompt": "Na có cấu hình kết thúc 3s¹, không có electron lớp cao hơn. Số electron ngoài cùng là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "11"}, {"id": "b", "text": "1"}, {"id": "c", "text": "3"}], "correctOptionId": "b", "explanation": "Lớp ngoài cùng n = 3 chỉ chứa một electron ở 3s."}, {"id": "chemistry-10-periodic-table-q1", "prompt": "Bảng tuần hoàn xếp theo chiều tăng của?", "difficulty": "EASY", "options": [{"id": "a", "text": "Số khối của mọi đồng vị"}, {"id": "b", "text": "Số hiệu nguyên tử"}, {"id": "c", "text": "Số neutron"}], "correctOptionId": "b", "explanation": "Z là số proton và xác định nguyên tố; các đồng vị vẫn chung một ô."}, {"id": "chemistry-10-periodic-table-q2", "prompt": "Nguyên tử trạng thái cơ bản có hai lớp electron thuộc chu kì?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "2"}, {"id": "b", "text": "1"}, {"id": "c", "text": "4"}], "correctOptionId": "a", "explanation": "Số lớp đang có electron bằng số chu kì."}, {"id": "chemistry-10-periodic-trends-q1", "prompt": "Từ trái sang phải trong một chu kì nhóm A, bán kính nhìn chung?", "difficulty": "EASY", "options": [{"id": "a", "text": "Giảm"}, {"id": "b", "text": "Tăng mãi"}, {"id": "c", "text": "Luôn bằng nhau"}], "correctOptionId": "a", "explanation": "Điện tích hạt nhân tăng trong khi electron được thêm cùng lớp chính, làm lực hút hiệu dụng nhìn chung tăng."}, {"id": "chemistry-10-periodic-trends-q2", "prompt": "Trong chu kì 3, Na và Cl: nguyên tử nào thường có bán kính lớn hơn?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cl"}, {"id": "b", "text": "Luôn bằng nhau"}, {"id": "c", "text": "Na"}], "correctOptionId": "c", "explanation": "Na ở phía trái chu kì, phù hợp xu hướng bán kính giảm sang phải."}]'::jsonb,'["chemistry-10-electron-shells", "chemistry-10-electron-configuration", "chemistry-10-valence-electrons", "chemistry-10-periodic-table", "chemistry-10-periodic-trends"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('chemistry',10,'intro-2026.1','chemistry-10-octet',13,'LESSON','Quy tắc octet và giới hạn','Từ nguyên tử đến phản ứng hóa học','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Nhiều nguyên tử nhóm A có xu hướng nhường, nhận hoặc dùng chung electron để có lớp ngoài cùng bền kiểu khí hiếm, thường tám electron. H thường đạt hai electron; quy tắc octet không đúng cho mọi chất."]'::jsonb,'["Na nhường một electron tạo Na⁺ có cấu hình như Ne. Cl nhận một electron tạo Cl⁻ có cấu hình như Ar."]'::jsonb,'[{"id": "chemistry-10-octet-q1", "prompt": "Theo quy tắc octet, nhiều nguyên tử hướng đến bao nhiêu electron ngoài cùng?", "difficulty": "EASY", "options": [{"id": "a", "text": "12"}, {"id": "b", "text": "18"}, {"id": "c", "text": "8"}], "correctOptionId": "c", "explanation": "Octet nghĩa là tám; vẫn có ngoại lệ và H theo cấu hình hai electron."}, {"id": "chemistry-10-octet-q2", "prompt": "Na có một electron ngoài cùng thường tạo Na⁺ bằng cách?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Nhường 1 proton"}, {"id": "b", "text": "Nhường 1 electron"}, {"id": "c", "text": "Nhận 1 electron"}], "correctOptionId": "b", "explanation": "Mất một electron tạo điện tích +1; hạt nhân không đổi trong quá trình hóa học này."}, {"id": "chemistry-10-octet-q3", "prompt": "Trong phân tử H₂, mỗi H có thể được xem là đạt lớp bền với?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "2 electron nhờ cặp dùng chung"}, {"id": "b", "text": "8 electron riêng"}, {"id": "c", "text": "0 electron"}], "correctOptionId": "a", "explanation": "Hai H dùng chung một cặp electron; mỗi H đạt cấu hình lớp thứ nhất hai electron, không phải octet."}]'::jsonb,'["chemistry-10-octet"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('chemistry',10,'intro-2026.1','chemistry-10-ionic-bond',14,'LESSON','Liên kết ion','Từ nguyên tử đến phản ứng hóa học','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Liên kết ion là lực hút tĩnh điện giữa các ion trái dấu. Chất ion thường tạo mạng tinh thể; công thức biểu diễn tỉ lệ ion để tổng điện tích bằng 0, không nhất thiết là phân tử riêng biệt."]'::jsonb,'["Mg²⁺ cần hai Cl⁻ để trung hòa điện: công thức MgCl₂."]'::jsonb,'[{"id": "chemistry-10-ionic-bond-q1", "prompt": "Liên kết ion hình thành chủ yếu do?", "difficulty": "EASY", "options": [{"id": "a", "text": "Chuyển neutron qua lại"}, {"id": "b", "text": "Hút tĩnh điện giữa ion trái dấu"}, {"id": "c", "text": "Hai ion cùng dấu hút nhau"}], "correctOptionId": "b", "explanation": "Ion dương và ion âm hút nhau bằng tương tác điện."}, {"id": "chemistry-10-ionic-bond-q2", "prompt": "Ca²⁺ và Cl⁻ tạo chất có công thức nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "CaCl₂"}, {"id": "b", "text": "Ca₂Cl"}, {"id": "c", "text": "CaCl"}], "correctOptionId": "a", "explanation": "Một Ca²⁺ cần hai Cl⁻ để tổng điện tích +2 − 2 = 0."}, {"id": "chemistry-10-ionic-bond-q3", "prompt": "Al³⁺ và O²⁻ tạo chất trung hòa với tỉ lệ ion tối giản nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "1 Al³⁺ : 1 O²⁻"}, {"id": "b", "text": "3 Al³⁺ : 2 O²⁻"}, {"id": "c", "text": "2 Al³⁺ : 3 O²⁻"}], "correctOptionId": "c", "explanation": "Bội chung của 3 và 2 là 6: hai ion Al tổng +6, ba ion O tổng −6, được Al₂O₃."}]'::jsonb,'["chemistry-10-ionic-bond"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('chemistry',10,'intro-2026.1','chemistry-10-covalent-bond',15,'LESSON','Liên kết cộng hóa trị','Từ nguyên tử đến phản ứng hóa học','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Liên kết cộng hóa trị được tạo bởi một hoặc nhiều cặp electron dùng chung. Một cặp tạo liên kết đơn, hai cặp tạo liên kết đôi, ba cặp tạo liên kết ba."]'::jsonb,'["Trong H₂, hai nguyên tử H dùng chung một cặp electron, tạo liên kết đơn H–H."]'::jsonb,'[{"id": "chemistry-10-covalent-bond-q1", "prompt": "Đặc trưng của liên kết cộng hóa trị là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Cặp electron dùng chung"}, {"id": "b", "text": "Luôn chuyển hoàn toàn electron thành ion"}, {"id": "c", "text": "Dùng chung proton"}], "correctOptionId": "a", "explanation": "Các nguyên tử liên kết thông qua một hay nhiều cặp electron chung."}, {"id": "chemistry-10-covalent-bond-q2", "prompt": "Liên kết đôi tương ứng bao nhiêu cặp electron chung?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "1"}, {"id": "b", "text": "4"}, {"id": "c", "text": "2"}], "correctOptionId": "c", "explanation": "Mỗi vạch liên kết biểu diễn một cặp electron dùng chung."}, {"id": "chemistry-10-covalent-bond-q3", "prompt": "Trong N₂ có liên kết ba. Số electron tham gia ba cặp chung là?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "12"}, {"id": "b", "text": "6"}, {"id": "c", "text": "3"}], "correctOptionId": "b", "explanation": "Ba cặp, mỗi cặp hai electron: 3 × 2 = 6 electron dùng chung."}]'::jsonb,'["chemistry-10-covalent-bond"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('chemistry',10,'intro-2026.1','chemistry-10-bond-polarity',16,'LESSON','Độ phân cực của liên kết','Từ nguyên tử đến phản ứng hóa học','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Khi hai nguyên tử hút cặp electron chung khác nhau, liên kết có thể phân cực về nguyên tử có độ âm điện lớn hơn. Phân cực liên kết và phân cực toàn phân tử là hai khái niệm khác nhau."]'::jsonb,'["Trong H–Cl, electron chung lệch về Cl: Cl mang phần điện tích âm, H mang phần điện tích dương; không phải hai ion tách rời trong phân tử khí HCl."]'::jsonb,'[{"id": "chemistry-10-bond-polarity-q1", "prompt": "Cặp electron chung lệch về nguyên tử có?", "difficulty": "EASY", "options": [{"id": "a", "text": "Số neutron luôn lớn hơn"}, {"id": "b", "text": "Khối lượng luôn nhỏ hơn"}, {"id": "c", "text": "Độ âm điện lớn hơn"}], "correctOptionId": "c", "explanation": "Độ âm điện mô tả khả năng hút electron của nguyên tử trong liên kết."}, {"id": "chemistry-10-bond-polarity-q2", "prompt": "Liên kết Cl–Cl giữa hai nguyên tử giống nhau được coi là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Không có electron chung"}, {"id": "b", "text": "Cộng hóa trị không phân cực"}, {"id": "c", "text": "Ion thuần túy"}], "correctOptionId": "b", "explanation": "Hai nguyên tử có cùng độ âm điện nên không có sự lệch ưu tiên của cặp chung."}, {"id": "chemistry-10-bond-polarity-q3", "prompt": "CO₂ thẳng có hai liên kết C=O phân cực đối xứng. Toàn phân tử?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Không phân cực do các moment triệt tiêu"}, {"id": "b", "text": "Luôn phân cực vì từng liên kết phân cực"}, {"id": "c", "text": "Không có liên kết cộng hóa trị"}], "correctOptionId": "a", "explanation": "Cần xét hình học: hai moment bằng nhau ngược chiều nên tổng moment lưỡng cực bằng 0."}]'::jsonb,'["chemistry-10-bond-polarity"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('chemistry',10,'intro-2026.1','chemistry-10-hydrogen-bond',17,'LESSON','Liên kết hydrogen','Từ nguyên tử đến phản ứng hóa học','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Liên kết hydrogen thường xuất hiện khi H đã liên kết với F, O hoặc N tương tác với cặp electron tự do thích hợp của nguyên tử khác. Tương tác này yếu hơn liên kết cộng hóa trị O–H bên trong phân tử nước."]'::jsonb,'["Giữa các phân tử nước có liên kết hydrogen; đun sôi chủ yếu làm các phân tử tách xa nhau, không phân hủy nước thành hydrogen và oxygen."]'::jsonb,'[{"id": "chemistry-10-hydrogen-bond-q1", "prompt": "Trong nước, liên kết hydrogen điển hình hình thành giữa?", "difficulty": "EASY", "options": [{"id": "a", "text": "Chỉ hai nguyên tử O tạo liên kết đôi"}, {"id": "b", "text": "Các phân tử nước"}, {"id": "c", "text": "Hai neutron trong hạt nhân"}], "correctOptionId": "b", "explanation": "H của một phân tử tương tác với cặp electron tự do trên O của phân tử khác."}, {"id": "chemistry-10-hydrogen-bond-q2", "prompt": "Liên kết O–H bên trong phân tử nước là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Liên kết cộng hóa trị"}, {"id": "b", "text": "Liên kết hydrogen giữa hai phân tử"}, {"id": "c", "text": "Liên kết kim loại"}], "correctOptionId": "a", "explanation": "Phải phân biệt cặp electron chung O–H với tương tác hydrogen giữa các phân tử."}, {"id": "chemistry-10-hydrogen-bond-q3", "prompt": "Khi nước sôi ở điều kiện thường, mô tả phù hợp là?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Mọi H₂O tách thành H₂ và O₂"}, {"id": "b", "text": "Proton biến thành electron"}, {"id": "c", "text": "Phân tử nước tách xa, vẫn chủ yếu là H₂O"}], "correctOptionId": "c", "explanation": "Chuyển thể không đồng nghĩa phản ứng phân hủy; liên kết cộng hóa trị trong H₂O vẫn được giữ."}]'::jsonb,'["chemistry-10-hydrogen-bond"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('chemistry',10,'intro-2026.1','chemistry-10-review-3',18,'FIVE_LESSON_REVIEW','Ôn tập 3','Từ nguyên tử đến phản ứng hóa học','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "chemistry-10-octet-q1", "prompt": "Theo quy tắc octet, nhiều nguyên tử hướng đến bao nhiêu electron ngoài cùng?", "difficulty": "EASY", "options": [{"id": "a", "text": "12"}, {"id": "b", "text": "18"}, {"id": "c", "text": "8"}], "correctOptionId": "c", "explanation": "Octet nghĩa là tám; vẫn có ngoại lệ và H theo cấu hình hai electron."}, {"id": "chemistry-10-octet-q2", "prompt": "Na có một electron ngoài cùng thường tạo Na⁺ bằng cách?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Nhường 1 proton"}, {"id": "b", "text": "Nhường 1 electron"}, {"id": "c", "text": "Nhận 1 electron"}], "correctOptionId": "b", "explanation": "Mất một electron tạo điện tích +1; hạt nhân không đổi trong quá trình hóa học này."}, {"id": "chemistry-10-ionic-bond-q1", "prompt": "Liên kết ion hình thành chủ yếu do?", "difficulty": "EASY", "options": [{"id": "a", "text": "Chuyển neutron qua lại"}, {"id": "b", "text": "Hút tĩnh điện giữa ion trái dấu"}, {"id": "c", "text": "Hai ion cùng dấu hút nhau"}], "correctOptionId": "b", "explanation": "Ion dương và ion âm hút nhau bằng tương tác điện."}, {"id": "chemistry-10-ionic-bond-q2", "prompt": "Ca²⁺ và Cl⁻ tạo chất có công thức nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "CaCl₂"}, {"id": "b", "text": "Ca₂Cl"}, {"id": "c", "text": "CaCl"}], "correctOptionId": "a", "explanation": "Một Ca²⁺ cần hai Cl⁻ để tổng điện tích +2 − 2 = 0."}, {"id": "chemistry-10-covalent-bond-q1", "prompt": "Đặc trưng của liên kết cộng hóa trị là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Cặp electron dùng chung"}, {"id": "b", "text": "Luôn chuyển hoàn toàn electron thành ion"}, {"id": "c", "text": "Dùng chung proton"}], "correctOptionId": "a", "explanation": "Các nguyên tử liên kết thông qua một hay nhiều cặp electron chung."}, {"id": "chemistry-10-covalent-bond-q2", "prompt": "Liên kết đôi tương ứng bao nhiêu cặp electron chung?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "1"}, {"id": "b", "text": "4"}, {"id": "c", "text": "2"}], "correctOptionId": "c", "explanation": "Mỗi vạch liên kết biểu diễn một cặp electron dùng chung."}, {"id": "chemistry-10-bond-polarity-q1", "prompt": "Cặp electron chung lệch về nguyên tử có?", "difficulty": "EASY", "options": [{"id": "a", "text": "Số neutron luôn lớn hơn"}, {"id": "b", "text": "Khối lượng luôn nhỏ hơn"}, {"id": "c", "text": "Độ âm điện lớn hơn"}], "correctOptionId": "c", "explanation": "Độ âm điện mô tả khả năng hút electron của nguyên tử trong liên kết."}, {"id": "chemistry-10-bond-polarity-q2", "prompt": "Liên kết Cl–Cl giữa hai nguyên tử giống nhau được coi là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Không có electron chung"}, {"id": "b", "text": "Cộng hóa trị không phân cực"}, {"id": "c", "text": "Ion thuần túy"}], "correctOptionId": "b", "explanation": "Hai nguyên tử có cùng độ âm điện nên không có sự lệch ưu tiên của cặp chung."}, {"id": "chemistry-10-hydrogen-bond-q1", "prompt": "Trong nước, liên kết hydrogen điển hình hình thành giữa?", "difficulty": "EASY", "options": [{"id": "a", "text": "Chỉ hai nguyên tử O tạo liên kết đôi"}, {"id": "b", "text": "Các phân tử nước"}, {"id": "c", "text": "Hai neutron trong hạt nhân"}], "correctOptionId": "b", "explanation": "H của một phân tử tương tác với cặp electron tự do trên O của phân tử khác."}, {"id": "chemistry-10-hydrogen-bond-q2", "prompt": "Liên kết O–H bên trong phân tử nước là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Liên kết cộng hóa trị"}, {"id": "b", "text": "Liên kết hydrogen giữa hai phân tử"}, {"id": "c", "text": "Liên kết kim loại"}], "correctOptionId": "a", "explanation": "Phải phân biệt cặp electron chung O–H với tương tác hydrogen giữa các phân tử."}]'::jsonb,'["chemistry-10-octet", "chemistry-10-ionic-bond", "chemistry-10-covalent-bond", "chemistry-10-bond-polarity", "chemistry-10-hydrogen-bond"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('chemistry',10,'intro-2026.1','chemistry-10-oxidation-number',19,'LESSON','Xác định số oxi hóa','Từ nguyên tử đến phản ứng hóa học','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Tổng số oxi hóa của các nguyên tử bằng điện tích tiểu phân. Đơn chất có số oxi hóa 0; O thường −2 trừ ngoại lệ như peroxide, H thường +1 trừ hydride kim loại. Số oxi hóa là quy ước, không luôn là điện tích thật."]'::jsonb,'["Trong CO₂ trung hòa: x + 2 × (−2) = 0, nên carbon có số oxi hóa +4."]'::jsonb,'[{"id": "chemistry-10-oxidation-number-q1", "prompt": "Số oxi hóa của nguyên tố trong đơn chất O₂ là?", "difficulty": "EASY", "options": [{"id": "a", "text": "0"}, {"id": "b", "text": "−2"}, {"id": "c", "text": "+2"}], "correctOptionId": "a", "explanation": "Mọi nguyên tố trong đơn chất có số oxi hóa bằng 0."}, {"id": "chemistry-10-oxidation-number-q2", "prompt": "Trong MgO, O có số oxi hóa −2. Mg có số oxi hóa?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "−2"}, {"id": "b", "text": "0"}, {"id": "c", "text": "+2"}], "correctOptionId": "c", "explanation": "Tổng bằng 0 nên x − 2 = 0, x = +2."}, {"id": "chemistry-10-oxidation-number-q3", "prompt": "Trong ion SO₄²⁻, O có số oxi hóa −2. S có số oxi hóa?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "+4"}, {"id": "b", "text": "+6"}, {"id": "c", "text": "+8"}], "correctOptionId": "b", "explanation": "x + 4 × (−2) = −2, nên x = +6. Tổng bằng điện tích ion, không phải 0."}]'::jsonb,'["chemistry-10-oxidation-number"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('chemistry',10,'intro-2026.1','chemistry-10-redox',20,'LESSON','Oxi hóa và khử','Từ nguyên tử đến phản ứng hóa học','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Oxi hóa là nhường electron, số oxi hóa tăng. Khử là nhận electron, số oxi hóa giảm. Chất khử nhường electron và bị oxi hóa; chất oxi hóa nhận electron và bị khử."]'::jsonb,'["Zn → Zn²⁺ + 2e là oxi hóa. Cu²⁺ + 2e → Cu là khử; trong phản ứng Zn + Cu²⁺ → Zn²⁺ + Cu, Zn là chất khử."]'::jsonb,'[{"id": "chemistry-10-redox-q1", "prompt": "Quá trình nhường electron gọi là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Khử"}, {"id": "b", "text": "Thẩm thấu"}, {"id": "c", "text": "Oxi hóa"}], "correctOptionId": "c", "explanation": "Nhường electron làm số oxi hóa tăng."}, {"id": "chemistry-10-redox-q2", "prompt": "Cu²⁺ nhận 2 electron thành Cu. Cu²⁺ trải qua quá trình?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Không đổi số oxi hóa"}, {"id": "b", "text": "Khử"}, {"id": "c", "text": "Oxi hóa"}], "correctOptionId": "b", "explanation": "Số oxi hóa giảm từ +2 xuống 0, tương ứng nhận electron."}, {"id": "chemistry-10-redox-q3", "prompt": "Trong Zn + Cu²⁺ → Zn²⁺ + Cu, chất khử là?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Zn"}, {"id": "b", "text": "Cu²⁺"}, {"id": "c", "text": "Zn²⁺"}], "correctOptionId": "a", "explanation": "Zn nhường electron cho Cu²⁺, nên Zn là chất khử và bị oxi hóa."}]'::jsonb,'["chemistry-10-redox"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('chemistry',10,'intro-2026.1','chemistry-10-reaction-enthalpy',21,'LESSON','Phản ứng tỏa nhiệt và thu nhiệt','Từ nguyên tử đến phản ứng hóa học','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Phản ứng tỏa nhiệt truyền nhiệt ra môi trường, có ΔH < 0 khi xét hệ phản ứng ở áp suất không đổi. Phản ứng thu nhiệt nhận nhiệt từ môi trường, ΔH > 0. Cần phân biệt hệ và môi trường."]'::jsonb,'["Một phản ứng có ΔH = −100 kJ theo phương trình đã viết: hệ tỏa 100 kJ khi phản ứng xảy ra đúng lượng chất theo hệ số đó."]'::jsonb,'[{"id": "chemistry-10-reaction-enthalpy-q1", "prompt": "Phản ứng tỏa nhiệt có ΔH?", "difficulty": "EASY", "options": [{"id": "a", "text": "Luôn bằng 0"}, {"id": "b", "text": "Âm"}, {"id": "c", "text": "Dương"}], "correctOptionId": "b", "explanation": "Hệ mất năng lượng dưới dạng nhiệt nên enthalpy giảm, ΔH < 0."}, {"id": "chemistry-10-reaction-enthalpy-q2", "prompt": "Phản ứng có ΔH = +50 kJ là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Thu nhiệt"}, {"id": "b", "text": "Tỏa nhiệt"}, {"id": "c", "text": "Không trao đổi nhiệt"}], "correctOptionId": "a", "explanation": "Dấu dương cho biết hệ nhận nhiệt theo phương trình đã xét."}, {"id": "chemistry-10-reaction-enthalpy-q3", "prompt": "Đảo chiều phương trình có ΔH = −80 kJ, cùng lượng chất. ΔH chiều ngược bằng?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "−80 kJ"}, {"id": "b", "text": "0 kJ"}, {"id": "c", "text": "+80 kJ"}], "correctOptionId": "c", "explanation": "Đảo chiều biến đổi thì đổi dấu enthalpy: từ tỏa 80 kJ thành thu 80 kJ."}]'::jsonb,'["chemistry-10-reaction-enthalpy"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('chemistry',10,'intro-2026.1','chemistry-10-reaction-rate',22,'LESSON','Tốc độ phản ứng','Từ nguyên tử đến phản ứng hóa học','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Tốc độ phản ứng thể hiện mức thay đổi nồng độ theo thời gian. Nhiệt độ, nồng độ, diện tích tiếp xúc và chất xúc tác có thể ảnh hưởng tốc độ; không đồng nhất phản ứng nhanh với tạo nhiều sản phẩm cuối hơn."]'::jsonb,'["Cùng khối lượng CaCO₃, dạng bột phản ứng với acid nhanh hơn dạng viên trong điều kiện giống nhau vì diện tích tiếp xúc lớn hơn."]'::jsonb,'[{"id": "chemistry-10-reaction-rate-q1", "prompt": "Tốc độ phản ứng cho biết?", "difficulty": "EASY", "options": [{"id": "a", "text": "Phản ứng diễn ra nhanh hay chậm"}, {"id": "b", "text": "Chỉ khối lượng sản phẩm cuối"}, {"id": "c", "text": "Chỉ số neutron"}], "correctOptionId": "a", "explanation": "Tốc độ liên hệ lượng chất hoặc nồng độ biến đổi trong một đơn vị thời gian."}, {"id": "chemistry-10-reaction-rate-q2", "prompt": "Cùng khối lượng đá vôi, dạng bột thường phản ứng nhanh hơn viên do?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Bột luôn có số mol lớn hơn"}, {"id": "b", "text": "Bột không có liên kết hóa học"}, {"id": "c", "text": "Diện tích tiếp xúc lớn hơn"}], "correctOptionId": "c", "explanation": "Chia nhỏ tăng diện tích tiếp xúc, còn số mol giữ nguyên nếu cùng chất và khối lượng."}, {"id": "chemistry-10-reaction-rate-q3", "prompt": "Thêm xúc tác thích hợp vào phản ứng, nhận xét nào đúng?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Biến mất hoàn toàn như chất phản ứng"}, {"id": "b", "text": "Có thể tăng tốc độ mà không bị tiêu hao tổng thể"}, {"id": "c", "text": "Luôn tăng lượng sản phẩm cực đại bất kể chất đầu"}], "correctOptionId": "b", "explanation": "Xúc tác tạo con đường phản ứng thuận lợi hơn và được tái tạo; không tự tạo thêm nguyên tử hay thay giới hạn chất phản ứng."}]'::jsonb,'["chemistry-10-reaction-rate"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('chemistry',10,'intro-2026.1','chemistry-10-halogens',23,'LESSON','Làm quen với nhóm halogen','Từ nguyên tử đến phản ứng hóa học','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Halogen thuộc nhóm 17 (VIIA), có bảy electron lớp ngoài cùng. Đơn chất thường gồm phân tử X₂ và có tính oxi hóa; ion halide X⁻ nhận thêm một electron so với nguyên tử trung hòa. Không tự thử với halogen vì có độc tính."]'::jsonb,'["Cl₂ + 2e → 2Cl⁻: mỗi nguyên tử chlorine nhận một electron, số oxi hóa giảm từ 0 xuống −1."]'::jsonb,'[{"id": "chemistry-10-halogens-q1", "prompt": "Nguyên tử halogen nhóm A có bao nhiêu electron ngoài cùng?", "difficulty": "EASY", "options": [{"id": "a", "text": "1"}, {"id": "b", "text": "8"}, {"id": "c", "text": "7"}], "correctOptionId": "c", "explanation": "Halogen thuộc nhóm VIIA, tương ứng bảy electron ngoài cùng."}, {"id": "chemistry-10-halogens-q2", "prompt": "Cl trung hòa có Z = 17. Ion Cl⁻ có bao nhiêu electron?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "17"}, {"id": "b", "text": "18"}, {"id": "c", "text": "16"}], "correctOptionId": "b", "explanation": "Cl⁻ nhận thêm một electron so với Cl trung hòa: 17 + 1 = 18."}, {"id": "chemistry-10-halogens-q3", "prompt": "Trong Cl₂ + 2e → 2Cl⁻, chlorine trải qua quá trình?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Khử vì nhận electron"}, {"id": "b", "text": "Oxi hóa vì nhận electron"}, {"id": "c", "text": "Không thay đổi số oxi hóa"}], "correctOptionId": "a", "explanation": "Số oxi hóa giảm từ 0 xuống −1; nhận electron là khử."}]'::jsonb,'["chemistry-10-halogens"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('chemistry',10,'intro-2026.1','chemistry-10-review-4',24,'FIVE_LESSON_REVIEW','Ôn tập 4','Từ nguyên tử đến phản ứng hóa học','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "chemistry-10-oxidation-number-q1", "prompt": "Số oxi hóa của nguyên tố trong đơn chất O₂ là?", "difficulty": "EASY", "options": [{"id": "a", "text": "0"}, {"id": "b", "text": "−2"}, {"id": "c", "text": "+2"}], "correctOptionId": "a", "explanation": "Mọi nguyên tố trong đơn chất có số oxi hóa bằng 0."}, {"id": "chemistry-10-oxidation-number-q2", "prompt": "Trong MgO, O có số oxi hóa −2. Mg có số oxi hóa?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "−2"}, {"id": "b", "text": "0"}, {"id": "c", "text": "+2"}], "correctOptionId": "c", "explanation": "Tổng bằng 0 nên x − 2 = 0, x = +2."}, {"id": "chemistry-10-redox-q1", "prompt": "Quá trình nhường electron gọi là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Khử"}, {"id": "b", "text": "Thẩm thấu"}, {"id": "c", "text": "Oxi hóa"}], "correctOptionId": "c", "explanation": "Nhường electron làm số oxi hóa tăng."}, {"id": "chemistry-10-redox-q2", "prompt": "Cu²⁺ nhận 2 electron thành Cu. Cu²⁺ trải qua quá trình?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Không đổi số oxi hóa"}, {"id": "b", "text": "Khử"}, {"id": "c", "text": "Oxi hóa"}], "correctOptionId": "b", "explanation": "Số oxi hóa giảm từ +2 xuống 0, tương ứng nhận electron."}, {"id": "chemistry-10-reaction-enthalpy-q1", "prompt": "Phản ứng tỏa nhiệt có ΔH?", "difficulty": "EASY", "options": [{"id": "a", "text": "Luôn bằng 0"}, {"id": "b", "text": "Âm"}, {"id": "c", "text": "Dương"}], "correctOptionId": "b", "explanation": "Hệ mất năng lượng dưới dạng nhiệt nên enthalpy giảm, ΔH < 0."}, {"id": "chemistry-10-reaction-enthalpy-q2", "prompt": "Phản ứng có ΔH = +50 kJ là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Thu nhiệt"}, {"id": "b", "text": "Tỏa nhiệt"}, {"id": "c", "text": "Không trao đổi nhiệt"}], "correctOptionId": "a", "explanation": "Dấu dương cho biết hệ nhận nhiệt theo phương trình đã xét."}, {"id": "chemistry-10-reaction-rate-q1", "prompt": "Tốc độ phản ứng cho biết?", "difficulty": "EASY", "options": [{"id": "a", "text": "Phản ứng diễn ra nhanh hay chậm"}, {"id": "b", "text": "Chỉ khối lượng sản phẩm cuối"}, {"id": "c", "text": "Chỉ số neutron"}], "correctOptionId": "a", "explanation": "Tốc độ liên hệ lượng chất hoặc nồng độ biến đổi trong một đơn vị thời gian."}, {"id": "chemistry-10-reaction-rate-q2", "prompt": "Cùng khối lượng đá vôi, dạng bột thường phản ứng nhanh hơn viên do?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Bột luôn có số mol lớn hơn"}, {"id": "b", "text": "Bột không có liên kết hóa học"}, {"id": "c", "text": "Diện tích tiếp xúc lớn hơn"}], "correctOptionId": "c", "explanation": "Chia nhỏ tăng diện tích tiếp xúc, còn số mol giữ nguyên nếu cùng chất và khối lượng."}, {"id": "chemistry-10-halogens-q1", "prompt": "Nguyên tử halogen nhóm A có bao nhiêu electron ngoài cùng?", "difficulty": "EASY", "options": [{"id": "a", "text": "1"}, {"id": "b", "text": "8"}, {"id": "c", "text": "7"}], "correctOptionId": "c", "explanation": "Halogen thuộc nhóm VIIA, tương ứng bảy electron ngoài cùng."}, {"id": "chemistry-10-halogens-q2", "prompt": "Cl trung hòa có Z = 17. Ion Cl⁻ có bao nhiêu electron?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "17"}, {"id": "b", "text": "18"}, {"id": "c", "text": "16"}], "correctOptionId": "b", "explanation": "Cl⁻ nhận thêm một electron so với Cl trung hòa: 17 + 1 = 18."}]'::jsonb,'["chemistry-10-oxidation-number", "chemistry-10-redox", "chemistry-10-reaction-enthalpy", "chemistry-10-reaction-rate", "chemistry-10-halogens"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('chemistry',10,'intro-2026.1','placement',0,'PLACEMENT','Khảo sát đầu vào','Từ nguyên tử đến phản ứng hóa học','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "chemistry-10-particles-q1", "prompt": "Hạt nào mang điện tích âm?", "difficulty": "EASY", "options": [{"id": "a", "text": "Electron"}, {"id": "b", "text": "Proton"}, {"id": "c", "text": "Neutron"}], "correctOptionId": "a", "explanation": "Electron mang điện tích −1 theo đơn vị điện tích nguyên tố."}, {"id": "chemistry-10-particles-q2", "prompt": "Hai loại hạt chủ yếu tạo nên hạt nhân nguyên tử là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Electron và proton"}, {"id": "b", "text": "Electron và neutron"}, {"id": "c", "text": "Proton và neutron"}], "correctOptionId": "c", "explanation": "Hạt nhân gồm proton và neutron; electron phân bố ngoài hạt nhân."}, {"id": "chemistry-10-atomic-number-q1", "prompt": "Số hiệu nguyên tử Z bằng số hạt nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Neutron"}, {"id": "b", "text": "Proton cộng neutron"}, {"id": "c", "text": "Proton"}], "correctOptionId": "c", "explanation": "Z được định nghĩa là số proton trong hạt nhân."}, {"id": "chemistry-10-atomic-number-q2", "prompt": "Nguyên tử có 11 proton thuộc nguyên tố có Z bằng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Không xác định"}, {"id": "b", "text": "11"}, {"id": "c", "text": "22"}], "correctOptionId": "b", "explanation": "Z bằng số proton nên Z = 11."}, {"id": "chemistry-10-mass-number-q1", "prompt": "Công thức liên hệ số khối A, proton Z và neutron N là?", "difficulty": "EASY", "options": [{"id": "a", "text": "A = số electron"}, {"id": "b", "text": "A = Z + N"}, {"id": "c", "text": "A = Z − N"}], "correctOptionId": "b", "explanation": "Số khối là tổng số proton và neutron trong hạt nhân."}, {"id": "chemistry-10-mass-number-q2", "prompt": "Nguyên tử có 6 proton và 7 neutron có số khối là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "13"}, {"id": "b", "text": "1"}, {"id": "c", "text": "6"}], "correctOptionId": "a", "explanation": "A = 6 + 7 = 13."}, {"id": "chemistry-10-isotopes-q1", "prompt": "Các đồng vị của cùng nguyên tố luôn giống nhau về?", "difficulty": "EASY", "options": [{"id": "a", "text": "Số proton"}, {"id": "b", "text": "Số neutron"}, {"id": "c", "text": "Số khối"}], "correctOptionId": "a", "explanation": "Cùng nguyên tố nghĩa cùng Z, do đó cùng số proton."}, {"id": "chemistry-10-isotopes-q2", "prompt": "Carbon-14 có 6 proton. Số neutron là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "6"}, {"id": "b", "text": "14"}, {"id": "c", "text": "8"}], "correctOptionId": "c", "explanation": "N = 14 − 6 = 8."}, {"id": "chemistry-10-ions-q1", "prompt": "Nguyên tử nhường một electron thường tạo thành?", "difficulty": "EASY", "options": [{"id": "a", "text": "Ion âm"}, {"id": "b", "text": "Nguyên tố mới"}, {"id": "c", "text": "Ion dương"}], "correctOptionId": "c", "explanation": "Mất electron âm khiến tổng điện tích trở nên dương; số proton không đổi."}, {"id": "chemistry-10-ions-q2", "prompt": "Nguyên tử có 17 proton nhận thêm 1 electron từ trạng thái trung hòa. Ion có bao nhiêu electron?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "17"}, {"id": "b", "text": "18"}, {"id": "c", "text": "16"}], "correctOptionId": "b", "explanation": "Ban đầu có 17 electron; nhận thêm 1 thành 18 electron."}]'::jsonb,'[]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('physics',10,'intro-2026.1','physics-10-position',1,'LESSON','Vị trí và hệ quy chiếu','Cơ học: chuyển động, lực và năng lượng','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Mô tả vị trí cần một mốc và chiều dương. Tọa độ có thể âm; điều đó không có nghĩa vật không chuyển động."]'::jsonb,'["Chọn cổng trường làm gốc, chiều đông là chiều dương. Một bạn cách cổng 20 m về tây có tọa độ −20 m."]'::jsonb,'[{"id": "physics-10-position-q1", "prompt": "Muốn nói rõ vị trí của một vật, trước hết cần chọn gì?", "difficulty": "EASY", "options": [{"id": "a", "text": "Mốc và hệ tọa độ"}, {"id": "b", "text": "Chỉ khối lượng vật"}, {"id": "c", "text": "Chỉ màu sắc vật"}], "correctOptionId": "a", "explanation": "Vị trí được xác định tương đối với mốc trong hệ tọa độ đã chọn."}, {"id": "physics-10-position-q2", "prompt": "Gốc tại nhà, chiều đông dương. Bạn ở 30 m về tây có tọa độ bao nhiêu?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "+30 m"}, {"id": "b", "text": "0 m"}, {"id": "c", "text": "−30 m"}], "correctOptionId": "c", "explanation": "Phía tây ngược chiều dương nên tọa độ là −30 m."}, {"id": "physics-10-position-q3", "prompt": "Xe đứng yên so với mặt đường. Người đi bộ có thấy xe đổi vị trí so với mình không?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Chỉ khi xe tăng khối lượng"}, {"id": "b", "text": "Có thể có"}, {"id": "c", "text": "Không bao giờ"}], "correctOptionId": "b", "explanation": "Chuyển động có tính tương đối. Người đi bộ đổi vị trí so với xe, nên xe cũng đổi vị trí trong hệ quy chiếu gắn với người đó."}]'::jsonb,'["physics-10-position"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('physics',10,'intro-2026.1','physics-10-displacement',2,'LESSON','Quãng đường và độ dịch chuyển','Cơ học: chuyển động, lực và năng lượng','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Quãng đường là tổng chiều dài đường đi. Độ dịch chuyển nối vị trí đầu với vị trí cuối; trong chuyển động thẳng, Δx = x₂ − x₁."]'::jsonb,'["Đi 5 m về đông rồi 2 m về tây: quãng đường 7 m, độ dịch chuyển +3 m nếu chọn chiều đông dương."]'::jsonb,'[{"id": "physics-10-displacement-q1", "prompt": "Đại lượng nào bằng tổng chiều dài đường đã đi?", "difficulty": "EASY", "options": [{"id": "a", "text": "Độ dịch chuyển luôn có dấu"}, {"id": "b", "text": "Gia tốc"}, {"id": "c", "text": "Quãng đường"}], "correctOptionId": "c", "explanation": "Quãng đường cộng chiều dài từng chặng, không trừ chặng đi ngược chiều."}, {"id": "physics-10-displacement-q2", "prompt": "Từ x = −2 m đến x = 4 m, độ dịch chuyển bằng bao nhiêu?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "−6 m"}, {"id": "b", "text": "+6 m"}, {"id": "c", "text": "+2 m"}], "correctOptionId": "b", "explanation": "Δx = 4 − (−2) = +6 m."}, {"id": "physics-10-displacement-q3", "prompt": "Chạy trọn một vòng sân dài 400 m về đúng chỗ cũ, độ lớn độ dịch chuyển là?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "0 m"}, {"id": "b", "text": "400 m"}, {"id": "c", "text": "800 m"}], "correctOptionId": "a", "explanation": "Vị trí đầu và cuối trùng nhau nên độ dịch chuyển bằng 0; quãng đường vẫn là 400 m."}]'::jsonb,'["physics-10-displacement"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('physics',10,'intro-2026.1','physics-10-speed',3,'LESSON','Tốc độ trung bình','Cơ học: chuyển động, lực và năng lượng','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Tốc độ trung bình bằng tổng quãng đường chia tổng thời gian: v = s/t. Tính cả thời gian dừng nếu nó thuộc khoảng thời gian đang xét."]'::jsonb,'["Đi 120 m trong 60 s rồi nghỉ 20 s: tốc độ trung bình của toàn bộ 80 s là 120/80 = 1,5 m/s."]'::jsonb,'[{"id": "physics-10-speed-q1", "prompt": "Công thức tính tốc độ trung bình là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Quãng đường × thời gian"}, {"id": "b", "text": "Tổng quãng đường / tổng thời gian"}, {"id": "c", "text": "Độ dịch chuyển × thời gian"}], "correctOptionId": "b", "explanation": "Tốc độ trung bình dùng tổng quãng đường và tổng thời gian, không lấy trung bình cộng tùy ý các tốc độ."}, {"id": "physics-10-speed-q2", "prompt": "Đi được 150 m trong 30 s, tốc độ trung bình là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "5 m/s"}, {"id": "b", "text": "0,2 m/s"}, {"id": "c", "text": "4500 m/s"}], "correctOptionId": "a", "explanation": "v = s/t = 150/30 = 5 m/s."}, {"id": "physics-10-speed-q3", "prompt": "Đi 100 m trong 50 s rồi nghỉ 50 s. Tốc độ trung bình cả khoảng là?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "2 m/s"}, {"id": "b", "text": "4 m/s"}, {"id": "c", "text": "1 m/s"}], "correctOptionId": "c", "explanation": "Tổng thời gian là 100 s. v = 100/100 = 1 m/s."}]'::jsonb,'["physics-10-speed"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('physics',10,'intro-2026.1','physics-10-velocity',4,'LESSON','Vận tốc và chiều chuyển động','Cơ học: chuyển động, lực và năng lượng','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Vận tốc trung bình bằng độ dịch chuyển chia thời gian. Trong chuyển động thẳng, dấu vận tốc thể hiện chiều so với chiều dương."]'::jsonb,'["Trong 4 s, vật từ x = 10 m đến x = 2 m: v = (2 − 10)/4 = −2 m/s."]'::jsonb,'[{"id": "physics-10-velocity-q1", "prompt": "Vận tốc trung bình được tính từ đại lượng nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Độ dịch chuyển và thời gian"}, {"id": "b", "text": "Chỉ quãng đường"}, {"id": "c", "text": "Chỉ khối lượng"}], "correctOptionId": "a", "explanation": "Vận tốc trung bình là Δx/Δt trong chuyển động thẳng."}, {"id": "physics-10-velocity-q2", "prompt": "Vật dịch chuyển −12 m trong 3 s. Vận tốc trung bình bằng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "+4 m/s"}, {"id": "b", "text": "−36 m/s"}, {"id": "c", "text": "−4 m/s"}], "correctOptionId": "c", "explanation": "v = −12/3 = −4 m/s, tức theo chiều âm."}, {"id": "physics-10-velocity-q3", "prompt": "Đi rồi quay lại đúng vị trí ban đầu sau 20 s. Vận tốc trung bình là?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Không thể bằng 0"}, {"id": "b", "text": "0 m/s"}, {"id": "c", "text": "Luôn dương"}], "correctOptionId": "b", "explanation": "Độ dịch chuyển bằng 0 nên vận tốc trung bình bằng 0, dù tốc độ trung bình có thể khác 0."}]'::jsonb,'["physics-10-velocity"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('physics',10,'intro-2026.1','physics-10-acceleration',5,'LESSON','Gia tốc trong chuyển động thẳng','Cơ học: chuyển động, lực và năng lượng','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Gia tốc trung bình a = (v₂ − v₁)/Δt. Dấu gia tốc phải xét cùng dấu vận tốc để biết vật nhanh lên hay chậm đi."]'::jsonb,'["Xe có v tăng từ 2 lên 8 m/s trong 3 s: a = (8 − 2)/3 = 2 m/s²."]'::jsonb,'[{"id": "physics-10-acceleration-q1", "prompt": "Đơn vị SI của gia tốc là?", "difficulty": "EASY", "options": [{"id": "a", "text": "m/s"}, {"id": "b", "text": "m²/s"}, {"id": "c", "text": "m/s²"}], "correctOptionId": "c", "explanation": "Gia tốc là độ biến thiên vận tốc trong một giây nên có đơn vị (m/s)/s = m/s²."}, {"id": "physics-10-acceleration-q2", "prompt": "Vận tốc tăng từ 4 lên 10 m/s trong 2 s. Gia tốc trung bình bằng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "12 m/s²"}, {"id": "b", "text": "3 m/s²"}, {"id": "c", "text": "7 m/s²"}], "correctOptionId": "b", "explanation": "a = (10 − 4)/2 = 3 m/s²."}, {"id": "physics-10-acceleration-q3", "prompt": "Xe đang có v = +10 m/s và a = −2 m/s² không đổi. Ngay lúc đó xe thế nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Đang chậm dần"}, {"id": "b", "text": "Đang nhanh dần"}, {"id": "c", "text": "Đã đứng yên"}], "correctOptionId": "a", "explanation": "Gia tốc ngược dấu vận tốc nên độ lớn vận tốc đang giảm; xe chưa đứng yên khi v vẫn là +10 m/s."}]'::jsonb,'["physics-10-acceleration"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('physics',10,'intro-2026.1','physics-10-review-1',6,'FIVE_LESSON_REVIEW','Ôn tập 1','Cơ học: chuyển động, lực và năng lượng','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "physics-10-position-q1", "prompt": "Muốn nói rõ vị trí của một vật, trước hết cần chọn gì?", "difficulty": "EASY", "options": [{"id": "a", "text": "Mốc và hệ tọa độ"}, {"id": "b", "text": "Chỉ khối lượng vật"}, {"id": "c", "text": "Chỉ màu sắc vật"}], "correctOptionId": "a", "explanation": "Vị trí được xác định tương đối với mốc trong hệ tọa độ đã chọn."}, {"id": "physics-10-position-q2", "prompt": "Gốc tại nhà, chiều đông dương. Bạn ở 30 m về tây có tọa độ bao nhiêu?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "+30 m"}, {"id": "b", "text": "0 m"}, {"id": "c", "text": "−30 m"}], "correctOptionId": "c", "explanation": "Phía tây ngược chiều dương nên tọa độ là −30 m."}, {"id": "physics-10-displacement-q1", "prompt": "Đại lượng nào bằng tổng chiều dài đường đã đi?", "difficulty": "EASY", "options": [{"id": "a", "text": "Độ dịch chuyển luôn có dấu"}, {"id": "b", "text": "Gia tốc"}, {"id": "c", "text": "Quãng đường"}], "correctOptionId": "c", "explanation": "Quãng đường cộng chiều dài từng chặng, không trừ chặng đi ngược chiều."}, {"id": "physics-10-displacement-q2", "prompt": "Từ x = −2 m đến x = 4 m, độ dịch chuyển bằng bao nhiêu?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "−6 m"}, {"id": "b", "text": "+6 m"}, {"id": "c", "text": "+2 m"}], "correctOptionId": "b", "explanation": "Δx = 4 − (−2) = +6 m."}, {"id": "physics-10-speed-q1", "prompt": "Công thức tính tốc độ trung bình là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Quãng đường × thời gian"}, {"id": "b", "text": "Tổng quãng đường / tổng thời gian"}, {"id": "c", "text": "Độ dịch chuyển × thời gian"}], "correctOptionId": "b", "explanation": "Tốc độ trung bình dùng tổng quãng đường và tổng thời gian, không lấy trung bình cộng tùy ý các tốc độ."}, {"id": "physics-10-speed-q2", "prompt": "Đi được 150 m trong 30 s, tốc độ trung bình là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "5 m/s"}, {"id": "b", "text": "0,2 m/s"}, {"id": "c", "text": "4500 m/s"}], "correctOptionId": "a", "explanation": "v = s/t = 150/30 = 5 m/s."}, {"id": "physics-10-velocity-q1", "prompt": "Vận tốc trung bình được tính từ đại lượng nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Độ dịch chuyển và thời gian"}, {"id": "b", "text": "Chỉ quãng đường"}, {"id": "c", "text": "Chỉ khối lượng"}], "correctOptionId": "a", "explanation": "Vận tốc trung bình là Δx/Δt trong chuyển động thẳng."}, {"id": "physics-10-velocity-q2", "prompt": "Vật dịch chuyển −12 m trong 3 s. Vận tốc trung bình bằng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "+4 m/s"}, {"id": "b", "text": "−36 m/s"}, {"id": "c", "text": "−4 m/s"}], "correctOptionId": "c", "explanation": "v = −12/3 = −4 m/s, tức theo chiều âm."}, {"id": "physics-10-acceleration-q1", "prompt": "Đơn vị SI của gia tốc là?", "difficulty": "EASY", "options": [{"id": "a", "text": "m/s"}, {"id": "b", "text": "m²/s"}, {"id": "c", "text": "m/s²"}], "correctOptionId": "c", "explanation": "Gia tốc là độ biến thiên vận tốc trong một giây nên có đơn vị (m/s)/s = m/s²."}, {"id": "physics-10-acceleration-q2", "prompt": "Vận tốc tăng từ 4 lên 10 m/s trong 2 s. Gia tốc trung bình bằng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "12 m/s²"}, {"id": "b", "text": "3 m/s²"}, {"id": "c", "text": "7 m/s²"}], "correctOptionId": "b", "explanation": "a = (10 − 4)/2 = 3 m/s²."}]'::jsonb,'["physics-10-position", "physics-10-displacement", "physics-10-speed", "physics-10-velocity", "physics-10-acceleration"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('physics',10,'intro-2026.1','physics-10-uniform-acceleration',7,'LESSON','Chuyển động thẳng biến đổi đều','Cơ học: chuyển động, lực và năng lượng','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Khi gia tốc không đổi, vận tốc v = v₀ + at. Công thức dùng vận tốc có dấu trong cùng một hệ quy chiếu; nhanh dần hay chậm dần phải xét cả v và a."]'::jsonb,'["Xe có v₀ = 3 m/s, a = 2 m/s². Sau 4 s, v = 3 + 2 × 4 = 11 m/s."]'::jsonb,'[{"id": "physics-10-uniform-acceleration-q1", "prompt": "Trong chuyển động thẳng biến đổi đều, đại lượng nào không đổi?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tọa độ"}, {"id": "b", "text": "Gia tốc"}, {"id": "c", "text": "Vận tốc"}], "correctOptionId": "b", "explanation": "Biến đổi đều nghĩa vận tốc thay đổi những lượng bằng nhau trong các khoảng thời gian bằng nhau: a không đổi."}, {"id": "physics-10-uniform-acceleration-q2", "prompt": "Vật có v₀ = 2 m/s, a = 3 m/s². Sau 2 s, v bằng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "8 m/s"}, {"id": "b", "text": "6 m/s"}, {"id": "c", "text": "10 m/s"}], "correctOptionId": "a", "explanation": "v = v₀ + at = 2 + 3 × 2 = 8 m/s."}, {"id": "physics-10-uniform-acceleration-q3", "prompt": "Xe có v₀ = 12 m/s, a = −3 m/s² không đổi. Sau bao lâu xe dừng lần đầu?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "9 s"}, {"id": "b", "text": "36 s"}, {"id": "c", "text": "4 s"}], "correctOptionId": "c", "explanation": "Đặt v = 0: 0 = 12 − 3t, suy ra t = 4 s. Công thức đang xét đến thời điểm dừng."}]'::jsonb,'["physics-10-uniform-acceleration"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('physics',10,'intro-2026.1','physics-10-motion-displacement',8,'LESSON','Độ dịch chuyển khi gia tốc không đổi','Cơ học: chuyển động, lực và năng lượng','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Chuyển động thẳng gia tốc không đổi có Δx = v₀t + at²/2. Độ dịch chuyển có thể khác quãng đường nếu vật đổi chiều trong khoảng xét."]'::jsonb,'["Vật xuất phát nghỉ, a = 2 m/s² trong 3 s: Δx = 0 + 2 × 3²/2 = 9 m; vật không đổi chiều nên quãng đường cũng là 9 m."]'::jsonb,'[{"id": "physics-10-motion-displacement-q1", "prompt": "Xuất phát nghỉ, gia tốc không đổi: độ dịch chuyển sau t là?", "difficulty": "EASY", "options": [{"id": "a", "text": "at²/2"}, {"id": "b", "text": "at"}, {"id": "c", "text": "a/t"}], "correctOptionId": "a", "explanation": "Thay v₀ = 0 vào Δx = v₀t + at²/2."}, {"id": "physics-10-motion-displacement-q2", "prompt": "Vật xuất phát nghỉ, a = 4 m/s² trong 2 s. Độ dịch chuyển là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "4 m"}, {"id": "b", "text": "16 m"}, {"id": "c", "text": "8 m"}], "correctOptionId": "c", "explanation": "Δx = 4 × 2²/2 = 8 m."}, {"id": "physics-10-motion-displacement-q3", "prompt": "Xe có v₀ = 6 m/s, a = −2 m/s². Đến lúc dừng lần đầu, xe đi được?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "3 m"}, {"id": "b", "text": "9 m"}, {"id": "c", "text": "18 m"}], "correctOptionId": "b", "explanation": "Thời gian dừng t = 6/2 = 3 s. Δx = 6 × 3 − 2 × 3²/2 = 9 m. Chưa đổi chiều nên quãng đường bằng 9 m."}]'::jsonb,'["physics-10-motion-displacement"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('physics',10,'intro-2026.1','physics-10-velocity-graph',9,'LESSON','Đọc đồ thị vận tốc – thời gian','Cơ học: chuyển động, lực và năng lượng','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Trên đồ thị v–t, hệ số góc cho gia tốc. Diện tích có dấu giữa đường biểu diễn và trục thời gian cho độ dịch chuyển; phần dưới trục mang dấu âm."]'::jsonb,'["v tăng đều từ 0 lên 6 m/s trong 3 s. Diện tích tam giác cho Δx = 3 × 6/2 = 9 m; a = 6/3 = 2 m/s²."]'::jsonb,'[{"id": "physics-10-velocity-graph-q1", "prompt": "Độ dốc của đồ thị v–t biểu thị?", "difficulty": "EASY", "options": [{"id": "a", "text": "Khối lượng"}, {"id": "b", "text": "Lực luôn bằng 0"}, {"id": "c", "text": "Gia tốc"}], "correctOptionId": "c", "explanation": "Độ dốc là Δv/Δt, chính là gia tốc trung bình trên đoạn xét."}, {"id": "physics-10-velocity-graph-q2", "prompt": "Đồ thị có v = 4 m/s không đổi trong 5 s. Độ dịch chuyển là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "9 m"}, {"id": "b", "text": "20 m"}, {"id": "c", "text": "1,25 m"}], "correctOptionId": "b", "explanation": "Diện tích hình chữ nhật v × t = 4 × 5 = 20 m."}, {"id": "physics-10-velocity-graph-q3", "prompt": "Trong 2 s đầu v = +3 m/s, 2 s sau v = −3 m/s. Độ dịch chuyển toàn khoảng là?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "0 m"}, {"id": "b", "text": "12 m"}, {"id": "c", "text": "6 m"}], "correctOptionId": "a", "explanation": "Cộng diện tích có dấu: 3 × 2 + (−3) × 2 = 0 m. Quãng đường là 12 m."}]'::jsonb,'["physics-10-velocity-graph"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('physics',10,'intro-2026.1','physics-10-free-fall',10,'LESSON','Rơi tự do gần mặt đất','Cơ học: chuyển động, lực và năng lượng','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Rơi tự do là chuyển động chỉ chịu trọng lực. Gần mặt đất, bỏ qua sức cản và coi g không đổi; chọn chiều xuống dương thì vật thả nghỉ có v = gt, s = gt²/2."]'::jsonb,'["Lấy g = 10 m/s², thả nghỉ trong 2 s: v = 20 m/s hướng xuống và s = 20 m."]'::jsonb,'[{"id": "physics-10-free-fall-q1", "prompt": "Mô hình rơi tự do bỏ qua yếu tố nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Gia tốc rơi"}, {"id": "b", "text": "Sức cản không khí"}, {"id": "c", "text": "Trọng lực"}], "correctOptionId": "b", "explanation": "Vật chỉ chịu trọng lực; khi sức cản đáng kể thì mô hình này không còn phù hợp."}, {"id": "physics-10-free-fall-q2", "prompt": "Thả nghỉ, g = 10 m/s². Sau 1 s, tốc độ là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "10 m/s"}, {"id": "b", "text": "5 m/s"}, {"id": "c", "text": "20 m/s"}], "correctOptionId": "a", "explanation": "v = gt = 10 × 1 = 10 m/s."}, {"id": "physics-10-free-fall-q3", "prompt": "Thả nghỉ từ độ cao 45 m, g = 10 m/s², bỏ qua sức cản. Thời gian chạm đất là?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "4,5 s"}, {"id": "b", "text": "9 s"}, {"id": "c", "text": "3 s"}], "correctOptionId": "c", "explanation": "45 = 10t²/2 = 5t², nên t² = 9, chọn t = 3 s."}]'::jsonb,'["physics-10-free-fall"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('physics',10,'intro-2026.1','physics-10-horizontal-launch',11,'LESSON','Ném ngang: tách hai phương','Cơ học: chuyển động, lực và năng lượng','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Bỏ qua sức cản: phương ngang chuyển động đều, phương đứng rơi tự do. Hai phương dùng cùng thời gian; t = √(2h/g), tầm ngang L = v₀t khi vật được ném ngang từ độ cao h."]'::jsonb,'["Ném ngang ở h = 20 m, v₀ = 5 m/s, g = 10 m/s²: t = 2 s, L = 10 m."]'::jsonb,'[{"id": "physics-10-horizontal-launch-q1", "prompt": "Bỏ qua sức cản, vận tốc theo phương ngang của vật ném ngang?", "difficulty": "EASY", "options": [{"id": "a", "text": "Không đổi"}, {"id": "b", "text": "Luôn bằng 0"}, {"id": "c", "text": "Tăng do trọng lực"}], "correctOptionId": "a", "explanation": "Trọng lực thẳng đứng nên gia tốc ngang bằng 0."}, {"id": "physics-10-horizontal-launch-q2", "prompt": "Ném ngang v₀ = 6 m/s, thời gian bay 2 s. Tầm ngang là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "3 m"}, {"id": "b", "text": "8 m"}, {"id": "c", "text": "12 m"}], "correctOptionId": "c", "explanation": "L = v₀t = 6 × 2 = 12 m."}, {"id": "physics-10-horizontal-launch-q3", "prompt": "Hai vật cùng độ cao: một thả nghỉ, một ném ngang cùng lúc. Bỏ qua sức cản, mặt đất phẳng. Vật nào chạm đất trước?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Vật thả nghỉ"}, {"id": "b", "text": "Cùng lúc"}, {"id": "c", "text": "Vật ném ngang"}], "correctOptionId": "b", "explanation": "Cả hai có vận tốc đứng ban đầu bằng 0 và cùng gia tốc g nên có cùng thời gian rơi."}]'::jsonb,'["physics-10-horizontal-launch"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('physics',10,'intro-2026.1','physics-10-review-2',12,'FIVE_LESSON_REVIEW','Ôn tập 2','Cơ học: chuyển động, lực và năng lượng','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "physics-10-uniform-acceleration-q1", "prompt": "Trong chuyển động thẳng biến đổi đều, đại lượng nào không đổi?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tọa độ"}, {"id": "b", "text": "Gia tốc"}, {"id": "c", "text": "Vận tốc"}], "correctOptionId": "b", "explanation": "Biến đổi đều nghĩa vận tốc thay đổi những lượng bằng nhau trong các khoảng thời gian bằng nhau: a không đổi."}, {"id": "physics-10-uniform-acceleration-q2", "prompt": "Vật có v₀ = 2 m/s, a = 3 m/s². Sau 2 s, v bằng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "8 m/s"}, {"id": "b", "text": "6 m/s"}, {"id": "c", "text": "10 m/s"}], "correctOptionId": "a", "explanation": "v = v₀ + at = 2 + 3 × 2 = 8 m/s."}, {"id": "physics-10-motion-displacement-q1", "prompt": "Xuất phát nghỉ, gia tốc không đổi: độ dịch chuyển sau t là?", "difficulty": "EASY", "options": [{"id": "a", "text": "at²/2"}, {"id": "b", "text": "at"}, {"id": "c", "text": "a/t"}], "correctOptionId": "a", "explanation": "Thay v₀ = 0 vào Δx = v₀t + at²/2."}, {"id": "physics-10-motion-displacement-q2", "prompt": "Vật xuất phát nghỉ, a = 4 m/s² trong 2 s. Độ dịch chuyển là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "4 m"}, {"id": "b", "text": "16 m"}, {"id": "c", "text": "8 m"}], "correctOptionId": "c", "explanation": "Δx = 4 × 2²/2 = 8 m."}, {"id": "physics-10-velocity-graph-q1", "prompt": "Độ dốc của đồ thị v–t biểu thị?", "difficulty": "EASY", "options": [{"id": "a", "text": "Khối lượng"}, {"id": "b", "text": "Lực luôn bằng 0"}, {"id": "c", "text": "Gia tốc"}], "correctOptionId": "c", "explanation": "Độ dốc là Δv/Δt, chính là gia tốc trung bình trên đoạn xét."}, {"id": "physics-10-velocity-graph-q2", "prompt": "Đồ thị có v = 4 m/s không đổi trong 5 s. Độ dịch chuyển là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "9 m"}, {"id": "b", "text": "20 m"}, {"id": "c", "text": "1,25 m"}], "correctOptionId": "b", "explanation": "Diện tích hình chữ nhật v × t = 4 × 5 = 20 m."}, {"id": "physics-10-free-fall-q1", "prompt": "Mô hình rơi tự do bỏ qua yếu tố nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Gia tốc rơi"}, {"id": "b", "text": "Sức cản không khí"}, {"id": "c", "text": "Trọng lực"}], "correctOptionId": "b", "explanation": "Vật chỉ chịu trọng lực; khi sức cản đáng kể thì mô hình này không còn phù hợp."}, {"id": "physics-10-free-fall-q2", "prompt": "Thả nghỉ, g = 10 m/s². Sau 1 s, tốc độ là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "10 m/s"}, {"id": "b", "text": "5 m/s"}, {"id": "c", "text": "20 m/s"}], "correctOptionId": "a", "explanation": "v = gt = 10 × 1 = 10 m/s."}, {"id": "physics-10-horizontal-launch-q1", "prompt": "Bỏ qua sức cản, vận tốc theo phương ngang của vật ném ngang?", "difficulty": "EASY", "options": [{"id": "a", "text": "Không đổi"}, {"id": "b", "text": "Luôn bằng 0"}, {"id": "c", "text": "Tăng do trọng lực"}], "correctOptionId": "a", "explanation": "Trọng lực thẳng đứng nên gia tốc ngang bằng 0."}, {"id": "physics-10-horizontal-launch-q2", "prompt": "Ném ngang v₀ = 6 m/s, thời gian bay 2 s. Tầm ngang là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "3 m"}, {"id": "b", "text": "8 m"}, {"id": "c", "text": "12 m"}], "correctOptionId": "c", "explanation": "L = v₀t = 6 × 2 = 12 m."}]'::jsonb,'["physics-10-uniform-acceleration", "physics-10-motion-displacement", "physics-10-velocity-graph", "physics-10-free-fall", "physics-10-horizontal-launch"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('physics',10,'intro-2026.1','physics-10-force-resultant',13,'LESSON','Lực và hợp lực','Cơ học: chuyển động, lực và năng lượng','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Lực là đại lượng vectơ. Các lực cùng phương cùng chiều cộng độ lớn; ngược chiều lấy hiệu và chiều theo lực lớn hơn. Hợp lực quyết định gia tốc, không phải từng lực riêng lẻ."]'::jsonb,'["Kéo sang phải 8 N, sang trái 3 N: hợp lực 5 N sang phải."]'::jsonb,'[{"id": "physics-10-force-resultant-q1", "prompt": "Lực có cả độ lớn và chiều nên là đại lượng?", "difficulty": "EASY", "options": [{"id": "a", "text": "Chỉ là số không có đơn vị"}, {"id": "b", "text": "Luôn dương theo mọi trục"}, {"id": "c", "text": "Vectơ"}], "correctOptionId": "c", "explanation": "Biểu diễn lực cần độ lớn, phương, chiều và điểm đặt."}, {"id": "physics-10-force-resultant-q2", "prompt": "Hai lực cùng chiều có độ lớn 4 N và 6 N. Hợp lực bằng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "24 N"}, {"id": "b", "text": "10 N"}, {"id": "c", "text": "2 N"}], "correctOptionId": "b", "explanation": "Cùng phương cùng chiều nên F = 4 + 6 = 10 N."}, {"id": "physics-10-force-resultant-q3", "prompt": "Hai lực ngang 12 N sang phải, 7 N sang trái. Hợp lực là?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "5 N sang phải"}, {"id": "b", "text": "19 N sang trái"}, {"id": "c", "text": "5 N sang trái"}], "correctOptionId": "a", "explanation": "Chọn chiều phải dương: F = 12 − 7 = +5 N, tức sang phải."}]'::jsonb,'["physics-10-force-resultant"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('physics',10,'intro-2026.1','physics-10-inertia',14,'LESSON','Quán tính và định luật I Newton','Cơ học: chuyển động, lực và năng lượng','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Trong hệ quy chiếu quán tính, khi hợp lực bằng 0, vật giữ nguyên trạng thái đứng yên hoặc chuyển động thẳng đều. Không cần lực cùng chiều vận tốc để duy trì chuyển động thẳng đều."]'::jsonb,'["Xe phanh, cơ thể có xu hướng tiếp tục chuyển động về trước do quán tính; dây an toàn tạo lực giúp người giảm tốc cùng xe."]'::jsonb,'[{"id": "physics-10-inertia-q1", "prompt": "Hợp lực bằng 0, một vật đang chuyển động sẽ?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tự tăng tốc"}, {"id": "b", "text": "Tiếp tục thẳng đều trong hệ quán tính"}, {"id": "c", "text": "Dừng ngay"}], "correctOptionId": "b", "explanation": "Định luật I: vận tốc không đổi khi hợp lực bằng 0 trong hệ quán tính."}, {"id": "physics-10-inertia-q2", "prompt": "Sách nằm yên trên bàn: trọng lực và lực đỡ có hợp lực?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Bằng 0"}, {"id": "b", "text": "Bằng hai lần trọng lực"}, {"id": "c", "text": "Luôn hướng xuống"}], "correctOptionId": "a", "explanation": "Hai lực cân bằng theo phương đứng nên sách không có gia tốc."}, {"id": "physics-10-inertia-q3", "prompt": "Vì sao hành khách nghiêng về trước khi xe phanh?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Có lực bí ẩn luôn đẩy người về trước"}, {"id": "b", "text": "Trọng lực đột ngột biến mất"}, {"id": "c", "text": "Cơ thể có xu hướng giữ vận tốc trước đó"}], "correctOptionId": "c", "explanation": "Do quán tính, cơ thể chưa giảm vận tốc ngay như xe; dây an toàn giúp giảm tốc an toàn."}]'::jsonb,'["physics-10-inertia"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('physics',10,'intro-2026.1','physics-10-newton-second',15,'LESSON','Định luật II Newton','Cơ học: chuyển động, lực và năng lượng','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Trong hệ quán tính, hợp lực F = ma đối với vật có khối lượng không đổi. Gia tốc cùng chiều hợp lực; đơn vị N = kg·m/s²."]'::jsonb,'["Hợp lực ngang 6 N tác dụng lên vật 2 kg: a = 6/2 = 3 m/s² theo chiều hợp lực."]'::jsonb,'[{"id": "physics-10-newton-second-q1", "prompt": "Trong F = ma, F là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Hợp lực tác dụng lên vật"}, {"id": "b", "text": "Chỉ lực lớn nhất"}, {"id": "c", "text": "Luôn là trọng lực"}], "correctOptionId": "a", "explanation": "Phải cộng vectơ tất cả lực để tìm hợp lực trước khi tính gia tốc."}, {"id": "physics-10-newton-second-q2", "prompt": "Hợp lực 8 N, khối lượng 4 kg. Gia tốc bằng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "32 m/s²"}, {"id": "b", "text": "0,5 m/s²"}, {"id": "c", "text": "2 m/s²"}], "correctOptionId": "c", "explanation": "a = F/m = 8/4 = 2 m/s²."}, {"id": "physics-10-newton-second-q3", "prompt": "Vật 2 kg chịu lực 10 N sang phải và 4 N sang trái. Gia tốc là?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "3 m/s² sang trái"}, {"id": "b", "text": "3 m/s² sang phải"}, {"id": "c", "text": "7 m/s² sang phải"}], "correctOptionId": "b", "explanation": "Hợp lực 10 − 4 = 6 N sang phải; a = 6/2 = 3 m/s²."}]'::jsonb,'["physics-10-newton-second"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('physics',10,'intro-2026.1','physics-10-newton-third',16,'LESSON','Lực và phản lực','Cơ học: chuyển động, lực và năng lượng','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Hai vật tương tác tác dụng lên nhau hai lực cùng phương, ngược chiều, bằng độ lớn. Hai lực đặt lên hai vật khác nhau nên không phải cặp lực cân bằng trên một vật."]'::jsonb,'["Tay đẩy tường 20 N thì tường đẩy tay 20 N theo chiều ngược lại, dù tường không chuyển động thấy rõ."]'::jsonb,'[{"id": "physics-10-newton-third-q1", "prompt": "Lực và phản lực tác dụng lên?", "difficulty": "EASY", "options": [{"id": "a", "text": "Cùng một vật"}, {"id": "b", "text": "Chỉ vật nặng hơn"}, {"id": "c", "text": "Hai vật khác nhau"}], "correctOptionId": "c", "explanation": "Định luật III mô tả hai lực của cùng tương tác nhưng đặt trên hai vật."}, {"id": "physics-10-newton-third-q2", "prompt": "Chân đẩy đất về sau khi đi bộ. Đất tác dụng lên chân theo chiều nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Không có lực"}, {"id": "b", "text": "Về trước"}, {"id": "c", "text": "Về sau"}], "correctOptionId": "b", "explanation": "Đất tác dụng lực ma sát về trước lên chân, đối ứng lực chân đẩy đất về sau."}, {"id": "physics-10-newton-third-q3", "prompt": "Xe tải và xe nhỏ va chạm. Lực tương tác hai xe trong cùng thời điểm thế nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Bằng độ lớn, ngược chiều"}, {"id": "b", "text": "Xe tải luôn tác dụng lực lớn hơn"}, {"id": "c", "text": "Xe nhỏ không tác dụng lực"}], "correctOptionId": "a", "explanation": "Lực bằng nhau theo định luật III; gia tốc và biến dạng có thể khác do khối lượng và cấu trúc khác."}]'::jsonb,'["physics-10-newton-third"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('physics',10,'intro-2026.1','physics-10-weight-normal',17,'LESSON','Trọng lực và lực đỡ','Cơ học: chuyển động, lực và năng lượng','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Trọng lực gần mặt đất có độ lớn P = mg, hướng xuống. Lực đỡ vuông góc mặt tiếp xúc. N = mg chỉ đúng trong những điều kiện cân bằng đứng phù hợp, không phải mọi tình huống."]'::jsonb,'["Sách 0,5 kg nằm yên trên bàn ngang, chỉ có trọng lực và lực đỡ theo phương đứng. Lấy g = 10 m/s²: P = N = 5 N."]'::jsonb,'[{"id": "physics-10-weight-normal-q1", "prompt": "Công thức độ lớn trọng lực gần mặt đất là?", "difficulty": "EASY", "options": [{"id": "a", "text": "P = g/m"}, {"id": "b", "text": "P = mg"}, {"id": "c", "text": "P = m/g"}], "correctOptionId": "b", "explanation": "Với g tại nơi xét, trọng lực có độ lớn bằng khối lượng nhân gia tốc trọng trường."}, {"id": "physics-10-weight-normal-q2", "prompt": "Vật 3 kg, g = 10 m/s². Trọng lực bằng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "30 N"}, {"id": "b", "text": "3 N"}, {"id": "c", "text": "0,3 N"}], "correctOptionId": "a", "explanation": "P = 3 × 10 = 30 N."}, {"id": "physics-10-weight-normal-q3", "prompt": "Ấn thêm lực 4 N xuống sách đang yên trên bàn ngang. Sách có P = 6 N. Lực đỡ bằng?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "6 N"}, {"id": "b", "text": "2 N"}, {"id": "c", "text": "10 N"}], "correctOptionId": "c", "explanation": "Cân bằng đứng: N − 6 − 4 = 0, nên N = 10 N; không thể mặc định N = P."}]'::jsonb,'["physics-10-weight-normal"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('physics',10,'intro-2026.1','physics-10-review-3',18,'FIVE_LESSON_REVIEW','Ôn tập 3','Cơ học: chuyển động, lực và năng lượng','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "physics-10-force-resultant-q1", "prompt": "Lực có cả độ lớn và chiều nên là đại lượng?", "difficulty": "EASY", "options": [{"id": "a", "text": "Chỉ là số không có đơn vị"}, {"id": "b", "text": "Luôn dương theo mọi trục"}, {"id": "c", "text": "Vectơ"}], "correctOptionId": "c", "explanation": "Biểu diễn lực cần độ lớn, phương, chiều và điểm đặt."}, {"id": "physics-10-force-resultant-q2", "prompt": "Hai lực cùng chiều có độ lớn 4 N và 6 N. Hợp lực bằng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "24 N"}, {"id": "b", "text": "10 N"}, {"id": "c", "text": "2 N"}], "correctOptionId": "b", "explanation": "Cùng phương cùng chiều nên F = 4 + 6 = 10 N."}, {"id": "physics-10-inertia-q1", "prompt": "Hợp lực bằng 0, một vật đang chuyển động sẽ?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tự tăng tốc"}, {"id": "b", "text": "Tiếp tục thẳng đều trong hệ quán tính"}, {"id": "c", "text": "Dừng ngay"}], "correctOptionId": "b", "explanation": "Định luật I: vận tốc không đổi khi hợp lực bằng 0 trong hệ quán tính."}, {"id": "physics-10-inertia-q2", "prompt": "Sách nằm yên trên bàn: trọng lực và lực đỡ có hợp lực?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Bằng 0"}, {"id": "b", "text": "Bằng hai lần trọng lực"}, {"id": "c", "text": "Luôn hướng xuống"}], "correctOptionId": "a", "explanation": "Hai lực cân bằng theo phương đứng nên sách không có gia tốc."}, {"id": "physics-10-newton-second-q1", "prompt": "Trong F = ma, F là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Hợp lực tác dụng lên vật"}, {"id": "b", "text": "Chỉ lực lớn nhất"}, {"id": "c", "text": "Luôn là trọng lực"}], "correctOptionId": "a", "explanation": "Phải cộng vectơ tất cả lực để tìm hợp lực trước khi tính gia tốc."}, {"id": "physics-10-newton-second-q2", "prompt": "Hợp lực 8 N, khối lượng 4 kg. Gia tốc bằng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "32 m/s²"}, {"id": "b", "text": "0,5 m/s²"}, {"id": "c", "text": "2 m/s²"}], "correctOptionId": "c", "explanation": "a = F/m = 8/4 = 2 m/s²."}, {"id": "physics-10-newton-third-q1", "prompt": "Lực và phản lực tác dụng lên?", "difficulty": "EASY", "options": [{"id": "a", "text": "Cùng một vật"}, {"id": "b", "text": "Chỉ vật nặng hơn"}, {"id": "c", "text": "Hai vật khác nhau"}], "correctOptionId": "c", "explanation": "Định luật III mô tả hai lực của cùng tương tác nhưng đặt trên hai vật."}, {"id": "physics-10-newton-third-q2", "prompt": "Chân đẩy đất về sau khi đi bộ. Đất tác dụng lên chân theo chiều nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Không có lực"}, {"id": "b", "text": "Về trước"}, {"id": "c", "text": "Về sau"}], "correctOptionId": "b", "explanation": "Đất tác dụng lực ma sát về trước lên chân, đối ứng lực chân đẩy đất về sau."}, {"id": "physics-10-weight-normal-q1", "prompt": "Công thức độ lớn trọng lực gần mặt đất là?", "difficulty": "EASY", "options": [{"id": "a", "text": "P = g/m"}, {"id": "b", "text": "P = mg"}, {"id": "c", "text": "P = m/g"}], "correctOptionId": "b", "explanation": "Với g tại nơi xét, trọng lực có độ lớn bằng khối lượng nhân gia tốc trọng trường."}, {"id": "physics-10-weight-normal-q2", "prompt": "Vật 3 kg, g = 10 m/s². Trọng lực bằng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "30 N"}, {"id": "b", "text": "3 N"}, {"id": "c", "text": "0,3 N"}], "correctOptionId": "a", "explanation": "P = 3 × 10 = 30 N."}]'::jsonb,'["physics-10-force-resultant", "physics-10-inertia", "physics-10-newton-second", "physics-10-newton-third", "physics-10-weight-normal"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('physics',10,'intro-2026.1','physics-10-sliding-friction',19,'LESSON','Ma sát trượt','Cơ học: chuyển động, lực và năng lượng','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Trong mô hình đơn giản, ma sát trượt F = μN, ngược chiều trượt tương đối giữa hai mặt. Hệ số μ không có đơn vị; công thức này không mô tả mọi trường hợp ma sát nghỉ."]'::jsonb,'["Vật trượt trên bàn, N = 20 N và μ = 0,2: ma sát trượt 4 N, ngược chiều trượt."]'::jsonb,'[{"id": "physics-10-sliding-friction-q1", "prompt": "Ma sát trượt trên vật có chiều?", "difficulty": "EASY", "options": [{"id": "a", "text": "Ngược chiều trượt tương đối"}, {"id": "b", "text": "Luôn cùng chiều trượt"}, {"id": "c", "text": "Luôn thẳng đứng"}], "correctOptionId": "a", "explanation": "Cần xét chuyển động tương đối tại chỗ tiếp xúc, không chỉ hướng chuyển động so với đất."}, {"id": "physics-10-sliding-friction-q2", "prompt": "μ = 0,3; N = 10 N. Ma sát trượt có độ lớn?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "30 N"}, {"id": "b", "text": "0,03 N"}, {"id": "c", "text": "3 N"}], "correctOptionId": "c", "explanation": "F = μN = 0,3 × 10 = 3 N."}, {"id": "physics-10-sliding-friction-q3", "prompt": "Vật đang trượt sang phải, kéo 9 N sang phải, ma sát 3 N sang trái, m = 2 kg. Gia tốc là?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "3 m/s² sang trái"}, {"id": "b", "text": "3 m/s² sang phải"}, {"id": "c", "text": "6 m/s² sang phải"}], "correctOptionId": "b", "explanation": "Hợp lực ngang 9 − 3 = 6 N, a = 6/2 = 3 m/s² sang phải."}]'::jsonb,'["physics-10-sliding-friction"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('physics',10,'intro-2026.1','physics-10-work',20,'LESSON','Công của lực không đổi','Cơ học: chuyển động, lực và năng lượng','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Công A = Fs cosα khi lực không đổi, α là góc giữa lực và độ dịch chuyển thẳng. Công dương hỗ trợ chuyển động, âm cản chuyển động; lực vuông góc độ dịch chuyển có công bằng 0."]'::jsonb,'["Kéo vật đi 3 m bằng lực 5 N cùng chiều: A = 5 × 3 = 15 J."]'::jsonb,'[{"id": "physics-10-work-q1", "prompt": "Đơn vị SI của công là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Watt (W)"}, {"id": "b", "text": "Newton (N)"}, {"id": "c", "text": "Joule (J)"}], "correctOptionId": "c", "explanation": "1 J = 1 N·m; watt là đơn vị công suất."}, {"id": "physics-10-work-q2", "prompt": "Lực 4 N cùng chiều dịch chuyển 2 m. Công bằng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "16 J"}, {"id": "b", "text": "8 J"}, {"id": "c", "text": "2 J"}], "correctOptionId": "b", "explanation": "α = 0°, cosα = 1, nên A = 4 × 2 = 8 J."}, {"id": "physics-10-work-q3", "prompt": "Lực ma sát 2 N ngược chiều vật trượt 5 m. Công của ma sát là?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "−10 J"}, {"id": "b", "text": "+10 J"}, {"id": "c", "text": "0 J"}], "correctOptionId": "a", "explanation": "Góc 180° có cosα = −1, nên A = 2 × 5 × (−1) = −10 J."}]'::jsonb,'["physics-10-work"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('physics',10,'intro-2026.1','physics-10-power',21,'LESSON','Công suất','Cơ học: chuyển động, lực và năng lượng','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Công suất trung bình bằng công thực hiện chia thời gian: P = A/t. Công suất lớn nghĩa truyền năng lượng nhanh hơn, không nhất thiết tổng năng lượng lớn hơn."]'::jsonb,'["Máy thực hiện công 600 J trong 3 s có công suất trung bình 200 W."]'::jsonb,'[{"id": "physics-10-power-q1", "prompt": "Công suất đo tốc độ thực hiện?", "difficulty": "EASY", "options": [{"id": "a", "text": "Khối lượng"}, {"id": "b", "text": "Công hoặc truyền năng lượng"}, {"id": "c", "text": "Chỉ quãng đường"}], "correctOptionId": "b", "explanation": "Công suất là năng lượng truyền trong một đơn vị thời gian."}, {"id": "physics-10-power-q2", "prompt": "Thực hiện 1000 J trong 5 s. Công suất trung bình là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "200 W"}, {"id": "b", "text": "5000 W"}, {"id": "c", "text": "5 W"}], "correctOptionId": "a", "explanation": "P = 1000/5 = 200 W."}, {"id": "physics-10-power-q3", "prompt": "Hai máy cùng thực hiện 1200 J. Máy A mất 4 s, máy B mất 6 s. Nhận xét đúng?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "B có công suất lớn hơn A"}, {"id": "b", "text": "Hai máy công suất bằng nhau"}, {"id": "c", "text": "A có công suất lớn hơn B"}], "correctOptionId": "c", "explanation": "P_A = 300 W; P_B = 200 W. Cùng công nhưng A thực hiện nhanh hơn."}]'::jsonb,'["physics-10-power"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('physics',10,'intro-2026.1','physics-10-kinetic-potential',22,'LESSON','Động năng và thế năng trọng trường','Cơ học: chuyển động, lực và năng lượng','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Động năng Wđ = mv²/2. Thế năng trọng trường Wt = mgh gần mặt đất, với h tính từ mốc chọn; thế năng phụ thuộc mốc nhưng độ biến thiên giữa hai vị trí không phụ thuộc mốc."]'::jsonb,'["Vật 2 kg chạy 3 m/s có Wđ = 9 J. Cũng vật đó ở cao 1 m so với mốc, g = 10 m/s²: Wt = 20 J."]'::jsonb,'[{"id": "physics-10-kinetic-potential-q1", "prompt": "Giữ m không đổi, tốc độ tăng gấp đôi thì động năng?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tăng gấp bốn"}, {"id": "b", "text": "Tăng gấp đôi"}, {"id": "c", "text": "Không đổi"}], "correctOptionId": "a", "explanation": "Động năng tỉ lệ v² nên (2v)² = 4v²."}, {"id": "physics-10-kinetic-potential-q2", "prompt": "Vật 2 kg chuyển động 4 m/s. Động năng bằng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "8 J"}, {"id": "b", "text": "32 J"}, {"id": "c", "text": "16 J"}], "correctOptionId": "c", "explanation": "Wđ = 2 × 4²/2 = 16 J."}, {"id": "physics-10-kinetic-potential-q3", "prompt": "Vật 1 kg được nâng từ h = 1 m lên h = 3 m, g = 10 m/s². Thế năng tăng bao nhiêu?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "10 J"}, {"id": "b", "text": "20 J"}, {"id": "c", "text": "30 J"}], "correctOptionId": "b", "explanation": "ΔWt = mg(h₂ − h₁) = 1 × 10 × (3 − 1) = 20 J."}]'::jsonb,'["physics-10-kinetic-potential"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('physics',10,'intro-2026.1','physics-10-mechanical-energy',23,'LESSON','Bảo toàn cơ năng','Cơ học: chuyển động, lực và năng lượng','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','["Cơ năng bằng tổng động năng và thế năng. Khi chỉ trọng lực sinh công, cơ năng bảo toàn. Có ma sát sinh công thì một phần cơ năng chuyển thành nội năng; không thể áp dụng bảo toàn cơ năng máy móc."]'::jsonb,'["Thả nghỉ từ h = 5 m, g = 10 m/s², không có sức cản: mgh = mv²/2 tại đất, nên v = √(2gh) = 10 m/s."]'::jsonb,'[{"id": "physics-10-mechanical-energy-q1", "prompt": "Cơ năng trong trọng trường là tổng?", "difficulty": "EASY", "options": [{"id": "a", "text": "Khối lượng và tốc độ"}, {"id": "b", "text": "Công suất và thời gian"}, {"id": "c", "text": "Động năng và thế năng trọng trường"}], "correctOptionId": "c", "explanation": "Hai dạng năng lượng cơ học có thể chuyển hóa lẫn nhau."}, {"id": "physics-10-mechanical-energy-q2", "prompt": "Cơ năng 30 J, thế năng 12 J. Động năng bằng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "2,5 J"}, {"id": "b", "text": "18 J"}, {"id": "c", "text": "42 J"}], "correctOptionId": "b", "explanation": "Wđ = W − Wt = 30 − 12 = 18 J."}, {"id": "physics-10-mechanical-energy-q3", "prompt": "Vật thả nghỉ từ h = 20 m, g = 10 m/s², bỏ qua sức cản. Tốc độ ngay trước chạm đất là?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "20 m/s"}, {"id": "b", "text": "10 m/s"}, {"id": "c", "text": "40 m/s"}], "correctOptionId": "a", "explanation": "Bảo toàn cơ năng: v = √(2gh) = √400 = 20 m/s, lấy độ lớn dương."}]'::jsonb,'["physics-10-mechanical-energy"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('physics',10,'intro-2026.1','physics-10-review-4',24,'FIVE_LESSON_REVIEW','Ôn tập 4','Cơ học: chuyển động, lực và năng lượng','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "physics-10-sliding-friction-q1", "prompt": "Ma sát trượt trên vật có chiều?", "difficulty": "EASY", "options": [{"id": "a", "text": "Ngược chiều trượt tương đối"}, {"id": "b", "text": "Luôn cùng chiều trượt"}, {"id": "c", "text": "Luôn thẳng đứng"}], "correctOptionId": "a", "explanation": "Cần xét chuyển động tương đối tại chỗ tiếp xúc, không chỉ hướng chuyển động so với đất."}, {"id": "physics-10-sliding-friction-q2", "prompt": "μ = 0,3; N = 10 N. Ma sát trượt có độ lớn?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "30 N"}, {"id": "b", "text": "0,03 N"}, {"id": "c", "text": "3 N"}], "correctOptionId": "c", "explanation": "F = μN = 0,3 × 10 = 3 N."}, {"id": "physics-10-work-q1", "prompt": "Đơn vị SI của công là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Watt (W)"}, {"id": "b", "text": "Newton (N)"}, {"id": "c", "text": "Joule (J)"}], "correctOptionId": "c", "explanation": "1 J = 1 N·m; watt là đơn vị công suất."}, {"id": "physics-10-work-q2", "prompt": "Lực 4 N cùng chiều dịch chuyển 2 m. Công bằng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "16 J"}, {"id": "b", "text": "8 J"}, {"id": "c", "text": "2 J"}], "correctOptionId": "b", "explanation": "α = 0°, cosα = 1, nên A = 4 × 2 = 8 J."}, {"id": "physics-10-power-q1", "prompt": "Công suất đo tốc độ thực hiện?", "difficulty": "EASY", "options": [{"id": "a", "text": "Khối lượng"}, {"id": "b", "text": "Công hoặc truyền năng lượng"}, {"id": "c", "text": "Chỉ quãng đường"}], "correctOptionId": "b", "explanation": "Công suất là năng lượng truyền trong một đơn vị thời gian."}, {"id": "physics-10-power-q2", "prompt": "Thực hiện 1000 J trong 5 s. Công suất trung bình là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "200 W"}, {"id": "b", "text": "5000 W"}, {"id": "c", "text": "5 W"}], "correctOptionId": "a", "explanation": "P = 1000/5 = 200 W."}, {"id": "physics-10-kinetic-potential-q1", "prompt": "Giữ m không đổi, tốc độ tăng gấp đôi thì động năng?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tăng gấp bốn"}, {"id": "b", "text": "Tăng gấp đôi"}, {"id": "c", "text": "Không đổi"}], "correctOptionId": "a", "explanation": "Động năng tỉ lệ v² nên (2v)² = 4v²."}, {"id": "physics-10-kinetic-potential-q2", "prompt": "Vật 2 kg chuyển động 4 m/s. Động năng bằng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "8 J"}, {"id": "b", "text": "32 J"}, {"id": "c", "text": "16 J"}], "correctOptionId": "c", "explanation": "Wđ = 2 × 4²/2 = 16 J."}, {"id": "physics-10-mechanical-energy-q1", "prompt": "Cơ năng trong trọng trường là tổng?", "difficulty": "EASY", "options": [{"id": "a", "text": "Khối lượng và tốc độ"}, {"id": "b", "text": "Công suất và thời gian"}, {"id": "c", "text": "Động năng và thế năng trọng trường"}], "correctOptionId": "c", "explanation": "Hai dạng năng lượng cơ học có thể chuyển hóa lẫn nhau."}, {"id": "physics-10-mechanical-energy-q2", "prompt": "Cơ năng 30 J, thế năng 12 J. Động năng bằng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "2,5 J"}, {"id": "b", "text": "18 J"}, {"id": "c", "text": "42 J"}], "correctOptionId": "b", "explanation": "Wđ = W − Wt = 30 − 12 = 18 J."}]'::jsonb,'["physics-10-sliding-friction", "physics-10-work", "physics-10-power", "physics-10-kinetic-potential", "physics-10-mechanical-energy"]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values('physics',10,'intro-2026.1','placement',0,'PLACEMENT','Khảo sát đầu vào','Cơ học: chuyển động, lực và năng lượng','20 bài ngắn lớp 10 do AI Mentor biên soạn, không phải bản sao SGK hay toàn bộ chương trình năm học. Đầu vào chỉ khảo sát 5 bài nhập môn. Cần giáo viên duyệt trước khi dùng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "physics-10-position-q1", "prompt": "Muốn nói rõ vị trí của một vật, trước hết cần chọn gì?", "difficulty": "EASY", "options": [{"id": "a", "text": "Mốc và hệ tọa độ"}, {"id": "b", "text": "Chỉ khối lượng vật"}, {"id": "c", "text": "Chỉ màu sắc vật"}], "correctOptionId": "a", "explanation": "Vị trí được xác định tương đối với mốc trong hệ tọa độ đã chọn."}, {"id": "physics-10-position-q2", "prompt": "Gốc tại nhà, chiều đông dương. Bạn ở 30 m về tây có tọa độ bao nhiêu?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "+30 m"}, {"id": "b", "text": "0 m"}, {"id": "c", "text": "−30 m"}], "correctOptionId": "c", "explanation": "Phía tây ngược chiều dương nên tọa độ là −30 m."}, {"id": "physics-10-displacement-q1", "prompt": "Đại lượng nào bằng tổng chiều dài đường đã đi?", "difficulty": "EASY", "options": [{"id": "a", "text": "Độ dịch chuyển luôn có dấu"}, {"id": "b", "text": "Gia tốc"}, {"id": "c", "text": "Quãng đường"}], "correctOptionId": "c", "explanation": "Quãng đường cộng chiều dài từng chặng, không trừ chặng đi ngược chiều."}, {"id": "physics-10-displacement-q2", "prompt": "Từ x = −2 m đến x = 4 m, độ dịch chuyển bằng bao nhiêu?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "−6 m"}, {"id": "b", "text": "+6 m"}, {"id": "c", "text": "+2 m"}], "correctOptionId": "b", "explanation": "Δx = 4 − (−2) = +6 m."}, {"id": "physics-10-speed-q1", "prompt": "Công thức tính tốc độ trung bình là?", "difficulty": "EASY", "options": [{"id": "a", "text": "Quãng đường × thời gian"}, {"id": "b", "text": "Tổng quãng đường / tổng thời gian"}, {"id": "c", "text": "Độ dịch chuyển × thời gian"}], "correctOptionId": "b", "explanation": "Tốc độ trung bình dùng tổng quãng đường và tổng thời gian, không lấy trung bình cộng tùy ý các tốc độ."}, {"id": "physics-10-speed-q2", "prompt": "Đi được 150 m trong 30 s, tốc độ trung bình là?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "5 m/s"}, {"id": "b", "text": "0,2 m/s"}, {"id": "c", "text": "4500 m/s"}], "correctOptionId": "a", "explanation": "v = s/t = 150/30 = 5 m/s."}, {"id": "physics-10-velocity-q1", "prompt": "Vận tốc trung bình được tính từ đại lượng nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Độ dịch chuyển và thời gian"}, {"id": "b", "text": "Chỉ quãng đường"}, {"id": "c", "text": "Chỉ khối lượng"}], "correctOptionId": "a", "explanation": "Vận tốc trung bình là Δx/Δt trong chuyển động thẳng."}, {"id": "physics-10-velocity-q2", "prompt": "Vật dịch chuyển −12 m trong 3 s. Vận tốc trung bình bằng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "+4 m/s"}, {"id": "b", "text": "−36 m/s"}, {"id": "c", "text": "−4 m/s"}], "correctOptionId": "c", "explanation": "v = −12/3 = −4 m/s, tức theo chiều âm."}, {"id": "physics-10-acceleration-q1", "prompt": "Đơn vị SI của gia tốc là?", "difficulty": "EASY", "options": [{"id": "a", "text": "m/s"}, {"id": "b", "text": "m²/s"}, {"id": "c", "text": "m/s²"}], "correctOptionId": "c", "explanation": "Gia tốc là độ biến thiên vận tốc trong một giây nên có đơn vị (m/s)/s = m/s²."}, {"id": "physics-10-acceleration-q2", "prompt": "Vận tốc tăng từ 4 lên 10 m/s trong 2 s. Gia tốc trung bình bằng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "12 m/s²"}, {"id": "b", "text": "3 m/s²"}, {"id": "c", "text": "7 m/s²"}], "correctOptionId": "b", "explanation": "a = (10 − 4)/2 = 3 m/s²."}]'::jsonb,'[]'::jsonb) on conflict(subject_id,grade,unit_id) do nothing;
commit;

begin;
create function public.mentor_public_learner(profile_id uuid) returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('id',p.id,'nickname',p.nickname,'bio',p.bio,'avatarUrl',p.avatar_path,'learningDay',(now() at time zone 'Asia/Ho_Chi_Minh')::date,'dailyXp',coalesce((select sum(xp) from public.mentor_awards where user_id=p.id and learning_day=(now() at time zone 'Asia/Ho_Chi_Minh')::date),0),'streakDays',public.mentor_streak(p.id)) from public.mentor_profiles p where p.id=profile_id;
$$;
revoke all on function public.mentor_public_learner(uuid) from public,anon,authenticated;
create function public.mentor_overview(g int) returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); items jsonb; series jsonb; total bigint; daily bigint; completed int; lessons int; practice jsonb;
begin
 if uid is null then raise sqlstate 'PT401' using message='AUTHENTICATION_REQUIRED'; end if;
 if g not between 10 and 12 then raise sqlstate 'PT400' using message='INVALID_GRADE'; end if;
 select jsonb_agg(jsonb_build_object('subjectId',s,'curriculumAvailable',exists(select 1 from public.mentor_course_units where subject_id=s and grade=g),'totalXp',coalesce((select sum(xp) from public.mentor_awards where user_id=uid and subject_id=s),0),'completedLessons',(select count(*) from public.mentor_awards a join public.mentor_course_units u on u.subject_id=a.subject_id and u.grade=a.grade and u.unit_id=a.unit_id and u.kind='LESSON' where a.user_id=uid and a.subject_id=s and a.grade=g),'totalLessons',(select count(*) from public.mentor_course_units where subject_id=s and grade=g and kind='LESSON'))) into items from unnest(array['math','literature','english','history','geography','physics','chemistry','biology','economics_law']) s;
 select coalesce(sum((value->>'totalXp')::bigint),0),coalesce(sum((value->>'completedLessons')::int),0),coalesce(sum((value->>'totalLessons')::int),0) into total,completed,lessons from jsonb_array_elements(items);
 select coalesce(sum(xp),0) into daily from public.mentor_awards where user_id=uid and learning_day=(now() at time zone 'Asia/Ho_Chi_Minh')::date;
 select jsonb_build_object('questionCount',count(*),'firstTryCorrect',count(*) filter(where (v.value->>'firstTryCorrect')::boolean),'assisted',count(*) filter(where (v.value->>'assisted')::boolean)) into practice from public.mentor_attempts a cross join lateral jsonb_each(a.answers) v where a.user_id=uid and a.kind<>'PLACEMENT';
 select jsonb_agg(jsonb_build_object('day',d::date,'xp',coalesce((select sum(xp) from public.mentor_awards where user_id=uid and learning_day=d::date),0),'streakLit',exists(select 1 from public.mentor_learning_days where user_id=uid and day=d::date)) order by d) into series from generate_series((now() at time zone 'Asia/Ho_Chi_Minh')::date-6,(now() at time zone 'Asia/Ho_Chi_Minh')::date,interval '1 day') d;
 return jsonb_build_object('profileId',uid,'grade',g,'totalXp',total,'dailyXp',daily,'completedLessons',completed,'totalLessons',lessons,'streakDays',public.mentor_streak(uid),'rankTier',case when total=0 then 'UNRANKED' else 'BRONZE' end,'subjects',items,'practice',practice,'week',series);
end; $$;
revoke all on function public.mentor_overview(int) from public,anon;
grant execute on function public.mentor_overview(int) to authenticated;
create table public.mentor_friendships(id uuid primary key default gen_random_uuid(),requester uuid not null references auth.users(id) on delete cascade,recipient uuid not null references auth.users(id) on delete cascade,state text not null default 'PENDING' check(state in ('PENDING','ACCEPTED')),created_at timestamptz not null default now(),check(requester<>recipient));
create unique index mentor_one_friendship on public.mentor_friendships(least(requester,recipient),greatest(requester,recipient));
alter table public.mentor_friendships enable row level security;
revoke all on public.mentor_friendships from anon,authenticated;
create function public.mentor_social_api(method text,path text,body jsonb default '{}',query jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); result jsonb; metric text:=coalesce(query->>'metric','STREAK'); scope text:=coalesce(query->>'scope','GLOBAL'); target uuid; item uuid; rows jsonb;
begin
 if uid is null then raise sqlstate 'PT401' using message='AUTHENTICATION_REQUIRED'; end if;
 if path='/rankings' then
  if metric not in ('STREAK','DAILY_XP') or scope not in ('FRIENDS','GLOBAL') then raise sqlstate 'PT400' using message='INVALID_RANKING'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('rank',r,'value',score,'profile',profile) order by score desc,pid),'[]') into rows from (
   select pid,profile,score,dense_rank() over(order by score desc) r from (
    select p.id pid,public.mentor_public_learner(p.id) profile,case when metric='STREAK' then public.mentor_streak(p.id)::bigint else coalesce((select sum(xp) from public.mentor_awards where user_id=p.id and learning_day=(now() at time zone 'Asia/Ho_Chi_Minh')::date),0) end score
    from public.mentor_profiles p where scope='GLOBAL' or p.id=uid or exists(select 1 from public.mentor_friendships where state='ACCEPTED' and ((requester=uid and recipient=p.id) or (recipient=uid and requester=p.id)))
   ) scores order by score desc,pid limit 100
  ) ranked;
  result:=jsonb_build_object('metric',metric,'scope',scope,'learningDay',(now() at time zone 'Asia/Ho_Chi_Minh')::date,'entries',rows);
 elsif path='/me/public-profile' and method='PATCH' then
  update public.mentor_profiles set nickname=coalesce(body->>'nickname',nickname),bio=coalesce(body->>'bio',bio) where id=uid;
  result:=public.mentor_public_learner(uid);
 elsif path='/me/public-profile' then result:=public.mentor_public_learner(uid);
 elsif path ~ '^/profiles/[^/]+$' then result:=public.mentor_public_learner(split_part(path,'/',3)::uuid);
 elsif path='/me/account' then
  result:=jsonb_build_object('id',uid,'username',uid,'profile',public.mentor_public_learner(uid));
 elsif path='/friendships' and method='GET' then
  select jsonb_build_object('items',coalesce(jsonb_agg(jsonb_build_object('id',f.id,'status',f.state,'direction',case when f.requester=uid then 'OUTGOING' else 'INCOMING' end,'profile',public.mentor_public_learner(case when f.requester=uid then f.recipient else f.requester end))),'[]')) into result from public.mentor_friendships f where f.requester=uid or f.recipient=uid;
 elsif path='/friendships' and method='POST' then
  target:=(body->>'profileId')::uuid;
  insert into public.mentor_friendships(requester,recipient) values(uid,target) returning id into item;
  result:=jsonb_build_object('id',item,'status','PENDING');
 elsif path ~ '^/friendships/[^/]+$' and method='DELETE' then
  delete from public.mentor_friendships where id=split_part(path,'/',3)::uuid and (requester=uid or recipient=uid);
  result:='{}';
 elsif path ~ '^/friendships/[^/]+$' and method='PATCH' then
  update public.mentor_friendships set state='ACCEPTED' where id=split_part(path,'/',3)::uuid and recipient=uid returning id into item;
  if item is null then raise sqlstate 'PT404' using message='FRIENDSHIP_NOT_FOUND'; end if;
  result:=jsonb_build_object('id',item,'status','ACCEPTED');
 else raise sqlstate 'PT404' using message='API_NOT_IMPLEMENTED'; end if;
 if result is null then raise sqlstate 'PT404' using message='PROFILE_NOT_FOUND'; end if;
 return result;
end; $$;
revoke all on function public.mentor_social_api(text,text,jsonb,jsonb) from public,anon;
grant execute on function public.mentor_social_api(text,text,jsonb,jsonb) to authenticated;
commit;


begin;
alter table public.mentor_preferences add column onboarding_step int not null default 0 check(onboarding_step between 0 and 5);
alter table public.mentor_preferences add column goal int not null default 0 check(goal between 0 and 3);
alter table public.mentor_preferences add column minutes int not null default 0 check(minutes=0 or minutes between 5 and 240);
alter table public.mentor_preferences add column consented_at timestamptz;
alter table public.mentor_enrollments add column selected boolean not null default true;
create function public.mentor_setup(data jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); p public.mentor_preferences; next_step int; chosen text[];
begin
 if uid is null then raise sqlstate 'PT401' using message='AUTHENTICATION_REQUIRED'; end if;
 select * into p from public.mentor_preferences where user_id=uid for update;
 next_step:=greatest(p.onboarding_step,coalesce((data->>'step')::int,p.onboarding_step));
 if data ? 'subjects' then select array_agg(value) into chosen from jsonb_array_elements_text(data->'subjects'); end if;
 if next_step=5 and (coalesce((data->>'grade')::int,p.grade,0) not between 10 and 12 or char_length(coalesce(data->>'nickname',(select nickname from public.mentor_profiles where id=uid)))<2) then raise sqlstate 'PT400' using message='INVALID_PROFILE'; end if;
 update public.mentor_preferences set onboarding_step=next_step,grade=coalesce((data->>'grade')::int,grade),subjects=case when data ? 'subjects' then coalesce(chosen,'{}') else subjects end,goal=coalesce((data->>'goal')::int,goal),minutes=coalesce((data->>'minutes')::int,minutes),consented_at=case when next_step=5 then coalesce(consented_at,now()) else consented_at end where user_id=uid returning * into p;
 if data ? 'nickname' then update public.mentor_profiles set nickname=data->>'nickname' where id=uid; end if;
 return to_jsonb(p);
end; $$;
revoke all on function public.mentor_setup(jsonb) from public,anon;
grant execute on function public.mentor_setup(jsonb) to authenticated;
create function public.mentor_selected_subjects(g int) returns jsonb language sql security definer set search_path='' as $$
 select jsonb_build_object('items',coalesce(jsonb_agg(subject_id),'[]')) from public.mentor_enrollments where user_id=auth.uid() and grade=g and selected;
$$;
revoke all on function public.mentor_selected_subjects(int) from public,anon;
grant execute on function public.mentor_selected_subjects(int) to authenticated;
create function public.mentor_select_subjects(g int,subjects text[]) returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); s text;
begin
 if uid is null then raise sqlstate 'PT401' using message='AUTHENTICATION_REQUIRED'; end if;
 if g not between 10 and 12 or not(subjects <@ array['physics','chemistry','biology']) then raise sqlstate 'PT400' using message='INVALID_SUBJECTS'; end if;
 perform pg_advisory_xact_lock(hashtextextended(uid::text,0));
 update public.mentor_enrollments set selected=false where user_id=uid and grade=g;
 foreach s in array subjects loop
  insert into public.mentor_enrollments(user_id,subject_id,grade,selected) values(uid,s,g,true) on conflict(user_id,subject_id,grade) do update set selected=true;
 end loop;
 return public.mentor_selected_subjects(g);
end; $$;
revoke all on function public.mentor_select_subjects(int,text[]) from public,anon;
grant execute on function public.mentor_select_subjects(int,text[]) to authenticated;
commit;


begin;
create table public.mentor_chat_folders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null check(char_length(title) between 1 and 100),unique(id,user_id));
create table public.mentor_chat_threads(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,folder_id uuid,title text not null default '' check(char_length(title)<=100),draft text not null default '' check(char_length(draft)<=30000),automatic_title boolean not null default true,updated_at timestamptz not null default now(),unique(id,user_id),foreign key(folder_id,user_id) references public.mentor_chat_folders(id,user_id));
create table public.mentor_chat_messages(id uuid primary key default gen_random_uuid(),user_id uuid not null,thread_id uuid not null,turn_index int not null,role text not null check(role in ('USER','ASSISTANT')),text text not null check(char_length(text)<=120000),status text not null check(status in ('PENDING','SENT','FAILED','CANCELLED')),error text not null default '',truncated boolean not null default false,pending_device text,updated_at timestamptz not null default now(),unique(thread_id,turn_index,role),unique(id,user_id,thread_id),foreign key(thread_id,user_id) references public.mentor_chat_threads(id,user_id) on delete cascade);
create table public.mentor_chat_files(id uuid primary key,user_id uuid not null,thread_id uuid not null,message_id uuid,metadata jsonb not null,foreign key(thread_id,user_id) references public.mentor_chat_threads(id,user_id) on delete cascade,foreign key(message_id,user_id,thread_id) references public.mentor_chat_messages(id,user_id,thread_id) on delete cascade);
alter table public.mentor_chat_folders enable row level security;
alter table public.mentor_chat_threads enable row level security;
alter table public.mentor_chat_messages enable row level security;
alter table public.mentor_chat_files enable row level security;
revoke all on public.mentor_chat_folders,public.mentor_chat_threads,public.mentor_chat_messages,public.mentor_chat_files from anon,authenticated;
create function public.mentor_chat_thread_view(tid uuid) returns jsonb language sql security definer set search_path='' as $$
 select jsonb_build_object('id',id,'title',title,'folderId',folder_id,'draft',draft,'automaticTitle',automatic_title,'updatedAt',(extract(epoch from updated_at)*1000)::bigint) from public.mentor_chat_threads where id=tid and user_id=auth.uid();
$$;
revoke all on function public.mentor_chat_thread_view(uuid) from public,anon,authenticated;
create function public.mentor_chat_action(op text,data jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); tid uuid; fid uuid; mid uuid; item uuid; result jsonb; rows jsonb; turn int; rowmsg public.mentor_chat_messages;
begin
 if uid is null then raise sqlstate 'PT401' using message='AUTHENTICATION_REQUIRED'; end if;
 perform pg_advisory_xact_lock(hashtextextended(uid::text,0));
 tid:=nullif(data->>'threadId','')::uuid; fid:=nullif(data->>'folderId','')::uuid; mid:=nullif(data->>'messageId','')::uuid;
 if tid is not null and not exists(select 1 from public.mentor_chat_threads where id=tid and user_id=uid) then raise sqlstate 'PT404' using message='CHAT_NOT_FOUND'; end if;
 if fid is not null and not exists(select 1 from public.mentor_chat_folders where id=fid and user_id=uid) then raise sqlstate 'PT404' using message='FOLDER_NOT_FOUND'; end if;
 if op='create' then
  insert into public.mentor_chat_threads(user_id,folder_id) values(uid,fid) returning id into tid;
  return public.mentor_chat_thread_view(tid);
 elsif op='thread' then return public.mentor_chat_thread_view(tid);
 elsif op='threads' then
  select coalesce(jsonb_agg(public.mentor_chat_thread_view(id) order by updated_at desc,id),'[]') into rows from public.mentor_chat_threads where user_id=uid and (coalesce(data->>'query','')='' or strpos(lower(title),lower(data->>'query'))>0 or strpos(lower(draft),lower(data->>'query'))>0);
  return jsonb_build_object('items',rows);
 elsif op='folders' then
  select coalesce(jsonb_agg(jsonb_build_object('id',id,'title',title) order by title,id),'[]') into rows from public.mentor_chat_folders where user_id=uid;
  return jsonb_build_object('items',rows);
 elsif op='create_folder' then
  insert into public.mentor_chat_folders(user_id,title) values(uid,trim(data->>'title')) returning id into item;
  return jsonb_build_object('id',item);
 elsif op='rename_folder' then update public.mentor_chat_folders set title=trim(data->>'title') where id=fid and user_id=uid;
 elsif op='delete_folder' then
  if coalesce((data->>'deleteChats')::boolean,false) then delete from public.mentor_chat_threads where user_id=uid and folder_id=fid;
  else update public.mentor_chat_threads set folder_id=null,updated_at=now() where user_id=uid and folder_id=fid; end if;
  delete from public.mentor_chat_folders where user_id=uid and id=fid;
 elsif op='rename_thread' then update public.mentor_chat_threads set title=trim(data->>'title'),automatic_title=false,updated_at=now() where id=tid and user_id=uid;
 elsif op='move_thread' then update public.mentor_chat_threads set folder_id=fid,updated_at=now() where id=tid and user_id=uid;
 elsif op='delete_thread' then delete from public.mentor_chat_threads where id=tid and user_id=uid;
 elsif op='draft' then update public.mentor_chat_threads set draft=data->>'text' where id=tid and user_id=uid;
 elsif op='add_file' then
  if (select count(*) from public.mentor_chat_files where user_id=uid and thread_id=tid and message_id is null)>=4 then raise sqlstate 'PT400' using message='TOO_MANY_FILES'; end if;
  if (data->'file'->>'size')::int not between 1 and 8388608 or (data->'file'->>'storageKey') !~ '^[0-9a-fA-F-]{36}\.bin$' then raise sqlstate 'PT400' using message='INVALID_FILE'; end if;
  insert into public.mentor_chat_files(id,user_id,thread_id,metadata) values((data->'file'->>'id')::uuid,uid,tid,data->'file');
 elsif op='remove_file' then delete from public.mentor_chat_files where user_id=uid and thread_id=tid and id=(data->>'fileId')::uuid and message_id is null;
 elsif op='stage' then
  if length(trim(coalesce(data->>'text','')))=0 and not exists(select 1 from public.mentor_chat_files where user_id=uid and thread_id=tid and message_id is null) then raise sqlstate 'PT400' using message='EMPTY_MESSAGE'; end if;
  if char_length(data->>'text')>30000 then raise sqlstate 'PT400' using message='MESSAGE_TOO_LONG'; end if;
  select coalesce(max(turn_index),0)+1 into turn from public.mentor_chat_messages where user_id=uid and thread_id=tid;
  insert into public.mentor_chat_messages(user_id,thread_id,turn_index,role,text,status,pending_device) values(uid,tid,turn,'USER',data->>'text','PENDING',data->>'device_id') returning id into mid;
  update public.mentor_chat_files set message_id=mid where user_id=uid and thread_id=tid and message_id is null;
  update public.mentor_chat_threads set draft='',updated_at=now(),title=case when automatic_title and title='' then left(coalesce(nullif(trim(data->>'text'),''),'Chat'),70) else title end where user_id=uid and id=tid;
  return jsonb_build_object('id',mid);
 elsif op='retry' then
  update public.mentor_chat_messages set status='PENDING',error='',pending_device=data->>'device_id',updated_at=now() where user_id=uid and thread_id=tid and id=mid and role='USER' and status in ('FAILED','CANCELLED');
  if not found then raise sqlstate 'PT409' using message='MESSAGE_NOT_RETRYABLE'; end if;
 elsif op='finish' then
  select * into rowmsg from public.mentor_chat_messages where user_id=uid and thread_id=tid and id=mid and role='USER' and status='PENDING' for update;
  if rowmsg.id is null then return jsonb_build_object('changed',false); end if;
  update public.mentor_chat_messages set status=case when data ? 'reply' then 'SENT' when data->>'error'='CANCELLED' then 'CANCELLED' else 'FAILED' end,error=coalesce(data->>'error',''),updated_at=now() where id=mid;
  if data ? 'reply' then insert into public.mentor_chat_messages(user_id,thread_id,turn_index,role,text,status,truncated) values(uid,tid,rowmsg.turn_index,'ASSISTANT',data->>'reply','SENT',coalesce((data->>'truncated')::boolean,false)); end if;
  update public.mentor_chat_threads set updated_at=now() where id=tid;
  return jsonb_build_object('changed',true);
 elsif op='recover' then
  update public.mentor_chat_messages set status='CANCELLED',error='CANCELLED',updated_at=now() where user_id=uid and role='USER' and status='PENDING' and (pending_device=data->>'device_id' or updated_at<now()-interval '10 minutes');
 elsif op='snapshot' then
  select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'text',m.text,'role',m.role,'status',m.status,'error',m.error,'truncated',m.truncated,'files',coalesce((select jsonb_agg(f.metadata) from public.mentor_chat_files f where f.user_id=uid and f.thread_id=tid and f.message_id=m.id),'[]')) order by m.turn_index,case when m.role='USER' then 0 else 1 end),'[]') into rows from public.mentor_chat_messages m where m.user_id=uid and m.thread_id=tid;
  return jsonb_build_object('thread',public.mentor_chat_thread_view(tid),'messages',rows,'draftFiles',coalesce((select jsonb_agg(metadata) from public.mentor_chat_files where user_id=uid and thread_id=tid and message_id is null),'[]'));
 else raise sqlstate 'PT400' using message='UNKNOWN_OPERATION'; end if;
 return '{}';
end; $$;
revoke all on function public.mentor_chat_action(text,jsonb) from public,anon;
grant execute on function public.mentor_chat_action(text,jsonb) to authenticated;
insert into storage.buckets(id,name,public,file_size_limit) values('mentor-chat-files','mentor-chat-files',false,8388608),('mentor-avatars','mentor-avatars',false,2097152) on conflict do nothing;
create policy mentor_file_insert on storage.objects for insert to authenticated with check(bucket_id in ('mentor-chat-files','mentor-avatars') and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy mentor_file_read on storage.objects for select to authenticated using((bucket_id='mentor-chat-files' and (storage.foldername(name))[1]=(select auth.uid())::text) or bucket_id='mentor-avatars');
create policy mentor_file_update on storage.objects for update to authenticated using(bucket_id in ('mentor-chat-files','mentor-avatars') and (storage.foldername(name))[1]=(select auth.uid())::text) with check(bucket_id in ('mentor-chat-files','mentor-avatars') and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy mentor_file_delete on storage.objects for delete to authenticated using(bucket_id in ('mentor-chat-files','mentor-avatars') and (storage.foldername(name))[1]=(select auth.uid())::text);
commit;


begin;
create table public.mentor_ai_usage(user_id uuid not null references auth.users(id) on delete cascade,day date not null,requests int not null default 0,primary key(user_id,day));
alter table public.mentor_ai_usage enable row level security;
revoke all on public.mentor_ai_usage from anon,authenticated;
create function public.mentor_reserve_ai_request() returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); d date:=(now() at time zone 'Asia/Ho_Chi_Minh')::date; count_requests int;
begin
 if uid is null then raise sqlstate 'PT401' using message='AUTHENTICATION_REQUIRED'; end if;
 insert into public.mentor_ai_usage values(uid,d,1) on conflict(user_id,day) do update set requests=public.mentor_ai_usage.requests+1 where public.mentor_ai_usage.requests<60 returning requests into count_requests;
 if count_requests is null then raise sqlstate 'PT429' using message='RATE_LIMITED'; end if;
 return jsonb_build_object('remaining',60-count_requests);
end; $$;
revoke all on function public.mentor_reserve_ai_request() from public,anon;
grant execute on function public.mentor_reserve_ai_request() to authenticated;
commit;


alter table public.mentor_preferences
  add column address text not null default '',
  add column phone text not null default '';

grant update(address,phone) on public.mentor_preferences to authenticated;


create function public.mentor_update_profile(data jsonb)
returns jsonb
language plpgsql
security definer
set search_path=''
as $$
declare uid uuid:=auth.uid(); profile_row public.mentor_profiles;
begin
  if uid is null then raise sqlstate 'PT401' using message='UNAUTHORIZED'; end if;
  if char_length(coalesce(data->>'nickname','')) not between 2 and 40
     or char_length(coalesce(data->>'address',''))>240
     or char_length(coalesce(data->>'phone',''))>32
     or char_length(coalesce(data->>'avatar_path',''))>96 then
    raise sqlstate 'PT400' using message='INVALID_PROFILE';
  end if;
  update public.mentor_profiles
    set nickname=data->>'nickname',
        avatar_path=case when data ? 'avatar_path' then nullif(data->>'avatar_path','') else avatar_path end
    where id=uid returning * into profile_row;
  update public.mentor_preferences
    set address=data->>'address',phone=data->>'phone'
    where user_id=uid;
  return jsonb_build_object('nickname',profile_row.nickname,'avatarPath',profile_row.avatar_path,
    'address',(select address from public.mentor_preferences where user_id=uid),
    'phone',(select phone from public.mentor_preferences where user_id=uid));
end $$;

revoke all on function public.mentor_update_profile(jsonb) from public,anon;
grant execute on function public.mentor_update_profile(jsonb) to authenticated;


do $$
declare table_name text;
begin
  foreach table_name in array array['mentor_awards','mentor_learning_days','mentor_friendships'] loop
    if not exists (
      select 1 from pg_publication_tables
      where pubname='supabase_realtime' and schemaname='public' and tablename=table_name
    ) then
      execute format('alter publication supabase_realtime add table public.%I',table_name);
    end if;
  end loop;
end $$;


do $$
declare
  table_name text;
begin
  foreach table_name in array array[
    'mentor_profiles',
    'mentor_preferences',
    'mentor_enrollments',
    'mentor_attempts',
    'mentor_chat_threads',
    'mentor_chat_messages',
    'mentor_timetable',
    'mentor_todos',
    'mentor_schedule_logs'
  ] loop
    if to_regclass(format('public.%I', table_name)) is not null
       and not exists (
         select 1 from pg_publication_tables
         where pubname = 'supabase_realtime'
           and schemaname = 'public'
           and tablename = table_name
       ) then
      execute format('alter publication supabase_realtime add table public.%I', table_name);
    end if;
  end loop;
end $$;


create or replace function public.mentor_overview(g int) returns jsonb
language plpgsql security definer set search_path='' as $$
declare
  uid uuid:=auth.uid();
  items jsonb;
  series jsonb;
  total bigint;
  daily bigint;
  completed int;
  lessons int;
  practice jsonb;
begin
  if uid is null then raise sqlstate 'PT401' using message='AUTHENTICATION_REQUIRED'; end if;
  if g not between 10 and 12 then raise sqlstate 'PT400' using message='INVALID_GRADE'; end if;

  select jsonb_agg(jsonb_build_object(
    'subjectId',s,
    'curriculumAvailable',exists(select 1 from public.mentor_course_units where subject_id=s and grade=g),
    'totalXp',coalesce((select sum(xp) from public.mentor_awards where user_id=uid and subject_id=s),0),
    'completedLessons',case when exists(select 1 from public.mentor_enrollments e where e.user_id=uid and e.grade=g and e.subject_id=s and e.selected)
      then (select count(*) from public.mentor_awards a join public.mentor_course_units u on u.subject_id=a.subject_id and u.grade=a.grade and u.unit_id=a.unit_id and u.kind='LESSON' where a.user_id=uid and a.subject_id=s and a.grade=g)
      else 0 end,
    'totalLessons',case when exists(select 1 from public.mentor_enrollments e where e.user_id=uid and e.grade=g and e.subject_id=s and e.selected)
      then (select count(*) from public.mentor_course_units where subject_id=s and grade=g and kind='LESSON')
      else 0 end
  )) into items
  from unnest(array['math','literature','english','history','geography','physics','chemistry','biology','economics_law']) s;

  select coalesce(sum((value->>'totalXp')::bigint),0),
         coalesce(sum((value->>'completedLessons')::int),0),
         coalesce(sum((value->>'totalLessons')::int),0)
    into total,completed,lessons from jsonb_array_elements(items);
  select coalesce(sum(xp),0) into daily from public.mentor_awards
    where user_id=uid and learning_day=(now() at time zone 'Asia/Ho_Chi_Minh')::date;
  select jsonb_build_object('questionCount',count(*),
      'firstTryCorrect',count(*) filter(where (v.value->>'firstTryCorrect')::boolean),
      'assisted',count(*) filter(where (v.value->>'assisted')::boolean))
    into practice from public.mentor_attempts a cross join lateral jsonb_each(a.answers) v
    where a.user_id=uid and a.kind<>'PLACEMENT';
  select jsonb_agg(jsonb_build_object('day',d::date,
      'xp',coalesce((select sum(xp) from public.mentor_awards where user_id=uid and learning_day=d::date),0),
      'streakLit',exists(select 1 from public.mentor_learning_days where user_id=uid and day=d::date)) order by d)
    into series from generate_series((now() at time zone 'Asia/Ho_Chi_Minh')::date-6,
      (now() at time zone 'Asia/Ho_Chi_Minh')::date,interval '1 day') d;

  return jsonb_build_object(
    'profileId',uid,'grade',g,'totalXp',total,'dailyXp',daily,'completedLessons',completed,
    'totalLessons',lessons,'streakDays',public.mentor_streak(uid),
    'rankTier',case when total>=10000 then 'DIAMOND' when total>=5000 then 'PLATINUM'
      when total>=2000 then 'GOLD' when total>=500 then 'SILVER' when total>0 then 'BRONZE' else 'UNRANKED' end,
    'subjects',items,'practice',coalesce(practice,jsonb_build_object('questionCount',0,'firstTryCorrect',0,'assisted',0)),
    'week',series);
end; $$;

revoke all on function public.mentor_overview(int) from public,anon;
grant execute on function public.mentor_overview(int) to authenticated;


begin;

alter table public.mentor_friendships
  drop constraint if exists mentor_friendships_state_check;
alter table public.mentor_friendships
  add constraint mentor_friendships_state_check
  check (state in ('PENDING','ACCEPTED','DECLINED'));
alter table public.mentor_friendships
  add column if not exists revision int not null default 1,
  add column if not exists updated_at timestamptz not null default now();

create table if not exists public.mentor_social_requests(
  user_id uuid not null references auth.users(id) on delete cascade,
  request_key text not null,
  fingerprint text not null,
  result jsonb not null,
  created_at timestamptz not null default now(),
  primary key(user_id,request_key)
);
alter table public.mentor_social_requests enable row level security;
revoke all on public.mentor_social_requests from public,anon,authenticated;

alter function public.mentor_social_api(text,text,jsonb,jsonb) rename to mentor_social_api_v1;
revoke all on function public.mentor_social_api_v1(text,text,jsonb,jsonb) from public,anon,authenticated;

create function public.mentor_social_api(method text,path text,body jsonb default '{}',query jsonb default '{}')
returns jsonb language plpgsql security definer set search_path='' as $$
declare
  uid uuid:=auth.uid();
  target uuid;
  item uuid;
  expected int;
  current_revision int;
  state_value text;
  result jsonb;
  rows jsonb;
  request_key text:=nullif(query->>'requestKey','');
  fingerprint text:=md5(method||':'||path||':'||coalesce(body,'{}'::jsonb)::text);
  cached public.mentor_social_requests;
begin
  if uid is null then raise sqlstate 'PT401' using message='AUTHENTICATION_REQUIRED'; end if;
  if path not like '/friendships%' then
    return public.mentor_social_api_v1(method,path,body,query);
  end if;

  perform pg_advisory_xact_lock(hashtextextended(uid::text,1));
  if method='POST' and request_key is not null then
    if char_length(request_key) not between 1 and 100 then raise sqlstate 'PT400' using message='INVALID_REQUEST_KEY'; end if;
    select * into cached from public.mentor_social_requests where user_id=uid and mentor_social_requests.request_key=request_key;
    if cached.request_key is not null then
      if cached.fingerprint<>fingerprint then raise sqlstate 'PT409' using message='IDEMPOTENCY_CONFLICT'; end if;
      return cached.result;
    end if;
  end if;

  if path='/friendships' and method='GET' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id',f.id,'requesterProfileId',f.requester,'recipientProfileId',f.recipient,
      'state',f.state,'status',f.state,'revision',f.revision,
      'updatedAt',f.updated_at,'direction',case when f.requester=uid then 'OUTGOING' else 'INCOMING' end,
      'profile',public.mentor_public_learner(case when f.requester=uid then f.recipient else f.requester end)
    ) order by f.updated_at desc,f.id),'[]') into rows
    from public.mentor_friendships f where f.requester=uid or f.recipient=uid;
    return jsonb_build_object('items',rows,'nextCursor',null,'asOf',now());
  elsif path='/friendships' and method='POST' then
    target:=coalesce(nullif(body->>'recipientProfileId',''),nullif(body->>'profileId',''))::uuid;
    if target is null then raise sqlstate 'PT400' using message='INVALID_PROFILE'; end if;
    if target=uid then raise sqlstate 'PT400' using message='CANNOT_FRIEND_SELF'; end if;
    if not exists(select 1 from public.mentor_profiles where id=target) then raise sqlstate 'PT404' using message='PROFILE_NOT_FOUND'; end if;
    if exists(select 1 from public.mentor_friendships where least(requester,recipient)=least(uid,target) and greatest(requester,recipient)=greatest(uid,target)) then
      raise sqlstate 'PT409' using message='FRIENDSHIP_EXISTS';
    end if;
    insert into public.mentor_friendships(requester,recipient,state,revision,updated_at)
      values(uid,target,'PENDING',1,now()) returning id into item;
    result:=jsonb_build_object('id',item,'requesterProfileId',uid,'recipientProfileId',target,
      'state','PENDING','status','PENDING','revision',1,'updatedAt',now(),'direction','OUTGOING');
    if request_key is not null then
      insert into public.mentor_social_requests(user_id,request_key,fingerprint,result)
        values(uid,request_key,fingerprint,result);
    end if;
    return result;
  elsif path ~ '^/friendships/[^/]+$' and method='PATCH' then
    item:=split_part(path,'/',3)::uuid;
    expected:=nullif(query->>'expectedRevision','')::int;
    select revision,state into current_revision,state_value from public.mentor_friendships
      where id=item and recipient=uid for update;
    if current_revision is null then raise sqlstate 'PT404' using message='FRIENDSHIP_NOT_FOUND'; end if;
    if expected is not null and expected<>current_revision then raise sqlstate 'PT409' using message='REVISION_CONFLICT'; end if;
    if state_value<>'PENDING' then raise sqlstate 'PT409' using message='FRIENDSHIP_ALREADY_DECIDED'; end if;
    state_value:=case upper(coalesce(body->>'decision','')) when 'ACCEPT' then 'ACCEPTED' when 'DECLINE' then 'DECLINED' else null end;
    if state_value is null then raise sqlstate 'PT400' using message='INVALID_DECISION'; end if;
    update public.mentor_friendships set state=state_value,revision=revision+1,updated_at=now()
      where id=item returning jsonb_build_object('id',id,'requesterProfileId',requester,
        'recipientProfileId',recipient,'state',state,'status',state,'revision',revision,'updatedAt',updated_at) into result;
    return result;
  elsif path ~ '^/friendships/[^/]+$' and method='DELETE' then
    item:=split_part(path,'/',3)::uuid;
    expected:=nullif(query->>'expectedRevision','')::int;
    select revision into current_revision from public.mentor_friendships
      where id=item and (requester=uid or recipient=uid) for update;
    if current_revision is null then raise sqlstate 'PT404' using message='FRIENDSHIP_NOT_FOUND'; end if;
    if expected is not null and expected<>current_revision then raise sqlstate 'PT409' using message='REVISION_CONFLICT'; end if;
    delete from public.mentor_friendships where id=item;
    return '{}';
  end if;
  raise sqlstate 'PT404' using message='API_NOT_IMPLEMENTED';
end; $$;
revoke all on function public.mentor_social_api(text,text,jsonb,jsonb) from public,anon;
grant execute on function public.mentor_social_api(text,text,jsonb,jsonb) to authenticated;

commit;


begin;

create table public.mentor_study_sessions(
  id uuid primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  subject_id text not null,
  grade int not null check(grade between 10 and 12),
  state text not null default 'ACTIVE' check(state in ('ACTIVE','CLOSED')),
  started_at timestamptz not null default now(),
  last_seen_at timestamptz not null default now(),
  ended_at timestamptz,
  total_seconds int not null default 0 check(total_seconds>=0),
  unique(id,user_id)
);
create table public.mentor_study_events(
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  session_id uuid not null,
  event_key uuid not null,
  subject_id text not null,
  grade int not null check(grade between 10 and 12),
  learning_day date not null,
  seconds int not null check(seconds between 0 and 120),
  created_at timestamptz not null default now(),
  unique(user_id,event_key),
  foreign key(session_id,user_id) references public.mentor_study_sessions(id,user_id) on delete cascade
);
create unique index mentor_one_active_study_session on public.mentor_study_sessions(user_id) where state='ACTIVE';
create index mentor_study_events_user_day on public.mentor_study_events(user_id,learning_day);
alter table public.mentor_study_sessions enable row level security;
alter table public.mentor_study_events enable row level security;
revoke all on public.mentor_study_sessions,public.mentor_study_events from public,anon,authenticated;

create function public.mentor_study_action(op text,data jsonb default '{}') returns jsonb
language plpgsql security definer set search_path='' as $$
declare
  uid uuid:=auth.uid(); sid uuid:=nullif(data->>'sessionId','')::uuid;
  event_id uuid:=nullif(data->>'eventKey','')::uuid;
  subject text; g int; row_session public.mentor_study_sessions;
  elapsed int; day date:=(now() at time zone 'Asia/Ho_Chi_Minh')::date;
begin
  if uid is null then raise sqlstate 'PT401' using message='AUTHENTICATION_REQUIRED'; end if;
  if sid is null then raise sqlstate 'PT400' using message='INVALID_SESSION_ID'; end if;
  if op='start' then
    perform pg_advisory_xact_lock(hashtextextended(uid::text,2));
    subject:=lower(trim(coalesce(data->>'subjectId',''))); g:=(data->>'grade')::int;
    if g not between 10 and 12 then raise sqlstate 'PT400' using message='INVALID_GRADE'; end if;
    if not exists(select 1 from public.mentor_enrollments where user_id=uid and subject_id=subject and grade=g and selected) then
      raise sqlstate 'PT409' using message='SUBJECT_NOT_SELECTED';
    end if;
    select * into row_session from public.mentor_study_sessions where id=sid and user_id=uid;
    if row_session.id is not null then
      if row_session.subject_id<>subject or row_session.grade<>g then raise sqlstate 'PT409' using message='STUDY_SESSION_SCOPE_CONFLICT'; end if;
      return jsonb_build_object('sessionId',sid,'subjectId',subject,'grade',g,'state',row_session.state,'studySeconds',row_session.total_seconds);
    end if;
    update public.mentor_study_sessions set state='CLOSED',ended_at=now(),last_seen_at=now()
      where user_id=uid and state='ACTIVE';
    insert into public.mentor_study_sessions(id,user_id,subject_id,grade)
      values(sid,uid,subject,g) on conflict(id) do nothing;
    select * into row_session from public.mentor_study_sessions where id=sid and user_id=uid;
    if row_session.id is null then raise sqlstate 'PT404' using message='STUDY_SESSION_NOT_FOUND'; end if;
    if row_session.subject_id<>subject or row_session.grade<>g then raise sqlstate 'PT409' using message='STUDY_SESSION_SCOPE_CONFLICT'; end if;
    return jsonb_build_object('sessionId',sid,'subjectId',subject,'grade',g,'state',row_session.state,'studySeconds',row_session.total_seconds);
  elsif op not in ('heartbeat','stop') or event_id is null then
    raise sqlstate 'PT400' using message='INVALID_STUDY_OPERATION';
  end if;

  select * into row_session from public.mentor_study_sessions where id=sid and user_id=uid for update;
  if row_session.id is null then raise sqlstate 'PT404' using message='STUDY_SESSION_NOT_FOUND'; end if;
  if exists(select 1 from public.mentor_study_events where user_id=uid and event_key=event_id) then
    return jsonb_build_object('sessionId',sid,'state',row_session.state,'studySeconds',row_session.total_seconds,'addedSeconds',0,'replayed',true);
  end if;
  if row_session.state<>'ACTIVE' then raise sqlstate 'PT409' using message='STUDY_SESSION_CLOSED'; end if;
  elapsed:=least(120,greatest(0,floor(extract(epoch from (now()-row_session.last_seen_at)))::int));
  insert into public.mentor_study_events(user_id,session_id,event_key,subject_id,grade,learning_day,seconds)
    values(uid,sid,event_id,row_session.subject_id,row_session.grade,day,elapsed);
  update public.mentor_study_sessions set last_seen_at=now(),
    total_seconds=total_seconds+elapsed,
    state=case when op='stop' then 'CLOSED' else state end,
    ended_at=case when op='stop' then now() else ended_at end
    where id=sid and user_id=uid returning * into row_session;
  return jsonb_build_object('sessionId',sid,'state',row_session.state,
    'studySeconds',row_session.total_seconds,'addedSeconds',elapsed,'replayed',false);
end; $$;
revoke all on function public.mentor_study_action(text,jsonb) from public,anon;
grant execute on function public.mentor_study_action(text,jsonb) to authenticated;

create table public.mentor_badge_catalog(
  code text primary key,
  title text not null,
  description text not null,
  rule text not null check(rule in ('FIRST_LESSON','TEN_LESSONS','SEVEN_DAY_STREAK','ONE_THOUSAND_XP'))
);
create table public.mentor_badge_awards(
  user_id uuid not null references auth.users(id) on delete cascade,
  badge_code text not null references public.mentor_badge_catalog(code),
  unlocked_at timestamptz not null default now(),
  primary key(user_id,badge_code)
);
insert into public.mentor_badge_catalog(code,title,description,rule) values
 ('FIRST_LESSON','Bước khởi đầu','Hoàn thành bài học đầu tiên.','FIRST_LESSON'),
 ('TEN_LESSONS','Bền bỉ tiến bước','Hoàn thành 10 bài học.','TEN_LESSONS'),
 ('SEVEN_DAY_STREAK','Một tuần kiên trì','Học liên tiếp 7 ngày.','SEVEN_DAY_STREAK'),
 ('ONE_THOUSAND_XP','Người tích lũy','Đạt 1.000 EXP từ học tập.','ONE_THOUSAND_XP')
on conflict(code) do update set title=excluded.title,description=excluded.description,rule=excluded.rule;
alter table public.mentor_badge_catalog enable row level security;
alter table public.mentor_badge_awards enable row level security;
revoke all on public.mentor_badge_catalog,public.mentor_badge_awards from public,anon,authenticated;

create function public.mentor_badges() returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); rows jsonb;
begin
  if uid is null then raise sqlstate 'PT401' using message='AUTHENTICATION_REQUIRED'; end if;
  insert into public.mentor_badge_awards(user_id,badge_code)
  select uid,b.code from public.mentor_badge_catalog b where
    case b.rule
      when 'FIRST_LESSON' then exists(select 1 from public.mentor_awards a join public.mentor_course_units u on u.subject_id=a.subject_id and u.grade=a.grade and u.unit_id=a.unit_id and u.kind='LESSON' where a.user_id=uid)
      when 'TEN_LESSONS' then (select count(*) from public.mentor_awards a join public.mentor_course_units u on u.subject_id=a.subject_id and u.grade=a.grade and u.unit_id=a.unit_id and u.kind='LESSON' where a.user_id=uid)>=10
      when 'SEVEN_DAY_STREAK' then public.mentor_streak(uid)>=7
      when 'ONE_THOUSAND_XP' then (select coalesce(sum(xp),0) from public.mentor_awards a where a.user_id=uid)>=1000
      else false end
  on conflict(user_id,badge_code) do nothing;
  select coalesce(jsonb_agg(jsonb_build_object('code',b.code,'title',b.title,'description',b.description,
      'unlocked',a.badge_code is not null,'unlockedAt',a.unlocked_at) order by b.code),'[]') into rows
    from public.mentor_badge_catalog b left join public.mentor_badge_awards a on a.badge_code=b.code and a.user_id=uid;
  return jsonb_build_object('badges',rows);
end; $$;
revoke all on function public.mentor_badges() from public,anon;
grant execute on function public.mentor_badges() to authenticated;

create function public.mentor_study_summary() returns jsonb language sql security definer set search_path='' as $$
  select jsonb_build_object(
    'totalSeconds',coalesce((select sum(seconds) from public.mentor_study_events where user_id=auth.uid()),0),
    'week',coalesce((select jsonb_agg(jsonb_build_object('day',d::date,'seconds',coalesce(x.seconds,0)) order by d)
      from generate_series((now() at time zone 'Asia/Ho_Chi_Minh')::date-6,
        (now() at time zone 'Asia/Ho_Chi_Minh')::date,interval '1 day') d
      left join (select learning_day,sum(seconds)::int seconds from public.mentor_study_events
        where user_id=auth.uid() and learning_day>=(now() at time zone 'Asia/Ho_Chi_Minh')::date-6
        group by learning_day) x on x.learning_day=d::date),'[]'),
    'subjects',coalesce((select jsonb_agg(jsonb_build_object('subjectId',subject_id,'seconds',seconds) order by subject_id)
      from (select subject_id,sum(seconds)::int seconds from public.mentor_study_events
        where user_id=auth.uid() group by subject_id) s),'[]')
  ) where auth.uid() is not null;
$$;
revoke all on function public.mentor_study_summary() from public,anon;
grant execute on function public.mentor_study_summary() to authenticated;

do $$ begin
  if exists(select 1 from pg_publication where pubname='supabase_realtime') then
    alter publication supabase_realtime add table public.mentor_study_sessions;
    alter publication supabase_realtime add table public.mentor_study_events;
    alter publication supabase_realtime add table public.mentor_badge_awards;
  end if;
exception when duplicate_object then null; end $$;

commit;


begin;

create table public.mentor_library_quizzes(
  id text primary key,
  title text not null,
  subject_id text not null,
  grade int not null check(grade between 10 and 12),
  chapter text not null default '',
  topic text not null default '',
  difficulty text not null default 'MEDIUM',
  questions jsonb not null check(jsonb_typeof(questions)='array' and jsonb_array_length(questions)>0),
  status text not null default 'DRAFT' check(status in ('DRAFT','PUBLISHED')),
  created_at timestamptz not null default now()
);
create table public.mentor_practice_sessions(
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  quiz_id text not null references public.mentor_library_quizzes(id),
  subject_id text not null,
  grade int not null check(grade between 10 and 12),
  question_snapshots jsonb not null check(jsonb_typeof(question_snapshots)='array'),
  answers jsonb not null default '{}',
  state text not null default 'IN_PROGRESS' check(state in ('IN_PROGRESS','COMPLETED')),
  score int not null default 0,
  correct_count int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create table public.mentor_wrong_questions(
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  question_id text not null,
  subject_id text not null,
  grade int not null check(grade between 10 and 12),
  selected_option text not null,
  correct_option text not null,
  explanation text not null default '',
  question_snapshot jsonb not null,
  state text not null default 'NEEDS_REVIEW' check(state in ('NEEDS_REVIEW','RESOLVED')),
  created_at timestamptz not null default now(),
  updated_at timestamptz,
  unique(user_id,question_id)
);
create index mentor_practice_user_active on public.mentor_practice_sessions(user_id,state,updated_at desc);
create index mentor_wrong_user_subject on public.mentor_wrong_questions(user_id,subject_id,grade,state);
alter table public.mentor_library_quizzes enable row level security;
alter table public.mentor_practice_sessions enable row level security;
alter table public.mentor_wrong_questions enable row level security;
revoke all on public.mentor_library_quizzes,public.mentor_practice_sessions,public.mentor_wrong_questions from public,anon,authenticated;

create function public.mentor_library_view(s public.mentor_practice_sessions) returns jsonb
language sql stable security definer set search_path='' as $$
  select jsonb_build_object(
    'id',s.id,'quizId',s.quiz_id,'subjectId',s.subject_id,'grade',s.grade,'state',s.state,
    'score',s.score,'maxScore',coalesce((select sum((q->>'points')::int) from jsonb_array_elements(s.question_snapshots) q),0),
    'correctCount',s.correct_count,'totalCount',jsonb_array_length(s.question_snapshots),
    'answeredCount',(select count(*) from jsonb_object_keys(s.answers)),
    'firstUnansweredIndex',coalesce((select min(i-1) from jsonb_array_elements(s.question_snapshots) with ordinality as q(value,i) where not(s.answers ? (q.value->>'id'))),0),
    'questions',(select jsonb_agg(
      (q.value - case when s.state='COMPLETED' or s.answers ? (q.value->>'id') then '' else 'correctOption' end
       - case when s.state='COMPLETED' or s.answers ? (q.value->>'id') then '' else 'explanation' end)
       || jsonb_build_object('userAnswer',s.answers->>(q.value->>'id'),
         'isCorrect',case when s.answers ? (q.value->>'id') then s.answers->>(q.value->>'id')=q.value->>'correctOption' else null end)
       order by q.i) from jsonb_array_elements(s.question_snapshots) with ordinality as q(value,i))
  );
$$;
revoke all on function public.mentor_library_view(public.mentor_practice_sessions) from public,anon,authenticated;

create function public.mentor_library_api(method text,path text,body jsonb default '{}',query jsonb default '{}') returns jsonb
language plpgsql security definer set search_path='' as $$
declare
  uid uuid:=auth.uid(); q public.mentor_library_quizzes; s public.mentor_practice_sessions;
  sid uuid; qid text; question jsonb; answer text; correct text; items jsonb; state_value text;
  entry public.mentor_wrong_questions;
begin
  if uid is null then raise sqlstate 'PT401' using message='AUTHENTICATION_REQUIRED'; end if;
  if path='/library/quizzes' and method='GET' then
    select coalesce(jsonb_agg(jsonb_build_object('id',id,'title',title,'subjectId',subject_id,'grade',grade,
      'chapter',chapter,'topic',topic,'difficulty',difficulty,'questionCount',jsonb_array_length(questions)) order by created_at desc,id),'[]')
      into items from public.mentor_library_quizzes where status='PUBLISHED'
        and (coalesce(query->>'subject_id',query->>'subjectId','')='' or subject_id=coalesce(query->>'subject_id',query->>'subjectId'))
        and (coalesce(query->>'grade','')='' or grade=(query->>'grade')::int);
    return jsonb_build_object('items',items);
  elsif path='/library/sessions' and method='GET' then
    select coalesce(jsonb_agg(jsonb_build_object('id',id,'quizId',quiz_id,'subjectId',subject_id,'grade',grade,
      'state',state,'score',score,'correctCount',correct_count,'totalCount',jsonb_array_length(question_snapshots),
      'answeredCount',(select count(*) from jsonb_object_keys(answers)),'firstUnansweredIndex',coalesce((select min(i-1) from jsonb_array_elements(question_snapshots) with ordinality as q(value,i) where not(answers ? (q.value->>'id'))),0),
      'updatedAt',updated_at) order by updated_at desc),'[]') into items
      from public.mentor_practice_sessions where user_id=uid and state='IN_PROGRESS'
        and (coalesce(query->>'subject_id',query->>'subjectId','')='' or subject_id=coalesce(query->>'subject_id',query->>'subjectId'))
        and (coalesce(query->>'grade','')='' or grade=(query->>'grade')::int);
    return jsonb_build_object('items',items);
  elsif path='/library/sessions' and method='POST' then
    select * into q from public.mentor_library_quizzes where id=body->>'quizId' and status='PUBLISHED';
    if q.id is null then raise sqlstate 'PT404' using message='QUIZ_NOT_FOUND'; end if;
    if not exists(select 1 from public.mentor_enrollments where user_id=uid and subject_id=q.subject_id and grade=q.grade and selected) then
      raise sqlstate 'PT409' using message='SUBJECT_NOT_SELECTED';
    end if;
    insert into public.mentor_practice_sessions(user_id,quiz_id,subject_id,grade,question_snapshots)
      values(uid,q.id,q.subject_id,q.grade,q.questions) returning * into s;
    return public.mentor_library_view(s);
  elsif path ~ '^/library/sessions/[^/]+/answers$' and method='POST' then
    sid:=split_part(path,'/',4)::uuid; qid:=body->>'questionId'; answer:=upper(trim(body->>'selectedOption'));
    select * into s from public.mentor_practice_sessions where id=sid and user_id=uid for update;
    if s.id is null then raise sqlstate 'PT404' using message='SESSION_NOT_FOUND'; end if;
    if s.state<>'IN_PROGRESS' then raise sqlstate 'PT409' using message='SESSION_COMPLETED'; end if;
    select value into question from jsonb_array_elements(s.question_snapshots) where value->>'id'=qid;
    if question is null or not exists(select 1 from jsonb_array_elements(question->'options') o where o->>'id'=answer) then
      raise sqlstate 'PT400' using message='INVALID_ANSWER';
    end if;
    if s.answers ? qid then
      if s.answers->>qid<>answer then raise sqlstate 'PT409' using message='ANSWER_ALREADY_SUBMITTED'; end if;
      return public.mentor_library_view(s);
    end if;
    correct:=question->>'correctOption';
    update public.mentor_practice_sessions set answers=answers||jsonb_build_object(qid,answer),
      correct_count=correct_count+case when answer=correct then 1 else 0 end,
      score=score+case when answer=correct then coalesce((question->>'points')::int,10) else 0 end,
      updated_at=now() where id=sid returning * into s;
    if answer<>correct then
      insert into public.mentor_wrong_questions(user_id,question_id,subject_id,grade,selected_option,correct_option,explanation,question_snapshot)
        values(uid,qid,s.subject_id,s.grade,answer,correct,coalesce(question->>'explanation',''),question)
      on conflict(user_id,question_id) do update set selected_option=excluded.selected_option,
        correct_option=excluded.correct_option,explanation=excluded.explanation,question_snapshot=excluded.question_snapshot,
        state='NEEDS_REVIEW',updated_at=now();
    end if;
    return public.mentor_library_view(s);
  elsif path ~ '^/library/sessions/[^/]+/complete$' and method='POST' then
    sid:=split_part(path,'/',4)::uuid;
    select * into s from public.mentor_practice_sessions where id=sid and user_id=uid for update;
    if s.id is null then raise sqlstate 'PT404' using message='SESSION_NOT_FOUND'; end if;
    if (select count(*) from jsonb_object_keys(s.answers))<jsonb_array_length(s.question_snapshots) then raise sqlstate 'PT409' using message='PRACTICE_NOT_FINISHED'; end if;
    update public.mentor_practice_sessions set state='COMPLETED',updated_at=now() where id=sid returning * into s;
    return public.mentor_library_view(s);
  elsif path ~ '^/library/sessions/[^/]+$' and method='GET' then
    sid:=split_part(path,'/',4)::uuid;
    select * into s from public.mentor_practice_sessions where id=sid and user_id=uid;
    if s.id is null then raise sqlstate 'PT404' using message='SESSION_NOT_FOUND'; end if;
    return public.mentor_library_view(s);
  elsif path='/me/wrong-questions' and method='GET' then
    select coalesce(jsonb_agg(jsonb_build_object('id',w.id,'questionId',w.question_id,'subjectId',w.subject_id,
      'grade',w.grade,'chapter',coalesce(w.question_snapshot->>'chapter','Chưa phân loại'),
      'topic',coalesce(w.question_snapshot->>'topic','Chủ đề chung'),'prompt',w.question_snapshot->>'prompt',
      'options',w.question_snapshot->'options','selectedOption',w.selected_option,'correctOption',w.correct_option,
      'explanation',w.explanation,'difficulty',coalesce(w.question_snapshot->>'difficulty','MEDIUM'),
      'state',w.state,'hasSnapshot',true,'canRetry',true,'createdAt',w.created_at,'updatedAt',w.updated_at)
      order by w.updated_at desc nulls last,w.created_at desc),'[]') into items
      from public.mentor_wrong_questions w where w.user_id=uid
        and (coalesce(query->>'subject_id',query->>'subjectId','')='' or w.subject_id=coalesce(query->>'subject_id',query->>'subjectId'))
        and (coalesce(query->>'grade','')='' or w.grade=(query->>'grade')::int)
        and (coalesce(query->>'state','')='' or query->>'state'='ALL' or w.state=query->>'state');
    return jsonb_build_object('items',items);
  elsif path ~ '^/me/wrong-questions/[^/]+/retry$' and method='POST' then
    sid:=split_part(path,'/',4)::uuid; answer:=upper(trim(body->>'selectedOption'));
    select * into entry from public.mentor_wrong_questions where id=sid and user_id=uid for update;
    if entry.id is null then raise sqlstate 'PT404' using message='WRONG_QUESTION_NOT_FOUND'; end if;
    question:=entry.question_snapshot;
    if not exists(select 1 from jsonb_array_elements(question->'options') o where o->>'id'=answer) then raise sqlstate 'PT400' using message='INVALID_ANSWER'; end if;
    update public.mentor_wrong_questions set selected_option=answer,
      state=case when answer=entry.correct_option then 'RESOLVED' else 'NEEDS_REVIEW' end,updated_at=now()
      where id=sid returning * into entry;
    return jsonb_build_object('entryId',entry.id,'questionId',entry.question_id,'selectedOption',answer,
      'correctOption',entry.correct_option,'isCorrect',answer=entry.correct_option,'state',entry.state,
      'explanation',entry.explanation,'updatedAt',entry.updated_at);
  end if;
  raise sqlstate 'PT404' using message='API_NOT_IMPLEMENTED';
end; $$;
revoke all on function public.mentor_library_api(text,text,jsonb,jsonb) from public,anon;
grant execute on function public.mentor_library_api(text,text,jsonb,jsonb) to authenticated;

commit;


begin;

do $$
declare item record;
begin
  for item in select * from (values
    ('mentor_awards','user_id = auth.uid()'),
    ('mentor_learning_days','user_id = auth.uid()'),
    ('mentor_profiles','id = auth.uid()'),
    ('mentor_preferences','user_id = auth.uid()'),
    ('mentor_enrollments','user_id = auth.uid()'),
    ('mentor_attempts','user_id = auth.uid()'),
    ('mentor_friendships','requester = auth.uid() or recipient = auth.uid()'),
    ('mentor_chat_threads','user_id = auth.uid()'),
    ('mentor_chat_messages','user_id = auth.uid()'),
    ('mentor_timetable','user_id = auth.uid()'),
    ('mentor_todos','user_id = auth.uid()'),
    ('mentor_schedule_logs','user_id = auth.uid()'),
    ('mentor_study_sessions','user_id = auth.uid()'),
    ('mentor_study_events','user_id = auth.uid()'),
    ('mentor_badge_awards','user_id = auth.uid()'),
    ('mentor_practice_sessions','user_id = auth.uid()'),
    ('mentor_wrong_questions','user_id = auth.uid()')
  ) as policies(table_name,predicate)
  loop
    if to_regclass('public.'||item.table_name) is not null then
      execute format('alter table public.%I enable row level security',item.table_name);
      execute format('grant select on public.%I to authenticated',item.table_name);
      if not exists(select 1 from pg_policies where schemaname='public' and tablename=item.table_name and policyname='mentor_realtime_owner_read') then
        execute format('create policy mentor_realtime_owner_read on public.%I for select to authenticated using (%s)',item.table_name,item.predicate);
      end if;
    end if;
  end loop;
  if exists(select 1 from pg_publication where pubname='supabase_realtime') then
    for item in select unnest(array['mentor_study_sessions','mentor_study_events','mentor_badge_awards','mentor_practice_sessions','mentor_wrong_questions']) as table_name
    loop
      if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename=item.table_name) then
        execute format('alter publication supabase_realtime add table public.%I',item.table_name);
      end if;
    end loop;
  end if;
end $$;

commit;


begin;

-- Derive review quizzes from the approved lesson question bank. This keeps the
-- practice library populated without maintaining a second copy of questions.
do $$
declare
  group_row record;
  question_set jsonb;
  question_total int;
  quiz_id text;
begin
  for group_row in
    with numbered as (
      select subject_id, grade, unit_id, position, title,
        row_number() over(partition by subject_id, grade order by position, unit_id) as lesson_no
      from public.mentor_course_units
      where kind='LESSON' and subject_id in ('physics','chemistry','biology')
    )
    select subject_id, grade,
      ((lesson_no - 1) / 5 + 1)::int as group_no,
      min(lesson_no)::int as first_lesson,
      max(lesson_no)::int as last_lesson,
      count(*)::int as lesson_count
    from numbered
    group by subject_id, grade, ((lesson_no - 1) / 5 + 1)::int
    having count(*)=5
  loop
    with numbered as (
      select subject_id, grade, unit_id, position, questions,
        row_number() over(partition by subject_id, grade order by position, unit_id) as lesson_no
      from public.mentor_course_units
      where kind='LESSON' and subject_id=group_row.subject_id and grade=group_row.grade
    ), selected as (
      select n.lesson_no, q.ordinality as question_no,
        jsonb_build_object(
          'id',q.value->>'id',
          'prompt',q.value->>'prompt',
          'options',(select coalesce(jsonb_agg(jsonb_build_object('id',upper(o.value->>'id'),'text',o.value->>'text') order by o.ordinality),'[]')
            from jsonb_array_elements(case when jsonb_typeof(q.value->'options')='array' then q.value->'options' else '[]'::jsonb end) with ordinality o(value,ordinality)),
          'correctOption',upper(coalesce(q.value->>'correctOption',q.value->>'correctOptionId')),
          'explanation',coalesce(q.value->>'explanation',''),
          'difficulty',case upper(coalesce(q.value->>'difficulty','MEDIUM'))
            when 'EASY' then 'EASY' when 'HARD' then 'HARD' else 'MEDIUM' end,
          'points',10
        ) as item
      from numbered n
      cross join lateral jsonb_array_elements(case when jsonb_typeof(n.questions)='array' then n.questions else '[]'::jsonb end) with ordinality q(value,ordinality)
      where ((n.lesson_no - 1) / 5 + 1)::int=group_row.group_no
        and jsonb_typeof(n.questions)='array'
        and q.value ? 'id' and q.value ? 'prompt'
        and coalesce(q.value->>'correctOption',q.value->>'correctOptionId') is not null
        and jsonb_typeof(q.value->'options')='array'
        and jsonb_array_length(q.value->'options')>=2
      order by n.lesson_no,q.ordinality
      limit 15
    )
    select coalesce(jsonb_agg(item order by lesson_no,question_no),'[]') into question_set from selected;

    question_total:=jsonb_array_length(question_set);
    if question_total between 10 and 15 then
      quiz_id:='review-'||group_row.subject_id||'-'||group_row.grade||'-'||group_row.group_no;
      insert into public.mentor_library_quizzes(
        id,title,subject_id,grade,chapter,topic,difficulty,questions,status
      ) values (
        quiz_id,
        'Ôn tập bài '||group_row.first_lesson||'–'||group_row.last_lesson,
        group_row.subject_id,
        group_row.grade,
        'Bài '||group_row.first_lesson||'–'||group_row.last_lesson,
        'Ôn tập 5 bài gần nhất',
        'MEDIUM',
        question_set,
        'PUBLISHED'
      ) on conflict(id) do nothing;
    end if;
  end loop;
end $$;

commit;


begin;
-- Seed the six newly authored Grade 10 introductory courses. Content is partial, not a full-year claim.
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'placement', 0, 'PLACEMENT', 'Khảo sát đầu vào', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '[]'::jsonb, '[]'::jsonb, '[{"id":"math-10-sets-q1","prompt":"Kí hiệu nào diễn tả 2 thuộc tập A?","difficulty":"EASY","options":[{"id":"a","text":"2 ∈ A"},{"id":"b","text":"A ∈ 2"},{"id":"c","text":"2 ⊂ A"}],"correctOptionId":"a","explanation":"∈ diễn tả quan hệ giữa một phần tử và một tập hợp."},{"id":"math-10-sets-q2","prompt":"A={1,2,3}, B={2,3,4}. A∩B là gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"{1,4}"},{"id":"b","text":"{1,2,3,4}"},{"id":"c","text":"{2,3}"}],"correctOptionId":"c","explanation":"Giao gồm phần tử có mặt trong cả hai tập."},{"id":"math-10-intervals-q1","prompt":"Đoạn [−1;4] có chứa đầu mút 4 không?","difficulty":"EASY","options":[{"id":"a","text":"Không"},{"id":"b","text":"Chỉ khi 4 âm"},{"id":"c","text":"Có"}],"correctOptionId":"c","explanation":"Dấu ngoặc vuông cho biết đầu mút được lấy."},{"id":"math-10-intervals-q2","prompt":"|−7| bằng bao nhiêu?","difficulty":"MEDIUM","options":[{"id":"a","text":"0"},{"id":"b","text":"7"},{"id":"c","text":"−7"}],"correctOptionId":"b","explanation":"Giá trị tuyệt đối là khoảng cách nên không âm."},{"id":"math-10-linear-inequalities-q1","prompt":"Khi chia hai vế bất đẳng thức cho số âm, cần làm gì?","difficulty":"EASY","options":[{"id":"a","text":"Đổi dấu cả hai vế thành bằng"},{"id":"b","text":"Đổi chiều dấu"},{"id":"c","text":"Giữ nguyên dấu"}],"correctOptionId":"b","explanation":"Nhân hoặc chia với số âm làm thứ tự trên trục số đảo ngược."},{"id":"math-10-linear-inequalities-q2","prompt":"Nghiệm của 3x+1≥7 là?","difficulty":"MEDIUM","options":[{"id":"a","text":"x≥2"},{"id":"b","text":"x≤2"},{"id":"c","text":"x≥6"}],"correctOptionId":"a","explanation":"Trừ 1 rồi chia 3: 3x≥6."},{"id":"math-10-systems-regions-q1","prompt":"Miền nghiệm của hệ gồm những điểm nào?","difficulty":"EASY","options":[{"id":"a","text":"Thỏa đồng thời mọi bất phương trình"},{"id":"b","text":"Chỉ thỏa một bất phương trình bất kỳ"},{"id":"c","text":"Không cần thay tọa độ"}],"correctOptionId":"a","explanation":"Nghiệm hệ phải làm tất cả các điều kiện cùng đúng."},{"id":"math-10-systems-regions-q2","prompt":"Điểm (2,1) có thỏa x≥0, y≥0 không?","difficulty":"MEDIUM","options":[{"id":"a","text":"Không"},{"id":"b","text":"Chỉ thỏa x≥0"},{"id":"c","text":"Có"}],"correctOptionId":"c","explanation":"Cả hai tọa độ đều không âm."},{"id":"math-10-quadratic-function-q1","prompt":"Đồ thị hàm số bậc hai là hình nào?","difficulty":"EASY","options":[{"id":"a","text":"Đường tròn"},{"id":"b","text":"Đường thẳng luôn luôn"},{"id":"c","text":"Parabol"}],"correctOptionId":"c","explanation":"Biểu thức bậc hai theo x tạo nên đồ thị parabol."},{"id":"math-10-quadratic-function-q2","prompt":"y=−x²+3 mở về phía nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Không có đồ thị"},{"id":"b","text":"Mở xuống"},{"id":"c","text":"Mở lên"}],"correctOptionId":"b","explanation":"Hệ số a âm nên hai nhánh hướng xuống."}]'::jsonb, '[]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'math-10-sets', 1, 'LESSON', 'Tập hợp và cách biểu diễn', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Tập hợp gom các đối tượng xác định rõ. Kí hiệu x ∈ A nghĩa là x thuộc A; A ⊂ B nghĩa là mọi phần tử của A đều thuộc B."]'::jsonb, '["A={1,2,3}, B={2,3,4} thì A∩B={2,3} và A∪B={1,2,3,4}."]'::jsonb, '[{"id":"math-10-sets-q1","prompt":"Kí hiệu nào diễn tả 2 thuộc tập A?","difficulty":"EASY","options":[{"id":"a","text":"2 ∈ A"},{"id":"b","text":"A ∈ 2"},{"id":"c","text":"2 ⊂ A"}],"correctOptionId":"a","explanation":"∈ diễn tả quan hệ giữa một phần tử và một tập hợp."},{"id":"math-10-sets-q2","prompt":"A={1,2,3}, B={2,3,4}. A∩B là gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"{1,4}"},{"id":"b","text":"{1,2,3,4}"},{"id":"c","text":"{2,3}"}],"correctOptionId":"c","explanation":"Giao gồm phần tử có mặt trong cả hai tập."},{"id":"math-10-sets-q3","prompt":"Lớp 10A có 18 bạn thích Toán, 12 bạn thích Anh, 5 bạn thích cả hai. Có bao nhiêu bạn thích ít nhất một môn?","difficulty":"APPLIED","options":[{"id":"a","text":"35"},{"id":"b","text":"25"},{"id":"c","text":"30"}],"correctOptionId":"b","explanation":"Dùng |A∪B|=|A|+|B|−|A∩B|=18+12−5."}]'::jsonb, '["math-10-sets"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'math-10-intervals', 2, 'LESSON', 'Khoảng, đoạn và giá trị tuyệt đối', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Khoảng (a;b) không lấy hai đầu mút; đoạn [a;b] có lấy hai đầu mút. |x| là khoảng cách từ x đến 0 trên trục số."]'::jsonb, '["|x−3|≤2 tương đương 1≤x≤5, tức x∈[1;5]."]'::jsonb, '[{"id":"math-10-intervals-q1","prompt":"Đoạn [−1;4] có chứa đầu mút 4 không?","difficulty":"EASY","options":[{"id":"a","text":"Không"},{"id":"b","text":"Chỉ khi 4 âm"},{"id":"c","text":"Có"}],"correctOptionId":"c","explanation":"Dấu ngoặc vuông cho biết đầu mút được lấy."},{"id":"math-10-intervals-q2","prompt":"|−7| bằng bao nhiêu?","difficulty":"MEDIUM","options":[{"id":"a","text":"0"},{"id":"b","text":"7"},{"id":"c","text":"−7"}],"correctOptionId":"b","explanation":"Giá trị tuyệt đối là khoảng cách nên không âm."},{"id":"math-10-intervals-q3","prompt":"Điều kiện |x−2|<3 tương đương khoảng nào?","difficulty":"APPLIED","options":[{"id":"a","text":"(−1;5)"},{"id":"b","text":"[−1;5]"},{"id":"c","text":"(2;5)"}],"correctOptionId":"a","explanation":"Bất đẳng thức tương đương −3<x−2<3; cộng 2 vào ba vế."}]'::jsonb, '["math-10-intervals"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'math-10-linear-inequalities', 3, 'LESSON', 'Bất phương trình bậc nhất một ẩn', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Giải bất phương trình là tìm mọi giá trị của ẩn làm mệnh đề đúng. Khi nhân hoặc chia hai vế cho số âm, phải đổi chiều bất đẳng thức."]'::jsonb, '["−2x<6 suy ra x>−3 vì chia cả hai vế cho −2."]'::jsonb, '[{"id":"math-10-linear-inequalities-q1","prompt":"Khi chia hai vế bất đẳng thức cho số âm, cần làm gì?","difficulty":"EASY","options":[{"id":"a","text":"Đổi dấu cả hai vế thành bằng"},{"id":"b","text":"Đổi chiều dấu"},{"id":"c","text":"Giữ nguyên dấu"}],"correctOptionId":"b","explanation":"Nhân hoặc chia với số âm làm thứ tự trên trục số đảo ngược."},{"id":"math-10-linear-inequalities-q2","prompt":"Nghiệm của 3x+1≥7 là?","difficulty":"MEDIUM","options":[{"id":"a","text":"x≥2"},{"id":"b","text":"x≤2"},{"id":"c","text":"x≥6"}],"correctOptionId":"a","explanation":"Trừ 1 rồi chia 3: 3x≥6."},{"id":"math-10-linear-inequalities-q3","prompt":"Một chuyến xe có phí 20 nghìn và mỗi km 8 nghìn. Ngân sách tối đa 100 nghìn. Số km d thỏa điều kiện nào?","difficulty":"APPLIED","options":[{"id":"a","text":"20d+8≤100"},{"id":"b","text":"8(d+20)=100"},{"id":"c","text":"20+8d≤100"}],"correctOptionId":"c","explanation":"Tổng tiền gồm phí cố định và tiền theo quãng đường, không vượt ngân sách."}]'::jsonb, '["math-10-linear-inequalities"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'math-10-systems-regions', 4, 'LESSON', 'Hệ bất phương trình và miền nghiệm', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Mỗi bất phương trình hai ẩn xác định một nửa mặt phẳng. Miền nghiệm của hệ là phần giao các miền tương ứng."]'::jsonb, '["x≥0 và y≥0 chọn góc phần tư thứ nhất kể cả hai trục."]'::jsonb, '[{"id":"math-10-systems-regions-q1","prompt":"Miền nghiệm của hệ gồm những điểm nào?","difficulty":"EASY","options":[{"id":"a","text":"Thỏa đồng thời mọi bất phương trình"},{"id":"b","text":"Chỉ thỏa một bất phương trình bất kỳ"},{"id":"c","text":"Không cần thay tọa độ"}],"correctOptionId":"a","explanation":"Nghiệm hệ phải làm tất cả các điều kiện cùng đúng."},{"id":"math-10-systems-regions-q2","prompt":"Điểm (2,1) có thỏa x≥0, y≥0 không?","difficulty":"MEDIUM","options":[{"id":"a","text":"Không"},{"id":"b","text":"Chỉ thỏa x≥0"},{"id":"c","text":"Có"}],"correctOptionId":"c","explanation":"Cả hai tọa độ đều không âm."},{"id":"math-10-systems-regions-q3","prompt":"Một cửa hàng cần x hộp loại A, y hộp loại B; tổng không quá 10 hộp và mỗi loại ít nhất 2. Hệ điều kiện là?","difficulty":"APPLIED","options":[{"id":"a","text":"xy≤10"},{"id":"b","text":"x+y≤10, x≥2, y≥2"},{"id":"c","text":"x+y≥10, x≤2, y≤2"}],"correctOptionId":"b","explanation":"Tổng số hộp bị chặn trên; mỗi số lượng có chặn dưới."}]'::jsonb, '["math-10-systems-regions"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'math-10-quadratic-function', 5, 'LESSON', 'Hàm số bậc hai và đồ thị', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Hàm số bậc hai có dạng y=ax²+bx+c, a≠0. Đồ thị là parabol; dấu của a quyết định parabol mở lên hay mở xuống."]'::jsonb, '["y=2x² mở lên vì a=2>0."]'::jsonb, '[{"id":"math-10-quadratic-function-q1","prompt":"Đồ thị hàm số bậc hai là hình nào?","difficulty":"EASY","options":[{"id":"a","text":"Đường tròn"},{"id":"b","text":"Đường thẳng luôn luôn"},{"id":"c","text":"Parabol"}],"correctOptionId":"c","explanation":"Biểu thức bậc hai theo x tạo nên đồ thị parabol."},{"id":"math-10-quadratic-function-q2","prompt":"y=−x²+3 mở về phía nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Không có đồ thị"},{"id":"b","text":"Mở xuống"},{"id":"c","text":"Mở lên"}],"correctOptionId":"b","explanation":"Hệ số a âm nên hai nhánh hướng xuống."},{"id":"math-10-quadratic-function-q3","prompt":"Một vật được phóng lên có độ cao h(t)=−5t²+20t. Đồ thị giúp tìm thời điểm đạt độ cao cực đại bằng cách nào?","difficulty":"APPLIED","options":[{"id":"a","text":"Tìm hoành độ đỉnh parabol"},{"id":"b","text":"Tìm giao điểm với trục Oy"},{"id":"c","text":"Lấy hệ số tự do"}],"correctOptionId":"a","explanation":"Parabol mở xuống nên đỉnh biểu diễn giá trị lớn nhất."}]'::jsonb, '["math-10-quadratic-function"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
