values ('math', 10, 'intro-2026.1', 'math-10-review-1', 6, 'FIVE_LESSON_REVIEW', 'Ôn tập 1', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '[]'::jsonb, '[]'::jsonb, '[{"id":"math-10-sets-q1","prompt":"Kí hiệu nào diễn tả 2 thuộc tập A?","difficulty":"EASY","options":[{"id":"a","text":"2 ∈ A"},{"id":"b","text":"A ∈ 2"},{"id":"c","text":"2 ⊂ A"}],"correctOptionId":"a","explanation":"∈ diễn tả quan hệ giữa một phần tử và một tập hợp."},{"id":"math-10-sets-q2","prompt":"A={1,2,3}, B={2,3,4}. A∩B là gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"{1,4}"},{"id":"b","text":"{1,2,3,4}"},{"id":"c","text":"{2,3}"}],"correctOptionId":"c","explanation":"Giao gồm phần tử có mặt trong cả hai tập."},{"id":"math-10-intervals-q1","prompt":"Đoạn [−1;4] có chứa đầu mút 4 không?","difficulty":"EASY","options":[{"id":"a","text":"Không"},{"id":"b","text":"Chỉ khi 4 âm"},{"id":"c","text":"Có"}],"correctOptionId":"c","explanation":"Dấu ngoặc vuông cho biết đầu mút được lấy."},{"id":"math-10-intervals-q2","prompt":"|−7| bằng bao nhiêu?","difficulty":"MEDIUM","options":[{"id":"a","text":"0"},{"id":"b","text":"7"},{"id":"c","text":"−7"}],"correctOptionId":"b","explanation":"Giá trị tuyệt đối là khoảng cách nên không âm."},{"id":"math-10-linear-inequalities-q1","prompt":"Khi chia hai vế bất đẳng thức cho số âm, cần làm gì?","difficulty":"EASY","options":[{"id":"a","text":"Đổi dấu cả hai vế thành bằng"},{"id":"b","text":"Đổi chiều dấu"},{"id":"c","text":"Giữ nguyên dấu"}],"correctOptionId":"b","explanation":"Nhân hoặc chia với số âm làm thứ tự trên trục số đảo ngược."},{"id":"math-10-linear-inequalities-q2","prompt":"Nghiệm của 3x+1≥7 là?","difficulty":"MEDIUM","options":[{"id":"a","text":"x≥2"},{"id":"b","text":"x≤2"},{"id":"c","text":"x≥6"}],"correctOptionId":"a","explanation":"Trừ 1 rồi chia 3: 3x≥6."},{"id":"math-10-systems-regions-q1","prompt":"Miền nghiệm của hệ gồm những điểm nào?","difficulty":"EASY","options":[{"id":"a","text":"Thỏa đồng thời mọi bất phương trình"},{"id":"b","text":"Chỉ thỏa một bất phương trình bất kỳ"},{"id":"c","text":"Không cần thay tọa độ"}],"correctOptionId":"a","explanation":"Nghiệm hệ phải làm tất cả các điều kiện cùng đúng."},{"id":"math-10-systems-regions-q2","prompt":"Điểm (2,1) có thỏa x≥0, y≥0 không?","difficulty":"MEDIUM","options":[{"id":"a","text":"Không"},{"id":"b","text":"Chỉ thỏa x≥0"},{"id":"c","text":"Có"}],"correctOptionId":"c","explanation":"Cả hai tọa độ đều không âm."},{"id":"math-10-quadratic-function-q1","prompt":"Đồ thị hàm số bậc hai là hình nào?","difficulty":"EASY","options":[{"id":"a","text":"Đường tròn"},{"id":"b","text":"Đường thẳng luôn luôn"},{"id":"c","text":"Parabol"}],"correctOptionId":"c","explanation":"Biểu thức bậc hai theo x tạo nên đồ thị parabol."},{"id":"math-10-quadratic-function-q2","prompt":"y=−x²+3 mở về phía nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Không có đồ thị"},{"id":"b","text":"Mở xuống"},{"id":"c","text":"Mở lên"}],"correctOptionId":"b","explanation":"Hệ số a âm nên hai nhánh hướng xuống."}]'::jsonb, '["math-10-sets","math-10-intervals","math-10-linear-inequalities","math-10-systems-regions","math-10-quadratic-function"]'::jsonb)
