insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'math-10-quadratic-sign', 7, 'LESSON', 'Dấu tam thức bậc hai', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Nghiệm của ax²+bx+c=0 chia trục số thành các khoảng. Với hai nghiệm phân biệt, tam thức cùng dấu với a ở ngoài hai nghiệm và trái dấu với a ở giữa."]'::jsonb, '["x²−5x+6=(x−2)(x−3) âm khi 2<x<3."]'::jsonb, '[{"id":"math-10-quadratic-sign-q1","prompt":"Khi tam thức có hai nghiệm phân biệt, dấu ở ngoài hai nghiệm cùng hay trái dấu với a?","difficulty":"EASY","options":[{"id":"a","text":"Luôn bằng 0"},{"id":"b","text":"Cùng dấu"},{"id":"c","text":"Trái dấu"}],"correctOptionId":"b","explanation":"Quy tắc dấu cho tam thức bậc hai cho dấu cùng a ở hai miền ngoài."},{"id":"math-10-quadratic-sign-q2","prompt":"x²−4 âm trên khoảng nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"(−2;2)"},{"id":"b","text":"(−∞;−2)∪(2;+∞)"},{"id":"c","text":"Chỉ tại x=2"}],"correctOptionId":"a","explanation":"x²−4=(x−2)(x+2), tam thức âm giữa hai nghiệm."},{"id":"math-10-quadratic-sign-q3","prompt":"Để x²−2x−3≤0, chọn tập nghiệm nào?","difficulty":"APPLIED","options":[{"id":"a","text":"(−∞;−1]∪[3;+∞)"},{"id":"b","text":"(−1;3)"},{"id":"c","text":"[−1;3]"}],"correctOptionId":"c","explanation":"Tam thức có nghiệm −1 và 3, hệ số đầu dương; lấy phần giữa, kể cả hai nghiệm."}]'::jsonb, '["math-10-quadratic-sign"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'math-10-quadratic-equations', 8, 'LESSON', 'Phương trình bậc hai', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Với ax²+bx+c=0, biệt thức Δ=b²−4ac cho biết số nghiệm thực: Δ>0 có hai nghiệm, Δ=0 có nghiệm kép, Δ<0 không có nghiệm thực."]'::jsonb, '["x²−5x+6=0 có Δ=1 và nghiệm 2, 3."]'::jsonb, '[{"id":"math-10-quadratic-equations-q1","prompt":"Nếu Δ<0 thì phương trình bậc hai có bao nhiêu nghiệm thực?","difficulty":"EASY","options":[{"id":"a","text":"Không có nghiệm thực"},{"id":"b","text":"Hai nghiệm thực phân biệt"},{"id":"c","text":"Một nghiệm kép"}],"correctOptionId":"a","explanation":"Biệt thức âm loại trừ giao điểm thực với trục hoành."},{"id":"math-10-quadratic-equations-q2","prompt":"Phương trình x²−5x+6=0 có nghiệm nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"−2 và −3"},{"id":"b","text":"1 và 6"},{"id":"c","text":"2 và 3"}],"correctOptionId":"c","explanation":"Phân tích thành (x−2)(x−3)=0."},{"id":"math-10-quadratic-equations-q3","prompt":"Diện tích hình chữ nhật 24 m², chiều dài hơn chiều rộng 2 m. Nếu rộng x, phương trình phù hợp là?","difficulty":"APPLIED","options":[{"id":"a","text":"x²−2=24"},{"id":"b","text":"x(x+2)=24"},{"id":"c","text":"2x+24=0"}],"correctOptionId":"b","explanation":"Diện tích bằng rộng nhân dài; chiều dài là x+2."}]'::jsonb, '["math-10-quadratic-equations"]'::jsonb)
