values ('english', 10, 'intro-2026.1', 'english-10-review-1', 6, 'FIVE_LESSON_REVIEW', 'Ôn tập 1', 'Tiếng Anh: ngữ pháp, từ vựng và giao tiếp nền tảng', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '[]'::jsonb, '[]'::jsonb, '[{"id":"english-10-present-simple-q1","prompt":"Choose the correct form: He ___ to school by bus.","difficulty":"EASY","options":[{"id":"a","text":"goes"},{"id":"b","text":"go"},{"id":"c","text":"going"}],"correctOptionId":"a","explanation":"He is third-person singular, so the verb takes -es."},{"id":"english-10-present-simple-q2","prompt":"Which sentence describes a routine?","difficulty":"MEDIUM","options":[{"id":"a","text":"I am reading right now."},{"id":"b","text":"I read a book yesterday."},{"id":"c","text":"I read for twenty minutes every night."}],"correctOptionId":"c","explanation":"“Every night” signals a repeated habit."},{"id":"english-10-present-continuous-q1","prompt":"Present continuous uses which structure?","difficulty":"EASY","options":[{"id":"a","text":"do/does + base verb"},{"id":"b","text":"will + verb-ing"},{"id":"c","text":"am/is/are + verb-ing"}],"correctOptionId":"c","explanation":"The auxiliary be is followed by the -ing form."},{"id":"english-10-present-continuous-q2","prompt":"Look! The children ___ in the yard.","difficulty":"MEDIUM","options":[{"id":"a","text":"played"},{"id":"b","text":"are playing"},{"id":"c","text":"play"}],"correctOptionId":"b","explanation":"“Look!” points to an action happening now."},{"id":"english-10-past-simple-q1","prompt":"Choose the past form of “go”.","difficulty":"EASY","options":[{"id":"a","text":"gone"},{"id":"b","text":"went"},{"id":"c","text":"goed"}],"correctOptionId":"b","explanation":"“Went” is the simple past form; “gone” is the past participle."},{"id":"english-10-past-simple-q2","prompt":"They ___ the clean-up event yesterday.","difficulty":"MEDIUM","options":[{"id":"a","text":"joined"},{"id":"b","text":"join"},{"id":"c","text":"are join"}],"correctOptionId":"a","explanation":"“Yesterday” calls for the past simple."},{"id":"english-10-future-plans-q1","prompt":"Complete: I ___ going to call my teacher.","difficulty":"EASY","options":[{"id":"a","text":"am"},{"id":"b","text":"is"},{"id":"c","text":"are"}],"correctOptionId":"a","explanation":"Use am with I."},{"id":"english-10-future-plans-q2","prompt":"Which sentence expresses a prior plan?","difficulty":"MEDIUM","options":[{"id":"a","text":"They visited it last week."},{"id":"b","text":"They visit it every Monday."},{"id":"c","text":"They are going to visit the science fair tomorrow."}],"correctOptionId":"c","explanation":"“Be going to” presents a plan for the future."},{"id":"english-10-countable-uncountable-q1","prompt":"Which noun is normally uncountable?","difficulty":"EASY","options":[{"id":"a","text":"apple"},{"id":"b","text":"notebook"},{"id":"c","text":"water"}],"correctOptionId":"c","explanation":"Water is generally treated as an uncountable noun."},{"id":"english-10-countable-uncountable-q2","prompt":"Choose the natural phrase.","difficulty":"MEDIUM","options":[{"id":"a","text":"three informations"},{"id":"b","text":"some information"},{"id":"c","text":"an information"}],"correctOptionId":"b","explanation":"Information is uncountable in standard English."}]'::jsonb, '["english-10-present-simple","english-10-present-continuous","english-10-past-simple","english-10-future-plans","english-10-countable-uncountable"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('english', 10, 'intro-2026.1', 'english-10-comparatives', 7, 'LESSON', 'So sánh hơn', 'Tiếng Anh: ngữ pháp, từ vựng và giao tiếp nền tảng', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Tính từ ngắn thường thêm -er; tính từ dài thường dùng more. So sánh hai đối tượng với than; tránh dùng đồng thời more và -er."]'::jsonb, '["This route is shorter than the old one. The new map is more useful."]'::jsonb, '[{"id":"english-10-comparatives-q1","prompt":"The comparative of “small” is?","difficulty":"EASY","options":[{"id":"a","text":"smallest"},{"id":"b","text":"smaller"},{"id":"c","text":"more small"}],"correctOptionId":"b","explanation":"“Small” normally takes -er for a two-item comparison."},{"id":"english-10-comparatives-q2","prompt":"This exercise is ___ than the last one.","difficulty":"MEDIUM","options":[{"id":"a","text":"more difficult"},{"id":"b","text":"difficulter"},{"id":"c","text":"most difficult than"}],"correctOptionId":"a","explanation":"Long adjectives normally use more in the comparative."},{"id":"english-10-comparatives-q3","prompt":"A bike uses less fuel than a car. Which comparison is expressed?","difficulty":"APPLIED","options":[{"id":"a","text":"The bike uses no fuel in every case."},{"id":"b","text":"The car is always slower."},{"id":"c","text":"The bike uses a smaller amount of fuel."}],"correctOptionId":"c","explanation":"“Less…than” compares quantities and does not mean zero."}]'::jsonb, '["english-10-comparatives"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('english', 10, 'intro-2026.1', 'english-10-modals', 8, 'LESSON', 'Modal verbs: can, should, must', 'Tiếng Anh: ngữ pháp, từ vựng và giao tiếp nền tảng', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Modal verbs đi với động từ nguyên mẫu không to. Can diễn tả khả năng/cho phép; should đưa lời khuyên; must diễn tả sự cần thiết mạnh."]'::jsonb, '["You should save your work; you must wear a helmet here."]'::jsonb, '[{"id":"english-10-modals-q1","prompt":"After “should”, use which verb form?","difficulty":"EASY","options":[{"id":"a","text":"Base form without to"},{"id":"b","text":"Past participle"},{"id":"c","text":"Verb-ing"}],"correctOptionId":"a","explanation":"Modal should is followed by the bare infinitive."},{"id":"english-10-modals-q2","prompt":"Choose a suitable piece of advice.","difficulty":"MEDIUM","options":[{"id":"a","text":"You should to take a break."},{"id":"b","text":"You should took a break."},{"id":"c","text":"You should take a short break."}],"correctOptionId":"c","explanation":"The correct pattern is should + base verb."},{"id":"english-10-modals-q3","prompt":"A sign says helmets are required. Which sentence best expresses the rule?","difficulty":"APPLIED","options":[{"id":"a","text":"You should to wear a helmet."},{"id":"b","text":"You must wear a helmet."},{"id":"c","text":"You can wearing a helmet."}],"correctOptionId":"b","explanation":"Must expresses a strong requirement; the verb remains in base form."}]'::jsonb, '["english-10-modals"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('english', 10, 'intro-2026.1', 'english-10-passive', 9, 'LESSON', 'Câu bị động cơ bản', 'Tiếng Anh: ngữ pháp, từ vựng và giao tiếp nền tảng', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Dùng be + past participle khi muốn nhấn mạnh đối tượng chịu tác động. Thì của câu được thể hiện qua be; tác nhân có thể nêu với by."]'::jsonb, '["The school library was opened in 2015."]'::jsonb, '[{"id":"english-10-passive-q1","prompt":"A basic passive verb phrase contains?","difficulty":"EASY","options":[{"id":"a","text":"have + -ing"},{"id":"b","text":"do + base verb"},{"id":"c","text":"be + past participle"}],"correctOptionId":"c","explanation":"The auxiliary be changes with tense and the main verb uses a past participle."},{"id":"english-10-passive-q2","prompt":"Choose the correct passive sentence.","difficulty":"MEDIUM","options":[{"id":"a","text":"The posters was design by students."},{"id":"b","text":"The posters were designed by students."},{"id":"c","text":"The posters designed by students."}],"correctOptionId":"b","explanation":"Plural subject posters takes were; designed is the past participle."},{"id":"english-10-passive-q3","prompt":"People recycle paper at this center. What is the passive form?","difficulty":"APPLIED","options":[{"id":"a","text":"Paper is recycled at this center."},{"id":"b","text":"Paper recycled people at this center."},{"id":"c","text":"Paper are recycle at this center."}],"correctOptionId":"a","explanation":"Paper is the singular subject; use is + recycled."}]'::jsonb, '["english-10-passive"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('english', 10, 'intro-2026.1', 'english-10-gerunds-infinitives', 10, 'LESSON', 'V-ing và to-infinitive sau động từ', 'Tiếng Anh: ngữ pháp, từ vựng và giao tiếp nền tảng', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Một số động từ theo sau bởi V-ing, một số theo sau bởi to + động từ nguyên mẫu. Học theo cụm động từ, không thay dạng theo cảm tính."]'::jsonb, '["enjoy reading; decide to join; want to learn."]'::jsonb, '[{"id":"english-10-gerunds-infinitives-q1","prompt":"Complete: I enjoy ___ novels.","difficulty":"EASY","options":[{"id":"a","text":"read"},{"id":"b","text":"reading"},{"id":"c","text":"to reading"}],"correctOptionId":"b","explanation":"Enjoy is followed by a gerund."},{"id":"english-10-gerunds-infinitives-q2","prompt":"Complete: They decided ___ the club.","difficulty":"MEDIUM","options":[{"id":"a","text":"to join"},{"id":"b","text":"joining to"},{"id":"c","text":"join"}],"correctOptionId":"a","explanation":"Decide is commonly followed by a to-infinitive."},{"id":"english-10-gerunds-infinitives-q3","prompt":"Which sentence uses the pattern correctly?","difficulty":"APPLIED","options":[{"id":"a","text":"She hopes improving her pronunciation."},{"id":"b","text":"She hopes improve her pronunciation."},{"id":"c","text":"She hopes to improve her pronunciation."}],"correctOptionId":"c","explanation":"Hope is followed by to + base verb."}]'::jsonb, '["english-10-gerunds-infinitives"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('english', 10, 'intro-2026.1', 'english-10-relative-clauses', 11, 'LESSON', 'Mệnh đề quan hệ với who, which, that', 'Tiếng Anh: ngữ pháp, từ vựng và giao tiếp nền tảng', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Mệnh đề quan hệ bổ sung thông tin cho danh từ. Who thường chỉ người; which chỉ vật/sự việc; that có thể thay trong nhiều mệnh đề xác định."]'::jsonb, '["The student who won the contest thanked her team."]'::jsonb, '[{"id":"english-10-relative-clauses-q1","prompt":"Choose a relative word for a person.","difficulty":"EASY","options":[{"id":"a","text":"who"},{"id":"b","text":"where"},{"id":"c","text":"when"}],"correctOptionId":"a","explanation":"Who refers to people."},{"id":"english-10-relative-clauses-q2","prompt":"The book ___ I borrowed is about space.","difficulty":"MEDIUM","options":[{"id":"a","text":"who"},{"id":"b","text":"where"},{"id":"c","text":"which"}],"correctOptionId":"c","explanation":"Which refers to the thing, book."},{"id":"english-10-relative-clauses-q3","prompt":"A “teacher who listens carefully” means the teacher ___ carefully.","difficulty":"APPLIED","options":[{"id":"a","text":"happened yesterday"},{"id":"b","text":"listens carefully"},{"id":"c","text":"is a place"}],"correctOptionId":"b","explanation":"The relative clause gives information about the teacher."}]'::jsonb, '["english-10-relative-clauses"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('english', 10, 'intro-2026.1', 'english-10-review-2', 12, 'FIVE_LESSON_REVIEW', 'Ôn tập 2', 'Tiếng Anh: ngữ pháp, từ vựng và giao tiếp nền tảng', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '[]'::jsonb, '[]'::jsonb, '[{"id":"english-10-comparatives-q1","prompt":"The comparative of “small” is?","difficulty":"EASY","options":[{"id":"a","text":"smallest"},{"id":"b","text":"smaller"},{"id":"c","text":"more small"}],"correctOptionId":"b","explanation":"“Small” normally takes -er for a two-item comparison."},{"id":"english-10-comparatives-q2","prompt":"This exercise is ___ than the last one.","difficulty":"MEDIUM","options":[{"id":"a","text":"more difficult"},{"id":"b","text":"difficulter"},{"id":"c","text":"most difficult than"}],"correctOptionId":"a","explanation":"Long adjectives normally use more in the comparative."},{"id":"english-10-modals-q1","prompt":"After “should”, use which verb form?","difficulty":"EASY","options":[{"id":"a","text":"Base form without to"},{"id":"b","text":"Past participle"},{"id":"c","text":"Verb-ing"}],"correctOptionId":"a","explanation":"Modal should is followed by the bare infinitive."},{"id":"english-10-modals-q2","prompt":"Choose a suitable piece of advice.","difficulty":"MEDIUM","options":[{"id":"a","text":"You should to take a break."},{"id":"b","text":"You should took a break."},{"id":"c","text":"You should take a short break."}],"correctOptionId":"c","explanation":"The correct pattern is should + base verb."},{"id":"english-10-passive-q1","prompt":"A basic passive verb phrase contains?","difficulty":"EASY","options":[{"id":"a","text":"have + -ing"},{"id":"b","text":"do + base verb"},{"id":"c","text":"be + past participle"}],"correctOptionId":"c","explanation":"The auxiliary be changes with tense and the main verb uses a past participle."},{"id":"english-10-passive-q2","prompt":"Choose the correct passive sentence.","difficulty":"MEDIUM","options":[{"id":"a","text":"The posters was design by students."},{"id":"b","text":"The posters were designed by students."},{"id":"c","text":"The posters designed by students."}],"correctOptionId":"b","explanation":"Plural subject posters takes were; designed is the past participle."},{"id":"english-10-gerunds-infinitives-q1","prompt":"Complete: I enjoy ___ novels.","difficulty":"EASY","options":[{"id":"a","text":"read"},{"id":"b","text":"reading"},{"id":"c","text":"to reading"}],"correctOptionId":"b","explanation":"Enjoy is followed by a gerund."},{"id":"english-10-gerunds-infinitives-q2","prompt":"Complete: They decided ___ the club.","difficulty":"MEDIUM","options":[{"id":"a","text":"to join"},{"id":"b","text":"joining to"},{"id":"c","text":"join"}],"correctOptionId":"a","explanation":"Decide is commonly followed by a to-infinitive."},{"id":"english-10-relative-clauses-q1","prompt":"Choose a relative word for a person.","difficulty":"EASY","options":[{"id":"a","text":"who"},{"id":"b","text":"where"},{"id":"c","text":"when"}],"correctOptionId":"a","explanation":"Who refers to people."},{"id":"english-10-relative-clauses-q2","prompt":"The book ___ I borrowed is about space.","difficulty":"MEDIUM","options":[{"id":"a","text":"who"},{"id":"b","text":"where"},{"id":"c","text":"which"}],"correctOptionId":"c","explanation":"Which refers to the thing, book."}]'::jsonb, '["english-10-comparatives","english-10-modals","english-10-passive","english-10-gerunds-infinitives","english-10-relative-clauses"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('english', 10, 'intro-2026.1', 'english-10-conditionals', 13, 'LESSON', 'Câu điều kiện loại 0 và loại 1', 'Tiếng Anh: ngữ pháp, từ vựng và giao tiếp nền tảng', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Loại 0 nói quy luật chung: if + hiện tại đơn, hiện tại đơn. Loại 1 nói khả năng tương lai: if + hiện tại đơn, will + động từ nguyên mẫu."]'::jsonb, '["If you heat ice, it melts. If it rains, we will study indoors."]'::jsonb, '[{"id":"english-10-conditionals-q1","prompt":"A general scientific fact usually uses which pattern?","difficulty":"EASY","options":[{"id":"a","text":"If + past, will + past"},{"id":"b","text":"If + will, present"},{"id":"c","text":"If + present, present"}],"correctOptionId":"c","explanation":"Zero conditional uses present simple in both clauses."},{"id":"english-10-conditionals-q2","prompt":"If we finish early, we ___ the exhibition.","difficulty":"MEDIUM","options":[{"id":"a","text":"visiting"},{"id":"b","text":"will visit"},{"id":"c","text":"visited"}],"correctOptionId":"b","explanation":"First conditional uses will + base verb in the likely result."},{"id":"english-10-conditionals-q3","prompt":"If water reaches 100°C at standard pressure, it ___.","difficulty":"APPLIED","options":[{"id":"a","text":"boils"},{"id":"b","text":"will boiled"},{"id":"c","text":"boil yesterday"}],"correctOptionId":"a","explanation":"This describes a general condition and result."}]'::jsonb, '["english-10-conditionals"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('english', 10, 'intro-2026.1', 'english-10-reported-speech', 14, 'LESSON', 'Tường thuật lời nói đơn giản', 'Tiếng Anh: ngữ pháp, từ vựng và giao tiếp nền tảng', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Khi tường thuật lời nói ở quá khứ, đại từ và một số thì có thể lùi theo ngữ cảnh. Không đổi máy móc nếu thông tin vẫn đúng hoặc thời điểm không thay đổi."]'::jsonb, '["“I am tired,” Lan said. → Lan said that she was tired."]'::jsonb, '[{"id":"english-10-reported-speech-q1","prompt":"“I am ready,” he said. A common reported form is?","difficulty":"EASY","options":[{"id":"a","text":"He said that he is readyed."},{"id":"b","text":"He said that he was ready."},{"id":"c","text":"He says I am ready yesterday."}],"correctOptionId":"b","explanation":"With a past reporting verb, am commonly shifts to was and pronouns change."},{"id":"english-10-reported-speech-q2","prompt":"Which reporting verb is in the past?","difficulty":"MEDIUM","options":[{"id":"a","text":"said"},{"id":"b","text":"says"},{"id":"c","text":"will say"}],"correctOptionId":"a","explanation":"Said is the past form of say."},{"id":"english-10-reported-speech-q3","prompt":"A speaker says “We live here” and the reporter is describing a past conversation. What should guide tense choice?","difficulty":"APPLIED","options":[{"id":"a","text":"Always change every verb twice"},{"id":"b","text":"Ignore pronouns"},{"id":"c","text":"The reporting context and whether the fact remains true"}],"correctOptionId":"c","explanation":"Reported speech depends on time reference and current truth."}]'::jsonb, '["english-10-reported-speech"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('english', 10, 'intro-2026.1', 'english-10-environment-vocabulary', 15, 'LESSON', 'Từ vựng về môi trường', 'Tiếng Anh: ngữ pháp, từ vựng và giao tiếp nền tảng', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Học từ theo cụm và ngữ cảnh: reduce waste, protect wildlife, renewable energy. Dùng từ đúng sắc thái và kết hợp tự nhiên."]'::jsonb, '["Schools can reduce waste by reusing paper and sorting recyclable materials."]'::jsonb, '[{"id":"english-10-environment-vocabulary-q1","prompt":"Which phrase means “giảm rác thải”?","difficulty":"EASY","options":[{"id":"a","text":"reduce waste"},{"id":"b","text":"make waste"},{"id":"c","text":"waste a reduce"}],"correctOptionId":"a","explanation":"Reduce means make something smaller or less."},{"id":"english-10-environment-vocabulary-q2","prompt":"Solar power is an example of ___ energy.","difficulty":"MEDIUM","options":[{"id":"a","text":"single-use"},{"id":"b","text":"polluted"},{"id":"c","text":"renewable"}],"correctOptionId":"c","explanation":"Solar energy is naturally replenished."},{"id":"english-10-environment-vocabulary-q3","prompt":"A class wants to protect local birds. Which action best matches the goal?","difficulty":"APPLIED","options":[{"id":"a","text":"Feed them plastic scraps."},{"id":"b","text":"Keep nesting areas clean and avoid disturbing them."},{"id":"c","text":"Remove every tree near the school."}],"correctOptionId":"b","explanation":"Protecting habitat and reducing disturbance support wildlife."}]'::jsonb, '["english-10-environment-vocabulary"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('english', 10, 'intro-2026.1', 'english-10-reading-strategies', 16, 'LESSON', 'Đọc hiểu: ý chính và chi tiết', 'Tiếng Anh: ngữ pháp, từ vựng và giao tiếp nền tảng', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Đọc lướt để nắm chủ đề; đọc quét để tìm tên, số liệu hoặc từ khóa. Suy luận phải dựa trên thông tin văn bản và tránh thêm giả định."]'::jsonb, '["Nếu đoạn nêu ba lợi ích của vận động nhưng không nói thời lượng, không thể kết luận chính xác bao lâu là tối ưu."]'::jsonb, '[{"id":"english-10-reading-strategies-q1","prompt":"Skimming is mainly used to find?","difficulty":"EASY","options":[{"id":"a","text":"Every punctuation mark"},{"id":"b","text":"A word''s spelling only"},{"id":"c","text":"The general idea"}],"correctOptionId":"c","explanation":"Skimming quickly identifies the overall topic and structure."},{"id":"english-10-reading-strategies-q2","prompt":"Scanning is useful when you need to find?","difficulty":"MEDIUM","options":[{"id":"a","text":"A new paragraph to add"},{"id":"b","text":"A specific date or name"},{"id":"c","text":"The author''s entire life story"}],"correctOptionId":"b","explanation":"Scanning searches selectively for a particular detail."},{"id":"english-10-reading-strategies-q3","prompt":"The text says a park opened in 2022 and attracts many families. Can you infer its exact visitor count?","difficulty":"APPLIED","options":[{"id":"a","text":"No, the exact number is not given."},{"id":"b","text":"Yes, it must be 2,022."},{"id":"c","text":"Yes, every family visits daily."}],"correctOptionId":"a","explanation":"Inference must stay within what the text supports."}]'::jsonb, '["english-10-reading-strategies"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('english', 10, 'intro-2026.1', 'english-10-paragraph-writing', 17, 'LESSON', 'Viết đoạn văn tiếng Anh có mạch lạc', 'Tiếng Anh: ngữ pháp, từ vựng và giao tiếp nền tảng', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Một đoạn ngắn thường có câu chủ đề, các câu hỗ trợ và câu kết hoặc chuyển ý. Dùng từ nối đúng quan hệ, kiểm tra hòa hợp chủ-vị và dấu câu."]'::jsonb, '["Topic sentence: “Walking to school can benefit students.” Supporting details explain exercise and reduced traffic."]'::jsonb, '[{"id":"english-10-paragraph-writing-q1","prompt":"What does a topic sentence usually do?","difficulty":"EASY","options":[{"id":"a","text":"Replace all supporting details"},{"id":"b","text":"State the paragraph''s main idea"},{"id":"c","text":"List every source"}],"correctOptionId":"b","explanation":"The topic sentence guides the paragraph''s focus."},{"id":"english-10-paragraph-writing-q2","prompt":"Choose the correct connector for a contrast.","difficulty":"MEDIUM","options":[{"id":"a","text":"However"},{"id":"b","text":"Because of"},{"id":"c","text":"For example of"}],"correctOptionId":"a","explanation":"However introduces a contrasting idea."},{"id":"english-10-paragraph-writing-q3","prompt":"Which paragraph plan is clearest?","difficulty":"APPLIED","options":[{"id":"a","text":"Unrelated facts → new topic → title"},{"id":"b","text":"Only a list of connectors"},{"id":"c","text":"Main idea → reasons/examples → closing sentence"}],"correctOptionId":"c","explanation":"A logical order helps readers follow the argument."}]'::jsonb, '["english-10-paragraph-writing"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
