},{"id":"c","text":"waste a reduce"}],"correctOptionId":"a","explanation":"Reduce means make something smaller or less."},{"id":"english-10-environment-vocabulary-q2","prompt":"Solar power is an example of ___ energy.","difficulty":"MEDIUM","options":[{"id":"a","text":"single-use"},{"id":"b","text":"polluted"},{"id":"c","text":"renewable"}],"correctOptionId":"c","explanation":"Solar energy is naturally replenished."},{"id":"english-10-reading-strategies-q1","prompt":"Skimming is mainly used to find?","difficulty":"EASY","options":[{"id":"a","text":"Every punctuation mark"},{"id":"b","text":"A word''s spelling only"},{"id":"c","text":"The general idea"}],"correctOptionId":"c","explanation":"Skimming quickly identifies the overall topic and structure."},{"id":"english-10-reading-strategies-q2","prompt":"Scanning is useful when you need to find?","difficulty":"MEDIUM","options":[{"id":"a","text":"A new paragraph to add"},{"id":"b","text":"A specific date or name"},{"id":"c","text":"The author''s entire life story"}],"correctOptionId":"b","explanation":"Scanning searches selectively for a particular detail."},{"id":"english-10-paragraph-writing-q1","prompt":"What does a topic sentence usually do?","difficulty":"EASY","options":[{"id":"a","text":"Replace all supporting details"},{"id":"b","text":"State the paragraph''s main idea"},{"id":"c","text":"List every source"}],"correctOptionId":"b","explanation":"The topic sentence guides the paragraph''s focus."},{"id":"english-10-paragraph-writing-q2","prompt":"Choose the correct connector for a contrast.","difficulty":"MEDIUM","options":[{"id":"a","text":"However"},{"id":"b","text":"Because of"},{"id":"c","text":"For example of"}],"correctOptionId":"a","explanation":"However introduces a contrasting idea."}]'::jsonb, '["english-10-conditionals","english-10-reported-speech","english-10-environment-vocabulary","english-10-reading-strategies","english-10-paragraph-writing"]'::jsonb)
