insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('history', 10, 'intro-2026.1', 'placement', 0, 'PLACEMENT', 'Khảo sát đầu vào', 'Lịch sử: tư liệu, văn minh và biến đổi xã hội', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '[]'::jsonb, '[]'::jsonb, '[{"id":"history-10-historical-evidence-q1","prompt":"Tư liệu gốc thường được tạo khi nào?","difficulty":"EASY","options":[{"id":"a","text":"Trong hoặc gần thời kì được nghiên cứu"},{"id":"b","text":"Luôn luôn nhiều thế kỉ sau"},{"id":"c","text":"Sau khi mọi sử gia đồng ý"}],"correctOptionId":"a","explanation":"Tính gốc gắn với quan hệ gần thời gian, không tự bảo đảm tính chính xác."},{"id":"history-10-historical-evidence-q2","prompt":"Một bài nghiên cứu tổng hợp nhiều biên niên sử thường là?","difficulty":"MEDIUM","options":[{"id":"a","text":"Hiện vật tiền sử"},{"id":"b","text":"Địa hình tự nhiên"},{"id":"c","text":"Tư liệu thứ cấp"}],"correctOptionId":"c","explanation":"Nó diễn giải các nguồn khác thay vì là hiện vật trực tiếp của sự kiện."},{"id":"history-10-chronology-q1","prompt":"Dòng thời gian chủ yếu giúp ích việc nào?","difficulty":"EASY","options":[{"id":"a","text":"Tự chứng minh nguyên nhân"},{"id":"b","text":"Xác định cảm xúc tác giả"},{"id":"c","text":"Sắp xếp trình tự sự kiện"}],"correctOptionId":"c","explanation":"Trình tự thời gian không tự trả lời vì sao sự kiện xảy ra."},{"id":"history-10-chronology-q2","prompt":"Trong mốc trước Công nguyên, năm 500 TCN hay 200 TCN xảy ra trước?","difficulty":"MEDIUM","options":[{"id":"a","text":"Cùng lúc"},{"id":"b","text":"500 TCN"},{"id":"c","text":"200 TCN"}],"correctOptionId":"b","explanation":"Số năm TCN lớn hơn nằm xa hơn về quá khứ."},{"id":"history-10-prehistory-q1","prompt":"Khảo cổ học chủ yếu dựa vào loại bằng chứng nào?","difficulty":"EASY","options":[{"id":"a","text":"Dự báo thời tiết"},{"id":"b","text":"Di tích và hiện vật vật chất"},{"id":"c","text":"Tin đồn chưa kiểm chứng"}],"correctOptionId":"b","explanation":"Đồ vật và di tích cung cấp bằng chứng vật chất về hoạt động con người."},{"id":"history-10-prehistory-q2","prompt":"Vì sao bối cảnh tìm thấy hiện vật quan trọng?","difficulty":"MEDIUM","options":[{"id":"a","text":"Nó giúp xác định niên đại và mối liên hệ"},{"id":"b","text":"Nó làm hiện vật tự nói mọi điều"},{"id":"c","text":"Nó thay thế việc bảo quản"}],"correctOptionId":"a","explanation":"Vị trí, lớp đất và vật đi kèm ảnh hưởng cách diễn giải."},{"id":"history-10-early-civilizations-q1","prompt":"Sông có thể hỗ trợ cư dân cổ đại bằng cách nào?","difficulty":"EASY","options":[{"id":"a","text":"Nước, đất canh tác và giao thông"},{"id":"b","text":"Tự động tạo nhà nước hiện đại"},{"id":"c","text":"Loại bỏ mọi thiên tai"}],"correctOptionId":"a","explanation":"Sông tạo điều kiện nhưng xã hội vẫn cần tổ chức và thích nghi."},{"id":"history-10-early-civilizations-q2","prompt":"Chữ viết cổ thường giúp gì cho nhà nước?","difficulty":"MEDIUM","options":[{"id":"a","text":"Thay thế mọi hoạt động sản xuất"},{"id":"b","text":"Bảo đảm mọi người biết đọc"},{"id":"c","text":"Ghi chép giao dịch, luật lệ hoặc sự kiện"}],"correctOptionId":"c","explanation":"Ghi chép hỗ trợ quản lý nhưng mức biết chữ khác nhau."},{"id":"history-10-india-china-q1","prompt":"Khi so sánh hai nền văn minh, bước đầu nên làm gì?","difficulty":"EASY","options":[{"id":"a","text":"Gộp mọi thế kỉ"},{"id":"b","text":"Chọn một bên làm chuẩn duy nhất"},{"id":"c","text":"Xác định thời kì và tiêu chí chung"}],"correctOptionId":"c","explanation":"Tiêu chí và mốc thời gian rõ giúp so sánh công bằng."},{"id":"history-10-india-china-q2","prompt":"Một truyền thống tư tưởng kéo dài qua nhiều triều đại có nghĩa là?","difficulty":"MEDIUM","options":[{"id":"a","text":"Mọi cư dân đều nghĩ giống nhau"},{"id":"b","text":"Có sự kế thừa và biến đổi theo bối cảnh"},{"id":"c","text":"Không bao giờ thay đổi"}],"correctOptionId":"b","explanation":"Truyền thống thường được diễn giải lại trong các thời kì."}]'::jsonb, '[]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('history', 10, 'intro-2026.1', 'history-10-historical-evidence', 1, 'LESSON', 'Lịch sử và bằng chứng', 'Lịch sử: tư liệu, văn minh và biến đổi xã hội', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Lịch sử nghiên cứu quá khứ con người qua tư liệu. Tư liệu gốc được tạo trong thời kì hoặc sự kiện; tư liệu thứ cấp phân tích, tổng hợp tư liệu khác."]'::jsonb, '["Một lá thư cùng thời là tư liệu gốc về người viết, nhưng vẫn cần kiểm tra người nhận, mục đích và độ xác thực."]'::jsonb, '[{"id":"history-10-historical-evidence-q1","prompt":"Tư liệu gốc thường được tạo khi nào?","difficulty":"EASY","options":[{"id":"a","text":"Trong hoặc gần thời kì được nghiên cứu"},{"id":"b","text":"Luôn luôn nhiều thế kỉ sau"},{"id":"c","text":"Sau khi mọi sử gia đồng ý"}],"correctOptionId":"a","explanation":"Tính gốc gắn với quan hệ gần thời gian, không tự bảo đảm tính chính xác."},{"id":"history-10-historical-evidence-q2","prompt":"Một bài nghiên cứu tổng hợp nhiều biên niên sử thường là?","difficulty":"MEDIUM","options":[{"id":"a","text":"Hiện vật tiền sử"},{"id":"b","text":"Địa hình tự nhiên"},{"id":"c","text":"Tư liệu thứ cấp"}],"correctOptionId":"c","explanation":"Nó diễn giải các nguồn khác thay vì là hiện vật trực tiếp của sự kiện."},{"id":"history-10-historical-evidence-q3","prompt":"Hai nguồn cùng thời đưa ra lời kể khác nhau. Cách làm phù hợp là?","difficulty":"APPLIED","options":[{"id":"a","text":"Bỏ qua cả hai"},{"id":"b","text":"So sánh nguồn gốc, mục đích và bằng chứng bổ sung"},{"id":"c","text":"Chọn nguồn kể hấp dẫn hơn"}],"correctOptionId":"b","explanation":"Đối chiếu giúp đánh giá giới hạn và điểm giao nhau giữa nguồn."}]'::jsonb, '["history-10-historical-evidence"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('history', 10, 'intro-2026.1', 'history-10-chronology', 2, 'LESSON', 'Niên đại và dòng thời gian', 'Lịch sử: tư liệu, văn minh và biến đổi xã hội', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Niên đại giúp sắp xếp trước-sau; quy đổi mốc cần chú ý hệ lịch và cách ghi. Dòng thời gian hỗ trợ thấy trình tự nhưng không tự giải thích nguyên nhân."]'::jsonb, '["Nếu sự kiện A năm 120 trước Công nguyên và B năm 30 trước Công nguyên, A xảy ra trước B."]'::jsonb, '[{"id":"history-10-chronology-q1","prompt":"Dòng thời gian chủ yếu giúp ích việc nào?","difficulty":"EASY","options":[{"id":"a","text":"Tự chứng minh nguyên nhân"},{"id":"b","text":"Xác định cảm xúc tác giả"},{"id":"c","text":"Sắp xếp trình tự sự kiện"}],"correctOptionId":"c","explanation":"Trình tự thời gian không tự trả lời vì sao sự kiện xảy ra."},{"id":"history-10-chronology-q2","prompt":"Trong mốc trước Công nguyên, năm 500 TCN hay 200 TCN xảy ra trước?","difficulty":"MEDIUM","options":[{"id":"a","text":"Cùng lúc"},{"id":"b","text":"500 TCN"},{"id":"c","text":"200 TCN"}],"correctOptionId":"b","explanation":"Số năm TCN lớn hơn nằm xa hơn về quá khứ."},{"id":"history-10-chronology-q3","prompt":"Hai cải cách diễn ra lần lượt nhưng có nhiều nguyên nhân xã hội. Chỉ dựa vào dòng thời gian có đủ để kết luận cải cách đầu gây ra cải cách sau không?","difficulty":"APPLIED","options":[{"id":"a","text":"Không, cần thêm chứng cứ về quan hệ nhân quả"},{"id":"b","text":"Có, vì cái trước luôn gây cái sau"},{"id":"c","text":"Có, nếu dùng màu khác"}],"correctOptionId":"a","explanation":"Trình tự là điều kiện xem xét nhưng không chứng minh quan hệ nhân quả."}]'::jsonb, '["history-10-chronology"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('history', 10, 'intro-2026.1', 'history-10-prehistory', 3, 'LESSON', 'Khảo cổ học và đời sống tiền sử', 'Lịch sử: tư liệu, văn minh và biến đổi xã hội', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Khảo cổ học nghiên cứu dấu tích vật chất để tìm hiểu đời sống quá khứ. Một hiện vật cần bối cảnh phát hiện; vật liệu hay hình dáng riêng lẻ không cho biết toàn bộ xã hội."]'::jsonb, '["Công cụ đá tìm trong lớp đất có niên đại xác định có thể gợi kỹ thuật, nhưng cần so sánh nhiều hiện vật."]'::jsonb, '[{"id":"history-10-prehistory-q1","prompt":"Khảo cổ học chủ yếu dựa vào loại bằng chứng nào?","difficulty":"EASY","options":[{"id":"a","text":"Dự báo thời tiết"},{"id":"b","text":"Di tích và hiện vật vật chất"},{"id":"c","text":"Tin đồn chưa kiểm chứng"}],"correctOptionId":"b","explanation":"Đồ vật và di tích cung cấp bằng chứng vật chất về hoạt động con người."},{"id":"history-10-prehistory-q2","prompt":"Vì sao bối cảnh tìm thấy hiện vật quan trọng?","difficulty":"MEDIUM","options":[{"id":"a","text":"Nó giúp xác định niên đại và mối liên hệ"},{"id":"b","text":"Nó làm hiện vật tự nói mọi điều"},{"id":"c","text":"Nó thay thế việc bảo quản"}],"correctOptionId":"a","explanation":"Vị trí, lớp đất và vật đi kèm ảnh hưởng cách diễn giải."},{"id":"history-10-prehistory-q3","prompt":"Tìm thấy một công cụ đá, kết luận chắc chắn nhất là?","difficulty":"APPLIED","options":[{"id":"a","text":"Đã biết chính xác mọi nghề nghiệp"},{"id":"b","text":"Chứng minh toàn bộ cư dân cùng sống một kiểu"},{"id":"c","text":"Có hoạt động chế tác hoặc sử dụng công cụ; cần thêm dữ liệu để mô tả xã hội"}],"correctOptionId":"c","explanation":"Một hiện vật hỗ trợ kết luận giới hạn, không đại diện toàn bộ đời sống."}]'::jsonb, '["history-10-prehistory"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('history', 10, 'intro-2026.1', 'history-10-early-civilizations', 4, 'LESSON', 'Những nền văn minh cổ đại ven sông', 'Lịch sử: tư liệu, văn minh và biến đổi xã hội', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Các nền văn minh sớm phát triển ở nhiều lưu vực sông nhờ nước, đất và giao thông. Không nên xem môi trường tự nhiên là nguyên nhân duy nhất; tổ chức xã hội và sáng tạo con người cũng quan trọng."]'::jsonb, '["Tưới tiêu ở lưu vực sông có thể hỗ trợ nông nghiệp và đòi hỏi phối hợp cộng đồng."]'::jsonb, '[{"id":"history-10-early-civilizations-q1","prompt":"Sông có thể hỗ trợ cư dân cổ đại bằng cách nào?","difficulty":"EASY","options":[{"id":"a","text":"Nước, đất canh tác và giao thông"},{"id":"b","text":"Tự động tạo nhà nước hiện đại"},{"id":"c","text":"Loại bỏ mọi thiên tai"}],"correctOptionId":"a","explanation":"Sông tạo điều kiện nhưng xã hội vẫn cần tổ chức và thích nghi."},{"id":"history-10-early-civilizations-q2","prompt":"Chữ viết cổ thường giúp gì cho nhà nước?","difficulty":"MEDIUM","options":[{"id":"a","text":"Thay thế mọi hoạt động sản xuất"},{"id":"b","text":"Bảo đảm mọi người biết đọc"},{"id":"c","text":"Ghi chép giao dịch, luật lệ hoặc sự kiện"}],"correctOptionId":"c","explanation":"Ghi chép hỗ trợ quản lý nhưng mức biết chữ khác nhau."},{"id":"history-10-early-civilizations-q3","prompt":"Một đô thị xuất hiện bên sông. Muốn giải thích sự phát triển, cần xem thêm điều gì ngoài nguồn nước?","difficulty":"APPLIED","options":[{"id":"a","text":"Màu sắc hiện vật"},{"id":"b","text":"Sản xuất, trao đổi và thiết chế xã hội"},{"id":"c","text":"Chỉ hình dáng con sông"}],"correctOptionId":"b","explanation":"Nhiều yếu tố tương tác tạo nên đô thị."}]'::jsonb, '["history-10-early-civilizations"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('history', 10, 'intro-2026.1', 'history-10-india-china', 5, 'LESSON', 'Văn minh Ấn Độ và Trung Hoa cổ', 'Lịch sử: tư liệu, văn minh và biến đổi xã hội', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Nam Á và Đông Á hình thành những truyền thống đa dạng về tư tưởng, chữ viết, chính trị và kỹ thuật. Cần xác định thời kì, địa bàn trước khi so sánh, tránh gom nhiều triều đại thành một."]'::jsonb, '["So sánh một văn bản triết học với luật lệ cùng thời có thể cho thấy các hình thức tổ chức tư tưởng khác nhau."]'::jsonb, '[{"id":"history-10-india-china-q1","prompt":"Khi so sánh hai nền văn minh, bước đầu nên làm gì?","difficulty":"EASY","options":[{"id":"a","text":"Gộp mọi thế kỉ"},{"id":"b","text":"Chọn một bên làm chuẩn duy nhất"},{"id":"c","text":"Xác định thời kì và tiêu chí chung"}],"correctOptionId":"c","explanation":"Tiêu chí và mốc thời gian rõ giúp so sánh công bằng."},{"id":"history-10-india-china-q2","prompt":"Một truyền thống tư tưởng kéo dài qua nhiều triều đại có nghĩa là?","difficulty":"MEDIUM","options":[{"id":"a","text":"Mọi cư dân đều nghĩ giống nhau"},{"id":"b","text":"Có sự kế thừa và biến đổi theo bối cảnh"},{"id":"c","text":"Không bao giờ thay đổi"}],"correctOptionId":"b","explanation":"Truyền thống thường được diễn giải lại trong các thời kì."},{"id":"history-10-india-china-q3","prompt":"Muốn so sánh hệ thống chữ viết của hai xã hội, nên xem gì?","difficulty":"APPLIED","options":[{"id":"a","text":"Dạng chữ, cách sử dụng và nhóm người dùng"},{"id":"b","text":"Chỉ số trang sách hiện đại"},{"id":"c","text":"Tỷ giá tiền hôm nay"}],"correctOptionId":"a","explanation":"So sánh lịch sử cần chứng cứ cùng chức năng và bối cảnh."}]'::jsonb, '["history-10-india-china"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('history', 10, 'intro-2026.1', 'history-10-review-1', 6, 'FIVE_LESSON_REVIEW', 'Ôn tập 1', 'Lịch sử: tư liệu, văn minh và biến đổi xã hội', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '[]'::jsonb, '[]'::jsonb, '[{"id":"history-10-historical-evidence-q1","prompt":"Tư liệu gốc thường được tạo khi nào?","difficulty":"EASY","options":[{"id":"a","text":"Trong hoặc gần thời kì được nghiên cứu"},{"id":"b","text":"Luôn luôn nhiều thế kỉ sau"},{"id":"c","text":"Sau khi mọi sử gia đồng ý"}],"correctOptionId":"a","explanation":"Tính gốc gắn với quan hệ gần thời gian, không tự bảo đảm tính chính xác."},{"id":"history-10-historical-evidence-q2","prompt":"Một bài nghiên cứu tổng hợp nhiều biên niên sử thường là?","difficulty":"MEDIUM","options":[{"id":"a","text":"Hiện vật tiền sử"},{"id":"b","text":"Địa hình tự nhiên"},{"id":"c","text":"Tư liệu thứ cấp"}],"correctOptionId":"c","explanation":"Nó diễn giải các nguồn khác thay vì là hiện vật trực tiếp của sự kiện."},{"id":"history-10-chronology-q1","prompt":"Dòng thời gian chủ yếu giúp ích việc nào?","difficulty":"EASY","options":[{"id":"a","text":"Tự chứng minh nguyên nhân"},{"id":"b","text":"Xác định cảm xúc tác giả"},{"id":"c","text":"Sắp xếp trình tự sự kiện"}],"correctOptionId":"c","explanation":"Trình tự thời gian không tự trả lời vì sao sự kiện xảy ra."},{"id":"history-10-chronology-q2","prompt":"Trong mốc trước Công nguyên, năm 500 TCN hay 200 TCN xảy ra trước?","difficulty":"MEDIUM","options":[{"id":"a","text":"Cùng lúc"},{"id":"b","text":"500 TCN"},{"id":"c","text":"200 TCN"}],"correctOptionId":"b","explanation":"Số năm TCN lớn hơn nằm xa hơn về quá khứ."},{"id":"history-10-prehistory-q1","prompt":"Khảo cổ học chủ yếu dựa vào loại bằng chứng nào?","difficulty":"EASY","options":[{"id":"a","text":"Dự báo thời tiết"},{"id":"b","text":"Di tích và hiện vật vật chất"},{"id":"c","text":"Tin đồn chưa kiểm chứng"}],"correctOptionId":"b","explanation":"Đồ vật và di tích cung cấp bằng chứng vật chất về hoạt động con người."},{"id":"history-10-prehistory-q2","prompt":"Vì sao bối cảnh tìm thấy hiện vật quan trọng?","difficulty":"MEDIUM","options":[{"id":"a","text":"Nó giúp xác định niên đại và mối liên hệ"},{"id":"b","text":"Nó làm hiện vật tự nói mọi điều"},{"id":"c","text":"Nó thay thế việc bảo quản"}],"correctOptionId":"a","explanation":"Vị trí, lớp đất và vật đi kèm ảnh hưởng cách diễn giải."},{"id":"history-10-early-civilizations-q1","prompt":"Sông có thể hỗ trợ cư dân cổ đại bằng cách nào?","difficulty":"EASY","options":[{"id":"a","text":"Nước, đất canh tác và giao thông"},{"id":"b","text":"Tự động tạo nhà nước hiện đại"},{"id":"c","text":"Loại bỏ mọi thiên tai"}],"correctOptionId":"a","explanation":"Sông tạo điều kiện nhưng xã hội vẫn cần tổ chức và thích nghi."},{"id":"history-10-early-civilizations-q2","prompt":"Chữ viết cổ thường giúp gì cho nhà nước?","difficulty":"MEDIUM","options":[{"id":"a","text":"Thay thế mọi hoạt động sản xuất"},{"id":"b","text":"Bảo đảm mọi người biết đọc"},{"id":"c","text":"Ghi chép giao dịch, luật lệ hoặc sự kiện"}],"correctOptionId":"c","explanation":"Ghi chép hỗ trợ quản lý nhưng mức biết chữ khác nhau."},{"id":"history-10-india-china-q1","prompt":"Khi so sánh hai nền văn minh, bước đầu nên làm gì?","difficulty":"EASY","options":[{"id":"a","text":"Gộp mọi thế kỉ"},{"id":"b","text":"Chọn một bên làm chuẩn duy nhất"},{"id":"c","text":"Xác định thời kì và tiêu chí chung"}],"correctOptionId":"c","explanation":"Tiêu chí và mốc thời gian rõ giúp so sánh công bằng."},{"id":"history-10-india-china-q2","prompt":"Một truyền thống tư tưởng kéo dài qua nhiều triều đại có nghĩa là?","difficulty":"MEDIUM","options":[{"id":"a","text":"Mọi cư dân đều nghĩ giống nhau"},{"id":"b","text":"Có sự kế thừa và biến đổi theo bối cảnh"},{"id":"c","text":"Không bao giờ thay đổi"}],"correctOptionId":"b","explanation":"Truyền thống thường được diễn giải lại trong các thời kì."}]'::jsonb, '["history-10-historical-evidence","history-10-chronology","history-10-prehistory","history-10-early-civilizations","history-10-india-china"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('history', 10, 'intro-2026.1', 'history-10-greece-rome', 7, 'LESSON', 'Di sản Hy Lạp và La Mã', 'Lịch sử: tư liệu, văn minh và biến đổi xã hội', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Các xã hội Hy Lạp và La Mã cổ đại để lại dấu ấn trong triết học, kiến trúc, luật và chính trị. Di sản được tiếp nhận, biến đổi; không nên đồng nhất thể chế cổ với dân chủ hiện đại."]'::jsonb, '["Một công trình mái vòm cho thấy kỹ thuật xây dựng, nhưng cần nguồn khác để hiểu đời sống chính trị."]'::jsonb, '[{"id":"history-10-greece-rome-q1","prompt":"Một công trình kiến trúc cho biết chắc nhất điều gì?","difficulty":"EASY","options":[{"id":"a","text":"Mọi luật lệ của xã hội"},{"id":"b","text":"Kỹ thuật và quan niệm xây dựng có thể quan sát"},{"id":"c","text":"Toàn bộ quyền lợi của cư dân"}],"correctOptionId":"b","explanation":"Hiện vật cung cấp loại thông tin giới hạn, cần nguồn bổ sung."},{"id":"history-10-greece-rome-q2","prompt":"Khi nói một xã hội cổ có hình thức tham gia chính trị, cần tránh điều gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Đồng nhất ngay với dân chủ hiện đại"},{"id":"b","text":"Xác định ai được tham gia"},{"id":"c","text":"Đọc văn bản luật"}],"correctOptionId":"a","explanation":"Quyền chính trị cổ đại có phạm vi và điều kiện riêng."},{"id":"history-10-greece-rome-q3","prompt":"Một khái niệm luật được dùng nhiều thế kỉ sau. Cách giải thích tốt là?","difficulty":"APPLIED","options":[{"id":"a","text":"Cho rằng nghĩa luôn không đổi"},{"id":"b","text":"Bỏ qua người sử dụng"},{"id":"c","text":"Theo dõi sự tiếp nhận và biến đổi trong từng bối cảnh"}],"correctOptionId":"c","explanation":"Di sản có thể được tái diễn giải theo xã hội tiếp nhận."}]'::jsonb, '["history-10-greece-rome"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('history', 10, 'intro-2026.1', 'history-10-southeast-asia', 8, 'LESSON', 'Giao lưu văn hóa Đông Nam Á', 'Lịch sử: tư liệu, văn minh và biến đổi xã hội', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Đông Nam Á là không gian đa dạng, kết nối qua biển và đất liền. Thương mại, di cư và tôn giáo góp phần giao lưu; mỗi cộng đồng tiếp nhận có chọn lọc và sáng tạo."]'::jsonb, '["Một phong cách kiến trúc có ảnh hưởng bên ngoài nhưng vật liệu và trang trí địa phương tạo diện mạo riêng."]'::jsonb, '[{"id":"history-10-southeast-asia-q1","prompt":"Đông Nam Á kết nối lịch sử qua những tuyến nào?","difficulty":"EASY","options":[{"id":"a","text":"Đường biển và đường bộ"},{"id":"b","text":"Chỉ một con đường duy nhất"},{"id":"c","text":"Không có giao lưu"}],"correctOptionId":"a","explanation":"Địa lí quần đảo và lục địa tạo nhiều tuyến tiếp xúc."},{"id":"history-10-southeast-asia-q2","prompt":"Tiếp nhận ảnh hưởng văn hóa thường diễn ra ra sao?","difficulty":"MEDIUM","options":[{"id":"a","text":"Sao chép nguyên vẹn trong mọi trường hợp"},{"id":"b","text":"Không để lại dấu vết"},{"id":"c","text":"Có chọn lọc và biến đổi tại địa phương"}],"correctOptionId":"c","explanation":"Cộng đồng điều chỉnh yếu tố ngoại lai theo nhu cầu và bản sắc."},{"id":"history-10-southeast-asia-q3","prompt":"Một hiện vật có kiểu dáng ngoại lai nhưng chất liệu địa phương. Kết luận phù hợp là?","difficulty":"APPLIED","options":[{"id":"a","text":"Không thể liên quan thương mại"},{"id":"b","text":"Có thể phản ánh giao lưu và thích ứng; cần thêm bằng chứng"},{"id":"c","text":"Chắc chắn được nhập khẩu nguyên chiếc"}],"correctOptionId":"b","explanation":"Kết hợp đặc điểm gợi giả thuyết nhưng chưa đủ để kết luận chắc chắn."}]'::jsonb, '["history-10-southeast-asia"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('history', 10, 'intro-2026.1', 'history-10-vietnam-civilizations', 9, 'LESSON', 'Văn minh và văn hóa Việt Nam', 'Lịch sử: tư liệu, văn minh và biến đổi xã hội', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Lịch sử văn hóa Việt Nam hình thành từ nhiều cộng đồng, thời kì và giao lưu. Di vật khảo cổ, văn bản và truyền thống dân gian có phạm vi thông tin khác nhau."]'::jsonb, '["Trống đồng có thể cung cấp dấu vết về kỹ thuật và biểu tượng; cách diễn giải cần đối chiếu địa điểm, niên đại và nguồn khác."]'::jsonb, '[{"id":"history-10-vietnam-civilizations-q1","prompt":"Khi học một di vật, cần đặt câu hỏi nào?","difficulty":"EASY","options":[{"id":"a","text":"Nó có màu đẹp không?"},{"id":"b","text":"Ai thích nó ngày nay?"},{"id":"c","text":"Nó được tìm ở đâu, niên đại nào, dùng để làm gì?"}],"correctOptionId":"c","explanation":"Bối cảnh tìm thấy giúp xác định giá trị chứng cứ."},{"id":"history-10-vietnam-civilizations-q2","prompt":"Truyền thống dân gian nên được tiếp cận thế nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Bỏ qua hoàn toàn"},{"id":"b","text":"Tôn trọng giá trị văn hóa và đối chiếu khi dùng làm chứng cứ sự kiện"},{"id":"c","text":"Coi mọi chi tiết là ghi chép nguyên văn"}],"correctOptionId":"b","explanation":"Truyền khẩu lưu giữ ký ức nhưng biến đổi qua truyền kể."},{"id":"history-10-vietnam-civilizations-q3","prompt":"Một nền văn hóa chịu nhiều ảnh hưởng nhưng vẫn có dấu ấn riêng. Điều đó cho thấy?","difficulty":"APPLIED","options":[{"id":"a","text":"Giao lưu có thể đi cùng sáng tạo và thích nghi"},{"id":"b","text":"Giao lưu luôn xóa bản sắc"},{"id":"c","text":"Văn hóa không thay đổi"}],"correctOptionId":"a","explanation":"Bản sắc và tiếp xúc có thể cùng tồn tại."}]'::jsonb, '["history-10-vietnam-civilizations"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('history', 10, 'intro-2026.1', 'history-10-heritage', 10, 'LESSON', 'Di sản và bảo tồn lịch sử', 'Lịch sử: tư liệu, văn minh và biến đổi xã hội', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Di sản vật thể và phi vật thể lưu giữ giá trị quá khứ. Bảo tồn cần tư liệu hóa, chăm sóc và tôn trọng cộng đồng; khai thác du lịch phải hạn chế gây hư hại."]'::jsonb, '["Ghi âm nghệ nhân kể một làn điệu giúp lưu giữ tri thức nhưng cần sự đồng thuận và ghi nguồn."]'::jsonb, '[{"id":"history-10-heritage-q1","prompt":"Di sản phi vật thể có thể là gì?","difficulty":"EASY","options":[{"id":"a","text":"Một thiết bị điện tử mới"},{"id":"b","text":"Tri thức, thực hành và nghệ thuật truyền thống"},{"id":"c","text":"Chỉ một tòa nhà"}],"correctOptionId":"b","explanation":"Di sản phi vật thể tồn tại qua thực hành và truyền dạy."},{"id":"history-10-heritage-q2","prompt":"Trước khi ghi hình một nghệ nhân, cần làm gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Xin đồng thuận và ghi rõ bối cảnh"},{"id":"b","text":"Tự ý đăng mọi nội dung"},{"id":"c","text":"Cắt bỏ tên người kể"}],"correctOptionId":"a","explanation":"Tôn trọng quyền và tri thức của cộng đồng là phần của bảo tồn."},{"id":"history-10-heritage-q3","prompt":"Lượng khách lớn làm mòn một di tích. Giải pháp phù hợp hướng tới điều gì?","difficulty":"APPLIED","options":[{"id":"a","text":"Tăng khách không giới hạn"},{"id":"b","text":"Sơn phủ lên hiện vật"},{"id":"c","text":"Điều tiết tham quan và bảo vệ cấu trúc di tích"}],"correctOptionId":"c","explanation":"Bảo tồn cân bằng tiếp cận với sức chịu tải của di tích."}]'::jsonb, '["history-10-heritage"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('history', 10, 'intro-2026.1', 'history-10-historical-causation', 11, 'LESSON', 'Nguyên nhân và hệ quả lịch sử', 'Lịch sử: tư liệu, văn minh và biến đổi xã hội', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Một biến cố thường có nhiều nguyên nhân gần, xa và điều kiện nền. Phân biệt nguyên nhân với cái cớ và xem hệ quả ngắn hạn, dài hạn."]'::jsonb, '["Mất mùa có thể làm tăng bất mãn nhưng chính sách, phân phối và bối cảnh chính trị cũng ảnh hưởng khủng hoảng."]'::jsonb, '[{"id":"history-10-historical-causation-q1","prompt":"Một biến cố lớn thường nên được giải thích bằng?","difficulty":"EASY","options":[{"id":"a","text":"Nhiều nguyên nhân tương tác"},{"id":"b","text":"Một nguyên nhân duy nhất mặc định"},{"id":"c","text":"Chỉ một ngày xảy ra"}],"correctOptionId":"a","explanation":"Giải thích đa nguyên nhân phù hợp độ phức tạp lịch sử."},{"id":"history-10-historical-causation-q2","prompt":"Nguyên nhân gần khác điều kiện nền ở điểm nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Hai khái niệm luôn giống nhau"},{"id":"b","text":"Điều kiện nền là hậu quả"},{"id":"c","text":"Nguyên nhân gần kích hoạt trực tiếp; điều kiện nền tạo bối cảnh"}],"correctOptionId":"c","explanation":"Phân biệt giúp mô tả cơ chế của sự kiện."},{"id":"history-10-historical-causation-q3","prompt":"Một chính sách tạo kết quả tốt ngay nhưng vấn đề mới sau nhiều năm. Cách đánh giá nào đầy đủ hơn?","difficulty":"APPLIED","options":[{"id":"a","text":"Chỉ hỏi người đề xuất"},{"id":"b","text":"Xem cả hệ quả ngắn hạn và dài hạn"},{"id":"c","text":"Chỉ xem ngày ban hành"}],"correctOptionId":"b","explanation":"Hệ quả có thể khác nhau theo thời gian và nhóm chịu tác động."}]'::jsonb, '["history-10-historical-causation"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('history', 10, 'intro-2026.1', 'history-10-review-2', 12, 'FIVE_LESSON_REVIEW', 'Ôn tập 2', 'Lịch sử: tư liệu, văn minh và biến đổi xã hội', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '[]'::jsonb, '[]'::jsonb, '[{"id":"history-10-greece-rome-q1","prompt":"Một công trình kiến trúc cho biết chắc nhất điều gì?","difficulty":"EASY","options":[{"id":"a","text":"Mọi luật lệ của xã hội"},{"id":"b","text":"Kỹ thuật và quan niệm xây dựng có thể quan sát"},{"id":"c","text":"Toàn bộ quyền lợi của cư dân"}],"correctOptionId":"b","explanation":"Hiện vật cung cấp loại thông tin giới hạn, cần nguồn bổ sung."},{"id":"history-10-greece-rome-q2","prompt":"Khi nói một xã hội cổ có hình thức tham gia chính trị, cần tránh điều gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Đồng nhất ngay với dân chủ hiện đại"},{"id":"b","text":"Xác định ai được tham gia"},{"id":"c","text":"Đọc văn bản luật"}],"correctOptionId":"a","explanation":"Quyền chính trị cổ đại có phạm vi và điều kiện riêng."},{"id":"history-10-southeast-asia-q1","prompt":"Đông Nam Á kết nối lịch sử qua những tuyến nào?","difficulty":"EASY","options":[{"id":"a","text":"Đường biển và đường bộ"},{"id":"b","text":"Chỉ một con đường duy nhất"},{"id":"c","text":"Không có giao lưu"}],"correctOptionId":"a","explanation":"Địa lí quần đảo và lục địa tạo nhiều tuyến tiếp xúc."},{"id":"history-10-southeast-asia-q2","prompt":"Tiếp nhận ảnh hưởng văn hóa thường diễn ra ra sao?","difficulty":"MEDIUM","options":[{"id":"a","text":"Sao chép nguyên vẹn trong mọi trường hợp"},{"id":"b","text":"Không để lại dấu vết"},{"id":"c","text":"Có chọn lọc và biến đổi tại địa phương"}],"correctOptionId":"c","explanation":"Cộng đồng điều chỉnh yếu tố ngoại lai theo nhu cầu và bản sắc."},{"id":"history-10-vietnam-civilizations-q1","prompt":"Khi học một di vật, cần đặt câu hỏi nào?","difficulty":"EASY","options":[{"id":"a","text":"Nó có màu đẹp không?"},{"id":"b","text":"Ai thích nó ngày nay?"},{"id":"c","text":"Nó được tìm ở đâu, niên đại nào, dùng để làm gì?"}],"correctOptionId":"c","explanation":"Bối cảnh tìm thấy giúp xác định giá trị chứng cứ."},{"id":"history-10-vietnam-civilizations-q2","prompt":"Truyền thống dân gian nên được tiếp cận thế nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Bỏ qua hoàn toàn"},{"id":"b","text":"Tôn trọng giá trị văn hóa và đối chiếu khi dùng làm chứng cứ sự kiện"},{"id":"c","text":"Coi mọi chi tiết là ghi chép nguyên văn"}],"correctOptionId":"b","explanation":"Truyền khẩu lưu giữ ký ức nhưng biến đổi qua truyền kể."},{"id":"history-10-heritage-q1","prompt":"Di sản phi vật thể có thể là gì?","difficulty":"EASY","options":[{"id":"a","text":"Một thiết bị điện tử mới"},{"id":"b","text":"Tri thức, thực hành và nghệ thuật truyền thống"},{"id":"c","text":"Chỉ một tòa nhà"}],"correctOptionId":"b","explanation":"Di sản phi vật thể tồn tại qua thực hành và truyền dạy."},{"id":"history-10-heritage-q2","prompt":"Trước khi ghi hình một nghệ nhân, cần làm gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Xin đồng thuận và ghi rõ bối cảnh"},{"id":"b","text":"Tự ý đăng mọi nội dung"},{"id":"c","text":"Cắt bỏ tên người kể"}],"correctOptionId":"a","explanation":"Tôn trọng quyền và tri thức của cộng đồng là phần của bảo tồn."},{"id":"history-10-historical-causation-q1","prompt":"Một biến cố lớn thường nên được giải thích bằng?","difficulty":"EASY","options":[{"id":"a","text":"Nhiều nguyên nhân tương tác"},{"id":"b","text":"Một nguyên nhân duy nhất mặc định"},{"id":"c","text":"Chỉ một ngày xảy ra"}],"correctOptionId":"a","explanation":"Giải thích đa nguyên nhân phù hợp độ phức tạp lịch sử."},{"id":"history-10-historical-causation-q2","prompt":"Nguyên nhân gần khác điều kiện nền ở điểm nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Hai khái niệm luôn giống nhau"},{"id":"b","text":"Điều kiện nền là hậu quả"},{"id":"c","text":"Nguyên nhân gần kích hoạt trực tiếp; điều kiện nền tạo bối cảnh"}],"correctOptionId":"c","explanation":"Phân biệt giúp mô tả cơ chế của sự kiện."}]'::jsonb, '["history-10-greece-rome","history-10-southeast-asia","history-10-vietnam-civilizations","history-10-heritage","history-10-historical-causation"]'::jsonb)
