insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('history', 10, 'intro-2026.1', 'history-10-industrial-revolution', 13, 'LESSON', 'Các cuộc cách mạng công nghiệp', 'Lịch sử: tư liệu, văn minh và biến đổi xã hội', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Các cuộc cách mạng công nghiệp gắn với thay đổi công nghệ, năng lượng, sản xuất và lao động. Tốc độ và tác động khác nhau giữa khu vực, ngành nghề và nhóm dân cư."]'::jsonb, '["Máy móc có thể tăng sản lượng nhưng cũng làm thay đổi kỹ năng và tổ chức lao động."]'::jsonb, '[{"id":"history-10-industrial-revolution-q1","prompt":"Cách mạng công nghiệp thường làm biến đổi điều gì?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ tên các thành phố"},{"id":"b","text":"Trọng lực"},{"id":"c","text":"Phương thức sản xuất và tổ chức lao động"}],"correctOptionId":"c","explanation":"Công nghệ tác động cả quy trình và quan hệ lao động."},{"id":"history-10-industrial-revolution-q2","prompt":"Một công nghệ mới làm năng suất tăng. Tác động xã hội nào cần xem thêm?","difficulty":"MEDIUM","options":[{"id":"a","text":"Không có tác động xã hội"},{"id":"b","text":"Việc làm, kỹ năng và phân phối lợi ích"},{"id":"c","text":"Chỉ màu máy"}],"correctOptionId":"b","explanation":"Lợi ích và chi phí có thể phân bố không đều."},{"id":"history-10-industrial-revolution-q3","prompt":"Hai quốc gia tiếp nhận máy móc cùng thời nhưng kết quả khác. Cần xem thêm yếu tố nào?","difficulty":"APPLIED","options":[{"id":"a","text":"Hạ tầng, vốn, kỹ năng và thể chế"},{"id":"b","text":"Chỉ ngày phát minh"},{"id":"c","text":"Tên nhà phát minh duy nhất"}],"correctOptionId":"a","explanation":"Điều kiện địa phương ảnh hưởng cách công nghệ được áp dụng."}]'::jsonb, '["history-10-industrial-revolution"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('history', 10, 'intro-2026.1', 'history-10-modernization', 14, 'LESSON', 'Hiện đại hóa và cải cách', 'Lịch sử: tư liệu, văn minh và biến đổi xã hội', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Hiện đại hóa là quá trình thay đổi kinh tế, xã hội và thiết chế, không đồng nghĩa sao chép một mô hình duy nhất. So sánh cần xem mục tiêu, nguồn lực và nhóm chịu tác động."]'::jsonb, '["Cải cách giáo dục có thể mở rộng cơ hội nhưng kết quả còn phụ thuộc khả năng tiếp cận."]'::jsonb, '[{"id":"history-10-modernization-q1","prompt":"Hiện đại hóa có phải một con đường giống hệt cho mọi xã hội không?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ là đổi trang phục"},{"id":"b","text":"Không"},{"id":"c","text":"Có, chỉ có một mô hình"}],"correctOptionId":"b","explanation":"Quá trình chịu ảnh hưởng lịch sử và điều kiện địa phương."},{"id":"history-10-modernization-q2","prompt":"Đánh giá một cải cách nên xét thêm điều gì ngoài mục tiêu?","difficulty":"MEDIUM","options":[{"id":"a","text":"Kết quả thực tế và nhóm được hoặc chịu tác động"},{"id":"b","text":"Chỉ tiêu đề"},{"id":"c","text":"Màu tài liệu"}],"correctOptionId":"a","explanation":"Kết quả và tác động phân phối giúp đánh giá toàn diện."},{"id":"history-10-modernization-q3","prompt":"Một chính sách mở trường ở thành phố nhưng vùng xa khó đi học. Vấn đề cần xem là?","difficulty":"APPLIED","options":[{"id":"a","text":"Số trang sách"},{"id":"b","text":"Nhiệt độ lớp học duy nhất"},{"id":"c","text":"Khả năng tiếp cận không đồng đều"}],"correctOptionId":"c","explanation":"Cơ hội thực tế phụ thuộc địa lí và nguồn lực."}]'::jsonb, '["history-10-modernization"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('history', 10, 'intro-2026.1', 'history-10-global-exchange', 15, 'LESSON', 'Giao lưu và kết nối thế giới', 'Lịch sử: tư liệu, văn minh và biến đổi xã hội', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Giao lưu làm lưu chuyển hàng hóa, tri thức, tín ngưỡng và con người. Tác động gồm cơ hội và căng thẳng; cần xem ai tham gia, ai kiểm soát và bên nào hưởng lợi."]'::jsonb, '["Một tuyến thương mại đưa hàng hóa mới tới cảng, đồng thời tạo tiếp xúc ngôn ngữ và kỹ thuật."]'::jsonb, '[{"id":"history-10-global-exchange-q1","prompt":"Giao lưu lịch sử có thể truyền tải những gì?","difficulty":"EASY","options":[{"id":"a","text":"Hàng hóa, tri thức và tập quán"},{"id":"b","text":"Chỉ một loại tiền"},{"id":"c","text":"Không có thay đổi"}],"correctOptionId":"a","explanation":"Tiếp xúc diễn ra qua nhiều kênh."},{"id":"history-10-global-exchange-q2","prompt":"Vì sao cần hỏi ai hưởng lợi từ mạng lưới thương mại?","difficulty":"MEDIUM","options":[{"id":"a","text":"Vì mọi người luôn hưởng lợi như nhau"},{"id":"b","text":"Để bỏ qua nguồn hàng"},{"id":"c","text":"Lợi ích và quyền lực có thể phân bố không đều"}],"correctOptionId":"c","explanation":"Phân tích người tham gia giúp hiểu quan hệ xã hội."},{"id":"history-10-global-exchange-q3","prompt":"Một kỹ thuật lan sang vùng khác rồi được điều chỉnh. Đây là ví dụ của?","difficulty":"APPLIED","options":[{"id":"a","text":"Một hiện tượng tự nhiên"},{"id":"b","text":"Tiếp nhận và biến đổi tri thức qua giao lưu"},{"id":"c","text":"Không có giao lưu"}],"correctOptionId":"b","explanation":"Sự tiếp nhận có thể tạo hình thức mới tại địa phương."}]'::jsonb, '["history-10-global-exchange"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('history', 10, 'intro-2026.1', 'history-10-historical-argument', 16, 'LESSON', 'Viết nhận định lịch sử có căn cứ', 'Lịch sử: tư liệu, văn minh và biến đổi xã hội', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Nhận định lịch sử cần luận điểm, tư liệu và giải thích. Trích nguồn đúng, phân biệt điều nguồn ghi với cách người viết diễn giải."]'::jsonb, '["“Nguồn A cho thấy…” là mô tả; “điều này gợi ý…” là diễn giải cần kiểm tra thêm."]'::jsonb, '[{"id":"history-10-historical-argument-q1","prompt":"Một nhận định lịch sử thuyết phục cần gì?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ ý kiến cá nhân"},{"id":"b","text":"Một niên đại không liên quan"},{"id":"c","text":"Luận điểm, bằng chứng và giải thích"}],"correctOptionId":"c","explanation":"Bằng chứng và lập luận kết nối giúp kiểm tra nhận định."},{"id":"history-10-historical-argument-q2","prompt":"Khi nguồn chỉ nói về một địa phương, tránh điều gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Ghi thời gian"},{"id":"b","text":"Khái quát kết luận cho mọi nơi"},{"id":"c","text":"Nêu địa danh"}],"correctOptionId":"b","explanation":"Phạm vi kết luận không nên vượt quá phạm vi nguồn."},{"id":"history-10-historical-argument-q3","prompt":"Hai tư liệu mâu thuẫn về một sự việc. Bài viết tốt nên?","difficulty":"APPLIED","options":[{"id":"a","text":"Nêu mâu thuẫn, đánh giá nguồn và giới hạn kết luận"},{"id":"b","text":"Giấu nguồn bất tiện"},{"id":"c","text":"Tự chọn ngày trung bình"}],"correctOptionId":"a","explanation":"Minh bạch bất đồng giúp lập luận thận trọng."}]'::jsonb, '["history-10-historical-argument"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('history', 10, 'intro-2026.1', 'history-10-historical-periods', 17, 'LESSON', 'Thời kì lịch sử và sự tiếp nối', 'Lịch sử: tư liệu, văn minh và biến đổi xã hội', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Chia thời kì giúp tổ chức việc học, nhưng ranh giới thời kì là công cụ phân tích. Các biến đổi thường diễn ra không đồng đều và có sự tiếp nối giữa trước với sau."]'::jsonb, '["Khi chuyển từ một hình thái xã hội sang hình thái khác, có thể đồng thời tồn tại yếu tố cũ và mới."]'::jsonb, '[{"id":"history-10-historical-periods-q1","prompt":"Chia lịch sử thành các thời kì chủ yếu để làm gì?","difficulty":"EASY","options":[{"id":"a","text":"Thay thế việc đọc tư liệu"},{"id":"b","text":"Tổ chức và phân tích những biến đổi trong quá khứ"},{"id":"c","text":"Khẳng định mọi nơi thay đổi cùng lúc"}],"correctOptionId":"b","explanation":"Phân kì là cách nghiên cứu; cần xét khác biệt về không gian và nhịp độ biến đổi."},{"id":"history-10-historical-periods-q2","prompt":"Một công cụ tiếp tục được dùng sau khi xuất hiện kỹ thuật mới cho thấy điều gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Yếu tố cũ và mới có thể cùng tồn tại"},{"id":"b","text":"Mọi xã hội đã đổi hoàn toàn cùng lúc"},{"id":"c","text":"Không có sự thay đổi nào"}],"correctOptionId":"a","explanation":"Quá trình lịch sử thường có tiếp nối, không thay thế tức thì ở mọi nơi."},{"id":"history-10-historical-periods-q3","prompt":"Khi so sánh hai xã hội trong cùng một thời kì, cần lưu ý gì?","difficulty":"APPLIED","options":[{"id":"a","text":"Tên thời kì đủ giải thích mọi khác biệt"},{"id":"b","text":"Mọi cộng đồng có một trải nghiệm giống nhau"},{"id":"c","text":"Bối cảnh và tốc độ biến đổi có thể khác nhau"}],"correctOptionId":"c","explanation":"Nhãn thời kì không thay thế việc khảo sát từng bối cảnh."}]'::jsonb, '["history-10-historical-periods"]'::jsonb)
