insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('history', 10, 'intro-2026.1', 'history-10-review-3', 18, 'FIVE_LESSON_REVIEW', 'Ôn tập 3', 'Lịch sử: tư liệu, văn minh và biến đổi xã hội', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '[]'::jsonb, '[]'::jsonb, '[{"id":"history-10-industrial-revolution-q1","prompt":"Cách mạng công nghiệp thường làm biến đổi điều gì?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ tên các thành phố"},{"id":"b","text":"Trọng lực"},{"id":"c","text":"Phương thức sản xuất và tổ chức lao động"}],"correctOptionId":"c","explanation":"Công nghệ tác động cả quy trình và quan hệ lao động."},{"id":"history-10-industrial-revolution-q2","prompt":"Một công nghệ mới làm năng suất tăng. Tác động xã hội nào cần xem thêm?","difficulty":"MEDIUM","options":[{"id":"a","text":"Không có tác động xã hội"},{"id":"b","text":"Việc làm, kỹ năng và phân phối lợi ích"},{"id":"c","text":"Chỉ màu máy"}],"correctOptionId":"b","explanation":"Lợi ích và chi phí có thể phân bố không đều."},{"id":"history-10-modernization-q1","prompt":"Hiện đại hóa có phải một con đường giống hệt cho mọi xã hội không?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ là đổi trang phục"},{"id":"b","text":"Không"},{"id":"c","text":"Có, chỉ có một mô hình"}],"correctOptionId":"b","explanation":"Quá trình chịu ảnh hưởng lịch sử và điều kiện địa phương."},{"id":"history-10-modernization-q2","prompt":"Đánh giá một cải cách nên xét thêm điều gì ngoài mục tiêu?","difficulty":"MEDIUM","options":[{"id":"a","text":"Kết quả thực tế và nhóm được hoặc chịu tác động"},{"id":"b","text":"Chỉ tiêu đề"},{"id":"c","text":"Màu tài liệu"}],"correctOptionId":"a","explanation":"Kết quả và tác động phân phối giúp đánh giá toàn diện."},{"id":"history-10-global-exchange-q1","prompt":"Giao lưu lịch sử có thể truyền tải những gì?","difficulty":"EASY","options":[{"id":"a","text":"Hàng hóa, tri thức và tập quán"},{"id":"b","text":"Chỉ một loại tiền"},{"id":"c","text":"Không có thay đổi"}],"correctOptionId":"a","explanation":"Tiếp xúc diễn ra qua nhiều kênh."},{"id":"history-10-global-exchange-q2","prompt":"Vì sao cần hỏi ai hưởng lợi từ mạng lưới thương mại?","difficulty":"MEDIUM","options":[{"id":"a","text":"Vì mọi người luôn hưởng lợi như nhau"},{"id":"b","text":"Để bỏ qua nguồn hàng"},{"id":"c","text":"Lợi ích và quyền lực có thể phân bố không đều"}],"correctOptionId":"c","explanation":"Phân tích người tham gia giúp hiểu quan hệ xã hội."},{"id":"history-10-historical-argument-q1","prompt":"Một nhận định lịch sử thuyết phục cần gì?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ ý kiến cá nhân"},{"id":"b","text":"Một niên đại không liên quan"},{"id":"c","text":"Luận điểm, bằng chứng và giải thích"}],"correctOptionId":"c","explanation":"Bằng chứng và lập luận kết nối giúp kiểm tra nhận định."},{"id":"history-10-historical-argument-q2","prompt":"Khi nguồn chỉ nói về một địa phương, tránh điều gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Ghi thời gian"},{"id":"b","text":"Khái quát kết luận cho mọi nơi"},{"id":"c","text":"Nêu địa danh"}],"correctOptionId":"b","explanation":"Phạm vi kết luận không nên vượt quá phạm vi nguồn."},{"id":"history-10-historical-periods-q1","prompt":"Chia lịch sử thành các thời kì chủ yếu để làm gì?","difficulty":"EASY","options":[{"id":"a","text":"Thay thế việc đọc tư liệu"},{"id":"b","text":"Tổ chức và phân tích những biến đổi trong quá khứ"},{"id":"c","text":"Khẳng định mọi nơi thay đổi cùng lúc"}],"correctOptionId":"b","explanation":"Phân kì là cách nghiên cứu; cần xét khác biệt về không gian và nhịp độ biến đổi."},{"id":"history-10-historical-periods-q2","prompt":"Một công cụ tiếp tục được dùng sau khi xuất hiện kỹ thuật mới cho thấy điều gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Yếu tố cũ và mới có thể cùng tồn tại"},{"id":"b","text":"Mọi xã hội đã đổi hoàn toàn cùng lúc"},{"id":"c","text":"Không có sự thay đổi nào"}],"correctOptionId":"a","explanation":"Quá trình lịch sử thường có tiếp nối, không thay thế tức thì ở mọi nơi."}]'::jsonb, '["history-10-industrial-revolution","history-10-modernization","history-10-global-exchange","history-10-historical-argument","history-10-historical-periods"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('geography', 10, 'intro-2026.1', 'placement', 0, 'PLACEMENT', 'Khảo sát đầu vào', 'Địa lí: bản đồ, hệ tự nhiên và hoạt động kinh tế', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '[]'::jsonb, '[]'::jsonb, '[{"id":"geography-10-maps-scale-q1","prompt":"Tỉ lệ 1:100.000 có nghĩa là?","difficulty":"EASY","options":[{"id":"a","text":"1 đơn vị bản đồ bằng 100.000 đơn vị thực địa"},{"id":"b","text":"100.000 km trên bản đồ bằng 1 km"},{"id":"c","text":"Bản đồ có 100.000 trang"}],"correctOptionId":"a","explanation":"Hai độ dài phải dùng cùng đơn vị khi áp dụng tỉ lệ."},{"id":"geography-10-maps-scale-q2","prompt":"Trên bản đồ 1:50.000, 2 cm ứng với bao nhiêu?","difficulty":"MEDIUM","options":[{"id":"a","text":"100 m"},{"id":"b","text":"10 km"},{"id":"c","text":"1 km"}],"correctOptionId":"c","explanation":"2×50.000=100.000 cm=1.000 m."},{"id":"geography-10-earth-motion-q1","prompt":"Tự quay quanh trục chủ yếu tạo hiện tượng nào?","difficulty":"EASY","options":[{"id":"a","text":"Thủy triều duy nhất"},{"id":"b","text":"Các mùa giống nhau ở mọi nơi"},{"id":"c","text":"Ngày và đêm luân phiên"}],"correctOptionId":"c","explanation":"Mỗi nơi lần lượt hướng về và khuất khỏi ánh sáng Mặt Trời."},{"id":"geography-10-earth-motion-q2","prompt":"Trục Trái Đất nghiêng góp phần tạo ra điều gì trong năm?","difficulty":"MEDIUM","options":[{"id":"a","text":"Đổi vị trí xích đạo hằng ngày"},{"id":"b","text":"Khác biệt mùa giữa các bán cầu"},{"id":"c","text":"Tắt hoàn toàn trọng lực"}],"correctOptionId":"b","explanation":"Góc nhận bức xạ thay đổi theo thời gian và vĩ độ."},{"id":"geography-10-atmosphere-temperature-q1","prompt":"Phần lớn hiện tượng thời tiết diễn ra trong tầng nào?","difficulty":"EASY","options":[{"id":"a","text":"Nhân Trái Đất"},{"id":"b","text":"Đối lưu"},{"id":"c","text":"Ngoại quyển"}],"correctOptionId":"b","explanation":"Tầng đối lưu gần mặt đất và chứa phần lớn hơi nước, mây."},{"id":"geography-10-atmosphere-temperature-q2","prompt":"Nhiệt độ không khí thường thay đổi thế nào khi lên cao trong tầng đối lưu?","difficulty":"MEDIUM","options":[{"id":"a","text":"Giảm trung bình"},{"id":"b","text":"Tăng vô hạn"},{"id":"c","text":"Không bao giờ đổi"}],"correctOptionId":"a","explanation":"Đây là xu hướng trung bình, không phải quy luật tuyệt đối ở mọi thời điểm."},{"id":"geography-10-winds-pressure-q1","prompt":"Không khí gần mặt đất có xu hướng chuyển từ đâu đến đâu?","difficulty":"EASY","options":[{"id":"a","text":"Áp cao về áp thấp"},{"id":"b","text":"Áp thấp về áp cao trong mọi trường hợp"},{"id":"c","text":"Biển lên núi luôn luôn"}],"correctOptionId":"a","explanation":"Chênh lệch khí áp tạo lực thúc đẩy chuyển động không khí."},{"id":"geography-10-winds-pressure-q2","prompt":"Vì sao hướng gió thực tế có thể lệch so với đường nối hai vùng áp?","difficulty":"MEDIUM","options":[{"id":"a","text":"Màu mây"},{"id":"b","text":"Độ dài ngày duy nhất"},{"id":"c","text":"Sự quay Trái Đất và địa hình"}],"correctOptionId":"c","explanation":"Lực Coriolis và ma sát làm biến đổi hướng chuyển động."},{"id":"geography-10-precipitation-q1","prompt":"Mây hình thành chủ yếu khi hơi nước làm gì?","difficulty":"EASY","options":[{"id":"a","text":"Biến thành đất"},{"id":"b","text":"Chuyển thành khí quyển rắn"},{"id":"c","text":"Ngưng tụ thành giọt nhỏ hoặc tinh thể băng"}],"correctOptionId":"c","explanation":"Hơi nước ngưng tụ khi không khí đạt điều kiện phù hợp."},{"id":"geography-10-precipitation-q2","prompt":"Bốc hơi là chuyển trạng thái nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Rắn sang lỏng"},{"id":"b","text":"Lỏng sang khí"},{"id":"c","text":"Khí sang lỏng"}],"correctOptionId":"b","explanation":"Bốc hơi đưa nước lỏng vào khí quyển dưới dạng hơi."}]'::jsonb, '[]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('geography', 10, 'intro-2026.1', 'geography-10-maps-scale', 1, 'LESSON', 'Bản đồ và tỉ lệ', 'Địa lí: bản đồ, hệ tự nhiên và hoạt động kinh tế', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Bản đồ thu nhỏ không gian theo tỉ lệ. Tỉ lệ 1:100.000 nghĩa là 1 đơn vị trên bản đồ bằng 100.000 đơn vị cùng loại ngoài thực địa."]'::jsonb, '["2 cm trên bản đồ tỉ lệ 1:50.000 ứng với 100.000 cm = 1 km."]'::jsonb, '[{"id":"geography-10-maps-scale-q1","prompt":"Tỉ lệ 1:100.000 có nghĩa là?","difficulty":"EASY","options":[{"id":"a","text":"1 đơn vị bản đồ bằng 100.000 đơn vị thực địa"},{"id":"b","text":"100.000 km trên bản đồ bằng 1 km"},{"id":"c","text":"Bản đồ có 100.000 trang"}],"correctOptionId":"a","explanation":"Hai độ dài phải dùng cùng đơn vị khi áp dụng tỉ lệ."},{"id":"geography-10-maps-scale-q2","prompt":"Trên bản đồ 1:50.000, 2 cm ứng với bao nhiêu?","difficulty":"MEDIUM","options":[{"id":"a","text":"100 m"},{"id":"b","text":"10 km"},{"id":"c","text":"1 km"}],"correctOptionId":"c","explanation":"2×50.000=100.000 cm=1.000 m."},{"id":"geography-10-maps-scale-q3","prompt":"Một tuyến đường dài 4 cm trên bản đồ 1:25.000. Độ dài thực tế là?","difficulty":"APPLIED","options":[{"id":"a","text":"10 km"},{"id":"b","text":"1 km"},{"id":"c","text":"100 m"}],"correctOptionId":"b","explanation":"4×25.000=100.000 cm, đổi ra 1 km."}]'::jsonb, '["geography-10-maps-scale"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('geography', 10, 'intro-2026.1', 'geography-10-earth-motion', 2, 'LESSON', 'Chuyển động Trái Đất và mùa', 'Địa lí: bản đồ, hệ tự nhiên và hoạt động kinh tế', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Trái Đất tự quay quanh trục gây chu kì ngày đêm; chuyển động quanh Mặt Trời cùng trục nghiêng tạo phân bố mùa theo bán cầu."]'::jsonb, '["Khi bán cầu Bắc nghiêng về phía Mặt Trời, ngày thường dài hơn và nhận nhiều năng lượng hơn."]'::jsonb, '[{"id":"geography-10-earth-motion-q1","prompt":"Tự quay quanh trục chủ yếu tạo hiện tượng nào?","difficulty":"EASY","options":[{"id":"a","text":"Thủy triều duy nhất"},{"id":"b","text":"Các mùa giống nhau ở mọi nơi"},{"id":"c","text":"Ngày và đêm luân phiên"}],"correctOptionId":"c","explanation":"Mỗi nơi lần lượt hướng về và khuất khỏi ánh sáng Mặt Trời."},{"id":"geography-10-earth-motion-q2","prompt":"Trục Trái Đất nghiêng góp phần tạo ra điều gì trong năm?","difficulty":"MEDIUM","options":[{"id":"a","text":"Đổi vị trí xích đạo hằng ngày"},{"id":"b","text":"Khác biệt mùa giữa các bán cầu"},{"id":"c","text":"Tắt hoàn toàn trọng lực"}],"correctOptionId":"b","explanation":"Góc nhận bức xạ thay đổi theo thời gian và vĩ độ."},{"id":"geography-10-earth-motion-q3","prompt":"Khi Bắc bán cầu vào mùa hè, Nam bán cầu thường có mùa nào?","difficulty":"APPLIED","options":[{"id":"a","text":"Mùa đông"},{"id":"b","text":"Cũng luôn mùa hè"},{"id":"c","text":"Không có mùa"}],"correctOptionId":"a","explanation":"Hai bán cầu nhận phân bố năng lượng trái ngược do trục nghiêng."}]'::jsonb, '["geography-10-earth-motion"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('geography', 10, 'intro-2026.1', 'geography-10-atmosphere-temperature', 3, 'LESSON', 'Khí quyển và nhiệt độ', 'Địa lí: bản đồ, hệ tự nhiên và hoạt động kinh tế', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Khí quyển gồm nhiều tầng; thời tiết và khí hậu chịu ảnh hưởng bức xạ, độ cao, vĩ độ, mặt đệm và hoàn lưu. Nhiệt độ thường giảm theo độ cao ở tầng đối lưu nhưng có thể biến đổi theo điều kiện."]'::jsonb, '["Một sườn núi cao thường mát hơn chân núi nếu các yếu tố khác gần tương tự."]'::jsonb, '[{"id":"geography-10-atmosphere-temperature-q1","prompt":"Phần lớn hiện tượng thời tiết diễn ra trong tầng nào?","difficulty":"EASY","options":[{"id":"a","text":"Nhân Trái Đất"},{"id":"b","text":"Đối lưu"},{"id":"c","text":"Ngoại quyển"}],"correctOptionId":"b","explanation":"Tầng đối lưu gần mặt đất và chứa phần lớn hơi nước, mây."},{"id":"geography-10-atmosphere-temperature-q2","prompt":"Nhiệt độ không khí thường thay đổi thế nào khi lên cao trong tầng đối lưu?","difficulty":"MEDIUM","options":[{"id":"a","text":"Giảm trung bình"},{"id":"b","text":"Tăng vô hạn"},{"id":"c","text":"Không bao giờ đổi"}],"correctOptionId":"a","explanation":"Đây là xu hướng trung bình, không phải quy luật tuyệt đối ở mọi thời điểm."},{"id":"geography-10-atmosphere-temperature-q3","prompt":"Một thị trấn ven biển mát hơn nơi sâu trong đất liền cùng vĩ độ vào ban ngày. Yếu tố nào có thể góp phần?","difficulty":"APPLIED","options":[{"id":"a","text":"Kinh độ tự tạo mưa"},{"id":"b","text":"Độ cao luôn bằng 0"},{"id":"c","text":"Nước biển nóng lên chậm hơn đất"}],"correctOptionId":"c","explanation":"Nhiệt dung của nước làm giảm biên độ nhiệt ngày."}]'::jsonb, '["geography-10-atmosphere-temperature"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('geography', 10, 'intro-2026.1', 'geography-10-winds-pressure', 4, 'LESSON', 'Khí áp và gió', 'Địa lí: bản đồ, hệ tự nhiên và hoạt động kinh tế', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Gió là không khí chuyển động, chịu tác động của chênh lệch khí áp và lực làm lệch hướng do sự tự quay Trái Đất. Gió thực tế còn bị địa hình và ma sát ảnh hưởng."]'::jsonb, '["Không khí có xu hướng dịch chuyển từ vùng áp cao về vùng áp thấp, nhưng đường đi không nhất thiết thẳng."]'::jsonb, '[{"id":"geography-10-winds-pressure-q1","prompt":"Không khí gần mặt đất có xu hướng chuyển từ đâu đến đâu?","difficulty":"EASY","options":[{"id":"a","text":"Áp cao về áp thấp"},{"id":"b","text":"Áp thấp về áp cao trong mọi trường hợp"},{"id":"c","text":"Biển lên núi luôn luôn"}],"correctOptionId":"a","explanation":"Chênh lệch khí áp tạo lực thúc đẩy chuyển động không khí."},{"id":"geography-10-winds-pressure-q2","prompt":"Vì sao hướng gió thực tế có thể lệch so với đường nối hai vùng áp?","difficulty":"MEDIUM","options":[{"id":"a","text":"Màu mây"},{"id":"b","text":"Độ dài ngày duy nhất"},{"id":"c","text":"Sự quay Trái Đất và địa hình"}],"correctOptionId":"c","explanation":"Lực Coriolis và ma sát làm biến đổi hướng chuyển động."},{"id":"geography-10-winds-pressure-q3","prompt":"Gió vượt dãy núi có thể đổi nhiệt độ, độ ẩm ở hai sườn. Cần xem yếu tố nào?","difficulty":"APPLIED","options":[{"id":"a","text":"Màu bản đồ"},{"id":"b","text":"Hướng gió, độ cao và quá trình nâng/hạ không khí"},{"id":"c","text":"Chỉ tên ngọn núi"}],"correctOptionId":"b","explanation":"Địa hình buộc khối khí nâng lên hoặc hạ xuống, làm đổi trạng thái."}]'::jsonb, '["geography-10-winds-pressure"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('geography', 10, 'intro-2026.1', 'geography-10-precipitation', 5, 'LESSON', 'Mưa và vòng tuần hoàn nước', 'Địa lí: bản đồ, hệ tự nhiên và hoạt động kinh tế', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Nước bốc hơi, ngưng tụ thành mây, rồi trở lại bề mặt qua mưa hoặc tuyết. Địa hình, nhiệt độ, độ ẩm và hoàn lưu ảnh hưởng phân bố mưa."]'::jsonb, '["Không khí ẩm bị nâng lên sườn núi có thể lạnh đi và ngưng tụ thành mưa."]'::jsonb, '[{"id":"geography-10-precipitation-q1","prompt":"Mây hình thành chủ yếu khi hơi nước làm gì?","difficulty":"EASY","options":[{"id":"a","text":"Biến thành đất"},{"id":"b","text":"Chuyển thành khí quyển rắn"},{"id":"c","text":"Ngưng tụ thành giọt nhỏ hoặc tinh thể băng"}],"correctOptionId":"c","explanation":"Hơi nước ngưng tụ khi không khí đạt điều kiện phù hợp."},{"id":"geography-10-precipitation-q2","prompt":"Bốc hơi là chuyển trạng thái nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Rắn sang lỏng"},{"id":"b","text":"Lỏng sang khí"},{"id":"c","text":"Khí sang lỏng"}],"correctOptionId":"b","explanation":"Bốc hơi đưa nước lỏng vào khí quyển dưới dạng hơi."},{"id":"geography-10-precipitation-q3","prompt":"Một sườn đón gió ẩm thường mưa nhiều hơn sườn khuất gió trong một số điều kiện. Cơ chế là?","difficulty":"APPLIED","options":[{"id":"a","text":"Không khí ẩm bị nâng lên, lạnh và ngưng tụ"},{"id":"b","text":"Núi hút nước trực tiếp từ mây"},{"id":"c","text":"Sườn khuất luôn cao hơn"}],"correctOptionId":"a","explanation":"Nâng địa hình làm không khí lạnh đi và tăng khả năng ngưng tụ."}]'::jsonb, '["geography-10-precipitation"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('geography', 10, 'intro-2026.1', 'geography-10-review-1', 6, 'FIVE_LESSON_REVIEW', 'Ôn tập 1', 'Địa lí: bản đồ, hệ tự nhiên và hoạt động kinh tế', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '[]'::jsonb, '[]'::jsonb, '[{"id":"geography-10-maps-scale-q1","prompt":"Tỉ lệ 1:100.000 có nghĩa là?","difficulty":"EASY","options":[{"id":"a","text":"1 đơn vị bản đồ bằng 100.000 đơn vị thực địa"},{"id":"b","text":"100.000 km trên bản đồ bằng 1 km"},{"id":"c","text":"Bản đồ có 100.000 trang"}],"correctOptionId":"a","explanation":"Hai độ dài phải dùng cùng đơn vị khi áp dụng tỉ lệ."},{"id":"geography-10-maps-scale-q2","prompt":"Trên bản đồ 1:50.000, 2 cm ứng với bao nhiêu?","difficulty":"MEDIUM","options":[{"id":"a","text":"100 m"},{"id":"b","text":"10 km"},{"id":"c","text":"1 km"}],"correctOptionId":"c","explanation":"2×50.000=100.000 cm=1.000 m."},{"id":"geography-10-earth-motion-q1","prompt":"Tự quay quanh trục chủ yếu tạo hiện tượng nào?","difficulty":"EASY","options":[{"id":"a","text":"Thủy triều duy nhất"},{"id":"b","text":"Các mùa giống nhau ở mọi nơi"},{"id":"c","text":"Ngày và đêm luân phiên"}],"correctOptionId":"c","explanation":"Mỗi nơi lần lượt hướng về và khuất khỏi ánh sáng Mặt Trời."},{"id":"geography-10-earth-motion-q2","prompt":"Trục Trái Đất nghiêng góp phần tạo ra điều gì trong năm?","difficulty":"MEDIUM","options":[{"id":"a","text":"Đổi vị trí xích đạo hằng ngày"},{"id":"b","text":"Khác biệt mùa giữa các bán cầu"},{"id":"c","text":"Tắt hoàn toàn trọng lực"}],"correctOptionId":"b","explanation":"Góc nhận bức xạ thay đổi theo thời gian và vĩ độ."},{"id":"geography-10-atmosphere-temperature-q1","prompt":"Phần lớn hiện tượng thời tiết diễn ra trong tầng nào?","difficulty":"EASY","options":[{"id":"a","text":"Nhân Trái Đất"},{"id":"b","text":"Đối lưu"},{"id":"c","text":"Ngoại quyển"}],"correctOptionId":"b","explanation":"Tầng đối lưu gần mặt đất và chứa phần lớn hơi nước, mây."},{"id":"geography-10-atmosphere-temperature-q2","prompt":"Nhiệt độ không khí thường thay đổi thế nào khi lên cao trong tầng đối lưu?","difficulty":"MEDIUM","options":[{"id":"a","text":"Giảm trung bình"},{"id":"b","text":"Tăng vô hạn"},{"id":"c","text":"Không bao giờ đổi"}],"correctOptionId":"a","explanation":"Đây là xu hướng trung bình, không phải quy luật tuyệt đối ở mọi thời điểm."},{"id":"geography-10-winds-pressure-q1","prompt":"Không khí gần mặt đất có xu hướng chuyển từ đâu đến đâu?","difficulty":"EASY","options":[{"id":"a","text":"Áp cao về áp thấp"},{"id":"b","text":"Áp thấp về áp cao trong mọi trường hợp"},{"id":"c","text":"Biển lên núi luôn luôn"}],"correctOptionId":"a","explanation":"Chênh lệch khí áp tạo lực thúc đẩy chuyển động không khí."},{"id":"geography-10-winds-pressure-q2","prompt":"Vì sao hướng gió thực tế có thể lệch so với đường nối hai vùng áp?","difficulty":"MEDIUM","options":[{"id":"a","text":"Màu mây"},{"id":"b","text":"Độ dài ngày duy nhất"},{"id":"c","text":"Sự quay Trái Đất và địa hình"}],"correctOptionId":"c","explanation":"Lực Coriolis và ma sát làm biến đổi hướng chuyển động."},{"id":"geography-10-precipitation-q1","prompt":"Mây hình thành chủ yếu khi hơi nước làm gì?","difficulty":"EASY","options":[{"id":"a","text":"Biến thành đất"},{"id":"b","text":"Chuyển thành khí quyển rắn"},{"id":"c","text":"Ngưng tụ thành giọt nhỏ hoặc tinh thể băng"}],"correctOptionId":"c","explanation":"Hơi nước ngưng tụ khi không khí đạt điều kiện phù hợp."},{"id":"geography-10-precipitation-q2","prompt":"Bốc hơi là chuyển trạng thái nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Rắn sang lỏng"},{"id":"b","text":"Lỏng sang khí"},{"id":"c","text":"Khí sang lỏng"}],"correctOptionId":"b","explanation":"Bốc hơi đưa nước lỏng vào khí quyển dưới dạng hơi."}]'::jsonb, '["geography-10-maps-scale","geography-10-earth-motion","geography-10-atmosphere-temperature","geography-10-winds-pressure","geography-10-precipitation"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('geography', 10, 'intro-2026.1', 'geography-10-water-cycle', 7, 'LESSON', 'Sông, hồ và tài nguyên nước', 'Địa lí: bản đồ, hệ tự nhiên và hoạt động kinh tế', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Lưu vực là vùng nước mưa tập trung về một hệ thống sông. Dòng chảy thay đổi theo mưa, địa hình, thảm phủ và hoạt động của con người."]'::jsonb, '["Bê tông hóa làm giảm thấm nước, có thể tăng dòng chảy mặt và nguy cơ ngập nhanh."]'::jsonb, '[{"id":"geography-10-water-cycle-q1","prompt":"Lưu vực sông là gì?","difficulty":"EASY","options":[{"id":"a","text":"Đường biên quốc gia"},{"id":"b","text":"Vùng tập trung nước về một hệ thống sông"},{"id":"c","text":"Một khúc sông duy nhất"}],"correctOptionId":"b","explanation":"Ranh lưu vực thường theo địa hình phân thủy."},{"id":"geography-10-water-cycle-q2","prompt":"Bề mặt đô thị không thấm nước tăng có thể gây gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Dòng chảy mặt tăng"},{"id":"b","text":"Mưa biến mất"},{"id":"c","text":"Lưu vực tự mở rộng"}],"correctOptionId":"a","explanation":"Nước ít thấm xuống đất nên chảy nhanh trên bề mặt."},{"id":"geography-10-water-cycle-q3","prompt":"Để giảm thiếu nước mùa khô, biện pháp dài hạn hợp lí là?","difficulty":"APPLIED","options":[{"id":"a","text":"Chỉ khai thác nước ngầm nhanh hơn"},{"id":"b","text":"Xóa toàn bộ vùng đất ngập nước"},{"id":"c","text":"Bảo vệ lưu vực, trữ nước và sử dụng tiết kiệm"}],"correctOptionId":"c","explanation":"Quản lí tổng hợp cân bằng nguồn cung và hệ sinh thái."}]'::jsonb, '["geography-10-water-cycle"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('geography', 10, 'intro-2026.1', 'geography-10-ocean', 8, 'LESSON', 'Đại dương, dòng biển và khí hậu', 'Địa lí: bản đồ, hệ tự nhiên và hoạt động kinh tế', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Đại dương lưu trữ và vận chuyển nhiệt, ảnh hưởng khí hậu ven bờ. Dòng biển hình thành do gió, chênh lệch nhiệt độ-muối và cấu hình bờ biển."]'::jsonb, '["Dòng biển ấm có thể làm không khí ven bờ ẩm và ôn hòa hơn, tùy hoàn lưu khu vực."]'::jsonb, '[{"id":"geography-10-ocean-q1","prompt":"Đại dương ảnh hưởng khí hậu bằng cách nào?","difficulty":"EASY","options":[{"id":"a","text":"Lưu trữ và vận chuyển nhiệt"},{"id":"b","text":"Ngăn hoàn toàn gió"},{"id":"c","text":"Làm mọi nơi có cùng nhiệt độ"}],"correctOptionId":"a","explanation":"Nước biển có thể điều hòa và phân phối lại năng lượng."},{"id":"geography-10-ocean-q2","prompt":"Dòng biển có thể được thúc đẩy bởi?","difficulty":"MEDIUM","options":[{"id":"a","text":"Chỉ động đất"},{"id":"b","text":"Màu bờ biển"},{"id":"c","text":"Gió và chênh lệch nhiệt độ, độ muối"}],"correctOptionId":"c","explanation":"Nhiều cơ chế cùng tham gia tuần hoàn đại dương."},{"id":"geography-10-ocean-q3","prompt":"Một thành phố ven biển chịu ảnh hưởng dòng biển lạnh. Kết luận khí hậu nên dựa thêm vào?","difficulty":"APPLIED","options":[{"id":"a","text":"Tên thành phố"},{"id":"b","text":"Gió, địa hình, vĩ độ và mùa"},{"id":"c","text":"Dòng biển là yếu tố duy nhất"}],"correctOptionId":"b","explanation":"Khí hậu là kết quả tương tác nhiều yếu tố."}]'::jsonb, '["geography-10-ocean"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('geography', 10, 'intro-2026.1', 'geography-10-tectonics', 9, 'LESSON', 'Cấu trúc Trái Đất và kiến tạo', 'Địa lí: bản đồ, hệ tự nhiên và hoạt động kinh tế', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Thạch quyển gồm vỏ và phần trên cứng của manti, chia thành các mảng. Tương tác mảng liên quan đến động đất, núi lửa và tạo núi, nhưng mức độ phụ thuộc ranh giới và điều kiện địa phương."]'::jsonb, '["Một vùng gần ranh giới mảng có thể có hoạt động địa chấn cao hơn vùng ổn định."]'::jsonb, '[{"id":"geography-10-tectonics-q1","prompt":"Lớp ngoài cứng chia thành các mảng là?","difficulty":"EASY","options":[{"id":"a","text":"Thủy quyển"},{"id":"b","text":"Khí quyển"},{"id":"c","text":"Thạch quyển"}],"correctOptionId":"c","explanation":"Thạch quyển bao gồm vỏ và phần trên cứng của manti."},{"id":"geography-10-tectonics-q2","prompt":"Động đất thường liên quan đến quá trình nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Sự đổi mùa"},{"id":"b","text":"Tích lũy và giải phóng năng lượng trong vỏ"},{"id":"c","text":"Vòng tuần hoàn nước"}],"correctOptionId":"b","explanation":"Chuyển động kiến tạo có thể giải phóng năng lượng dưới dạng sóng địa chấn."},{"id":"geography-10-tectonics-q3","prompt":"Không phải mọi vùng gần núi lửa đều có cùng rủi ro. Cần đánh giá thêm điều gì?","difficulty":"APPLIED","options":[{"id":"a","text":"Hoạt động, địa hình, dân cư và khả năng ứng phó"},{"id":"b","text":"Chỉ tên núi"},{"id":"c","text":"Màu dung nham trong ảnh"}],"correctOptionId":"a","explanation":"Rủi ro kết hợp hiểm họa, mức phơi bày và tính dễ tổn thương."}]'::jsonb, '["geography-10-tectonics"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('geography', 10, 'intro-2026.1', 'geography-10-weathering-erosion', 10, 'LESSON', 'Phong hóa, xói mòn và địa hình', 'Địa lí: bản đồ, hệ tự nhiên và hoạt động kinh tế', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Phong hóa phá vỡ hoặc biến đổi đá tại chỗ; xói mòn bóc tách và vận chuyển vật liệu. Nước, gió, băng và trọng lực góp phần tạo địa hình."]'::jsonb, '["Rễ cây chui vào khe đá có thể làm đá nứt rộng theo thời gian."]'::jsonb, '[{"id":"geography-10-weathering-erosion-q1","prompt":"Phong hóa khác xói mòn ở điểm nào?","difficulty":"EASY","options":[{"id":"a","text":"Phong hóa chỉ do con người"},{"id":"b","text":"Phong hóa biến đổi tại chỗ; xói mòn vận chuyển vật liệu"},{"id":"c","text":"Hai quá trình luôn giống nhau"}],"correctOptionId":"b","explanation":"Phân biệt nơi biến đổi với quá trình bóc chuyển vật liệu."},{"id":"geography-10-weathering-erosion-q2","prompt":"Dòng sông mang cát đi khỏi bờ là quá trình gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Xói mòn và vận chuyển"},{"id":"b","text":"Ngưng tụ"},{"id":"c","text":"Kiến tạo mảng"}],"correctOptionId":"a","explanation":"Nước có thể bóc và chuyển vật liệu theo dòng."},{"id":"geography-10-weathering-erosion-q3","prompt":"Mất cây trên sườn dốc làm nguy cơ rửa trôi đất tăng vì?","difficulty":"APPLIED","options":[{"id":"a","text":"Đá biến thành nước"},{"id":"b","text":"Mưa không còn trọng lực"},{"id":"c","text":"Đất ít được rễ giữ và giảm che phủ"}],"correctOptionId":"c","explanation":"Thảm thực vật giảm làm đất dễ bị tác động bởi dòng chảy."}]'::jsonb, '["geography-10-weathering-erosion"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('geography', 10, 'intro-2026.1', 'geography-10-soil', 11, 'LESSON', 'Đất và các nhân tố hình thành', 'Địa lí: bản đồ, hệ tự nhiên và hoạt động kinh tế', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Đất hình thành từ vật liệu mẹ chịu tác động của khí hậu, sinh vật, địa hình, thời gian và con người. Độ phì liên quan đến khả năng cung cấp nước, khí và chất dinh dưỡng."]'::jsonb, '["Đất dốc trơ trụi dễ mất lớp mặt khi mưa lớn."]'::jsonb, '[{"id":"geography-10-soil-q1","prompt":"Yếu tố nào góp phần hình thành đất?","difficulty":"EASY","options":[{"id":"a","text":"Khí hậu, sinh vật, địa hình và vật liệu mẹ"},{"id":"b","text":"Chỉ kinh độ"},{"id":"c","text":"Chỉ ánh sáng ban đêm"}],"correctOptionId":"a","explanation":"Đất hình thành qua tương tác nhiều nhân tố trong thời gian dài."},{"id":"geography-10-soil-q2","prompt":"Lớp đất mặt thường quan trọng vì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Không có sinh vật"},{"id":"b","text":"Luôn dày nhất"},{"id":"c","text":"Chứa nhiều chất hữu cơ và hoạt động sinh học"}],"correctOptionId":"c","explanation":"Lớp mặt thường giàu hữu cơ nhưng có thể bị xói mòn."},{"id":"geography-10-soil-q3","prompt":"Trên sườn dốc canh tác, biện pháp nào giúp giảm mất đất?","difficulty":"APPLIED","options":[{"id":"a","text":"Đốt hết thảm thực vật"},{"id":"b","text":"Canh tác theo đường đồng mức và giữ che phủ"},{"id":"c","text":"Cày xuôi dốc trơ đất"}],"correctOptionId":"b","explanation":"Các biện pháp làm chậm dòng chảy và bảo vệ lớp đất."}]'::jsonb, '["geography-10-soil"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('geography', 10, 'intro-2026.1', 'geography-10-review-2', 12, 'FIVE_LESSON_REVIEW', 'Ôn tập 2', 'Địa lí: bản đồ, hệ tự nhiên và hoạt động kinh tế', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '[]'::jsonb, '[]'::jsonb, '[{"id":"geography-10-water-cycle-q1","prompt":"Lưu vực sông là gì?","difficulty":"EASY","options":[{"id":"a","text":"Đường biên quốc gia"},{"id":"b","text":"Vùng tập trung nước về một hệ thống sông"},{"id":"c","text":"Một khúc sông duy nhất"}],"correctOptionId":"b","explanation":"Ranh lưu vực thường theo địa hình phân thủy."},{"id":"geography-10-water-cycle-q2","prompt":"Bề mặt đô thị không thấm nước tăng có thể gây gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Dòng chảy mặt tăng"},{"id":"b","text":"Mưa biến mất"},{"id":"c","text":"Lưu vực tự mở rộng"}],"correctOptionId":"a","explanation":"Nước ít thấm xuống đất nên chảy nhanh trên bề mặt."},{"id":"geography-10-ocean-q1","prompt":"Đại dương ảnh hưởng khí hậu bằng cách nào?","difficulty":"EASY","options":[{"id":"a","text":"Lưu trữ và vận chuyển nhiệt"},{"id":"b","text":"Ngăn hoàn toàn gió"},{"id":"c","text":"Làm mọi nơi có cùng nhiệt độ"}],"correctOptionId":"a","explanation":"Nước biển có thể điều hòa và phân phối lại năng lượng."},{"id":"geography-10-ocean-q2","prompt":"Dòng biển có thể được thúc đẩy bởi?","difficulty":"MEDIUM","options":[{"id":"a","text":"Chỉ động đất"},{"id":"b","text":"Màu bờ biển"},{"id":"c","text":"Gió và chênh lệch nhiệt độ, độ muối"}],"correctOptionId":"c","explanation":"Nhiều cơ chế cùng tham gia tuần hoàn đại dương."},{"id":"geography-10-tectonics-q1","prompt":"Lớp ngoài cứng chia thành các mảng là?","difficulty":"EASY","options":[{"id":"a","text":"Thủy quyển"},{"id":"b","text":"Khí quyển"},{"id":"c","text":"Thạch quyển"}],"correctOptionId":"c","explanation":"Thạch quyển bao gồm vỏ và phần trên cứng của manti."},{"id":"geography-10-tectonics-q2","prompt":"Động đất thường liên quan đến quá trình nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Sự đổi mùa"},{"id":"b","text":"Tích lũy và giải phóng năng lượng trong vỏ"},{"id":"c","text":"Vòng tuần hoàn nước"}],"correctOptionId":"b","explanation":"Chuyển động kiến tạo có thể giải phóng năng lượng dưới dạng sóng địa chấn."},{"id":"geography-10-weathering-erosion-q1","prompt":"Phong hóa khác xói mòn ở điểm nào?","difficulty":"EASY","options":[{"id":"a","text":"Phong hóa chỉ do con người"},{"id":"b","text":"Phong hóa biến đổi tại chỗ; xói mòn vận chuyển vật liệu"},{"id":"c","text":"Hai quá trình luôn giống nhau"}],"correctOptionId":"b","explanation":"Phân biệt nơi biến đổi với quá trình bóc chuyển vật liệu."},{"id":"geography-10-weathering-erosion-q2","prompt":"Dòng sông mang cát đi khỏi bờ là quá trình gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Xói mòn và vận chuyển"},{"id":"b","text":"Ngưng tụ"},{"id":"c","text":"Kiến tạo mảng"}],"correctOptionId":"a","explanation":"Nước có thể bóc và chuyển vật liệu theo dòng."},{"id":"geography-10-soil-q1","prompt":"Yếu tố nào góp phần hình thành đất?","difficulty":"EASY","options":[{"id":"a","text":"Khí hậu, sinh vật, địa hình và vật liệu mẹ"},{"id":"b","text":"Chỉ kinh độ"},{"id":"c","text":"Chỉ ánh sáng ban đêm"}],"correctOptionId":"a","explanation":"Đất hình thành qua tương tác nhiều nhân tố trong thời gian dài."},{"id":"geography-10-soil-q2","prompt":"Lớp đất mặt thường quan trọng vì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Không có sinh vật"},{"id":"b","text":"Luôn dày nhất"},{"id":"c","text":"Chứa nhiều chất hữu cơ và hoạt động sinh học"}],"correctOptionId":"c","explanation":"Lớp mặt thường giàu hữu cơ nhưng có thể bị xói mòn."}]'::jsonb, '["geography-10-water-cycle","geography-10-ocean","geography-10-tectonics","geography-10-weathering-erosion","geography-10-soil"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('geography', 10, 'intro-2026.1', 'geography-10-biosphere', 13, 'LESSON', 'Sinh quyển và phân bố sinh vật', 'Địa lí: bản đồ, hệ tự nhiên và hoạt động kinh tế', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Sinh vật phân bố theo nhiệt, nước, đất và quan hệ sinh thái. Ranh giới sinh cảnh biến đổi dần; cùng một loài có thể thích nghi hoặc di chuyển khi điều kiện thay đổi."]'::jsonb, '["Rừng ngập mặn phát triển ở vùng bờ có nước mặn-lợ và chịu tác động thủy triều."]'::jsonb, '[{"id":"geography-10-biosphere-q1","prompt":"Nhân tố nào thường giới hạn sinh vật trên cạn?","difficulty":"EASY","options":[{"id":"a","text":"Tên vùng hành chính"},{"id":"b","text":"Kinh độ không đổi"},{"id":"c","text":"Nhiệt độ và nước"}],"correctOptionId":"c","explanation":"Khí hậu và nguồn nước ảnh hưởng khả năng tồn tại của loài."},{"id":"geography-10-biosphere-q2","prompt":"Rừng ngập mặn gắn với môi trường nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Sa mạc nội lục"},{"id":"b","text":"Vùng ven biển chịu thủy triều"},{"id":"c","text":"Đỉnh núi băng giá"}],"correctOptionId":"b","explanation":"Loài ngập mặn thích nghi với điều kiện mặn-lợ ven biển."},{"id":"geography-10-biosphere-q3","prompt":"Mất một loài thụ phấn có thể ảnh hưởng hệ sinh thái qua cách nào?","difficulty":"APPLIED","options":[{"id":"a","text":"Làm giảm sinh sản của một số thực vật và tác động chuỗi tương tác"},{"id":"b","text":"Không thể ảnh hưởng loài khác"},{"id":"c","text":"Chỉ đổi màu đất"}],"correctOptionId":"a","explanation":"Các loài liên kết qua quan hệ sinh thái."}]'::jsonb, '["geography-10-biosphere"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('geography', 10, 'intro-2026.1', 'geography-10-population', 14, 'LESSON', 'Dân số và phân bố dân cư', 'Địa lí: bản đồ, hệ tự nhiên và hoạt động kinh tế', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Mật độ dân số bằng dân số chia diện tích. Mật độ trung bình không cho biết phân bố trong từng khu vực, mức tập trung hay điều kiện sống."]'::jsonb, '["Một tỉnh đông dân nhưng diện tích lớn có thể có mật độ thấp hơn một đô thị nhỏ."]'::jsonb, '[{"id":"geography-10-population-q1","prompt":"Công thức mật độ dân số là?","difficulty":"EASY","options":[{"id":"a","text":"Dân số × diện tích"},{"id":"b","text":"Dân số / diện tích"},{"id":"c","text":"Diện tích / dân số"}],"correctOptionId":"b","explanation":"Mật độ cho biết số người trung bình trên một đơn vị diện tích."},{"id":"geography-10-population-q2","prompt":"Mật độ trung bình cao có nghĩa mọi nơi trong vùng đều đông như nhau không?","difficulty":"MEDIUM","options":[{"id":"a","text":"Không"},{"id":"b","text":"Có"},{"id":"c","text":"Chỉ ở miền núi"}],"correctOptionId":"a","explanation":"Giá trị trung bình che khuất khác biệt nội vùng."},{"id":"geography-10-population-q3","prompt":"Khu vực dân cư tập trung dọc bờ sông. Cần xem yếu tố nào để giải thích?","difficulty":"APPLIED","options":[{"id":"a","text":"Chỉ màu dòng sông"},{"id":"b","text":"Kinh độ duy nhất"},{"id":"c","text":"Nước, giao thông, lịch sử và việc làm"}],"correctOptionId":"c","explanation":"Phân bố dân cư phản ánh nhiều điều kiện tự nhiên và xã hội."}]'::jsonb, '["geography-10-population"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('geography', 10, 'intro-2026.1', 'geography-10-urbanization', 15, 'LESSON', 'Đô thị hóa và vấn đề đô thị', 'Địa lí: bản đồ, hệ tự nhiên và hoạt động kinh tế', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Đô thị hóa gồm tăng dân số đô thị và thay đổi lối sống, không gian, việc làm. Đô thị tạo cơ hội dịch vụ nhưng cũng cần giải quyết nhà ở, giao thông và môi trường."]'::jsonb, '["Mở rộng giao thông công cộng có thể giảm phụ thuộc xe cá nhân nếu mạng lưới thuận tiện."]'::jsonb, '[{"id":"geography-10-urbanization-q1","prompt":"Đô thị hóa chỉ là xây thêm nhà cao tầng đúng không?","difficulty":"EASY","options":[{"id":"a","text":"Không, còn là thay đổi dân cư và hoạt động kinh tế"},{"id":"b","text":"Đúng trong mọi trường hợp"},{"id":"c","text":"Chỉ là tăng dân số nông thôn"}],"correctOptionId":"a","explanation":"Khái niệm bao gồm biến đổi dân cư và chức năng không gian."},{"id":"geography-10-urbanization-q2","prompt":"Một thách thức thường gặp khi đô thị tăng nhanh là?","difficulty":"MEDIUM","options":[{"id":"a","text":"Mọi dịch vụ biến mất"},{"id":"b","text":"Không còn giao thông"},{"id":"c","text":"Áp lực nhà ở và hạ tầng"}],"correctOptionId":"c","explanation":"Tốc độ tăng nhanh có thể vượt khả năng cung cấp hạ tầng."},{"id":"geography-10-urbanization-q3","prompt":"Một thành phố muốn giảm ùn tắc bền vững. Giải pháp nào có tác động hệ thống?","difficulty":"APPLIED","options":[{"id":"a","text":"Thu hẹp vỉa hè"},{"id":"b","text":"Kết nối giao thông công cộng với khu dân cư và việc làm"},{"id":"c","text":"Chỉ xây thêm bãi đỗ xe ở trung tâm"}],"correctOptionId":"b","explanation":"Mạng lưới thuận tiện tạo lựa chọn thay thế xe cá nhân."}]'::jsonb, '["geography-10-urbanization"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('geography', 10, 'intro-2026.1', 'geography-10-economic-sectors', 16, 'LESSON', 'Các ngành kinh tế và phân bố', 'Địa lí: bản đồ, hệ tự nhiên và hoạt động kinh tế', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Nông nghiệp, công nghiệp và dịch vụ phân bố theo tài nguyên, lao động, thị trường, giao thông và chính sách. Một ngành thường cần nhiều yếu tố cùng lúc."]'::jsonb, '["Nhà máy chế biến gần vùng nguyên liệu có thể giảm chi phí vận chuyển đầu vào."]'::jsonb, '[{"id":"geography-10-economic-sectors-q1","prompt":"Yếu tố nào có thể ảnh hưởng vị trí nhà máy chế biến?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ lượng mưa hôm nay"},{"id":"b","text":"Màu đất trên bản đồ"},{"id":"c","text":"Nguyên liệu, lao động và giao thông"}],"correctOptionId":"c","explanation":"Vị trí sản xuất cân nhắc chi phí và khả năng tiếp cận."},{"id":"geography-10-economic-sectors-q2","prompt":"Dịch vụ thường gắn chặt với yếu tố nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Độ dốc duy nhất"},{"id":"b","text":"Dân cư và thị trường"},{"id":"c","text":"Chỉ mỏ khoáng sản"}],"correctOptionId":"b","explanation":"Nhiều dịch vụ cần khách hàng, lao động và kết nối."},{"id":"geography-10-economic-sectors-q3","prompt":"Một vùng chuyển từ nông nghiệp sang du lịch, cần xem tác động nào?","difficulty":"APPLIED","options":[{"id":"a","text":"Việc làm, thu nhập, môi trường và quyền tiếp cận đất"},{"id":"b","text":"Chỉ số khách trong một ngày"},{"id":"c","text":"Không cần hỏi cư dân"}],"correctOptionId":"a","explanation":"Phát triển ngành mới có tác động kinh tế-xã hội và môi trường."}]'::jsonb, '["geography-10-economic-sectors"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('geography', 10, 'intro-2026.1', 'geography-10-sustainable-development', 17, 'LESSON', 'Phát triển bền vững và bản đồ số liệu', 'Địa lí: bản đồ, hệ tự nhiên và hoạt động kinh tế', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Phát triển bền vững cân bằng kinh tế, xã hội và môi trường qua thời gian. Bản đồ, biểu đồ cần đọc đúng đơn vị, nguồn, thời điểm và phạm vi."]'::jsonb, '["Một biểu đồ lượng khách tăng không tự chứng minh thu nhập cư dân cũng tăng."]'::jsonb, '[{"id":"geography-10-sustainable-development-q1","prompt":"Phát triển bền vững xem xét các mặt nào?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ số lượng công trình"},{"id":"b","text":"Kinh tế, xã hội và môi trường"},{"id":"c","text":"Chỉ tốc độ tăng trưởng"}],"correctOptionId":"b","explanation":"Ba trụ cột cần được cân nhắc đồng thời."},{"id":"geography-10-sustainable-development-q2","prompt":"Trước khi so sánh hai số liệu, nên kiểm tra gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Đơn vị, thời điểm và phạm vi"},{"id":"b","text":"Màu đường biểu diễn"},{"id":"c","text":"Tên tác giả duy nhất"}],"correctOptionId":"a","explanation":"Số liệu khác đơn vị hoặc phạm vi không thể so sánh trực tiếp."},{"id":"geography-10-sustainable-development-q3","prompt":"Biểu đồ cho thấy khách du lịch tăng nhưng không có số liệu thu nhập. Có thể khẳng định đời sống mọi cư dân tốt lên không?","difficulty":"APPLIED","options":[{"id":"a","text":"Có, khách tăng luôn giúp tất cả"},{"id":"b","text":"Có, chỉ cần nhìn biểu đồ"},{"id":"c","text":"Chưa; cần thêm dữ liệu phân phối thu nhập và tác động"}],"correctOptionId":"c","explanation":"Một chỉ số không đủ đánh giá đầy đủ tính bền vững."}]'::jsonb, '["geography-10-sustainable-development"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('geography', 10, 'intro-2026.1', 'geography-10-review-3', 18, 'FIVE_LESSON_REVIEW', 'Ôn tập 3', 'Địa lí: bản đồ, hệ tự nhiên và hoạt động kinh tế', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '[]'::jsonb, '[]'::jsonb, '[{"id":"geography-10-biosphere-q1","prompt":"Nhân tố nào thường giới hạn sinh vật trên cạn?","difficulty":"EASY","options":[{"id":"a","text":"Tên vùng hành chính"},{"id":"b","text":"Kinh độ không đổi"},{"id":"c","text":"Nhiệt độ và nước"}],"correctOptionId":"c","explanation":"Khí hậu và nguồn nước ảnh hưởng khả năng tồn tại của loài."},{"id":"geography-10-biosphere-q2","prompt":"Rừng ngập mặn gắn với môi trường nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Sa mạc nội lục"},{"id":"b","text":"Vùng ven biển chịu thủy triều"},{"id":"c","text":"Đỉnh núi băng giá"}],"correctOptionId":"b","explanation":"Loài ngập mặn thích nghi với điều kiện mặn-lợ ven biển."},{"id":"geography-10-population-q1","prompt":"Công thức mật độ dân số là?","difficulty":"EASY","options":[{"id":"a","text":"Dân số × diện tích"},{"id":"b","text":"Dân số / diện tích"},{"id":"c","text":"Diện tích / dân số"}],"correctOptionId":"b","explanation":"Mật độ cho biết số người trung bình trên một đơn vị diện tích."},{"id":"geography-10-population-q2","prompt":"Mật độ trung bình cao có nghĩa mọi nơi trong vùng đều đông như nhau không?","difficulty":"MEDIUM","options":[{"id":"a","text":"Không"},{"id":"b","text":"Có"},{"id":"c","text":"Chỉ ở miền núi"}],"correctOptionId":"a","explanation":"Giá trị trung bình che khuất khác biệt nội vùng."},{"id":"geography-10-urbanization-q1","prompt":"Đô thị hóa chỉ là xây thêm nhà cao tầng đúng không?","difficulty":"EASY","options":[{"id":"a","text":"Không, còn là thay đổi dân cư và hoạt động kinh tế"},{"id":"b","text":"Đúng trong mọi trường hợp"},{"id":"c","text":"Chỉ là tăng dân số nông thôn"}],"correctOptionId":"a","explanation":"Khái niệm bao gồm biến đổi dân cư và chức năng không gian."},{"id":"geography-10-urbanization-q2","prompt":"Một thách thức thường gặp khi đô thị tăng nhanh là?","difficulty":"MEDIUM","options":[{"id":"a","text":"Mọi dịch vụ biến mất"},{"id":"b","text":"Không còn giao thông"},{"id":"c","text":"Áp lực nhà ở và hạ tầng"}],"correctOptionId":"c","explanation":"Tốc độ tăng nhanh có thể vượt khả năng cung cấp hạ tầng."},{"id":"geography-10-economic-sectors-q1","prompt":"Yếu tố nào có thể ảnh hưởng vị trí nhà máy chế biến?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ lượng mưa hôm nay"},{"id":"b","text":"Màu đất trên bản đồ"},{"id":"c","text":"Nguyên liệu, lao động và giao thông"}],"correctOptionId":"c","explanation":"Vị trí sản xuất cân nhắc chi phí và khả năng tiếp cận."},{"id":"geography-10-economic-sectors-q2","prompt":"Dịch vụ thường gắn chặt với yếu tố nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Độ dốc duy nhất"},{"id":"b","text":"Dân cư và thị trường"},{"id":"c","text":"Chỉ mỏ khoáng sản"}],"correctOptionId":"b","explanation":"Nhiều dịch vụ cần khách hàng, lao động và kết nối."},{"id":"geography-10-sustainable-development-q1","prompt":"Phát triển bền vững xem xét các mặt nào?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ số lượng công trình"},{"id":"b","text":"Kinh tế, xã hội và môi trường"},{"id":"c","text":"Chỉ tốc độ tăng trưởng"}],"correctOptionId":"b","explanation":"Ba trụ cột cần được cân nhắc đồng thời."},{"id":"geography-10-sustainable-development-q2","prompt":"Trước khi so sánh hai số liệu, nên kiểm tra gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Đơn vị, thời điểm và phạm vi"},{"id":"b","text":"Màu đường biểu diễn"},{"id":"c","text":"Tên tác giả duy nhất"}],"correctOptionId":"a","explanation":"Số liệu khác đơn vị hoặc phạm vi không thể so sánh trực tiếp."}]'::jsonb, '["geography-10-biosphere","geography-10-population","geography-10-urbanization","geography-10-economic-sectors","geography-10-sustainable-development"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('economics_law', 10, 'intro-2026.1', 'placement', 0, 'PLACEMENT', 'Khảo sát đầu vào', 'Giáo dục kinh tế và pháp luật: lựa chọn kinh tế và công dân', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '[]'::jsonb, '[]'::jsonb, '[{"id":"economics_law-10-scarcity-choice-q1","prompt":"Chi phí cơ hội là gì?","difficulty":"EASY","options":[{"id":"a","text":"Lợi ích tốt nhất bị bỏ qua khi lựa chọn"},{"id":"b","text":"Tổng mọi khoản tiền đã chi"},{"id":"c","text":"Giá rẻ nhất trên thị trường"}],"correctOptionId":"a","explanation":"Nó phản ánh phương án tốt nhất đã không chọn."},{"id":"economics_law-10-scarcity-choice-q2","prompt":"Nguồn lực khan hiếm có nghĩa là?","difficulty":"MEDIUM","options":[{"id":"a","text":"Không tồn tại"},{"id":"b","text":"Luôn miễn phí"},{"id":"c","text":"Không đủ để đáp ứng mọi nhu cầu cùng lúc"}],"correctOptionId":"c","explanation":"Khan hiếm làm nảy sinh lựa chọn và phân bổ nguồn lực."},{"id":"economics_law-10-economic-actors-q1","prompt":"Doanh nghiệp thường có vai trò nào?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ ban hành luật"},{"id":"b","text":"Chỉ tiêu dùng cuối cùng"},{"id":"c","text":"Tổ chức sản xuất hàng hóa hoặc dịch vụ"}],"correctOptionId":"c","explanation":"Doanh nghiệp kết hợp nguồn lực để tạo sản phẩm hoặc dịch vụ."},{"id":"economics_law-10-economic-actors-q2","prompt":"Nhà nước có thể cung cấp dịch vụ công nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Chỉ quảng cáo"},{"id":"b","text":"Giáo dục công lập"},{"id":"c","text":"Mọi hàng hóa tư nhân miễn phí"}],"correctOptionId":"b","explanation":"Dịch vụ công phục vụ lợi ích chung và được tổ chức theo chính sách."},{"id":"economics_law-10-market-q1","prompt":"Thị trường cần có yếu tố nào?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ Nhà nước"},{"id":"b","text":"Người mua, người bán và trao đổi"},{"id":"c","text":"Chỉ một nhà kho"}],"correctOptionId":"b","explanation":"Thị trường hình thành từ các quan hệ trao đổi hàng hóa, dịch vụ."},{"id":"economics_law-10-market-q2","prompt":"Giá cả có thể truyền tín hiệu gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Thông tin về cung cầu và mức khan hiếm"},{"id":"b","text":"Mọi thông tin cá nhân của người mua"},{"id":"c","text":"Bảo đảm chất lượng tuyệt đối"}],"correctOptionId":"a","explanation":"Giá là tín hiệu hữu ích nhưng không phản ánh đầy đủ mọi thuộc tính."},{"id":"economics_law-10-supply-demand-q1","prompt":"Cầu có bao gồm điều gì ngoài mong muốn mua?","difficulty":"EASY","options":[{"id":"a","text":"Khả năng thanh toán"},{"id":"b","text":"Sở thích không liên quan giá"},{"id":"c","text":"Nguồn cung của doanh nghiệp"}],"correctOptionId":"a","explanation":"Cầu kinh tế gắn với mong muốn và khả năng mua."},{"id":"economics_law-10-supply-demand-q2","prompt":"Cân bằng thị trường khi nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Giá bằng 0"},{"id":"b","text":"Mọi người mua cùng một món"},{"id":"c","text":"Lượng cung bằng lượng cầu"}],"correctOptionId":"c","explanation":"Tại cân bằng, kế hoạch mua và bán tương thích về lượng."},{"id":"economics_law-10-competition-q1","prompt":"Một lợi ích tiềm năng của cạnh tranh là?","difficulty":"EASY","options":[{"id":"a","text":"Bảo đảm mọi doanh nghiệp luôn lời"},{"id":"b","text":"Xóa nhu cầu pháp luật"},{"id":"c","text":"Khuyến khích nâng chất lượng và đổi mới"}],"correctOptionId":"c","explanation":"Cạnh tranh có thể thúc đẩy cải tiến nhưng kết quả không được bảo đảm."},{"id":"economics_law-10-competition-q2","prompt":"Tung tin sai về đối thủ là hành vi nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Bảo vệ người tiêu dùng"},{"id":"b","text":"Cạnh tranh không lành mạnh"},{"id":"c","text":"Cạnh tranh bằng chất lượng"}],"correctOptionId":"b","explanation":"Thông tin gian dối làm méo mó quyết định và gây thiệt hại."}]'::jsonb, '[]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('economics_law', 10, 'intro-2026.1', 'economics_law-10-scarcity-choice', 1, 'LESSON', 'Nhu cầu, khan hiếm và chi phí cơ hội', 'Giáo dục kinh tế và pháp luật: lựa chọn kinh tế và công dân', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Nguồn lực có hạn trong khi nhu cầu đa dạng. Lựa chọn một phương án thường làm mất lợi ích tốt nhất của phương án bị bỏ qua; đó là chi phí cơ hội."]'::jsonb, '["Dùng hai giờ đi làm thêm thay vì ôn bài có chi phí cơ hội là phần học tập tốt nhất bị bỏ lỡ."]'::jsonb, '[{"id":"economics_law-10-scarcity-choice-q1","prompt":"Chi phí cơ hội là gì?","difficulty":"EASY","options":[{"id":"a","text":"Lợi ích tốt nhất bị bỏ qua khi lựa chọn"},{"id":"b","text":"Tổng mọi khoản tiền đã chi"},{"id":"c","text":"Giá rẻ nhất trên thị trường"}],"correctOptionId":"a","explanation":"Nó phản ánh phương án tốt nhất đã không chọn."},{"id":"economics_law-10-scarcity-choice-q2","prompt":"Nguồn lực khan hiếm có nghĩa là?","difficulty":"MEDIUM","options":[{"id":"a","text":"Không tồn tại"},{"id":"b","text":"Luôn miễn phí"},{"id":"c","text":"Không đủ để đáp ứng mọi nhu cầu cùng lúc"}],"correctOptionId":"c","explanation":"Khan hiếm làm nảy sinh lựa chọn và phân bổ nguồn lực."},{"id":"economics_law-10-scarcity-choice-q3","prompt":"Bạn có 100 nghìn, chọn mua sách thay vì vé xem phim. Chi phí cơ hội gần nhất là?","difficulty":"APPLIED","options":[{"id":"a","text":"Giá cuốn sách luôn luôn"},{"id":"b","text":"Lợi ích của buổi xem phim đã không chọn"},{"id":"c","text":"100 nghìn tự biến mất"}],"correctOptionId":"b","explanation":"Chi phí cơ hội là giá trị phương án tốt nhất bị bỏ qua."}]'::jsonb, '["economics_law-10-scarcity-choice"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('economics_law', 10, 'intro-2026.1', 'economics_law-10-economic-actors', 2, 'LESSON', 'Các chủ thể của nền kinh tế', 'Giáo dục kinh tế và pháp luật: lựa chọn kinh tế và công dân', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Hộ gia đình tiêu dùng và cung cấp nguồn lực; doanh nghiệp sản xuất; Nhà nước ban hành chính sách, cung cấp dịch vụ công; các chủ thể tương tác qua thị trường."]'::jsonb, '["Một hộ gia đình mua thực phẩm từ doanh nghiệp và cung cấp lao động cho thị trường việc làm."]'::jsonb, '[{"id":"economics_law-10-economic-actors-q1","prompt":"Doanh nghiệp thường có vai trò nào?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ ban hành luật"},{"id":"b","text":"Chỉ tiêu dùng cuối cùng"},{"id":"c","text":"Tổ chức sản xuất hàng hóa hoặc dịch vụ"}],"correctOptionId":"c","explanation":"Doanh nghiệp kết hợp nguồn lực để tạo sản phẩm hoặc dịch vụ."},{"id":"economics_law-10-economic-actors-q2","prompt":"Nhà nước có thể cung cấp dịch vụ công nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Chỉ quảng cáo"},{"id":"b","text":"Giáo dục công lập"},{"id":"c","text":"Mọi hàng hóa tư nhân miễn phí"}],"correctOptionId":"b","explanation":"Dịch vụ công phục vụ lợi ích chung và được tổ chức theo chính sách."},{"id":"economics_law-10-economic-actors-q3","prompt":"Người lao động vừa là hộ tiêu dùng vừa cung cấp sức lao động. Điều này cho thấy?","difficulty":"APPLIED","options":[{"id":"a","text":"Một chủ thể có thể tham gia nhiều thị trường"},{"id":"b","text":"Thị trường chỉ có doanh nghiệp"},{"id":"c","text":"Vai trò kinh tế không thể giao nhau"}],"correctOptionId":"a","explanation":"Các chủ thể đảm nhiệm vai trò khác nhau tùy quan hệ trao đổi."}]'::jsonb, '["economics_law-10-economic-actors"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('economics_law', 10, 'intro-2026.1', 'economics_law-10-market', 3, 'LESSON', 'Thị trường và giá cả', 'Giáo dục kinh tế và pháp luật: lựa chọn kinh tế và công dân', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Thị trường là quan hệ trao đổi giữa người mua và người bán. Giá cả truyền tín hiệu về mức khan hiếm và nhu cầu nhưng có thể chịu tác động của quy định và điều kiện khác."]'::jsonb, '["Khi một mặt hàng được ưa chuộng hơn trong khi cung ngắn hạn chưa đổi, giá có thể chịu áp lực tăng."]'::jsonb, '[{"id":"economics_law-10-market-q1","prompt":"Thị trường cần có yếu tố nào?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ Nhà nước"},{"id":"b","text":"Người mua, người bán và trao đổi"},{"id":"c","text":"Chỉ một nhà kho"}],"correctOptionId":"b","explanation":"Thị trường hình thành từ các quan hệ trao đổi hàng hóa, dịch vụ."},{"id":"economics_law-10-market-q2","prompt":"Giá cả có thể truyền tín hiệu gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Thông tin về cung cầu và mức khan hiếm"},{"id":"b","text":"Mọi thông tin cá nhân của người mua"},{"id":"c","text":"Bảo đảm chất lượng tuyệt đối"}],"correctOptionId":"a","explanation":"Giá là tín hiệu hữu ích nhưng không phản ánh đầy đủ mọi thuộc tính."},{"id":"economics_law-10-market-q3","prompt":"Cầu tăng nhanh còn lượng hàng ngắn hạn ít đổi. Điều gì có thể xảy ra với giá?","difficulty":"APPLIED","options":[{"id":"a","text":"Chắc chắn giảm về 0"},{"id":"b","text":"Không thể biến động"},{"id":"c","text":"Có áp lực tăng"}],"correctOptionId":"c","explanation":"Nhu cầu tăng trong khi cung chưa điều chỉnh có thể đẩy giá lên."}]'::jsonb, '["economics_law-10-market"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('economics_law', 10, 'intro-2026.1', 'economics_law-10-supply-demand', 4, 'LESSON', 'Cung, cầu và cân bằng thị trường', 'Giáo dục kinh tế và pháp luật: lựa chọn kinh tế và công dân', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Cầu là lượng người mua sẵn sàng và có khả năng mua ở các mức giá; cung là lượng người bán sẵn sàng bán. Cân bằng xảy ra khi lượng cung bằng lượng cầu."]'::jsonb, '["Nếu giá bán cao hơn mức cân bằng, lượng cung có thể vượt lượng cầu."]'::jsonb, '[{"id":"economics_law-10-supply-demand-q1","prompt":"Cầu có bao gồm điều gì ngoài mong muốn mua?","difficulty":"EASY","options":[{"id":"a","text":"Khả năng thanh toán"},{"id":"b","text":"Sở thích không liên quan giá"},{"id":"c","text":"Nguồn cung của doanh nghiệp"}],"correctOptionId":"a","explanation":"Cầu kinh tế gắn với mong muốn và khả năng mua."},{"id":"economics_law-10-supply-demand-q2","prompt":"Cân bằng thị trường khi nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Giá bằng 0"},{"id":"b","text":"Mọi người mua cùng một món"},{"id":"c","text":"Lượng cung bằng lượng cầu"}],"correctOptionId":"c","explanation":"Tại cân bằng, kế hoạch mua và bán tương thích về lượng."},{"id":"economics_law-10-supply-demand-q3","prompt":"Nếu mùa bão làm nguồn rau giảm, đường cung rau có thể?","difficulty":"APPLIED","options":[{"id":"a","text":"Không đổi trong mọi trường hợp"},{"id":"b","text":"Dịch trái"},{"id":"c","text":"Dịch phải"}],"correctOptionId":"b","explanation":"Sản xuất ít hơn ở mỗi mức giá biểu thị cung giảm."}]'::jsonb, '["economics_law-10-supply-demand"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('economics_law', 10, 'intro-2026.1', 'economics_law-10-competition', 5, 'LESSON', 'Cạnh tranh và lựa chọn kinh doanh', 'Giáo dục kinh tế và pháp luật: lựa chọn kinh tế và công dân', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Cạnh tranh khuyến khích cải tiến và lựa chọn nhưng cần tuân thủ pháp luật. Hành vi gian lận, thông đồng hoặc gây hại người tiêu dùng không trở nên hợp lí chỉ vì mục tiêu lợi nhuận."]'::jsonb, '["Hai cửa hàng cạnh tranh bằng chất lượng và dịch vụ lành mạnh hơn việc tung tin sai về đối thủ."]'::jsonb, '[{"id":"economics_law-10-competition-q1","prompt":"Một lợi ích tiềm năng của cạnh tranh là?","difficulty":"EASY","options":[{"id":"a","text":"Bảo đảm mọi doanh nghiệp luôn lời"},{"id":"b","text":"Xóa nhu cầu pháp luật"},{"id":"c","text":"Khuyến khích nâng chất lượng và đổi mới"}],"correctOptionId":"c","explanation":"Cạnh tranh có thể thúc đẩy cải tiến nhưng kết quả không được bảo đảm."},{"id":"economics_law-10-competition-q2","prompt":"Tung tin sai về đối thủ là hành vi nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Bảo vệ người tiêu dùng"},{"id":"b","text":"Cạnh tranh không lành mạnh"},{"id":"c","text":"Cạnh tranh bằng chất lượng"}],"correctOptionId":"b","explanation":"Thông tin gian dối làm méo mó quyết định và gây thiệt hại."},{"id":"economics_law-10-competition-q3","prompt":"Một doanh nghiệp muốn giữ khách bền vững, nên ưu tiên?","difficulty":"APPLIED","options":[{"id":"a","text":"Chất lượng, minh bạch và dịch vụ"},{"id":"b","text":"Che giấu mọi điều kiện bán"},{"id":"c","text":"Giả mạo đánh giá"}],"correctOptionId":"a","explanation":"Uy tín dựa trên giá trị thực và thông tin trung thực."}]'::jsonb, '["economics_law-10-competition"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
