insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('economics_law', 10, 'intro-2026.1', 'economics_law-10-consumer-rights', 13, 'LESSON', 'Quyền và trách nhiệm người tiêu dùng', 'Giáo dục kinh tế và pháp luật: lựa chọn kinh tế và công dân', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Người tiêu dùng cần được cung cấp thông tin trung thực, an toàn và có cơ chế khiếu nại theo quy định. Cũng cần sử dụng hàng hóa đúng hướng dẫn và cung cấp phản ánh trung thực."]'::jsonb, '["Giữ hóa đơn và ảnh lỗi sản phẩm giúp trình bày khiếu nại có căn cứ."]'::jsonb, '[{"id":"economics_law-10-consumer-rights-q1","prompt":"Thông tin nào người mua nên xem trước khi chọn sản phẩm?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ màu quảng cáo"},{"id":"b","text":"Mật khẩu người bán"},{"id":"c","text":"Thành phần, hướng dẫn, giá và cảnh báo"}],"correctOptionId":"c","explanation":"Thông tin sản phẩm giúp quyết định an toàn và phù hợp."},{"id":"economics_law-10-consumer-rights-q2","prompt":"Sản phẩm có lỗi, bước hữu ích là?","difficulty":"MEDIUM","options":[{"id":"a","text":"Đăng thông tin cá nhân của nhân viên"},{"id":"b","text":"Giữ bằng chứng mua hàng và liên hệ kênh khiếu nại"},{"id":"c","text":"Xóa hóa đơn"}],"correctOptionId":"b","explanation":"Bằng chứng và kênh chính thức hỗ trợ xử lí minh bạch."},{"id":"economics_law-10-consumer-rights-q3","prompt":"Quảng cáo hứa hẹn kết quả “chắc chắn” nhưng không có căn cứ. Người tiêu dùng nên?","difficulty":"APPLIED","options":[{"id":"a","text":"Kiểm tra thông tin, điều kiện và nguồn độc lập"},{"id":"b","text":"Tin vì có nhiều lượt thích"},{"id":"c","text":"Chuyển tiền đặt cọc ngay"}],"correctOptionId":"a","explanation":"Số lượt thích không thay thế bằng chứng về chất lượng."}]'::jsonb, '["economics_law-10-consumer-rights"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('economics_law', 10, 'intro-2026.1', 'economics_law-10-law-and-norms', 14, 'LESSON', 'Pháp luật và quy tắc xã hội', 'Giáo dục kinh tế và pháp luật: lựa chọn kinh tế và công dân', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Pháp luật là hệ thống quy tắc xử sự chung do Nhà nước ban hành hoặc thừa nhận và bảo đảm thực hiện. Đạo đức, tập quán và nội quy cũng điều chỉnh hành vi nhưng không đồng nhất với luật."]'::jsonb, '["Đi học muộn có thể vi phạm nội quy; hành vi chỉ là vi phạm pháp luật khi thỏa quy định pháp luật tương ứng."]'::jsonb, '[{"id":"economics_law-10-law-and-norms-q1","prompt":"Pháp luật khác tập quán ở điểm nào?","difficulty":"EASY","options":[{"id":"a","text":"Không áp dụng chung"},{"id":"b","text":"Có hiệu lực và cơ chế bảo đảm theo Nhà nước"},{"id":"c","text":"Luôn do một gia đình đặt ra"}],"correctOptionId":"b","explanation":"Pháp luật có tính bắt buộc chung và cơ chế thực thi."},{"id":"economics_law-10-law-and-norms-q2","prompt":"Mọi hành vi bị chê trách có tự động là vi phạm pháp luật không?","difficulty":"MEDIUM","options":[{"id":"a","text":"Không"},{"id":"b","text":"Có"},{"id":"c","text":"Chỉ khi lên mạng"}],"correctOptionId":"a","explanation":"Đánh giá đạo đức và xác định vi phạm luật là hai việc khác nhau."},{"id":"economics_law-10-law-and-norms-q3","prompt":"Một hành vi trái nội quy trường nhưng không đủ căn cứ là tội phạm. Nên mô tả thế nào?","difficulty":"APPLIED","options":[{"id":"a","text":"Chắc chắn phạm tội"},{"id":"b","text":"Không cần xác minh"},{"id":"c","text":"Vi phạm nội quy; không tự gán nhãn tội phạm"}],"correctOptionId":"c","explanation":"Dùng đúng khái niệm tránh gây hiểu lầm về trách nhiệm pháp lí."}]'::jsonb, '["economics_law-10-law-and-norms"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('economics_law', 10, 'intro-2026.1', 'economics_law-10-legal-responsibility', 15, 'LESSON', 'Thực hiện pháp luật và trách nhiệm', 'Giáo dục kinh tế và pháp luật: lựa chọn kinh tế và công dân', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Cá nhân cần tìm hiểu quy định liên quan, thực hiện quyền-nghĩa vụ và chịu trách nhiệm khi có hành vi vi phạm được xác định theo trình tự. Không tự kết luận trách nhiệm của người khác chỉ từ một đoạn tin."]'::jsonb, '["Khi xảy ra va chạm, lưu thông tin an toàn và báo cơ quan phù hợp thay vì đăng kết luận chưa kiểm chứng."]'::jsonb, '[{"id":"economics_law-10-legal-responsibility-q1","prompt":"Trách nhiệm pháp lí nên được xác định dựa trên?","difficulty":"EASY","options":[{"id":"a","text":"Quy định và trình tự có thẩm quyền"},{"id":"b","text":"Tin đồn"},{"id":"c","text":"Lượt bình chọn mạng"}],"correctOptionId":"a","explanation":"Việc xác định cần chứng cứ và quy trình theo luật."},{"id":"economics_law-10-legal-responsibility-q2","prompt":"Khi chứng kiến sự việc chưa rõ, nên làm gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Đăng tên người bị nghi ngay"},{"id":"b","text":"Tự xử phạt"},{"id":"c","text":"Ghi nhận thông tin cần thiết và báo kênh phù hợp"}],"correctOptionId":"c","explanation":"Cách tiếp cận an toàn tôn trọng quy trình và quyền cá nhân."},{"id":"economics_law-10-legal-responsibility-q3","prompt":"Một bạn chia sẻ ảnh riêng tư của người khác để “cảnh cáo”. Vấn đề cần cân nhắc là?","difficulty":"APPLIED","options":[{"id":"a","text":"Màu ảnh"},{"id":"b","text":"Quyền riêng tư và cách xử lí qua kênh hợp pháp"},{"id":"c","text":"Lượt thích"}],"correctOptionId":"b","explanation":"Mục đích tốt không tự động biện minh cho việc xâm phạm quyền."}]'::jsonb, '["economics_law-10-legal-responsibility"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('economics_law', 10, 'intro-2026.1', 'economics_law-10-rights-duties', 16, 'LESSON', 'Quyền và nghĩa vụ công dân', 'Giáo dục kinh tế và pháp luật: lựa chọn kinh tế và công dân', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Quyền và nghĩa vụ được quy định trong Hiến pháp, luật và văn bản liên quan. Thực hiện quyền cần tôn trọng quyền của người khác và điều kiện pháp luật."]'::jsonb, '["Quyền tự do biểu đạt không đồng nghĩa quyền bịa đặt hoặc xâm phạm danh dự người khác."]'::jsonb, '[{"id":"economics_law-10-rights-duties-q1","prompt":"Thực hiện quyền của mình cần tôn trọng điều gì?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ ý muốn cá nhân"},{"id":"b","text":"Tin chưa kiểm chứng"},{"id":"c","text":"Quyền và lợi ích hợp pháp của người khác"}],"correctOptionId":"c","explanation":"Quyền đi cùng trách nhiệm và giới hạn theo pháp luật."},{"id":"economics_law-10-rights-duties-q2","prompt":"Nguồn nào xác định khung quyền cơ bản của công dân Việt Nam?","difficulty":"MEDIUM","options":[{"id":"a","text":"Bình luận cá nhân"},{"id":"b","text":"Hiến pháp và pháp luật liên quan"},{"id":"c","text":"Một quảng cáo"}],"correctOptionId":"b","explanation":"Hiến pháp là luật cơ bản, các luật cụ thể hóa quyền và nghĩa vụ."},{"id":"economics_law-10-rights-duties-q3","prompt":"Một bài đăng công khai thông tin sai gây ảnh hưởng danh dự. Quyền nào có thể bị liên quan?","difficulty":"APPLIED","options":[{"id":"a","text":"Quyền được bảo vệ danh dự, nhân phẩm"},{"id":"b","text":"Quyền sở hữu đất của mọi người"},{"id":"c","text":"Quyền đổi múi giờ"}],"correctOptionId":"a","explanation":"Thông tin sai có thể xâm hại quyền nhân thân; cần xử lí theo quy định."}]'::jsonb, '["economics_law-10-rights-duties"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
