values ('economics_law', 10, 'intro-2026.1', 'economics_law-10-digital-citizenship', 17, 'LESSON', 'Công dân số và an toàn giao dịch', 'Giáo dục kinh tế và pháp luật: lựa chọn kinh tế và công dân', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Trong môi trường số, cần bảo vệ dữ liệu cá nhân, kiểm tra nguồn và thận trọng với yêu cầu chuyển tiền. Quyền riêng tư và trách nhiệm pháp luật vẫn áp dụng trên mạng."]'::jsonb, '["Không gửi mật khẩu, mã OTP hoặc ảnh giấy tờ cho tài khoản chưa xác minh."]'::jsonb, '[{"id":"economics_law-10-digital-citizenship-q1","prompt":"Thông tin nào không nên gửi cho người lạ qua chat?","difficulty":"EASY","options":[{"id":"a","text":"Chủ đề học tập"},{"id":"b","text":"Mật khẩu và mã OTP"},{"id":"c","text":"Tên một cuốn sách"}],"correctOptionId":"b","explanation":"Mật khẩu và OTP có thể cho phép truy cập hoặc giao dịch."},{"id":"economics_law-10-digital-citizenship-q2","prompt":"Một đường link yêu cầu đăng nhập lại ngân hàng và tạo cảm giác khẩn cấp. Nên?","difficulty":"MEDIUM","options":[{"id":"a","text":"Mở ứng dụng/kênh chính thức để kiểm tra độc lập"},{"id":"b","text":"Nhập thông tin ngay"},{"id":"c","text":"Gửi mã xác thực cho người gửi"}],"correctOptionId":"a","explanation":"Tạo áp lực khẩn cấp là dấu hiệu cần thận trọng."},{"id":"economics_law-10-digital-citizenship-q3","prompt":"Bạn nhận được ảnh chụp tin đồn về một bạn học. Cách ứng xử phù hợp là?","difficulty":"APPLIED","options":[{"id":"a","text":"Chia sẻ để mọi người tự đoán"},{"id":"b","text":"Thêm số điện thoại vào bài"},{"id":"c","text":"Không phát tán; xác minh và tôn trọng quyền riêng tư"}],"correctOptionId":"c","explanation":"Không lan truyền thông tin chưa kiểm chứng giúp hạn chế gây hại."}]'::jsonb, '["economics_law-10-digital-citizenship"]'::jsonb)
